# ==================================================
# PWA MENUFACILE GESTOR v751
# ==================================================

PWA_STATIC_DIR = PROJECT_ROOT / "backend" / "static" / "pwa"


def _pwa_text_response(filename: str, media_type: str, headers: dict[str, str] | None = None) -> Response:
    path = PWA_STATIC_DIR / filename
    if not path.is_file():
        raise HTTPException(status_code=404, detail="Recurso PWA não encontrado.")
    return Response(
        content=path.read_text(encoding="utf-8"),
        media_type=media_type,
        headers=headers or {},
    )


@app.get("/manifest.webmanifest", include_in_schema=False)
def pwa_manifest() -> Response:
    return _pwa_text_response(
        "manifest.webmanifest",
        "application/manifest+json",
        {"Cache-Control": "no-cache, must-revalidate"},
    )


@app.get("/service-worker.js", include_in_schema=False)
def pwa_service_worker() -> Response:
    return _pwa_text_response(
        "service-worker.js",
        "application/javascript",
        {
            "Cache-Control": "no-cache, no-store, must-revalidate",
            "Service-Worker-Allowed": "/",
        },
    )


