def garantir_colunas_multilingue_cardapio():
    """Adiciona colunas opcionais PT/IT/EN sem quebrar bancos antigos."""
    try:
        with engine.begin() as conn:
            tabelas = {
                "categorias": {
                    "nome_pt": "TEXT", "nome_it": "TEXT", "nome_en": "TEXT",
                    "descricao_pt": "TEXT", "descricao_it": "TEXT", "descricao_en": "TEXT",
                },
                "itens": {
                    "nome_pt": "TEXT", "nome_it": "TEXT", "nome_en": "TEXT",
                    "descricao_pt": "TEXT", "descricao_it": "TEXT", "descricao_en": "TEXT",
                },
            }
            for tabela, colunas in tabelas.items():
                existentes = {linha[1] for linha in conn.execute(text(f"PRAGMA table_info({tabela})")).fetchall()}
                for coluna, ddl in colunas.items():
                    if coluna not in existentes:
                        conn.execute(text(f"ALTER TABLE {tabela} ADD COLUMN {coluna} {ddl}"))
    except Exception:
        pass


def texto_ml(obj, campo="nome", idioma="pt"):
    """Exibe a versão em português; usa o campo principal como fallback."""
    base = getattr(obj, campo, None) or ""
    portugues = getattr(obj, f"{campo}_pt", None) or ""
    portugues = str(portugues or "").strip()
    return portugues or base or ""


templates.env.globals["texto_ml"] = texto_ml





