def garantir_colunas_numero_diario():
    """Adiciona colunas de número diário sem quebrar bancos antigos."""
    try:
        with engine.begin() as conn:
            tabelas = {
                "pedidos": {
                    "numero_dia": "INTEGER",
                    "data_operacional": "DATE",
                },
                "reservas": {
                    "numero_dia": "INTEGER",
                    "data_operacional": "DATE",
                },
            }
            for tabela, colunas in tabelas.items():
                existentes = {
                    linha[1]
                    for linha in conn.execute(text(f"PRAGMA table_info({tabela})")).fetchall()
                }
                for coluna, ddl in colunas.items():
                    if coluna not in existentes:
                        conn.execute(text(f"ALTER TABLE {tabela} ADD COLUMN {coluna} {ddl}"))
    except Exception as e:
        try:
            print("Aviso: não foi possível garantir colunas de número diário:", e)
        except Exception:
            pass


def mf_parse_data_operacional(valor=None):
    """Converte string YYYY-MM-DD/DD-MM-YYYY/DD/MM/YYYY em date. Fallback: hoje."""
    if isinstance(valor, date) and not isinstance(valor, datetime):
        return valor
    if isinstance(valor, datetime):
        return valor.date()

    texto = str(valor or "").strip()
    if texto:
        for fmt in ("%Y-%m-%d", "%d/%m/%Y", "%d-%m-%Y"):
            try:
                return datetime.strptime(texto, fmt).date()
            except Exception:
                pass

    return hoje_brasilia()


def gerar_numero_dia(db, modelo, empresa_id, data_ref):
    """Gera número sequencial operacional por empresa + data.

    Tentativas de checkout online ainda não aprovadas não participam da
    numeração visível. Dessa forma, um Pix/cartão recusado não cria buracos na
    sequência diária dos pedidos que realmente chegaram à operação.
    """
    data_ref = mf_parse_data_operacional(data_ref)

    try:
        consulta = (
            db.query(modelo)
            .filter(modelo.empresa_id == empresa_id)
            .filter(modelo.data_operacional == data_ref)
            .filter(modelo.numero_dia.isnot(None))
        )
        if modelo is Pedido:
            status_normalizado = func.lower(
                func.trim(func.replace(func.coalesce(modelo.status, ""), "_", " "))
            )
            consulta = consulta.filter(~status_normalizado.in_([
                "aguardando pagamento",
                "pagamento recusado",
                "pagamento cancelado",
                "pagamento erro",
            ]))
        ultimo = consulta.order_by(modelo.numero_dia.desc()).first()
        if ultimo and getattr(ultimo, "numero_dia", None):
            return int(ultimo.numero_dia) + 1
    except Exception:
        pass

    return 1


def codigo_operacional(obj, prefixo=""):
    """Retorna código visual profissional: #001 ou RSV-001."""
    numero = getattr(obj, "numero_dia", None) or getattr(obj, "id", None) or 0
    try:
        numero = int(numero)
    except Exception:
        numero = 0
    codigo = f"{numero:03d}" if numero > 0 else "000"
    return f"{prefixo}{codigo}" if prefixo else codigo


templates.env.globals["codigo_operacional"] = codigo_operacional


