def proteger_credenciais_mercadopago_existentes():
    """Migra credenciais antigas em texto simples sem alterar valores vazios."""
    db = SessionLocal()
    try:
        empresas = db.query(Empresa).all()
        alterou = False
        for empresa in empresas:
            for campo in ("mercadopago_access_token", "mercadopago_webhook_secret"):
                atual = getattr(empresa, campo, None)
                if atual and not str(atual).startswith("enc:v1:"):
                    setattr(empresa, campo, encrypt_secret(atual))
                    alterou = True
        if alterou:
            db.commit()
    except Exception:
        db.rollback()
        LOGGER.exception("Não foi possível proteger credenciais legadas do Mercado Pago.")
    finally:
        db.close()


