# INICIO v22: carregar itens reais dos pedidos para painel funcionário
def mf_pedido_to_dict_safe(obj):
    try:
        if isinstance(obj, dict):
            return obj
        return {
            "quantidade": getattr(obj, "quantidade", None) or getattr(obj, "qtd", None) or 1,
            "nome_item": getattr(obj, "nome_item", None) or getattr(obj, "nome", None) or getattr(obj, "produto_nome", None) or (getattr(getattr(obj, "item", None), "nome", None)) or (getattr(getattr(obj, "produto", None), "nome", None)) or "Item",
            "preco_unitario": getattr(obj, "preco_unitario", None) or getattr(obj, "preco", None) or getattr(obj, "valor_unitario", None) or 0,
            "subtotal": getattr(obj, "subtotal", None) or getattr(obj, "total", None) or 0,
            "observacao": getattr(obj, "observacao", None) or getattr(obj, "obs", None) or "",
        }
    except Exception:
        return {"quantidade": 1, "nome_item": "Item", "preco_unitario": 0, "subtotal": 0, "observacao": ""}

def mf_enriquecer_pedidos_com_itens(db, pedidos):
    """
    Carrega os itens reais do pedido para p.itens_funcionario.
    Funciona com vários nomes possíveis de modelo/campo usados no projeto.
    """
    try:
        # possíveis modelos de itens do pedido
        possible_item_models = []
        for name in [
            "PedidoItem", "ItemPedido", "PedidoItens", "ItensPedido",
            "PedidoProduto", "ProdutoPedido", "OrderItem", "OrderItems",
            "ComandaItem", "ItemComanda"
        ]:
            m = globals().get(name)
            if m is not None:
                possible_item_models.append(m)

        possible_product_models = []
        for name in ["Item", "CardapioItem", "Produto", "ProdutoCardapio", "MenuItem", "Servico"]:
            m = globals().get(name)
            if m is not None:
                possible_product_models.append(m)

        for pedido in pedidos:
            itens_norm = []

            # 1) tenta relacionamentos já carregados no pedido
            for rel in ["itens_funcionario", "itens", "itens_pedido", "items", "produtos", "pedido_itens", "order_items"]:
                try:
                    value = getattr(pedido, rel, None)
                    if value:
                        for pi in list(value):
                            itens_norm.append(mf_pedido_to_dict_safe(pi))
                        if itens_norm:
                            break
                except Exception:
                    pass

            # 2) tenta modelos de item via pedido_id
            if not itens_norm:
                for Model in possible_item_models:
                    try:
                        if not hasattr(Model, "pedido_id"):
                            continue
                        rows = db.query(Model).filter(Model.pedido_id == pedido.id).all()
                        for pi in rows:
                            d = mf_pedido_to_dict_safe(pi)

                            # se nome ainda genérico, tenta buscar produto/item pelo id
                            nome_generico = not d.get("nome_item") or d.get("nome_item") == "Item"
                            item_id = (
                                getattr(pi, "item_id", None)
                                or getattr(pi, "produto_id", None)
                                or getattr(pi, "cardapio_item_id", None)
                                or getattr(pi, "menu_item_id", None)
                            )
                            if nome_generico and item_id:
                                for PM in possible_product_models:
                                    try:
                                        prod = db.query(PM).filter(PM.id == item_id).first()
                                        if prod:
                                            d["nome_item"] = getattr(prod, "nome", None) or getattr(prod, "titulo", None) or "Item"
                                            if not d.get("preco_unitario"):
                                                d["preco_unitario"] = getattr(prod, "preco", None) or 0
                                            break
                                    except Exception:
                                        pass

                            qtd = d.get("quantidade") or 1
                            preco = d.get("preco_unitario") or 0
                            if not d.get("subtotal"):
                                try:
                                    d["subtotal"] = float(preco or 0) * float(qtd or 1)
                                except Exception:
                                    d["subtotal"] = 0

                            itens_norm.append(d)
                        if itens_norm:
                            break
                    except Exception:
                        pass

            # 3) fallback: tenta campos JSON/lista dentro do próprio pedido
            if not itens_norm:
                for field in ["itens_json", "items_json", "produtos_json", "carrinho", "pedido_json", "detalhes"]:
                    try:
                        raw = getattr(pedido, field, None)
                        if not raw:
                            continue
                        import json
                        data = json.loads(raw) if isinstance(raw, str) else raw
                        if isinstance(data, dict):
                            data = data.get("itens") or data.get("items") or data.get("produtos") or []
                        if isinstance(data, list):
                            for pi in data:
                                if isinstance(pi, dict):
                                    qtd = pi.get("quantidade") or pi.get("qtd") or 1
                                    nome = pi.get("nome_item") or pi.get("nome") or pi.get("produto") or pi.get("titulo") or "Item"
                                    preco = pi.get("preco_unitario") or pi.get("preco") or pi.get("valor") or 0
                                    subtotal = pi.get("subtotal") or pi.get("total") or (float(preco or 0) * float(qtd or 1))
                                    itens_norm.append({"quantidade": qtd, "nome_item": nome, "preco_unitario": preco, "subtotal": subtotal, "observacao": pi.get("observacao") or pi.get("obs") or ""})
                        if itens_norm:
                            break
                    except Exception:
                        pass

            try:
                setattr(pedido, "itens_funcionario", itens_norm)
            except Exception:
                pass

        return pedidos
    except Exception:
        return pedidos
# FIM v22



# INICIO v28: tradução automática simples para cardápio PT/IT/EN
def mf_norm_txt_v28(txt):
    import re
    return re.sub(r"\s+", " ", str(txt or "").strip())

def mf_title_keep_v28(txt):
    txt = mf_norm_txt_v28(txt)
    return " ".join([p[:1].upper() + p[1:] if p else p for p in txt.split(" ")])

