def mf_translate_text_v28(texto, target_lang):
    """
    Tradutor automático interno simples/offline.
    Não usa API externa. Serve para preencher PT/IT/EN automaticamente e evitar campos vazios.
    Para nomes desconhecidos, mantém o original.
    """
    original = mf_norm_txt_v28(texto)
    if not original:
        return ""

    lang = target_lang if target_lang in ["pt","it","en"] else "it"
    low = original.lower().strip()

    # frase exata
    if low in MF_TRANSLATE_PHRASES_V28:
        return MF_TRANSLATE_PHRASES_V28[low].get(lang) or original

    # termo exato
    if low in MF_TRANSLATE_WORDS_V28:
        return MF_TRANSLATE_WORDS_V28[low].get(lang) or original

    # troca parcial por frases maiores primeiro
    result = original
    for key in sorted(MF_TRANSLATE_WORDS_V28.keys(), key=len, reverse=True):
        vals = MF_TRANSLATE_WORDS_V28[key]
        repl = vals.get(lang)
        if not repl:
            continue
        import re
        pattern = re.compile(re.escape(key), re.IGNORECASE)
        if pattern.search(result):
            result = pattern.sub(repl, result)

    # se nada mudou, mantém original
    return mf_title_keep_v28(result) if result != original and len(original) < 80 else result

def mf_auto_translate_fields_v28(obj, nome=None, descricao=None):
    """
    V36:
    Preenche campos multilíngues vazios e também corrige campos que foram
    preenchidos apenas copiando o mesmo nome/descrição original.
    Mantém campos manuais quando o usuário escreveu algo diferente do original.
    """
    nome_base = mf_norm_txt_v28(nome if nome is not None else getattr(obj, "nome", ""))
    desc_base = mf_norm_txt_v28(descricao if descricao is not None else getattr(obj, "descricao", ""))

    def deve_atualizar(valor_atual, base):
        atual = mf_norm_txt_v28(valor_atual)
        base = mf_norm_txt_v28(base)
        if not atual:
            return True
        # Se o botão antigo copiou igual ao original, considera tradução faltante.
        if base and atual.lower() == base.lower():
            return True
        return False

    for lang in ["pt","it","en"]:
        field = f"nome_{lang}"
        if hasattr(obj, field) and deve_atualizar(getattr(obj, field, ""), nome_base):
            traduzido = mf_translate_text_v28(nome_base, lang)
            setattr(obj, field, traduzido)

    for lang in ["pt","it","en"]:
        field = f"descricao_{lang}"
        if hasattr(obj, field) and deve_atualizar(getattr(obj, field, ""), desc_base):
            traduzido = mf_translate_text_v28(desc_base, lang)
            setattr(obj, field, traduzido)
# FIM v28


@app.get("/webhooks/whatsapp")
async def verificar_webhook_whatsapp(request: Request):
    """Validação inicial do webhook feita pela Meta."""
    if not WHATSAPP_VERIFY_TOKEN:
        LOGGER.error("WHATSAPP_VERIFY_TOKEN não configurado; verificação do webhook bloqueada.")
        return Response(content="Webhook não configurado", status_code=503)

    mode = str(request.query_params.get("hub.mode") or "")
    supplied = str(request.query_params.get("hub.verify_token") or "")
    challenge = str(request.query_params.get("hub.challenge") or "")
    token_ok = bool(supplied) and hmac.compare_digest(supplied, WHATSAPP_VERIFY_TOKEN)

    if mode == "subscribe" and token_ok:
        return Response(content=challenge, media_type="text/plain")

    LOGGER.warning("Tentativa inválida de verificação do webhook WhatsApp.")
    return Response(content="Token inválido", status_code=403)


@app.post("/webhooks/whatsapp")
async def receber_webhook_whatsapp(request: Request):
    """Recebe eventos da Meta apenas quando a assinatura HMAC é válida."""
    if not WHATSAPP_APP_SECRET:
        LOGGER.error("WHATSAPP_APP_SECRET não configurado; webhook WhatsApp bloqueado.")
        return JSONResponse({"status": "indisponivel"}, status_code=503)

    raw_body = await request.body()
    if len(raw_body) > 2 * 1024 * 1024:
        return JSONResponse({"status": "payload_invalido"}, status_code=413)

    if not verify_meta_webhook_signature(
        body=raw_body,
        signature=request.headers.get("x-hub-signature-256", ""),
        app_secret=WHATSAPP_APP_SECRET,
    ):
        LOGGER.warning("Assinatura inválida no webhook WhatsApp.")
        return JSONResponse({"status": "nao_autorizado"}, status_code=401)

    try:
        body = json.loads(raw_body.decode("utf-8")) if raw_body else {}
    except (UnicodeError, json.JSONDecodeError):
        return JSONResponse({"status": "payload_invalido"}, status_code=400)

    entries = body.get("entry") if isinstance(body, dict) else []
    LOGGER.info("Webhook WhatsApp validado: entradas=%s", len(entries or []))
    return {"status": "ok"}




