# V154 — VERIFICAÇÃO PARTITA IVA VIA VIES OFICIAL UE
# ==================================================

def normalizar_partita_iva_vies(valor: str):
    valor = re.sub(r"[^A-Za-z0-9]", "", valor or "").upper()

    if not valor:
        return None, None, "Digite uma Partita IVA."

    if len(valor) >= 3 and valor[:2].isalpha():
        pais = valor[:2]
        numero = valor[2:]
    else:
        pais = "IT"
        numero = valor

    if pais == "IT" and (not numero.isdigit() or len(numero) != 11):
        return None, None, "Partita IVA italiana deve ter 11 números. Exemplo: IT12345678901."

    if not pais.isalpha() or len(pais) != 2 or not numero:
        return None, None, "Formato de Partita IVA inválido."

    return pais, numero, None


def consultar_vies_oficial(pais: str, numero: str):
    endpoint = "https://ec.europa.eu/taxation_customs/vies/services/checkVatService"

    soap_body = """<?xml version="1.0" encoding="UTF-8"?>
<soapenv:Envelope xmlns:soapenv="http://schemas.xmlsoap.org/soap/envelope/" xmlns:urn="urn:ec.europa.eu:taxud:vies:services:checkVat:types">
  <soapenv:Header/>
  <soapenv:Body>
    <urn:checkVat>
      <urn:countryCode>{pais}</urn:countryCode>
      <urn:vatNumber>{numero}</urn:vatNumber>
    </urn:checkVat>
  </soapenv:Body>
</soapenv:Envelope>""".format(pais=pais, numero=numero)

    req = urllib.request.Request(
        endpoint,
        data=soap_body.encode("utf-8"),
        headers={
            "Content-Type": "text/xml; charset=utf-8",
            "SOAPAction": ""
        },
        method="POST"
    )

    try:
        with urllib.request.urlopen(req, timeout=12) as response:
            xml_text = response.read().decode("utf-8", errors="ignore")
    except urllib.error.HTTPError as exc:
        detalhe = exc.read().decode("utf-8", errors="ignore")
        return {
            "ok": False,
            "valida": False,
            "erro": "A consulta VIES retornou erro HTTP.",
            "detalhe": detalhe[:500]
        }
    except urllib.error.URLError:
        return {
            "ok": False,
            "valida": False,
            "erro": "Não foi possível conectar ao serviço VIES agora. Tente novamente mais tarde."
        }
    except Exception:
        return {
            "ok": False,
            "valida": False,
            "erro": "Erro inesperado ao consultar o VIES."
        }

    try:
        root = ET.fromstring(xml_text)

        fault = root.find(".//{http://schemas.xmlsoap.org/soap/envelope/}Fault")
        if fault is not None:
            fault_string = fault.findtext("faultstring") or "Erro no serviço VIES."
            return {
                "ok": False,
                "valida": False,
                "erro": traduzir_erro_vies(fault_string),
                "codigo": fault_string
            }

        ns = {"v": "urn:ec.europa.eu:taxud:vies:services:checkVat:types"}

        country_code = root.findtext(".//v:countryCode", default=pais, namespaces=ns)
        vat_number = root.findtext(".//v:vatNumber", default=numero, namespaces=ns)
        request_date = root.findtext(".//v:requestDate", default="", namespaces=ns)
        valid_text = root.findtext(".//v:valid", default="false", namespaces=ns)
        name = root.findtext(".//v:name", default="", namespaces=ns) or ""
        address = root.findtext(".//v:address", default="", namespaces=ns) or ""

        name_limpo = "" if name.strip("- \n\t") == "" else name.strip()
        address_limpo = "" if address.strip("- \n\t") == "" else address.strip()

        return {
            "ok": True,
            "valida": str(valid_text).lower() == "true",
            "pais": country_code,
            "numero": vat_number,
            "partita_iva": f"{country_code}{vat_number}",
            "ragione_sociale": name_limpo,
            "endereco": address_limpo,
            "data_consulta": request_date,
            "fonte": "VIES — Comissão Europeia"
        }
    except Exception:
        return {
            "ok": False,
            "valida": False,
            "erro": "Não foi possível interpretar a resposta do VIES."
        }


def traduzir_erro_vies(codigo: str):
    codigo = (codigo or "").upper()

    mensagens = {
        "INVALID_INPUT": "Formato inválido para consulta VIES.",
        "SERVICE_UNAVAILABLE": "Serviço VIES temporariamente indisponível.",
        "MS_UNAVAILABLE": "Base fiscal do país temporariamente indisponível.",
        "TIMEOUT": "Tempo de consulta esgotado no VIES.",
        "SERVER_BUSY": "Serviço VIES ocupado. Tente novamente em alguns minutos.",
        "VAT_BLOCKED": "Consulta bloqueada temporariamente pelo serviço VIES."
    }

    return mensagens.get(codigo, f"Erro retornado pelo VIES: {codigo}")


@app.get("/api/partita-iva/verificar")
def verificar_partita_iva_vies(
    empresa_id: int,
    piva: str,
    request: Request
):
    exigir_admin_empresa_api(request, empresa_id)

    pais, numero, erro = normalizar_partita_iva_vies(piva)

    if erro:
        return {
            "ok": False,
            "valida": False,
            "erro": erro
        }

    resultado = consultar_vies_oficial(pais, numero)
    resultado["consulta"] = {
        "pais": pais,
        "numero": numero
    }

    return resultado





