DIAS_FUNCIONAMENTO = [
    (0, "Segunda-feira"),
    (1, "Terça-feira"),
    (2, "Quarta-feira"),
    (3, "Quinta-feira"),
    (4, "Sexta-feira"),
    (5, "Sábado"),
    (6, "Domingo"),
]


def garantir_tabela_horarios_funcionamento():
    """Tabela simples para horários do menu público e bloqueio de pedidos."""
    try:
        conn = engine.raw_connection()
        cursor = conn.cursor()
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS horarios_funcionamento (
                empresa_id INTEGER NOT NULL,
                dia_semana INTEGER NOT NULL,
                aberto INTEGER DEFAULT 1,
                hora_inicio TEXT DEFAULT '',
                hora_fim TEXT DEFAULT '',
                texto_exibicao TEXT DEFAULT '',
                PRIMARY KEY (empresa_id, dia_semana)
            )
        """)
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS horarios_funcionamento_config (
                empresa_id INTEGER PRIMARY KEY,
                restricao_ativa INTEGER NOT NULL DEFAULT 1
            )
        """)
        conn.commit()
        conn.close()
    except Exception as erro:
        print("Aviso: não foi possível garantir horarios_funcionamento:", erro)


def obter_restricao_horarios_ativa(db, empresa_id: int) -> bool:
    garantir_tabela_horarios_funcionamento()
    linha = db.execute(
        text("SELECT restricao_ativa FROM horarios_funcionamento_config WHERE empresa_id = :empresa_id"),
        {"empresa_id": empresa_id}
    ).mappings().first()
    return True if not linha else bool(linha["restricao_ativa"])


def salvar_restricao_horarios(db, empresa_id: int, ativa: bool):
    garantir_tabela_horarios_funcionamento()
    db.execute(
        text("""
            INSERT INTO horarios_funcionamento_config (empresa_id, restricao_ativa)
            VALUES (:empresa_id, :restricao_ativa)
            ON CONFLICT(empresa_id) DO UPDATE SET restricao_ativa = excluded.restricao_ativa
        """),
        {"empresa_id": empresa_id, "restricao_ativa": 1 if ativa else 0}
    )


def _horario_padrao_linha(dia_numero: int, dia_nome: str):
    fechado = dia_numero == 6
    return {
        "dia_semana": dia_numero,
        "dia_nome": dia_nome,
        "aberto": not fechado,
        "hora_inicio": "" if fechado else "09:00",
        "hora_fim": "" if fechado else "18:00",
        "texto_exibicao": "Fechado" if fechado else "09:00 até 18:00",
        "display": "Fechado" if fechado else "09:00 até 18:00"
    }


def obter_horarios_funcionamento(db, empresa_id: int):
    garantir_tabela_horarios_funcionamento()
    try:
        linhas = db.execute(
            text("SELECT * FROM horarios_funcionamento WHERE empresa_id = :empresa_id ORDER BY dia_semana"),
            {"empresa_id": empresa_id}
        ).mappings().all()
        por_dia = {int(linha["dia_semana"]): linha for linha in linhas}

        horarios = []
        for dia_numero, dia_nome in DIAS_FUNCIONAMENTO:
            linha = por_dia.get(dia_numero)
            if not linha:
                horarios.append(_horario_padrao_linha(dia_numero, dia_nome))
                continue

            aberto = bool(linha["aberto"])
            inicio = (linha["hora_inicio"] or "").strip()
            fim = (linha["hora_fim"] or "").strip()
            texto_livre = (linha["texto_exibicao"] or "").strip()
            if texto_livre:
                display = texto_livre
            elif aberto and inicio and fim:
                display = f"{inicio} até {fim}"
            elif aberto:
                display = "Aberto"
            else:
                display = "Fechado"

            horarios.append({
                "dia_semana": dia_numero,
                "dia_nome": dia_nome,
                "aberto": aberto,
                "hora_inicio": inicio,
                "hora_fim": fim,
                "texto_exibicao": texto_livre,
                "display": display
            })

        return horarios
    except Exception as erro:
        print("Aviso: erro ao ler horarios_funcionamento:", erro)
        return [_horario_padrao_linha(n, nome) for n, nome in DIAS_FUNCIONAMENTO]


def salvar_horarios_funcionamento(db, empresa_id: int, formulario):
    garantir_tabela_horarios_funcionamento()
    for dia_numero, dia_nome in DIAS_FUNCIONAMENTO:
        aberto = 1 if str(formulario.get(f"horario_aberto_{dia_numero}", "1")).strip() == "1" else 0
        inicio = str(formulario.get(f"horario_inicio_{dia_numero}", "") or "").strip()[:5]
        fim = str(formulario.get(f"horario_fim_{dia_numero}", "") or "").strip()[:5]
        texto_livre = str(formulario.get(f"horario_texto_{dia_numero}", "") or "").strip()[:120]

        db.execute(
            text("""
                INSERT INTO horarios_funcionamento
                (empresa_id, dia_semana, aberto, hora_inicio, hora_fim, texto_exibicao)
                VALUES (:empresa_id, :dia_semana, :aberto, :hora_inicio, :hora_fim, :texto_exibicao)
                ON CONFLICT(empresa_id, dia_semana) DO UPDATE SET
                    aberto = excluded.aberto,
                    hora_inicio = excluded.hora_inicio,
                    hora_fim = excluded.hora_fim,
                    texto_exibicao = excluded.texto_exibicao
            """),
            {
                "empresa_id": empresa_id,
                "dia_semana": dia_numero,
                "aberto": aberto,
                "hora_inicio": inicio,
                "hora_fim": fim,
                "texto_exibicao": texto_livre
            }
        )


def _parse_hora_hhmm(valor: str):
    valor = (valor or "").strip()
    if not re.match(r"^\d{2}:\d{2}$", valor):
        return None
    try:
        h, m = [int(parte) for parte in valor.split(":", 1)]
        if 0 <= h <= 23 and 0 <= m <= 59:
            return time(h, m)
    except Exception:
        pass
    return None


def verificar_pedidos_abertos(db, empresa_id: int, agora: datetime | None = None):
    """Retorna se o pedido online pode ser enviado agora, sem bloquear a visualização do cardápio."""
    agora = agora or agora_brasilia()
    horarios = obter_horarios_funcionamento(db, empresa_id)
    if not obter_restricao_horarios_ativa(db, empresa_id):
        return True, "Pedidos disponíveis 24 horas.", horarios
    hoje = agora.weekday()
    linha = next((item for item in horarios if int(item["dia_semana"]) == hoje), None)

    if not linha:
        return True, "Pedidos disponíveis.", horarios

    display = linha.get("display") or ""

    if not linha.get("aberto"):
        return False, f"Estamos fechados no momento. Horário de hoje: {display}.", horarios

    inicio = _parse_hora_hhmm(linha.get("hora_inicio"))
    fim = _parse_hora_hhmm(linha.get("hora_fim"))

    if inicio and fim:
        hora_atual = agora.time()
        if inicio <= fim:
            dentro = inicio <= hora_atual <= fim
        else:
            # Ex.: 18:00 até 02:00
            dentro = hora_atual >= inicio or hora_atual <= fim

        if not dentro:
            return False, f"Estamos fechados no momento. Horário de hoje: {display}.", horarios

    return True, f"Estamos abertos hoje: {display}.", horarios



# ==================================================
# IMPRESSÃO UNIVERSAL — Navegador / QZ / IP / USB / Bluetooth / Serial
# ==================================================

IMPRESSAO_MODOS_VALIDOS = {"navegador", "qz", "ip_qz", "serial_qz", "app_local"}
IMPRESSAO_CONEXOES_VALIDAS = {"navegador", "usb", "bluetooth", "wifi", "ethernet", "serial"}
IMPRESSAO_LARGURAS_VALIDAS = {"58", "80", "a4"}


def _bool_formulario(formulario, nome: str, padrao: bool = False) -> bool:
    valor = str(formulario.get(nome, "1" if padrao else "0") or "").strip().lower()
    return valor in {"1", "true", "on", "sim", "yes"}


def _texto_curto(valor, limite: int = 120) -> str | None:
    valor = str(valor or "").strip()
    return valor[:limite] or None


def _inteiro_seguro(valor, padrao: int, minimo: int = 0, maximo: int = 999999) -> int:
    try:
        numero = int(str(valor or padrao).strip())
    except Exception:
        numero = padrao
    return max(minimo, min(maximo, numero))


def obter_impressao_config(db, empresa_id: int):
    colunas = colunas_tabela_sqlite(db, "empresas")

    padrao = {
        "impressao_modo": "navegador",
        "impressao_conexao": "navegador",
        "impressao_largura": "80",
        "impressora_nome": "",
        "impressora_ip": "",
        "impressora_porta": 9100,
        "impressora_porta_serial": "",
        "impressora_baud_rate": 9600,
        "impressora_modelo": "",
        "qz_ativo": False,
        "impressao_automatica": False,
        "imprimir_comanda": True,
        "imprimir_recibo": True,
        "imprimir_entregador": False,
    }

    campos = [campo for campo in padrao if campo in colunas]
    if not campos:
        return padrao

    try:
        linha = db.execute(
            text("SELECT " + ", ".join(campos) + " FROM empresas WHERE id = :empresa_id"),
            {"empresa_id": empresa_id}
        ).mappings().first()

        if not linha:
            return padrao

        config = dict(padrao)
        for campo in campos:
            valor = linha.get(campo)
            if campo in {"qz_ativo", "impressao_automatica", "imprimir_comanda", "imprimir_recibo", "imprimir_entregador"}:
                config[campo] = bool(valor)
            elif campo in {"impressora_porta", "impressora_baud_rate"}:
                config[campo] = int(valor or padrao[campo])
            else:
                config[campo] = valor or padrao[campo]

        if config["impressao_modo"] not in IMPRESSAO_MODOS_VALIDOS:
            config["impressao_modo"] = "navegador"
        if config["impressao_conexao"] not in IMPRESSAO_CONEXOES_VALIDAS:
            config["impressao_conexao"] = "navegador"
        if config["impressao_largura"] not in IMPRESSAO_LARGURAS_VALIDAS:
            config["impressao_largura"] = "80"

        return config
    except Exception as erro:
        print("Aviso: erro ao ler configuração de impressão:", erro)
        return padrao


def salvar_impressao_config(db, empresa_id: int, formulario):
    colunas = colunas_tabela_sqlite(db, "empresas")

    modo = str(formulario.get("impressao_modo") or "navegador").strip()
    conexao = str(formulario.get("impressao_conexao") or "navegador").strip()
    largura = str(formulario.get("impressao_largura") or "80").strip().lower()

    if modo not in IMPRESSAO_MODOS_VALIDOS:
        modo = "navegador"
    if conexao not in IMPRESSAO_CONEXOES_VALIDAS:
        conexao = "navegador"
    if largura not in IMPRESSAO_LARGURAS_VALIDAS:
        largura = "80"

    dados = {
        "impressao_modo": modo,
        "impressao_conexao": conexao,
        "impressao_largura": largura,
        "impressora_nome": _texto_curto(formulario.get("impressora_nome"), 160),
        "impressora_ip": _texto_curto(formulario.get("impressora_ip"), 80),
        "impressora_porta": _inteiro_seguro(formulario.get("impressora_porta"), 9100, 1, 65535),
        "impressora_porta_serial": _texto_curto(formulario.get("impressora_porta_serial"), 40),
        "impressora_baud_rate": _inteiro_seguro(formulario.get("impressora_baud_rate"), 9600, 300, 115200),
        "impressora_modelo": _texto_curto(formulario.get("impressora_modelo"), 120),
        "qz_ativo": 1 if _bool_formulario(formulario, "qz_ativo") else 0,
        "impressao_automatica": 1 if _bool_formulario(formulario, "impressao_automatica") else 0,
        "imprimir_comanda": 1 if _bool_formulario(formulario, "imprimir_comanda", True) else 0,
        "imprimir_recibo": 1 if _bool_formulario(formulario, "imprimir_recibo", True) else 0,
        "imprimir_entregador": 1 if _bool_formulario(formulario, "imprimir_entregador") else 0,
        "empresa_id": empresa_id,
    }

    campos = [campo for campo in dados if campo != "empresa_id" and campo in colunas]
    if not campos:
        return

    db.execute(
        text("UPDATE empresas SET " + ", ".join([f"{campo} = :{campo}" for campo in campos]) + " WHERE id = :empresa_id"),
        dados
    )

