def garantir_tabela_menu_configuracoes():
    """Tabela leve para opções do cardápio digital sem depender dos models."""
    try:
        conn = engine.raw_connection()
        cursor = conn.cursor()

        cursor.execute("""
            CREATE TABLE IF NOT EXISTS menu_configuracoes (
                empresa_id INTEGER PRIMARY KEY,
                pedidos_online INTEGER DEFAULT 1,
                retirada INTEGER DEFAULT 1,
                entrega INTEGER DEFAULT 1,
                reservas INTEGER DEFAULT 1,
                modo_mesa INTEGER DEFAULT 1,
                modo_tablet INTEGER DEFAULT 1,
                qtd_mesas INTEGER DEFAULT 10,
                prefixo_mesa TEXT DEFAULT 'Mesa'
            )
        """)

        conn.commit()
        conn.close()
    except Exception as erro:
        print("Aviso: não foi possível garantir menu_configuracoes:", erro)


def obter_menu_configuracoes(db, empresa_id: int):
    garantir_tabela_menu_configuracoes()

    padrao = {
        "pedidos_online": True,
        "retirada": True,
        "entrega": True,
        "reservas": True,
        "modo_mesa": True,
        "modo_tablet": True,
        "qtd_mesas": 10,
        "prefixo_mesa": "Mesa"
    }

    try:
        resultado = db.execute(
            text("SELECT * FROM menu_configuracoes WHERE empresa_id = :empresa_id"),
            {"empresa_id": empresa_id}
        ).mappings().first()

        if not resultado:
            db.execute(
                text("""
                    INSERT OR IGNORE INTO menu_configuracoes
                    (empresa_id, pedidos_online, retirada, entrega, reservas, modo_mesa, modo_tablet, qtd_mesas, prefixo_mesa)
                    VALUES (:empresa_id, 1, 1, 1, 1, 1, 1, 10, 'Mesa')
                """),
                {"empresa_id": empresa_id}
            )
            db.commit()
            return padrao

        return {
            "pedidos_online": bool(resultado["pedidos_online"]),
            "retirada": bool(resultado["retirada"]),
            "entrega": bool(resultado["entrega"]),
            "reservas": bool(resultado["reservas"]),
            "modo_mesa": bool(resultado["modo_mesa"]),
            "modo_tablet": bool(resultado["modo_tablet"]),
            "qtd_mesas": int(resultado["qtd_mesas"] or 10),
            "prefixo_mesa": resultado["prefixo_mesa"] or "Mesa"
        }

    except Exception as erro:
        print("Aviso: erro ao ler menu_configuracoes:", erro)
        return padrao


def salvar_menu_configuracoes(db, empresa_id: int, formulario):
    garantir_tabela_menu_configuracoes()

    def bool_form(nome, padrao="1"):
        return 1 if str(formulario.get(nome, padrao)).strip() == "1" else 0

    try:
        qtd_mesas = int(formulario.get("menu_qtd_mesas") or 10)
    except ValueError:
        qtd_mesas = 10

    qtd_mesas = max(1, min(200, qtd_mesas))
    prefixo_mesa = str(formulario.get("menu_prefixo_mesa") or "Mesa").strip() or "Mesa"

    db.execute(
        text("""
            INSERT INTO menu_configuracoes
            (empresa_id, pedidos_online, retirada, entrega, reservas, modo_mesa, modo_tablet, qtd_mesas, prefixo_mesa)
            VALUES (:empresa_id, :pedidos_online, :retirada, :entrega, :reservas, :modo_mesa, :modo_tablet, :qtd_mesas, :prefixo_mesa)
            ON CONFLICT(empresa_id) DO UPDATE SET
                pedidos_online = excluded.pedidos_online,
                retirada = excluded.retirada,
                entrega = excluded.entrega,
                reservas = excluded.reservas,
                modo_mesa = excluded.modo_mesa,
                modo_tablet = excluded.modo_tablet,
                qtd_mesas = excluded.qtd_mesas,
                prefixo_mesa = excluded.prefixo_mesa
        """),
        {
            "empresa_id": empresa_id,
            "pedidos_online": bool_form("menu_pedidos_online"),
            "retirada": bool_form("menu_retirada"),
            "entrega": bool_form("menu_entrega"),
            "reservas": bool_form("menu_reservas"),
            "modo_mesa": bool_form("menu_modo_mesa"),
            "modo_tablet": bool_form("menu_modo_tablet"),
            "qtd_mesas": qtd_mesas,
            "prefixo_mesa": prefixo_mesa
        }
    )


