APRESENTACAO_ENCOMENDAS_PADRAO = {
    "ativo": False,
    "titulo": "Conheça nossa história",
    "texto": "",
    "foto1_url": "",
    "foto2_url": "",
    "foto3_url": "",
    "botao_texto": "Acessar nosso cardápio",
    "faixa_categorias_ativa": False,
    "faixa_categorias_cor": "",
}


def garantir_tabela_apresentacao_encomendas():
    """Configuração leve da abertura institucional do menu de Encomendas."""
    try:
        conn = engine.raw_connection()
        cursor = conn.cursor()
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS encomendas_apresentacao (
                empresa_id INTEGER PRIMARY KEY,
                ativo INTEGER DEFAULT 0,
                titulo TEXT DEFAULT 'Conheça nossa história',
                texto TEXT DEFAULT '',
                foto1_url TEXT DEFAULT '',
                foto2_url TEXT DEFAULT '',
                foto3_url TEXT DEFAULT '',
                botao_texto TEXT DEFAULT 'Acessar nosso cardápio',
                faixa_categorias_ativa INTEGER DEFAULT 0,
                faixa_categorias_cor TEXT DEFAULT '',
                atualizado_em DATETIME DEFAULT CURRENT_TIMESTAMP
            )
        """)
        cursor.execute("PRAGMA table_info(encomendas_apresentacao)")
        colunas = {str(row[1]) for row in cursor.fetchall()}
        if "faixa_categorias_ativa" not in colunas:
            cursor.execute("ALTER TABLE encomendas_apresentacao ADD COLUMN faixa_categorias_ativa INTEGER DEFAULT 0")
        if "faixa_categorias_cor" not in colunas:
            cursor.execute("ALTER TABLE encomendas_apresentacao ADD COLUMN faixa_categorias_cor TEXT DEFAULT ''")
        conn.commit()
        conn.close()
    except Exception as erro:
        print("Aviso: não foi possível garantir encomendas_apresentacao:", erro)


def obter_apresentacao_encomendas(db, empresa_id: int):
    garantir_tabela_apresentacao_encomendas()
    padrao = dict(APRESENTACAO_ENCOMENDAS_PADRAO)
    try:
        linha = db.execute(
            text("SELECT * FROM encomendas_apresentacao WHERE empresa_id = :empresa_id"),
            {"empresa_id": empresa_id},
        ).mappings().first()
        if not linha:
            return padrao
        return {
            "ativo": bool(linha.get("ativo")),
            "titulo": str(linha.get("titulo") or padrao["titulo"]).strip(),
            "texto": str(linha.get("texto") or "").strip(),
            "foto1_url": str(linha.get("foto1_url") or "").strip(),
            "foto2_url": str(linha.get("foto2_url") or "").strip(),
            "foto3_url": str(linha.get("foto3_url") or "").strip(),
            "botao_texto": str(linha.get("botao_texto") or padrao["botao_texto"]).strip(),
            "faixa_categorias_ativa": bool(linha.get("faixa_categorias_ativa")),
            "faixa_categorias_cor": str(linha.get("faixa_categorias_cor") or "").strip(),
        }
    except Exception as erro:
        print("Aviso: erro ao ler apresentação de Encomendas:", erro)
        return padrao


def salvar_apresentacao_encomendas(db, empresa_id: int, formulario):
    campos = {
        "enc_intro_ativo",
        "enc_intro_titulo",
        "enc_intro_texto",
        "enc_intro_foto1_url",
        "enc_intro_foto2_url",
        "enc_intro_foto3_url",
        "enc_intro_botao_texto",
        "enc_faixa_categorias_ativa",
        "enc_faixa_categorias_cor",
    }
    if not any(campo in formulario for campo in campos):
        return

    garantir_tabela_apresentacao_encomendas()

    titulo = str(formulario.get("enc_intro_titulo") or "Conheça nossa história").strip()[:140]
    texto_apresentacao = str(formulario.get("enc_intro_texto") or "").strip()[:2500]
    foto1 = str(formulario.get("enc_intro_foto1_url") or "").strip()[:1000]
    foto2 = str(formulario.get("enc_intro_foto2_url") or "").strip()[:1000]
    foto3 = str(formulario.get("enc_intro_foto3_url") or "").strip()[:1000]
    botao = str(formulario.get("enc_intro_botao_texto") or "Acessar nosso cardápio").strip()[:80]
    ativo = 1 if "enc_intro_ativo" in formulario else 0
    faixa_ativa = 1 if "enc_faixa_categorias_ativa" in formulario else 0
    faixa_cor = str(formulario.get("enc_faixa_categorias_cor") or "").strip().upper()
    if not re.fullmatch(r"#[0-9A-F]{6}", faixa_cor):
        faixa_cor = ""

    db.execute(
        text("""
            INSERT INTO encomendas_apresentacao
            (empresa_id, ativo, titulo, texto, foto1_url, foto2_url, foto3_url, botao_texto, faixa_categorias_ativa, faixa_categorias_cor, atualizado_em)
            VALUES (:empresa_id, :ativo, :titulo, :texto, :foto1_url, :foto2_url, :foto3_url, :botao_texto, :faixa_categorias_ativa, :faixa_categorias_cor, CURRENT_TIMESTAMP)
            ON CONFLICT(empresa_id) DO UPDATE SET
                ativo = excluded.ativo,
                titulo = excluded.titulo,
                texto = excluded.texto,
                foto1_url = excluded.foto1_url,
                foto2_url = excluded.foto2_url,
                foto3_url = excluded.foto3_url,
                botao_texto = excluded.botao_texto,
                faixa_categorias_ativa = excluded.faixa_categorias_ativa,
                faixa_categorias_cor = excluded.faixa_categorias_cor,
                atualizado_em = CURRENT_TIMESTAMP
        """),
        {
            "empresa_id": empresa_id,
            "ativo": ativo,
            "titulo": titulo or "Conheça nossa história",
            "texto": texto_apresentacao,
            "foto1_url": foto1,
            "foto2_url": foto2,
            "foto3_url": foto3,
            "botao_texto": botao or "Acessar nosso cardápio",
            "faixa_categorias_ativa": faixa_ativa,
            "faixa_categorias_cor": faixa_cor,
        },
    )



def garantir_colunas_banco_antigo():
    """Garante compatibilidade do banco SQLite antigo com colunas novas."""
    try:
        conn = engine.raw_connection()
        cursor = conn.cursor()

        def add_coluna(tabela, coluna, sql_coluna):
            cursor.execute(f"PRAGMA table_info({tabela})")
            colunas = [linha[1] for linha in cursor.fetchall()]

            if coluna not in colunas:
                cursor.execute(f"ALTER TABLE {tabela} ADD COLUMN {sql_coluna}")
                print(f"Coluna criada: {tabela}.{coluna}")

        add_coluna("empresas", "capacidade_maxima", "capacidade_maxima INTEGER DEFAULT 0")
        add_coluna("horarios_reserva", "capacidade_maxima", "capacidade_maxima INTEGER DEFAULT 0")
        add_coluna("horarios_reserva", "profissional_id", "profissional_id INTEGER")
        add_coluna("reservas", "profissional_id", "profissional_id INTEGER")
        add_coluna("reservas", "horario_id", "horario_id INTEGER")

        conn.commit()
        conn.close()

    except Exception as erro:
        print("AVISO: não foi possível verificar/criar colunas do banco antigo:", repr(erro))


garantir_colunas_banco_antigo()



