# ==================================================
# HELPERS — APARÊNCIA DO MENU PÚBLICO
# ==================================================

COR_MENU_PADRAO = "#1236B5"
COR_FUNDO_MENU_PADRAO = "#F5F7FB"

def normalizar_cor_hex_menu(valor, padrao=COR_MENU_PADRAO):
    texto = str(valor or "").strip().upper()
    if re.fullmatch(r"#[0-9A-F]{6}", texto):
        return texto
    return padrao

def dados_cor_menu(valor, padrao=COR_MENU_PADRAO):
    cor = normalizar_cor_hex_menu(valor, padrao)
    vermelho = int(cor[1:3], 16)
    verde = int(cor[3:5], 16)
    azul = int(cor[5:7], 16)
    # Contraste simples e previsível para botões e elementos preenchidos.
    luminancia = (0.299 * vermelho) + (0.587 * verde) + (0.114 * azul)
    texto = "#111827" if luminancia >= 174 else "#FFFFFF"
    return cor, f"{vermelho}, {verde}, {azul}", texto

def anexar_hero_empresa(db, empresa):
    """
    Lê campos extras da tabela empresas mesmo que o modelo SQLAlchemy antigo
    ainda não tenha esses atributos mapeados.
    """
    if not empresa:
        return

    try:
        colunas = colunas_tabela_sqlite(db, "empresas")
    except Exception:
        colunas = set()

    if not {"hero_titulo", "hero_subtitulo", "hero_imagem_url"}.intersection(colunas):
        setattr(empresa, "hero_titulo", "")
        setattr(empresa, "hero_subtitulo", "")
        setattr(empresa, "hero_imagem_url", "")
        setattr(empresa, "hero_pos_x", 50)
        setattr(empresa, "hero_pos_y", 50)
        setattr(empresa, "hero_zoom", 100)
        setattr(empresa, "hero_overlay", 100)
        setattr(empresa, "hero_fit_mode", "contain")
        setattr(empresa, "hero_pos_x_mobile", 50)
        setattr(empresa, "hero_pos_y_mobile", 50)
        setattr(empresa, "hero_zoom_mobile", 100)
        setattr(empresa, "hero_fit_mode_mobile", "contain")
        cor, cor_rgb, cor_texto = dados_cor_menu(COR_MENU_PADRAO)
        setattr(empresa, "menu_cor_principal", cor)
        setattr(empresa, "menu_cor_rgb", cor_rgb)
        setattr(empresa, "menu_cor_texto", cor_texto)
        cor_fundo, cor_fundo_rgb, _ = dados_cor_menu(COR_FUNDO_MENU_PADRAO, COR_FUNDO_MENU_PADRAO)
        setattr(empresa, "menu_cor_fundo", cor_fundo)
        setattr(empresa, "menu_cor_fundo_rgb", cor_fundo_rgb)
        return

    try:
        linha = db.execute(
            text("""
                SELECT
                    hero_titulo,
                    hero_subtitulo,
                    hero_imagem_url,
                    hero_pos_x,
                    hero_pos_y,
                    hero_zoom,
                    hero_overlay,
                    hero_fit_mode,
                    hero_pos_x_mobile,
                    hero_pos_y_mobile,
                    hero_zoom_mobile,
                    hero_fit_mode_mobile,
                    menu_cor_principal,
                    menu_cor_fundo
                FROM empresas
                WHERE id = :empresa_id
            """),
            {"empresa_id": empresa.id}
        ).mappings().first()

        def inteiro_limitado(valor, padrao, minimo, maximo):
            try:
                numero = int(float(valor))
            except (TypeError, ValueError):
                numero = padrao
            return max(minimo, min(maximo, numero))

        setattr(empresa, "hero_titulo", (linha or {}).get("hero_titulo", "") or "")
        setattr(empresa, "hero_subtitulo", (linha or {}).get("hero_subtitulo", "") or "")
        setattr(empresa, "hero_imagem_url", (linha or {}).get("hero_imagem_url", "") or "")
        setattr(empresa, "hero_pos_x", inteiro_limitado((linha or {}).get("hero_pos_x"), 50, 0, 100))
        setattr(empresa, "hero_pos_y", inteiro_limitado((linha or {}).get("hero_pos_y"), 50, 0, 100))
        setattr(empresa, "hero_zoom", inteiro_limitado((linha or {}).get("hero_zoom"), 100, 60, 400))
        setattr(empresa, "hero_overlay", inteiro_limitado((linha or {}).get("hero_overlay"), 100, 0, 300))
        hero_fit_mode = str((linha or {}).get("hero_fit_mode", "contain") or "contain").strip().lower()
        hero_fit_mode = hero_fit_mode if hero_fit_mode in {"contain", "cover", "stretch"} else "contain"
        setattr(empresa, "hero_fit_mode", hero_fit_mode)
        setattr(empresa, "hero_pos_x_mobile", inteiro_limitado((linha or {}).get("hero_pos_x_mobile"), empresa.hero_pos_x, 0, 100))
        setattr(empresa, "hero_pos_y_mobile", inteiro_limitado((linha or {}).get("hero_pos_y_mobile"), empresa.hero_pos_y, 0, 100))
        setattr(empresa, "hero_zoom_mobile", inteiro_limitado((linha or {}).get("hero_zoom_mobile"), empresa.hero_zoom, 60, 400))
        hero_fit_mode_mobile = str((linha or {}).get("hero_fit_mode_mobile") or hero_fit_mode).strip().lower()
        setattr(empresa, "hero_fit_mode_mobile", hero_fit_mode_mobile if hero_fit_mode_mobile in {"contain", "cover", "stretch"} else hero_fit_mode)
        cor, cor_rgb, cor_texto = dados_cor_menu((linha or {}).get("menu_cor_principal"))
        setattr(empresa, "menu_cor_principal", cor)
        setattr(empresa, "menu_cor_rgb", cor_rgb)
        setattr(empresa, "menu_cor_texto", cor_texto)
        cor_fundo, cor_fundo_rgb, _ = dados_cor_menu((linha or {}).get("menu_cor_fundo"), COR_FUNDO_MENU_PADRAO)
        setattr(empresa, "menu_cor_fundo", cor_fundo)
        setattr(empresa, "menu_cor_fundo_rgb", cor_fundo_rgb)

    except Exception:
        setattr(empresa, "hero_titulo", "")
        setattr(empresa, "hero_subtitulo", "")
        setattr(empresa, "hero_imagem_url", "")
        setattr(empresa, "hero_pos_x", 50)
        setattr(empresa, "hero_pos_y", 50)
        setattr(empresa, "hero_zoom", 100)
        setattr(empresa, "hero_overlay", 100)
        setattr(empresa, "hero_fit_mode", "contain")
        setattr(empresa, "hero_pos_x_mobile", 50)
        setattr(empresa, "hero_pos_y_mobile", 50)
        setattr(empresa, "hero_zoom_mobile", 100)
        setattr(empresa, "hero_fit_mode_mobile", "contain")
        cor, cor_rgb, cor_texto = dados_cor_menu(COR_MENU_PADRAO)
        setattr(empresa, "menu_cor_principal", cor)
        setattr(empresa, "menu_cor_rgb", cor_rgb)
        setattr(empresa, "menu_cor_texto", cor_texto)
        cor_fundo, cor_fundo_rgb, _ = dados_cor_menu(COR_FUNDO_MENU_PADRAO, COR_FUNDO_MENU_PADRAO)
        setattr(empresa, "menu_cor_fundo", cor_fundo)
        setattr(empresa, "menu_cor_fundo_rgb", cor_fundo_rgb)


def salvar_hero_empresa_sqlite(db, empresa_id: int, formulario):
    colunas = colunas_tabela_sqlite(db, "empresas")
    updates = []
    params = {"empresa_id": empresa_id}

    if "hero_titulo" in colunas:
        updates.append("hero_titulo = :hero_titulo")
        params["hero_titulo"] = str(formulario.get("hero_titulo", "")).strip()

    if "hero_subtitulo" in colunas:
        updates.append("hero_subtitulo = :hero_subtitulo")
        params["hero_subtitulo"] = str(formulario.get("hero_subtitulo", "")).strip()

    if "hero_imagem_url" in colunas:
        updates.append("hero_imagem_url = :hero_imagem_url")
        params["hero_imagem_url"] = str(formulario.get("hero_imagem_url", "")).strip()

    def inteiro_formulario(nome, padrao, minimo, maximo):
        try:
            numero = int(float(formulario.get(nome, padrao)))
        except (TypeError, ValueError):
            numero = padrao
        return max(minimo, min(maximo, numero))

    if "hero_pos_x" in colunas:
        updates.append("hero_pos_x = :hero_pos_x")
        params["hero_pos_x"] = inteiro_formulario("hero_pos_x", 50, 0, 100)

    if "hero_pos_y" in colunas:
        updates.append("hero_pos_y = :hero_pos_y")
        params["hero_pos_y"] = inteiro_formulario("hero_pos_y", 50, 0, 100)

    if "hero_zoom" in colunas:
        updates.append("hero_zoom = :hero_zoom")
        params["hero_zoom"] = inteiro_formulario("hero_zoom", 100, 60, 400)

    if "hero_overlay" in colunas:
        updates.append("hero_overlay = :hero_overlay")
        params["hero_overlay"] = inteiro_formulario("hero_overlay", 100, 0, 300)

    if "hero_fit_mode" in colunas:
        updates.append("hero_fit_mode = :hero_fit_mode")
        hero_fit_mode = str(formulario.get("hero_fit_mode", "contain") or "contain").strip().lower()
        params["hero_fit_mode"] = hero_fit_mode if hero_fit_mode in {"contain", "cover", "stretch"} else "contain"

    if "hero_pos_x_mobile" in colunas:
        updates.append("hero_pos_x_mobile = :hero_pos_x_mobile")
        params["hero_pos_x_mobile"] = inteiro_formulario("hero_pos_x_mobile", params.get("hero_pos_x", 50), 0, 100)

    if "hero_pos_y_mobile" in colunas:
        updates.append("hero_pos_y_mobile = :hero_pos_y_mobile")
        params["hero_pos_y_mobile"] = inteiro_formulario("hero_pos_y_mobile", params.get("hero_pos_y", 50), 0, 100)

    if "hero_zoom_mobile" in colunas:
        updates.append("hero_zoom_mobile = :hero_zoom_mobile")
        params["hero_zoom_mobile"] = inteiro_formulario("hero_zoom_mobile", params.get("hero_zoom", 100), 60, 400)

    if "hero_fit_mode_mobile" in colunas:
        updates.append("hero_fit_mode_mobile = :hero_fit_mode_mobile")
        hero_fit_mode_mobile = str(formulario.get("hero_fit_mode_mobile", params.get("hero_fit_mode", "contain")) or "contain").strip().lower()
        params["hero_fit_mode_mobile"] = hero_fit_mode_mobile if hero_fit_mode_mobile in {"contain", "cover", "stretch"} else params.get("hero_fit_mode", "contain")

    if "menu_cor_principal" in colunas:
        updates.append("menu_cor_principal = :menu_cor_principal")
        params["menu_cor_principal"] = normalizar_cor_hex_menu(formulario.get("menu_cor_principal"))

    if "menu_cor_fundo" in colunas:
        updates.append("menu_cor_fundo = :menu_cor_fundo")
        params["menu_cor_fundo"] = normalizar_cor_hex_menu(formulario.get("menu_cor_fundo"), COR_FUNDO_MENU_PADRAO)

    if updates:
        db.execute(
            text("UPDATE empresas SET " + ", ".join(updates) + " WHERE id = :empresa_id"),
            params
        )



