def colunas_tabela_sqlite(db, tabela: str):
    try:
        return {
            linha[1]
            for linha in db.execute(text(f"PRAGMA table_info({tabela})")).fetchall()
        }
    except Exception:
        return set()


def normalizar_fotos_item_payload(payload: dict):
    """Mantém até cinco fotos, preservando a foto antiga como capa quando necessário."""
    dados = dict(payload or {})
    fotos = []
    bruto = dados.get("fotos_json")
    if isinstance(bruto, list):
        fotos = bruto
    elif isinstance(bruto, str) and bruto.strip():
        try:
            parsed = json.loads(bruto)
            if isinstance(parsed, list):
                fotos = parsed
        except (TypeError, ValueError, json.JSONDecodeError):
            fotos = []

    capa_informada = dados.get("foto_url") if "foto_url" in dados else None
    candidatos = []
    if capa_informada is not None:
        candidatos.append(capa_informada)
    candidatos.extend(fotos)

    resultado = []
    vistos = set()
    for valor in candidatos:
        url = str(valor or "").strip()
        if not url or url in vistos:
            continue
        vistos.add(url)
        resultado.append(url)
        if len(resultado) == 5:
            break

    # Só interfere na galeria quando o formulário enviou algum dos campos de foto.
    if "foto_url" in dados or "fotos_json" in dados:
        dados["foto_url"] = resultado[0] if resultado else None
        dados["fotos_json"] = json.dumps(resultado, ensure_ascii=False)
    return dados


def dados_item_para_modelo(payload: dict):
    payload = normalizar_fotos_item_payload(payload)
    colunas_modelo = {coluna.name for coluna in Item.__table__.columns}
    return {
        campo: valor
        for campo, valor in payload.items()
        if campo in colunas_modelo
    }


def salvar_codigo_item_sqlite(db, item_id: int, payload: dict):
    colunas = colunas_tabela_sqlite(db, "itens")

    if "codigo_produto" not in colunas:
        return

    db.execute(
        text("UPDATE itens SET codigo_produto = :codigo WHERE id = :item_id"),
        {
            "codigo": payload.get("codigo_produto") or "",
            "item_id": item_id
        }
    )


def anexar_codigo_itens_cardapio(db, itens):
    colunas = colunas_tabela_sqlite(db, "itens")

    if "codigo_produto" not in colunas:
        for item in itens:
            setattr(item, "codigo_produto", "")
        return

    linhas = db.execute(
        text("SELECT id, codigo_produto FROM itens")
    ).mappings().all()

    mapa = {
        linha["id"]: (linha.get("codigo_produto") or "")
        for linha in linhas
    }

    for item in itens:
        setattr(item, "codigo_produto", mapa.get(item.id, ""))



