# FUNÇÕES FISCAIS / IVA
# ==================================================

def moeda(valor) -> Decimal:
    return Decimal(str(valor or 0)).quantize(
        Decimal("0.01"),
        rounding=ROUND_HALF_UP
    )


def calcular_iva_preco_final(
    preco_final: float,
    quantidade: int,
    empresa_usa_iva: bool,
    item_aplica_iva: bool,
    aliquota: float | None
):
    """
    O cliente continua vendo o preço final.
    Internamente, o sistema separa:
    - base sem IVA
    - valor IVA
    - total final
    """
    preco_final_unitario = moeda(preco_final)
    qtd = Decimal(str(quantidade or 0))
    total_final = moeda(preco_final_unitario * qtd)

    aliquota_decimal = Decimal(str(aliquota or 0))

    if not empresa_usa_iva or not item_aplica_iva or aliquota_decimal <= 0:
        return {
            "preco_unitario_final": float(preco_final_unitario),
            "preco_unitario_sem_iva": float(preco_final_unitario),
            "subtotal_final": float(total_final),
            "subtotal_sem_iva": float(total_final),
            "valor_iva": 0.0,
            "aliquota_iva": 0.0,
            "aplica_iva": False
        }

    fator = Decimal("1") + (aliquota_decimal / Decimal("100"))
    preco_unitario_sem_iva = moeda(preco_final_unitario / fator)
    subtotal_sem_iva = moeda(total_final / fator)
    valor_iva = moeda(total_final - subtotal_sem_iva)

    return {
        "preco_unitario_final": float(preco_final_unitario),
        "preco_unitario_sem_iva": float(preco_unitario_sem_iva),
        "subtotal_final": float(total_final),
        "subtotal_sem_iva": float(subtotal_sem_iva),
        "valor_iva": float(valor_iva),
        "aliquota_iva": float(aliquota_decimal),
        "aplica_iva": True
    }






