def v156_obter_aliquota_padrao_empresa(db, empresa, tipo_item: str | None = None):
    """Retorna alíquota padrão de produto/serviço com fallback seguro."""
    tipo = (tipo_item or "").strip().lower()

    padrao_produto = float(getattr(empresa, "aliquota_iva_padrao", 0) or 0)
    padrao_servico = padrao_produto

    try:
        colunas = colunas_tabela_sqlite(db, "empresas")
        if "aliquota_iva_servicos" in colunas:
            linha = db.execute(
                text("SELECT aliquota_iva_servicos FROM empresas WHERE id = :empresa_id"),
                {"empresa_id": empresa.id}
            ).mappings().first()

            if linha is not None and linha.get("aliquota_iva_servicos") is not None:
                padrao_servico = float(linha.get("aliquota_iva_servicos") or 0)
    except Exception:
        padrao_servico = padrao_produto

    if tipo in {"servico", "serviço", "service", "agendamento"}:
        return padrao_servico

    return padrao_produto



def v156_salvar_aliquota_servicos_sqlite(db, empresa_id: int, formulario):
    colunas = colunas_tabela_sqlite(db, "empresas")

    if "aliquota_iva_servicos" not in colunas:
        return

    try:
        valor = float(str(formulario.get("aliquota_iva_servicos", 0) or 0).replace(",", "."))
    except Exception:
        valor = 0

    db.execute(
        text("UPDATE empresas SET aliquota_iva_servicos = :valor WHERE id = :empresa_id"),
        {"valor": valor, "empresa_id": empresa_id}
    )

def v156_anexar_aliquota_servicos(db, empresa):
    if not empresa:
        return

    try:
        colunas = colunas_tabela_sqlite(db, "empresas")
        if "aliquota_iva_servicos" not in colunas:
            setattr(empresa, "aliquota_iva_servicos", 0)
            return

        linha = db.execute(
            text("SELECT aliquota_iva_servicos FROM empresas WHERE id = :empresa_id"),
            {"empresa_id": empresa.id}
        ).mappings().first()

        setattr(empresa, "aliquota_iva_servicos", (linha or {}).get("aliquota_iva_servicos", 0) or 0)
    except Exception:
        setattr(empresa, "aliquota_iva_servicos", 0)


