# AUTENTICAÇÃO ADMINISTRATIVA
# ==================================================

def gerar_hash_senha(senha: str) -> str:
    salt = secrets.token_bytes(16)
    digest = hashlib.pbkdf2_hmac(
        "sha256",
        senha.encode("utf-8"),
        salt,
        200_000
    )
    return (
        base64.urlsafe_b64encode(salt).decode("utf-8")
        + "$"
        + base64.urlsafe_b64encode(digest).decode("utf-8")
    )


def validar_senha(senha: str, senha_hash: str) -> bool:
    try:
        salt_b64, digest_b64 = senha_hash.split("$", 1)
        salt = base64.urlsafe_b64decode(salt_b64.encode("utf-8"))
        digest_esperado = base64.urlsafe_b64decode(digest_b64.encode("utf-8"))

        digest = hashlib.pbkdf2_hmac(
            "sha256",
            senha.encode("utf-8"),
            salt,
            200_000
        )

        return hmac.compare_digest(digest, digest_esperado)
    except Exception:
        return False



# ==================================================
# SEGURANÇA DE LOGIN — LIMITE DE TENTATIVAS
# ==================================================
# Proteção leve em memória contra força bruta.
# Não muda banco e não altera usuários existentes.
LOGIN_MAX_TENTATIVAS = int(os.getenv("LOGIN_MAX_TENTATIVAS", "5"))
LOGIN_BLOQUEIO_MINUTOS = int(os.getenv("LOGIN_BLOQUEIO_MINUTOS", "15"))

_login_tentativas = defaultdict(lambda: {"qtd": 0, "bloqueado_ate": None})
_saas_login_tentativas = defaultdict(lambda: {"qtd": 0, "bloqueado_ate": None})


def _ip_cliente(request: Request) -> str:
    forwarded = request.headers.get("x-forwarded-for", "")
    if forwarded:
        return forwarded.split(",")[0].strip()
    return request.client.host if request.client else "desconhecido"


def _chave_login(request: Request, email: str, prefixo: str = "admin") -> str:
    email_normalizado = (email or "").strip().lower()
    return f"{prefixo}:{_ip_cliente(request)}:{email_normalizado}"


def _login_bloqueado(store, chave: str):
    info = store[chave]
    bloqueado_ate = info.get("bloqueado_ate")
    if bloqueado_ate and datetime.utcnow() < bloqueado_ate:
        minutos = max(1, int((bloqueado_ate - datetime.utcnow()).total_seconds() // 60) + 1)
        return True, minutos

    if bloqueado_ate and datetime.utcnow() >= bloqueado_ate:
        store.pop(chave, None)

    return False, 0


def _registrar_login_falhou(store, chave: str):
    info = store[chave]
    info["qtd"] = int(info.get("qtd") or 0) + 1

    if info["qtd"] >= LOGIN_MAX_TENTATIVAS:
        info["bloqueado_ate"] = datetime.utcnow() + timedelta(minutes=LOGIN_BLOQUEIO_MINUTOS)

    store[chave] = info


def _limpar_tentativas_login(store, chave: str):
    store.pop(chave, None)


def senha_saas_owner_valida(senha: str) -> bool:
    """
    Preferência segura:
    - SAAS_OWNER_PASSWORD_HASH com o mesmo formato de gerar_hash_senha().
    Compatibilidade:
    - SAAS_OWNER_PASSWORD continua funcionando para não quebrar instalação atual.
    """
    senha = senha or ""
    if SAAS_OWNER_PASSWORD_HASH:
        return validar_senha(senha, SAAS_OWNER_PASSWORD_HASH)

    return bool(SAAS_OWNER_PASSWORD) and hmac.compare_digest(senha, SAAS_OWNER_PASSWORD)

def empresa_admin_sessao(request: Request) -> int | None:
    empresa_id = request.session.get("empresa_id")
    try:
        return int(empresa_id) if empresa_id is not None else None
    except (TypeError, ValueError):
        return None


def redirecionar_login_se_necessario(request: Request, empresa_id: int):
    empresa_sessao = empresa_admin_sessao(request)

    if empresa_sessao != empresa_id:
        return RedirectResponse(
            url="/login",
            status_code=303
        )

    db = SessionLocal()

    empresa = db.query(Empresa).filter(
        Empresa.id == empresa_id
    ).first()

    if empresa and plano_empresa_bloqueado(empresa) and not request.session.get("saas_owner"):
        db.close()
        return RedirectResponse(
            url=f"/empresa-bloqueada/{empresa_id}",
            status_code=303
        )

    db.close()

    if request.session.get("troca_senha_obrigatoria"):
        caminho_atual = request.url.path.rstrip("/")
        caminhos_liberados = {
            f"/admin/{empresa_id}",
            f"/admin/{empresa_id}/perfil-atualizar",
            "/logout",
        }
        if caminho_atual not in caminhos_liberados:
            return RedirectResponse(
                url=f"/admin/{empresa_id}?perfil=troca_obrigatoria",
                status_code=303
            )

    return None


