def garantir_colunas_cargo_funcionario():
    """Adiciona campos visuais de cargo/ícone sem exigir migração manual."""
    try:
        with engine.begin() as conn:
            colunas = {row[1] for row in conn.execute(text("PRAGMA table_info(usuario_admin)")).fetchall()}
            # Compatibilidade com nomes de tabela comuns do SQLAlchemy.
            if not colunas:
                colunas = {row[1] for row in conn.execute(text("PRAGMA table_info(usuarios_admin)")).fetchall()}
                tabela = "usuarios_admin"
            else:
                tabela = "usuario_admin"

            if not colunas:
                return

            if "cargo_nome" not in colunas:
                conn.execute(text(f"ALTER TABLE {tabela} ADD COLUMN cargo_nome VARCHAR(80)"))
            if "cargo_icone" not in colunas:
                conn.execute(text(f"ALTER TABLE {tabela} ADD COLUMN cargo_icone VARCHAR(50)"))
    except Exception as exc:
        print("[FUNCIONARIOS] Não foi possível garantir colunas de cargo:", exc)


def normalizar_cargo_nome(valor: str, perfil: str) -> str:
    valor = re.sub(r"\s+", " ", (valor or "").strip())[:80]
    return valor or label_perfil_funcionario(perfil)


def normalizar_cargo_icone(valor: str) -> str:
    valor = (valor or "").strip().replace("fa-solid ", "")
    return valor if valor in FUNCIONARIO_ICONES_PERMITIDOS else "fa-user"


def tabela_usuario_admin():
    try:
        with engine.connect() as conn:
            if conn.execute(text("SELECT name FROM sqlite_master WHERE type='table' AND name='usuario_admin'")).first():
                return "usuario_admin"
    except Exception:
        pass
    return "usuarios_admin"


def ler_cargos_funcionarios(empresa_id: int) -> dict:
    garantir_colunas_cargo_funcionario()
    tabela = tabela_usuario_admin()
    try:
        with engine.connect() as conn:
            linhas = conn.execute(
                text(f"SELECT id, cargo_nome, cargo_icone FROM {tabela} WHERE empresa_id = :empresa_id"),
                {"empresa_id": empresa_id},
            ).mappings().all()
            return {int(linha["id"]): dict(linha) for linha in linhas}
    except Exception:
        return {}


def salvar_cargo_funcionario(usuario_id: int, cargo_nome: str, cargo_icone: str):
    garantir_colunas_cargo_funcionario()
    tabela = tabela_usuario_admin()
    try:
        with engine.begin() as conn:
            conn.execute(
                text(f"""
                    UPDATE {tabela}
                    SET cargo_nome = :cargo_nome, cargo_icone = :cargo_icone
                    WHERE id = :usuario_id
                """),
                {
                    "cargo_nome": cargo_nome,
                    "cargo_icone": cargo_icone,
                    "usuario_id": usuario_id,
                },
            )
    except Exception as exc:
        print("[FUNCIONARIOS] Erro ao salvar cargo/ícone:", exc)


def limpar_permissoes(permissoes) -> set[str]:
    if permissoes is None:
        return set()
    if isinstance(permissoes, str):
        bruto = permissoes.replace(";", ",").split(",")
    else:
        bruto = list(permissoes)
    return {str(item).strip() for item in bruto if str(item).strip() in PERMISSOES_FUNCIONARIOS}


def serializar_permissoes(permissoes) -> str:
    permissoes_limpas = limpar_permissoes(permissoes)
    return ",".join([chave for chave in PERMISSOES_FUNCIONARIOS if chave in permissoes_limpas])


def permissoes_padrao_para_perfil(perfil: str) -> set[str]:
    perfil = normalizar_perfil_funcionario(perfil)
    if perfil == "administrador":
        return set(PERMISSOES_FUNCIONARIOS.keys())
    return set(PERMISSOES_PADRAO_FUNCIONARIO)


def permissoes_do_usuario(usuario) -> set[str]:
    perfil = normalizar_perfil_funcionario(getattr(usuario, "perfil", "atendente"))
    if perfil == "administrador":
        return set(PERMISSOES_FUNCIONARIOS.keys())
    return limpar_permissoes(getattr(usuario, "permissoes", ""))


def perfil_admin_sessao(request: Request) -> str:
    return normalizar_perfil_funcionario(
        str(request.session.get("admin_perfil", "administrador"))
    )


def sessao_admin_total(request: Request) -> bool:
    return perfil_admin_sessao(request) == "administrador"


def permissoes_admin_sessao(request: Request) -> set[str]:
    if sessao_admin_total(request):
        return set(PERMISSOES_FUNCIONARIOS.keys())
    return limpar_permissoes(request.session.get("admin_permissoes", ""))


def permissao_admin_sessao(request: Request, area: str) -> bool:
    if sessao_admin_total(request):
        return True
    return area in permissoes_admin_sessao(request)


def primeira_area_permitida(request: Request) -> str:
    for area in ORDEM_AREA_INICIAL:
        if permissao_admin_sessao(request, area):
            return area
    return "dashboard"


def url_area_admin(empresa_id: int, area: str) -> str:
    caminhos = {
        "dashboard": "",
        "cardapio": "/cardapio",
        "produtos": "/produtos-pedidos",
        "pedidos": "/pedidos",
        "reservas": "/reservas",
        "financeiro": "/financeiro",
        "fiscal": "/fiscal",
        "pagamentos_online": "/pagamentos-online",
        "entrega_politicas": "/entrega-politicas",
        "configuracoes": "/configuracoes",
        "funcionarios": "/funcionarios",
        "integracoes": "/integracoes",
        "menu_publico": "/menu-publico",
    }
    return f"/admin/{empresa_id}{caminhos.get(area, '')}"


def redirecionar_area_admin_se_necessario(request: Request, empresa_id: int, area: str):
    redirecionamento = redirecionar_login_se_necessario(request, empresa_id)
    if redirecionamento:
        return redirecionamento

    if request.session.get("troca_senha_obrigatoria") and area != "dashboard":
        return RedirectResponse(
            url=f"/admin/{empresa_id}?perfil=troca_obrigatoria",
            status_code=303
        )

    if permissao_admin_sessao(request, area):
        return None

    destino = primeira_area_permitida(request)
    return RedirectResponse(
        url=f"{url_area_admin(empresa_id, destino)}?status=sem_permissao",
        status_code=303
    )


templates.env.globals["perfil_admin_sessao"] = perfil_admin_sessao
templates.env.globals["permissoes_admin_sessao"] = permissoes_admin_sessao
templates.env.globals["permissao_admin_sessao"] = permissao_admin_sessao


def usuario_admin_sessao(request: Request) -> int | None:
    usuario_id = request.session.get("admin_user_id")
    try:
        return int(usuario_id) if usuario_id is not None else None
    except (TypeError, ValueError):
        return None


def usuario_eh_admin_principal(usuario: UsuarioAdmin | None) -> bool:
    return (getattr(usuario, "perfil", None) or "administrador") == "administrador"


def exigir_admin_principal_ou_redirecionar(request: Request, empresa_id: int):
    redirecionamento = redirecionar_login_se_necessario(request, empresa_id)
    if redirecionamento:
        return redirecionamento

    db = SessionLocal()
    usuario = db.query(UsuarioAdmin).filter(
        UsuarioAdmin.id == usuario_admin_sessao(request),
        UsuarioAdmin.empresa_id == empresa_id,
        UsuarioAdmin.ativo == True
    ).first()
    perfil = getattr(usuario, "perfil", "administrador") if usuario else ""
    db.close()

    if perfil != "administrador":
        return RedirectResponse(
            url=f"/admin/{empresa_id}?status=sem_permissao",
            status_code=303
        )

    return None


def exigir_admin_empresa_api(request: Request, empresa_id: int, area: str | None = None):
    empresa_sessao = empresa_admin_sessao(request)

    if empresa_sessao != empresa_id:
        raise HTTPException(
            status_code=401,
            detail="Faça login para acessar esta empresa."
        )

    if request.session.get("troca_senha_obrigatoria"):
        raise HTTPException(
            status_code=403,
            detail="Defina uma nova senha antes de continuar."
        )

    if area and not sessao_admin_total(request) and not permissao_admin_sessao(request, area):
        raise HTTPException(
            status_code=403,
            detail="Você não possui permissão para este módulo."
        )

    db = SessionLocal()

    empresa = db.query(Empresa).filter(
        Empresa.id == empresa_id
    ).first()

    if empresa and plano_empresa_bloqueado(empresa) and not request.session.get("saas_owner"):
        db.close()
        raise HTTPException(
            status_code=403,
            detail="Sistema bloqueado. Entre em contato com o suporte para reativar."
        )

    db.close()


def exigir_admin_logado_api(request: Request):
    if empresa_admin_sessao(request) is None:
        raise HTTPException(
            status_code=401,
            detail="Faça login para continuar."
        )


