def _push_no_store(payload: dict, status_code: int = 200) -> JSONResponse:
    return JSONResponse(
        payload,
        status_code=status_code,
        headers={"Cache-Control": "no-store, no-cache, must-revalidate"},
    )


@app.get("/admin/{empresa_id}/push/config", include_in_schema=False)
def configurar_push_pwa(empresa_id: int, request: Request):
    exigir_admin_empresa_api(request, empresa_id)
    usuario_id = usuario_admin_sessao(request)
    if usuario_id is None:
        raise HTTPException(status_code=401, detail="Faça login novamente.")
    runtime = push_runtime_status()
    queue = push_queue_status(empresa_id=empresa_id)
    return _push_no_store({
        "ready": bool(runtime.get("ready")),
        "dependency_ready": bool(runtime.get("dependency_ready")),
        "key_ready": bool(runtime.get("key_ready")),
        "public_key": str(runtime.get("public_key") or ""),
        "subscriptions": subscription_count(
            empresa_id=empresa_id,
            usuario_admin_id=usuario_id,
        ),
        "devices": list_push_devices(
            empresa_id=empresa_id,
            usuario_admin_id=usuario_id,
        ),
        "queue": queue,
        "worker_interval_seconds": 30,
        "external_worker": runtime.get("external_worker") or {},
    })


@app.post("/admin/{empresa_id}/push/subscribe", include_in_schema=False)
async def assinar_push_pwa(empresa_id: int, request: Request):
    exigir_admin_empresa_api(request, empresa_id)
    usuario_id = usuario_admin_sessao(request)
    if usuario_id is None:
        raise HTTPException(status_code=401, detail="Faça login novamente.")
    try:
        payload = await request.json()
        if not isinstance(payload, dict):
            raise ValueError("Assinatura inválida.")
        row = save_subscription(
            empresa_id=empresa_id,
            usuario_admin_id=usuario_id,
            subscription=payload,
            user_agent=request.headers.get("user-agent", ""),
        )
        reminders = {"queued": 0, "duplicate": 0, "skipped": 0}
        deliveries = {"sent": 0, "failed": 0, "removed": 0, "expired": 0}
        # Quando o próprio service worker recupera uma assinatura rotacionada
        # enquanto o app está fechado, reconciliamos também os lembretes futuros.
        if bool(payload.get("mf_reconcile")):
            reminders = schedule_upcoming_reservation_reminders(empresa_id=empresa_id)
            encomenda_reminders = schedule_upcoming_encomenda_reminders(empresa_id=empresa_id)
            for key in ("queued", "duplicate", "skipped"):
                reminders[key] = int(reminders.get(key, 0)) + int(encomenda_reminders.get(key, 0))
            reminders["encomendas_24h_queued"] = int(encomenda_reminders.get("queued", 0))
            deliveries = process_due_push_deliveries(limit=80)
    except ValueError as exc:
        return _push_no_store({"ok": False, "detail": str(exc)}, status_code=400)
    return _push_no_store({
        "ok": True,
        "subscription_id": row.id,
        "subscriptions": subscription_count(empresa_id=empresa_id, usuario_admin_id=usuario_id),
        "reminders": reminders,
        "deliveries": deliveries,
    })


@app.post("/admin/{empresa_id}/push/unsubscribe", include_in_schema=False)
async def cancelar_push_pwa(empresa_id: int, request: Request):
    exigir_admin_empresa_api(request, empresa_id)
    usuario_id = usuario_admin_sessao(request)
    if usuario_id is None:
        raise HTTPException(status_code=401, detail="Faça login novamente.")
    payload = await request.json()
    endpoint = str((payload or {}).get("endpoint") or "").strip()
    if not endpoint:
        return _push_no_store({"ok": False, "detail": "Endpoint ausente."}, status_code=400)
    removed = remove_subscription(
        empresa_id=empresa_id,
        usuario_admin_id=usuario_id,
        endpoint=endpoint,
    )
    return _push_no_store({"ok": True, "removed": bool(removed)})


