@app.post("/admin/{empresa_id}/push/displayed", include_in_schema=False)
async def confirmar_push_exibido(empresa_id: int, request: Request):
    """Confirmação de fundo enviada pelo service worker após exibir o alerta.

    Não depende da sessão do painel: com o PWA fechado o service worker pode
    não ter uma sessão administrativa utilizável. O endpoint Push informado é
    conferido no banco e precisa pertencer à empresa recebida na rota.
    """
    try:
        payload = await request.json()
        if not isinstance(payload, dict):
            payload = {}
    except Exception:
        payload = {}
    result = acknowledge_push_displayed(
        empresa_id=empresa_id,
        endpoint=str((payload or {}).get("endpoint") or ""),
        delivery_id=(payload or {}).get("delivery_id"),
        event_type=str((payload or {}).get("event") or ""),
        tag=str((payload or {}).get("tag") or ""),
        stage=str((payload or {}).get("stage") or "shown"),
        test_id=str((payload or {}).get("test_id") or ""),
        worker_version=str((payload or {}).get("worker_version") or ""),
        client_at=str((payload or {}).get("client_at") or ""),
        visible_count=(payload or {}).get("visible_count"),
    )
    return _push_no_store(result, status_code=200 if result.get("ok") else 400)


