def normalizar_tipo_negocio(tipo: str) -> str:
    tipo = (tipo or "").strip().lower()
    tipo = tipo.replace("á", "a").replace("à", "a").replace("ã", "a").replace("â", "a")
    tipo = tipo.replace("é", "e").replace("ê", "e")
    tipo = tipo.replace("í", "i")
    tipo = tipo.replace("ó", "o").replace("ô", "o").replace("õ", "o")
    tipo = tipo.replace("ú", "u")
    tipo = tipo.replace("ç", "c")
    tipo = re.sub(r"[^a-z0-9]+", "_", tipo).strip("_")
    return tipo


def tipo_negocio_servico(tipo: str) -> bool:
    tipo_normalizado = normalizar_tipo_negocio(tipo)
    return tipo_normalizado in TIPOS_SERVICO


def tipo_negocio_produto(tipo: str) -> bool:
    return normalizar_tipo_negocio(tipo) in TIPOS_PRODUTO


def tipo_negocio_encomenda(tipo: str) -> bool:
    return normalizar_tipo_negocio(tipo) in TIPOS_ENCOMENDA


def template_menu_publico(tipo: str) -> str:
    if tipo_negocio_encomenda(tipo):
        return "menu_encomendas.html"
    if tipo_negocio_servico(tipo):
        return "menu_servicos.html"
    if tipo_negocio_produto(tipo):
        return "menu_produtos.html"
    return "menu_pedidos.html"


def tipo_negocio_pedido(tipo: str) -> bool:
    tipo_normalizado = normalizar_tipo_negocio(tipo)
    if tipo_normalizado in TIPOS_ENCOMENDA:
        return False
    if tipo_normalizado in TIPOS_PEDIDO or tipo_normalizado in TIPOS_PRODUTO:
        return True

    # Padrão seguro: se não for serviço conhecido, mantém o fluxo tradicional.
    return not tipo_negocio_servico(tipo_normalizado)


def tipo_negocio_entrega(tipo: str) -> bool:
    """Retorna True para qualquer menu que receba pedidos com entrega/retirada.

    Inclui restaurante/comida e loja/produtos. Menus exclusivamente de
    serviços/agendamento continuam sem configuração de frete.
    """
    return tipo_negocio_pedido(tipo) or tipo_negocio_produto(tipo) or tipo_negocio_encomenda(tipo)


