def _carregar_json_empresa(valor, padrao):
    resultado = json.loads(json.dumps(padrao, ensure_ascii=False))
    if not valor:
        return resultado
    try:
        salvo = json.loads(valor)
    except (TypeError, ValueError, json.JSONDecodeError):
        return resultado
    if isinstance(salvo, dict):
        for chave, conteudo in salvo.items():
            if isinstance(conteudo, dict) and isinstance(resultado.get(chave), dict):
                resultado[chave].update(conteudo)
            else:
                resultado[chave] = conteudo
    return resultado


def obter_entrega_config_empresa(empresa):
    config = _carregar_json_empresa(
        getattr(empresa, "entrega_config_json", None),
        ENTREGA_CONFIG_PADRAO,
    )
    for campo in ("entrega_ativa", "retirada_ativa"):
        config[campo] = bool(config.get(campo, ENTREGA_CONFIG_PADRAO[campo]))
    for campo in ("pedido_minimo_entrega", "frete_gratis_acima"):
        try:
            config[campo] = float(moeda(config.get(campo, 0)))
        except Exception:
            config[campo] = 0.0
    for campo in ("regioes_atendidas", "mensagem_entrega", "instrucoes_retirada"):
        config[campo] = str(config.get(campo) or "").strip()
    # Centraliza validação e compatibilidade do frete de produtos.
    try:
        config = normalize_shipping_config(config)
    except ShippingQuoteError:
        # Dados antigos ou incompletos nunca derrubam o menu público.
        config = normalize_shipping_config(ENTREGA_CONFIG_PADRAO)
    return config


def obter_politicas_loja_empresa(empresa):
    config = _carregar_json_empresa(
        getattr(empresa, "politicas_loja_json", None),
        {tipo: {"ativa": dados["ativa"], "pt": "", "it": "", "en": ""}
         for tipo, dados in POLITICAS_LOJA_PADRAO.items()},
    )
    for tipo in POLITICAS_LOJA_PADRAO:
        bloco = config.setdefault(tipo, {})
        bloco["ativa"] = bool(bloco.get("ativa", True))
        for idioma in ("pt", "it", "en"):
            bloco[idioma] = str(bloco.get(idioma) or "").strip()
    return config

