def calcular_cotacao_frete_produtos(empresa, subtotal, cep_destino):
    """Calcula no servidor o mesmo frete exibido no checkout público."""
    if not tipo_negocio_entrega(getattr(empresa, "tipo", "")):
        raise ShippingQuoteError("O cálculo de entrega não está disponível para este tipo de negócio.")
    config = obter_entrega_config_empresa(empresa)
    return quote_shipping(
        config=config,
        subtotal=subtotal,
        destination_cep=cep_destino,
        fixed_fee=getattr(empresa, "taxa_entrega_padrao", 0),
        origin_cep_fallback=getattr(empresa, "cep_fiscal", "") or "",
    )


@app.get("/api/publico/{slug}/frete/cotacao")
def cotar_frete_publico_produtos(slug: str, cep: str, subtotal: float = 0):
    db = SessionLocal()
    try:
        empresa = db.query(Empresa).filter(Empresa.slug == slug).first()
        if not empresa:
            return JSONResponse({"error": "Empresa não encontrada."}, status_code=404)
        if not tipo_negocio_entrega(empresa.tipo):
            return JSONResponse(
                {"error": "Este menu não utiliza cálculo automático de entrega."},
                status_code=400,
            )
        try:
            cotacao = calcular_cotacao_frete_produtos(empresa, subtotal, cep)
        except ShippingQuoteError as erro:
            return JSONResponse({"error": str(erro)}, status_code=422)
        return cotacao
    finally:
        db.close()


