def plano_empresa_bloqueado(empresa) -> bool:
    """Bloqueio manual real, controlado pelo dono do SaaS."""
    empresa_id = getattr(empresa, "id", None)
    if not empresa_id:
        return False
    try:
        with engine.connect() as conexao:
            valor = conexao.execute(text("""
                SELECT bloquear_acesso_painel
                FROM saas_empresa_controles
                WHERE empresa_id = :empresa_id
            """), {"empresa_id": int(empresa_id)}).scalar()
        return bool(valor)
    except Exception:
        # Em instalação ainda não migrada, preserva o acesso em vez de bloquear por engano.
        return False


def _normalizar_identificador_publico(valor) -> str:
    texto = unicodedata.normalize("NFKD", str(valor or ""))
    texto = "".join(ch for ch in texto if not unicodedata.combining(ch))
    return re.sub(r"[^a-z0-9]+", " ", texto.lower()).strip()


def plano_empresa_vencido(empresa) -> bool:
    """
    Vencido serve apenas para aviso visual.
    """
    status = (getattr(empresa, "plano_status", "") or "").lower().strip()

    if status == "vencido":
        return True

    vencimento = getattr(empresa, "assinatura_vencimento", None)

    if vencimento and status not in ["bloqueado", "cancelado"]:
        return vencimento.date() < agora_brasilia().date()

    return False


def plano_dias_restantes_empresa(empresa):
    vencimento = getattr(empresa, "assinatura_vencimento", None)
    if not vencimento:
        return None
    return (vencimento.date() - agora_brasilia().date()).days


def plano_status_texto_empresa(empresa) -> str:
    status = (getattr(empresa, "plano_status", "") or "ativo").lower().strip()
    dias = plano_dias_restantes_empresa(empresa)

    if status == "bloqueado":
        return "Bloqueado"
    if status == "cancelado":
        return "Cancelado"
    if status == "vencido" or (dias is not None and dias < 0):
        return "Vencido"

    if dias is not None and dias <= 3:
        idioma = idioma_empresa(empresa)

        if idioma == "it":
            return f"Quasi scaduto · {max(dias, 0)} giorno/i"

        if idioma == "en":
            return f"Almost expired · {max(dias, 0)} day(s)"

        return f"Quase vencendo · {max(dias, 0)} dia(s)"

    if status == "teste":
        if dias is None:
            return "Teste grátis"
        return f"Teste grátis · {dias} dia(s)"

    # Para empresas ativas, mostramos apenas "Ativo".
    # Os dias aparecem somente em teste grátis ou quando estiver quase vencendo.
    return "Ativo"


def plano_status_classe_empresa(empresa) -> str:
    status = (getattr(empresa, "plano_status", "") or "ativo").lower().strip()
    dias = plano_dias_restantes_empresa(empresa)

    if status in ["bloqueado", "cancelado", "vencido"] or (dias is not None and dias < 0):
        return "plan-pill--danger"
    if dias is not None and dias <= 3:
        return "plan-pill--warning"
    if status == "teste":
        return "plan-pill--trial"
    return "plan-pill--active"


templates.env.globals["plano_status_texto_empresa"] = plano_status_texto_empresa
templates.env.globals["plano_status_classe_empresa"] = plano_status_classe_empresa
templates.env.globals["plano_dias_restantes_empresa"] = plano_dias_restantes_empresa


