@app.post("/contratar")
async def realizar_contratacao(request: Request):
    formulario = await request.form()

    empresa_nome = str(formulario.get("empresa_nome", "")).strip()
    empresa_tipo = str(formulario.get("empresa_tipo", "restaurante")).strip() or "restaurante"
    telefone_whatsapp = str(formulario.get("telefone_whatsapp", "")).strip()
    email_empresa = str(formulario.get("email_empresa", "")).strip().lower()
    endereco = str(formulario.get("endereco", "")).strip()
    cidade = str(formulario.get("cidade", "")).strip()
    pais = str(formulario.get("pais", "Italia")).strip() or "Italia"
    idioma = normalizar_idioma(formulario.get("idioma_principal") or formulario.get("idioma") or "pt")

    admin_nome = str(formulario.get("admin_nome", "")).strip()
    admin_email = str(formulario.get("admin_email", "")).strip().lower()
    admin_senha = str(formulario.get("admin_senha", ""))
    confirmar_senha = str(formulario.get("confirmar_senha", ""))

    dados = {
        "empresa_nome": empresa_nome,
        "empresa_tipo": empresa_tipo,
        "telefone_whatsapp": telefone_whatsapp,
        "email_empresa": email_empresa,
        "endereco": endereco,
        "cidade": cidade,
        "pais": pais,
        "idioma": idioma,
        "idioma_principal": idioma,
        "admin_nome": admin_nome,
        "admin_email": admin_email,
    }

    def erro_contratacao(mensagem: str, status_code: int = 400):
        return templates.TemplateResponse(
            request=request,
            name="contratar.html",
            context={
                "erro": mensagem,
                "dados": dados,
                "preco_plano": "25.99"
            },
            status_code=status_code
        )

    if not empresa_nome or not telefone_whatsapp or not admin_nome or not admin_email or not admin_senha:
        return erro_contratacao("Preencha empresa, WhatsApp, nome, e-mail e senha.")

    if len(admin_senha) < 8:
        return erro_contratacao("A senha precisa ter pelo menos 8 caracteres.")

    if admin_senha != confirmar_senha:
        return erro_contratacao("As senhas não coincidem.")

    # Plano único do MenuFacile no Brasil. Mantido no código para não herdar
    # valores antigos de ambientes europeus preservados no servidor.
    valor_plano = 25.99

    db = SessionLocal()

    email_existente = db.query(UsuarioAdmin).filter(
        UsuarioAdmin.email == admin_email
    ).first()

    if email_existente:
        db.close()
        return erro_contratacao("Este e-mail já está cadastrado.")

    slug_base = slugify_simples(empresa_nome)
    slug_final = slug_base or "negocio"
    contador = 2

    while db.query(Empresa).filter(Empresa.slug == slug_final).first():
        slug_final = f"{slug_base}-{contador}"
        contador += 1

    empresa = Empresa(
        nome=empresa_nome,
        slug=slug_final,
        tipo=empresa_tipo,
        telefone_whatsapp=telefone_whatsapp,
        email=email_empresa or None,
        endereco=endereco or None,
        cidade=cidade or None,
        pais=pais,
        aceita_pedidos_online=True,
        aceita_agendamentos=not tipo_negocio_encomenda(empresa_tipo),
        ativo=True,
        plano_nome="Plano Completo",
        plano_status="teste",
        plano_valor_mensal=valor_plano,
        assinatura_inicio=agora_brasilia(),
        assinatura_vencimento=agora_brasilia() + timedelta(days=10),
        onboarding_concluido=False,
        onboarding_estado="pendente"
    )

    db.add(empresa)
    db.flush()
    salvar_idioma_empresa_sql(db, empresa, idioma)

    usuario = UsuarioAdmin(
        empresa_id=empresa.id,
        nome=admin_nome,
        email=admin_email,
        senha_hash=gerar_hash_senha(admin_senha),
        perfil="administrador",
        permissoes="",
        ativo=True
    )

    db.add(usuario)
    db.commit()

    request.session["admin_user_id"] = usuario.id
    request.session["empresa_id"] = empresa.id
    request.session["idioma_empresa"] = "pt"
    request.session["admin_perfil"] = "administrador"
    request.session["admin_permissoes"] = serializar_permissoes(set(PERMISSOES_FUNCIONARIOS.keys()))

    empresa_id = empresa.id
    db.close()

    return RedirectResponse(
        url=f"/admin/{empresa_id}",
        status_code=303
    )




