@app.post("/login")
async def realizar_login(request: Request):
    formulario = await request.form()

    email = str(formulario.get("email", "")).strip().lower()
    senha = str(formulario.get("senha", ""))

    chave_login = _chave_login(request, email, "admin")
    bloqueado, minutos = _login_bloqueado(_login_tentativas, chave_login)

    if bloqueado:
        return templates.TemplateResponse(
            request=request,
            name="login.html",
            context={
                "erro": f"Muitas tentativas incorretas. Tente novamente em {minutos} minuto(s)."
            },
            status_code=429
        )

    db = SessionLocal()

    usuario = db.query(UsuarioAdmin).filter(
        UsuarioAdmin.email == email,
        UsuarioAdmin.ativo == True
    ).first()

    if not usuario or not validar_senha(senha, usuario.senha_hash):
        db.close()
        _registrar_login_falhou(_login_tentativas, chave_login)
        return templates.TemplateResponse(
            request=request,
            name="login.html",
            context={
                "erro": "E-mail ou senha inválidos."
            },
            status_code=401
        )

    _limpar_tentativas_login(_login_tentativas, chave_login)

    request.session["admin_user_id"] = usuario.id
    request.session["empresa_id"] = usuario.empresa_id
    request.session["admin_perfil"] = getattr(usuario, "perfil", "administrador") or "administrador"
    request.session["admin_permissoes"] = serializar_permissoes(permissoes_do_usuario(usuario))
    request.session["admin_nome"] = usuario.nome or "Equipe"

    empresa_id = usuario.empresa_id
    troca_obrigatoria = usuario_requer_troca_senha_saas(usuario.id)
    request.session["troca_senha_obrigatoria"] = bool(troca_obrigatoria)
    ip_cliente = request.client.host if request.client else ""
    registrar_ultimo_acesso_saas(usuario.id, empresa_id, ip_cliente)

    db.close()

    if troca_obrigatoria:
        destino = f"/admin/{empresa_id}?perfil=troca_obrigatoria"
    else:
        destino = url_area_admin(empresa_id, primeira_area_permitida(request))

    return RedirectResponse(
        url=destino,
        status_code=303
    )


