@app.post("/cadastro")
async def realizar_cadastro(request: Request):
    formulario = await request.form()

    nome = str(formulario.get("nome", "")).strip()
    email = str(formulario.get("email", "")).strip().lower()
    senha = str(formulario.get("senha", ""))
    confirmar_senha = str(formulario.get("confirmar_senha", ""))
    modo_empresa = str(formulario.get("modo_empresa", "nova"))

    empresa_nome = str(formulario.get("empresa_nome", "")).strip()
    empresa_slug = str(formulario.get("empresa_slug", "")).strip().lower()
    empresa_tipo = str(formulario.get("empresa_tipo", "restaurante")).strip() or "restaurante"

    empresa_existente_id = str(formulario.get("empresa_existente_id", "")).strip()

    db = SessionLocal()

    empresas_com_admin = db.query(UsuarioAdmin.empresa_id).subquery()

    empresas_sem_admin = db.query(Empresa).filter(
        ~Empresa.id.in_(empresas_com_admin)
    ).order_by(Empresa.id.asc()).all()

    if not nome or not email or not senha:
        db.close()
        return templates.TemplateResponse(
            request=request,
            name="cadastro.html",
            context={
                "erro": "Preencha nome, e-mail e senha.",
                "empresas_sem_admin": empresas_sem_admin
            },
            status_code=400
        )

    if len(senha) < 8:
        db.close()
        return templates.TemplateResponse(
            request=request,
            name="cadastro.html",
            context={
                "erro": "A senha precisa ter pelo menos 8 caracteres.",
                "empresas_sem_admin": empresas_sem_admin
            },
            status_code=400
        )

    if senha != confirmar_senha:
        db.close()
        return templates.TemplateResponse(
            request=request,
            name="cadastro.html",
            context={
                "erro": "As senhas não coincidem.",
                "empresas_sem_admin": empresas_sem_admin
            },
            status_code=400
        )

    email_existente = db.query(UsuarioAdmin).filter(
        UsuarioAdmin.email == email
    ).first()

    if email_existente:
        db.close()
        return templates.TemplateResponse(
            request=request,
            name="cadastro.html",
            context={
                "erro": "Este e-mail já está cadastrado.",
                "empresas_sem_admin": empresas_sem_admin
            },
            status_code=400
        )

    empresa = None

    if modo_empresa == "existente" and empresa_existente_id:
        try:
            empresa_id_int = int(empresa_existente_id)
        except ValueError:
            empresa_id_int = 0

        empresa = db.query(Empresa).filter(
            Empresa.id == empresa_id_int
        ).first()

        empresa_ja_reivindicada = db.query(UsuarioAdmin).filter(
            UsuarioAdmin.empresa_id == empresa_id_int
        ).first()

        if not empresa or empresa_ja_reivindicada:
            db.close()
            return templates.TemplateResponse(
                request=request,
                name="cadastro.html",
                context={
                    "erro": "Empresa existente indisponível para vínculo.",
                    "empresas_sem_admin": empresas_sem_admin
                },
                status_code=400
            )
    else:
        if not empresa_nome or not empresa_slug:
            db.close()
            return templates.TemplateResponse(
                request=request,
                name="cadastro.html",
                context={
                    "erro": "Informe o nome e o slug da nova empresa.",
                    "empresas_sem_admin": empresas_sem_admin
                },
                status_code=400
            )

        slug_existente = db.query(Empresa).filter(
            Empresa.slug == empresa_slug
        ).first()

        if slug_existente:
            db.close()
            return templates.TemplateResponse(
                request=request,
                name="cadastro.html",
                context={
                    "erro": "Este slug já está em uso.",
                    "empresas_sem_admin": empresas_sem_admin
                },
                status_code=400
            )

        empresa = Empresa(
            nome=empresa_nome,
            slug=empresa_slug,
            tipo=empresa_tipo,
            pais="Italia",
            aceita_pedidos_online=True,
            aceita_agendamentos=not tipo_negocio_encomenda(empresa_tipo),
            ativo=True,

            # Plano único pago do SaaS
            plano_nome="Plano Completo",
            plano_status="ativo",
            plano_valor_mensal=0,
            assinatura_inicio=agora_brasilia(),
            assinatura_vencimento=agora_brasilia() + timedelta(days=30),
            onboarding_concluido=False,
            onboarding_estado="pendente"
        )

        db.add(empresa)
        db.flush()

    usuario = UsuarioAdmin(
        empresa_id=empresa.id,
        nome=nome,
        email=email,
        senha_hash=gerar_hash_senha(senha),
        ativo=True
    )

    db.add(usuario)
    db.commit()

    request.session["admin_user_id"] = usuario.id
    request.session["empresa_id"] = empresa.id

    empresa_id = empresa.id

    db.close()

    return RedirectResponse(
        url=f"/admin/{empresa_id}",
        status_code=303
    )






