SAAS_OWNER_SETTINGS_PATH = PROJECT_ROOT / ".saas_owner_settings.json"


def _carregar_configuracoes_owner_saas() -> dict:
    try:
        if SAAS_OWNER_SETTINGS_PATH.is_file():
            dados = json.loads(SAAS_OWNER_SETTINGS_PATH.read_text(encoding="utf-8"))
            if isinstance(dados, dict):
                return dados
    except Exception as erro:
        LOGGER.warning("Não foi possível carregar as configurações do dono do SaaS: %r", erro)
    return {}


def _salvar_configuracoes_owner_saas(dados: dict) -> None:
    SAAS_OWNER_SETTINGS_PATH.parent.mkdir(parents=True, exist_ok=True)
    temporario = SAAS_OWNER_SETTINGS_PATH.with_suffix(".json.tmp")
    temporario.write_text(
        json.dumps(dados, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    try:
        os.chmod(temporario, 0o600)
    except OSError:
        pass
    os.replace(temporario, SAAS_OWNER_SETTINGS_PATH)
    try:
        os.chmod(SAAS_OWNER_SETTINGS_PATH, 0o600)
    except OSError:
        pass


def _sincronizar_env_owner_saas(dados: dict) -> None:
    env_path = PROJECT_ROOT / ".env"
    valores = {
        "SAAS_OWNER_NAME": str(dados.get("owner_name") or ""),
        "SAAS_OWNER_EMAIL": str(dados.get("owner_email") or ""),
        "SAAS_OWNER_PHONE": str(dados.get("owner_phone") or ""),
        "SAAS_SUPPORT_WHATSAPP": str(dados.get("support_whatsapp") or ""),
        "SAAS_SUPPORT_EMAIL": str(dados.get("support_email") or ""),
        "SAAS_SUPPORT_HOURS": str(dados.get("support_hours") or ""),
        "SAAS_SUPPORT_MESSAGE": str(dados.get("support_message") or ""),
    }
    if dados.get("owner_password_hash"):
        valores["SAAS_OWNER_PASSWORD_HASH"] = str(dados["owner_password_hash"])

    linhas = env_path.read_text(encoding="utf-8").splitlines() if env_path.is_file() else []
    indices = {}
    for indice, linha in enumerate(linhas):
        encontrado = re.match(r"^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=", linha)
        if encontrado and encontrado.group(1) not in indices:
            indices[encontrado.group(1)] = indice

    for chave, valor in valores.items():
        linha_nova = f"{chave}={json.dumps(valor, ensure_ascii=False)}"
        if chave in indices:
            linhas[indices[chave]] = linha_nova
        else:
            linhas.append(linha_nova)

    temporario = env_path.with_suffix(".env.tmp")
    temporario.write_text("\n".join(linhas).rstrip() + "\n", encoding="utf-8")
    os.replace(temporario, env_path)


