# V365 — CONTROLE COMERCIAL, LIMITES E SEGURANÇA SAAS
# ==================================================

SAAS_LIMITE_FUNCIONARIOS_PADRAO = 3
SAAS_LIMITE_PROFISSIONAIS_PADRAO = 10


def _agora_saas_texto() -> str:
    return agora_brasilia().strftime("%Y-%m-%d %H:%M:%S")


def _formatar_data_saas(valor) -> str:
    if not valor:
        return "Nunca"
    if isinstance(valor, datetime):
        return valor.strftime("%d/%m/%Y às %H:%M")
    texto_data = str(valor).strip().replace("T", " ")
    try:
        return datetime.fromisoformat(texto_data).strftime("%d/%m/%Y às %H:%M")
    except ValueError:
        return texto_data


def preparar_controle_saas_v365() -> None:
    """Cria as tabelas auxiliares sem alterar os models existentes."""
    with engine.begin() as conexao:
        conexao.execute(text("""
            CREATE TABLE IF NOT EXISTS saas_empresa_controles (
                empresa_id INTEGER PRIMARY KEY,
                limite_funcionarios INTEGER NOT NULL DEFAULT 3,
                limite_profissionais INTEGER NOT NULL DEFAULT 10,
                funcionarios_ilimitados INTEGER NOT NULL DEFAULT 0,
                profissionais_ilimitados INTEGER NOT NULL DEFAULT 0,
                bloquear_novos_funcionarios INTEGER NOT NULL DEFAULT 0,
                bloquear_novos_profissionais INTEGER NOT NULL DEFAULT 0,
                bloquear_acesso_painel INTEGER NOT NULL DEFAULT 0,
                atualizado_em TEXT
            )
        """))
        colunas_controle = {str(item[1]) for item in conexao.execute(text("PRAGMA table_info(saas_empresa_controles)")).fetchall()}
        if "bloquear_acesso_painel" not in colunas_controle:
            conexao.execute(text("ALTER TABLE saas_empresa_controles ADD COLUMN bloquear_acesso_painel INTEGER NOT NULL DEFAULT 0"))
        conexao.execute(text("""
            CREATE TABLE IF NOT EXISTS saas_usuario_seguranca (
                usuario_id INTEGER PRIMARY KEY,
                empresa_id INTEGER NOT NULL,
                forcar_troca_senha INTEGER NOT NULL DEFAULT 0,
                ultimo_acesso TEXT,
                ultimo_ip TEXT,
                atualizado_em TEXT
            )
        """))
        conexao.execute(text("""
            CREATE TABLE IF NOT EXISTS saas_admin_atividades (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                empresa_id INTEGER,
                usuario_id INTEGER,
                acao TEXT NOT NULL,
                detalhes TEXT,
                criado_em TEXT NOT NULL
            )
        """))
        conexao.execute(text("CREATE INDEX IF NOT EXISTS idx_saas_atividade_empresa ON saas_admin_atividades (empresa_id, id DESC)"))
        conexao.execute(text("CREATE INDEX IF NOT EXISTS idx_saas_seguranca_empresa ON saas_usuario_seguranca (empresa_id)"))
        conexao.execute(text("""
            INSERT OR IGNORE INTO saas_empresa_controles (
                empresa_id, limite_funcionarios, limite_profissionais,
                funcionarios_ilimitados, profissionais_ilimitados,
                bloquear_novos_funcionarios, bloquear_novos_profissionais,
                bloquear_acesso_painel, atualizado_em
            )
            SELECT id, :limite_funcionarios, :limite_profissionais, 0, 0, 0, 0, 0, :agora
            FROM empresas
        """), {
            "limite_funcionarios": SAAS_LIMITE_FUNCIONARIOS_PADRAO,
            "limite_profissionais": SAAS_LIMITE_PROFISSIONAIS_PADRAO,
            "agora": _agora_saas_texto(),
        })
        conexao.execute(text("""
            INSERT OR IGNORE INTO saas_usuario_seguranca (
                usuario_id, empresa_id, forcar_troca_senha, atualizado_em
            )
            SELECT id, empresa_id, 0, :agora FROM usuarios_admin
        """), {"agora": _agora_saas_texto()})


def garantir_controle_saas_empresa(empresa_id: int) -> None:
    with engine.begin() as conexao:
        conexao.execute(text("""
            INSERT OR IGNORE INTO saas_empresa_controles (
                empresa_id, limite_funcionarios, limite_profissionais,
                funcionarios_ilimitados, profissionais_ilimitados,
                bloquear_novos_funcionarios, bloquear_novos_profissionais,
                bloquear_acesso_painel, atualizado_em
            ) VALUES (
                :empresa_id, :limite_funcionarios, :limite_profissionais,
                0, 0, 0, 0, 0, :agora
            )
        """), {
            "empresa_id": int(empresa_id),
            "limite_funcionarios": SAAS_LIMITE_FUNCIONARIOS_PADRAO,
            "limite_profissionais": SAAS_LIMITE_PROFISSIONAIS_PADRAO,
            "agora": _agora_saas_texto(),
        })


def obter_controles_saas_empresa(db, empresa_id: int) -> dict:
    registro = db.execute(text("""
        SELECT limite_funcionarios, limite_profissionais,
               funcionarios_ilimitados, profissionais_ilimitados,
               bloquear_novos_funcionarios, bloquear_novos_profissionais,
               bloquear_acesso_painel, atualizado_em
        FROM saas_empresa_controles
        WHERE empresa_id = :empresa_id
    """), {"empresa_id": int(empresa_id)}).mappings().first()
    registro = dict(registro or {})
    return {
        "limite_funcionarios": max(0, int(registro.get("limite_funcionarios") or 0)),
        "limite_profissionais": max(0, int(registro.get("limite_profissionais") or 0)),
        "funcionarios_ilimitados": bool(registro.get("funcionarios_ilimitados")),
        "profissionais_ilimitados": bool(registro.get("profissionais_ilimitados")),
        "bloquear_novos_funcionarios": bool(registro.get("bloquear_novos_funcionarios")),
        "bloquear_novos_profissionais": bool(registro.get("bloquear_novos_profissionais")),
        "bloquear_acesso_painel": bool(registro.get("bloquear_acesso_painel")),
        "atualizado_em": registro.get("atualizado_em"),
    }


def contar_funcionarios_saas(db, empresa_id: int) -> int:
    """O primeiro acesso da empresa é o dono e não consome vaga de funcionário."""
    usuario_principal_id = db.query(func.min(UsuarioAdmin.id)).filter(
        UsuarioAdmin.empresa_id == empresa_id
    ).scalar()
    consulta = db.query(UsuarioAdmin).filter(
        UsuarioAdmin.empresa_id == empresa_id,
        UsuarioAdmin.ativo == True,
    )
    if usuario_principal_id is not None:
        consulta = consulta.filter(UsuarioAdmin.id != usuario_principal_id)
    return int(consulta.count() or 0)


def contar_profissionais_saas(db, empresa_id: int) -> int:
    return int(db.query(Profissional).filter(
        Profissional.empresa_id == empresa_id,
        Profissional.ativo == True,
    ).count() or 0)


def validar_novo_funcionario_saas(db, empresa_id: int):
    controle = obter_controles_saas_empresa(db, empresa_id)
    uso = contar_funcionarios_saas(db, empresa_id)
    if controle["bloquear_novos_funcionarios"]:
        return False, "Novos funcionários estão bloqueados pelo administrador do MenuFacile.", 403
    if not controle["funcionarios_ilimitados"] and uso >= controle["limite_funcionarios"]:
        return False, f"Limite de funcionários atingido ({uso}/{controle['limite_funcionarios']}).", 409
    return True, "", 200


def validar_novo_profissional_saas(db, empresa_id: int):
    controle = obter_controles_saas_empresa(db, empresa_id)
    uso = contar_profissionais_saas(db, empresa_id)
    if controle["bloquear_novos_profissionais"]:
        return False, "Novos profissionais estão bloqueados pelo administrador do MenuFacile.", 403
    if not controle["profissionais_ilimitados"] and uso >= controle["limite_profissionais"]:
        return False, f"Limite de profissionais atingido ({uso}/{controle['limite_profissionais']}).", 409
    return True, "", 200


def registrar_atividade_saas(empresa_id: int | None, acao: str, detalhes: str = "", usuario_id: int | None = None) -> None:
    try:
        with engine.begin() as conexao:
            conexao.execute(text("""
                INSERT INTO saas_admin_atividades (empresa_id, usuario_id, acao, detalhes, criado_em)
                VALUES (:empresa_id, :usuario_id, :acao, :detalhes, :criado_em)
            """), {
                "empresa_id": int(empresa_id) if empresa_id is not None else None,
                "usuario_id": int(usuario_id) if usuario_id is not None else None,
                "acao": str(acao or "Ação administrativa")[:120],
                "detalhes": str(detalhes or "")[:700],
                "criado_em": _agora_saas_texto(),
            })
    except Exception as erro:
        LOGGER.warning("Não foi possível registrar atividade do SaaS: %r", erro)


def listar_atividades_saas(db, empresa_id: int, limite: int = 8) -> list[dict]:
    registros = db.execute(text("""
        SELECT id, usuario_id, acao, detalhes, criado_em
        FROM saas_admin_atividades
        WHERE empresa_id = :empresa_id
        ORDER BY id DESC
        LIMIT :limite
    """), {"empresa_id": int(empresa_id), "limite": max(1, min(int(limite), 30))}).mappings().all()
    return [
        {
            "id": int(item["id"]),
            "usuario_id": item.get("usuario_id"),
            "acao": item.get("acao") or "Ação administrativa",
            "detalhes": item.get("detalhes") or "",
            "criado_em": item.get("criado_em"),
            "criado_em_formatado": _formatar_data_saas(item.get("criado_em")),
        }
        for item in registros
    ]


def obter_seguranca_usuario_saas(db, usuario_id: int | None, empresa_id: int) -> dict:
    if not usuario_id:
        return {"forcar_troca_senha": False, "ultimo_acesso": None, "ultimo_acesso_formatado": "Nunca", "ultimo_ip": ""}
    registro = db.execute(text("""
        SELECT forcar_troca_senha, ultimo_acesso, ultimo_ip
        FROM saas_usuario_seguranca
        WHERE usuario_id = :usuario_id
    """), {"usuario_id": int(usuario_id)}).mappings().first()
    registro = dict(registro or {})
    return {
        "forcar_troca_senha": bool(registro.get("forcar_troca_senha")),
        "ultimo_acesso": registro.get("ultimo_acesso"),
        "ultimo_acesso_formatado": _formatar_data_saas(registro.get("ultimo_acesso")),
        "ultimo_ip": registro.get("ultimo_ip") or "",
    }


def definir_troca_senha_obrigatoria_saas(usuario_id: int, empresa_id: int, obrigatoria: bool) -> None:
    with engine.begin() as conexao:
        conexao.execute(text("""
            INSERT OR IGNORE INTO saas_usuario_seguranca (
                usuario_id, empresa_id, forcar_troca_senha, atualizado_em
            ) VALUES (:usuario_id, :empresa_id, 0, :agora)
        """), {
            "usuario_id": int(usuario_id),
            "empresa_id": int(empresa_id),
            "agora": _agora_saas_texto(),
        })
        conexao.execute(text("""
            UPDATE saas_usuario_seguranca
            SET empresa_id = :empresa_id,
                forcar_troca_senha = :obrigatoria,
                atualizado_em = :agora
            WHERE usuario_id = :usuario_id
        """), {
            "usuario_id": int(usuario_id),
            "empresa_id": int(empresa_id),
            "obrigatoria": 1 if obrigatoria else 0,
            "agora": _agora_saas_texto(),
        })


def usuario_requer_troca_senha_saas(usuario_id: int) -> bool:
    with engine.connect() as conexao:
        valor = conexao.execute(text("""
            SELECT forcar_troca_senha FROM saas_usuario_seguranca WHERE usuario_id = :usuario_id
        """), {"usuario_id": int(usuario_id)}).scalar()
    return bool(valor)


def registrar_ultimo_acesso_saas(usuario_id: int, empresa_id: int, ip: str = "") -> None:
    agora = _agora_saas_texto()
    with engine.begin() as conexao:
        conexao.execute(text("""
            INSERT OR IGNORE INTO saas_usuario_seguranca (
                usuario_id, empresa_id, forcar_troca_senha, atualizado_em
            ) VALUES (:usuario_id, :empresa_id, 0, :agora)
        """), {"usuario_id": int(usuario_id), "empresa_id": int(empresa_id), "agora": agora})
        conexao.execute(text("""
            UPDATE saas_usuario_seguranca
            SET empresa_id = :empresa_id,
                ultimo_acesso = :agora,
                ultimo_ip = :ip,
                atualizado_em = :agora
            WHERE usuario_id = :usuario_id
        """), {
            "usuario_id": int(usuario_id),
            "empresa_id": int(empresa_id),
            "agora": agora,
            "ip": str(ip or "")[:100],
        })


