def saas_admin_logado(request: Request):
    return request.session.get("saas_owner") == True


def redirecionar_saas_login_se_necessario(request: Request):
    if not saas_admin_logado(request):
        return RedirectResponse(
            url="/saas-login",
            status_code=303
        )

    return None


@app.get("/saas-login")
def tela_login_saas(request: Request):
    if saas_admin_logado(request):
        return RedirectResponse(
            url="/admin-saas",
            status_code=303
        )

    return templates.TemplateResponse(
        request=request,
        name="saas_login.html",
        context={
            "erro": None
        }
    )


@app.post("/saas-login")
async def realizar_login_saas(request: Request):
    formulario = await request.form()

    email = str(formulario.get("email", "")).strip().lower()
    senha = str(formulario.get("senha", "")).strip()

    chave_login = _chave_login(request, email, "saas")
    bloqueado, minutos = _login_bloqueado(_saas_login_tentativas, chave_login)

    if bloqueado:
        return templates.TemplateResponse(
            request=request,
            name="saas_login.html",
            context={
                "erro": f"Muitas tentativas incorretas. Tente novamente em {minutos} minuto(s)."
            },
            status_code=429
        )

    if SAAS_OWNER_EMAIL and email == SAAS_OWNER_EMAIL and senha_saas_owner_valida(senha):
        _limpar_tentativas_login(_saas_login_tentativas, chave_login)
        request.session["saas_owner"] = True

        return RedirectResponse(
            url="/admin-saas",
            status_code=303
        )

    _registrar_login_falhou(_saas_login_tentativas, chave_login)

    return templates.TemplateResponse(
        request=request,
        name="saas_login.html",
        context={
            "erro": "E-mail ou senha do dono do SaaS inválidos."
        },
        status_code=400
    )


@app.get("/saas-logout")
def logout_saas(request: Request):
    request.session.pop("saas_owner", None)

    return RedirectResponse(
        url="/saas-login",
        status_code=303
    )



