def calcular_resumo_whatsapp_saas(db):
    preparar_colunas_whatsapp_v164()

    linhas = db.execute(
        text("""
            SELECT
                e.id AS empresa_id,
                e.nome AS empresa_nome,
                e.slug AS empresa_slug,
                e.email AS empresa_email,
                e.telefone_whatsapp AS empresa_whatsapp,
                wc.status_comercial,
                wc.plano_ativo,
                wc.ativo,
                wc.valor_mensal,
                wc.limite_mensal,
                wc.mensagens_enviadas_mes,
                wc.excedentes_mes,
                wc.solicitado_em,
                wc.ativado_em,
                wc.responsavel_nome,
                wc.responsavel_email,
                wc.responsavel_telefone,
                wc.numero_whatsapp_empresa,
                wc.ja_tem_meta_business,
                wc.ja_usa_whatsapp_business,
                wc.avisos_solicitados,
                wc.solicitacao_observacoes,
                wc.pacote_codigo,
                wc.pacote_nome,
                wc.outro_volume_solicitado,
                wc.pais_empresa,
                wc.idioma_mensagens,
                wc.numero_ja_em_uso,
                wc.melhor_horario_contato,
                wc.site_perfil_empresa,
                wc.endereco_empresa,
                wc.cidade_empresa,
                wc.categoria_empresa,
                wc.nome_exibido_whatsapp,
                wc.numero_recebe_codigo,
                wc.autorizacao_ativacao,
                wc.modo_envio,
                wc.phone_number_id,
                wc.business_account_id,
                wc.access_token,
                wc.template_pedido_em_preparo,
                wc.template_pronto_retirada,
                wc.template_saiu_entrega,
                wc.template_reserva_confirmada,
                wc.template_idioma
            FROM empresas e
            LEFT JOIN whatsapp_cloud_configuracoes wc ON wc.empresa_id = e.id
            ORDER BY
                CASE
                    WHEN wc.status_comercial = 'solicitado' THEN 0
                    WHEN wc.status_comercial = 'em_analise' THEN 1
                    WHEN wc.status_comercial = 'aguardando_pagamento' THEN 2
                    WHEN wc.status_comercial = 'aguardando_cliente' THEN 3
                    WHEN wc.status_comercial = 'ativo' THEN 4
                    ELSE 5
                END,
                e.id DESC
        """)
    ).mappings().all()

    empresas = []
    total_solicitado = 0
    total_ativo = 0
    receita_whatsapp = 0
    mensagens_mes = 0

    for linha in linhas:
        item = dict(linha)
        status = item.get("status_comercial") or "nao_contratado"
        item["status_comercial"] = status

        if status in ["solicitado", "em_analise", "aguardando_pagamento", "aguardando_cliente"]:
            total_solicitado += 1

        if status == "ativo" or item.get("plano_ativo"):
            total_ativo += 1
            receita_whatsapp += float(item.get("valor_mensal") or 25)

        mensagens_mes += int(item.get("mensagens_enviadas_mes") or 0)

        try:
            ultimos_logs = listar_whatsapp_cloud_logs(db, item.get("empresa_id"), limite=1)
            ultimo_log = dict(ultimos_logs[0]) if ultimos_logs else {}
        except Exception:
            ultimo_log = {}
        item["ultimo_log_status"] = ultimo_log.get("status") or ""
        item["ultimo_log_mensagem"] = ultimo_log.get("mensagem") or ""
        item["ultimo_log_evento"] = ultimo_log.get("evento") or ""
        item["ultimo_log_template"] = ultimo_log.get("template") or ""
        item["ultimo_log_destino"] = ultimo_log.get("destino") or ""
        item["access_token"] = configured_secret(item.get("access_token"))

        empresas.append(item)

    return {
        "empresas": empresas,
        "total_solicitado": total_solicitado,
        "total_ativo": total_ativo,
        "receita_whatsapp": receita_whatsapp,
        "mensagens_mes": mensagens_mes
    }


