@app.post("/admin-saas/whatsapp/{empresa_id}/salvar")
async def salvar_whatsapp_saas_empresa(empresa_id: int, request: Request):
    redirecionamento = redirecionar_saas_login_se_necessario(request)
    if redirecionamento:
        return redirecionamento

    formulario = await request.form()

    db = SessionLocal()
    empresa = db.query(Empresa).filter(Empresa.id == empresa_id).first()

    if not empresa:
        db.close()
        return RedirectResponse(url="/admin-saas/whatsapp?erro=empresa_nao_encontrada", status_code=303)

    preparar_colunas_whatsapp_v164()
    obter_whatsapp_cloud_config(db, empresa_id)

    # Reutiliza o salvamento técnico, mas vindo do painel do dono do SaaS.
    salvar_whatsapp_cloud_config(db, empresa_id, formulario)

    acao_chamado = str(formulario.get("acao_chamado", "") or "").strip()
    status = str(formulario.get("wa_status_comercial", "nao_contratado") or "nao_contratado").strip()
    if acao_chamado == "em_analise":
        status = "em_analise"
    elif acao_chamado == "aguardando_cliente":
        status = "aguardando_cliente"
    elif acao_chamado == "aguardando_pagamento":
        status = "aguardando_pagamento"
    elif acao_chamado == "ativar":
        status = "ativo"
    elif acao_chamado == "cancelar":
        status = "cancelado"

    plano_ativo = 1 if str(formulario.get("wa_auto_plano_ativo", "0")) == "1" or status == "ativo" else 0
    ativo = 1 if str(formulario.get("wa_auto_ativo", "0")) == "1" or status == "ativo" else 0

    config_pos_salvamento = obter_whatsapp_cloud_config(db, empresa_id)
    ambiente_envio = str(config_pos_salvamento.get("modo_envio") or formulario.get("wa_modo_envio") or "teste").strip().lower()
    if status == "ativo" and ativo and ambiente_envio == "producao":
        producao_ok, producao_msg = validar_whatsapp_producao_real(config_pos_salvamento)
        if not producao_ok:
            status = "em_analise"
            plano_ativo = 0
            ativo = 0
            registrar_whatsapp_cloud_log(
                db=db,
                empresa_id=empresa_id,
                destino="",
                evento="validacao_producao_real",
                template="",
                status="erro",
                mensagem=producao_msg
            )

    pacote_codigo = str(formulario.get("wa_pacote_codigo", "") or "").strip()
    pacotes = {
        "inicial": {"nome": "100 mensagens", "limite": 100, "valor": 4.90},
        "essencial": {"nome": "500 mensagens", "limite": 500, "valor": 19.90},
        "crescimento": {"nome": "1.000 mensagens", "limite": 1000, "valor": 34.90},
        "outro": {"nome": "Cotação personalizada", "limite": int(str(formulario.get("wa_limite_mensal", "0") or "0") or 0), "valor": float(str(formulario.get("wa_valor_mensal", "0") or "0").replace(",", ".") or 0)},
    }
    pacote_nome = None
    if pacote_codigo in pacotes:
        pacote_nome = pacotes[pacote_codigo]["nome"]
        if pacote_codigo != "outro":
            db.execute(
                text("""
                    UPDATE whatsapp_cloud_configuracoes
                    SET pacote_codigo = :pacote_codigo,
                        pacote_nome = :pacote_nome,
                        valor_mensal = :valor_mensal,
                        limite_mensal = :limite_mensal,
                        inclui_mensagens = :limite_mensal
                    WHERE empresa_id = :empresa_id
                """),
                {
                    "empresa_id": empresa_id,
                    "pacote_codigo": pacote_codigo,
                    "pacote_nome": pacote_nome,
                    "valor_mensal": pacotes[pacote_codigo]["valor"],
                    "limite_mensal": pacotes[pacote_codigo]["limite"]
                }
            )
        else:
            db.execute(
                text("""
                    UPDATE whatsapp_cloud_configuracoes
                    SET pacote_codigo = :pacote_codigo,
                        pacote_nome = :pacote_nome
                    WHERE empresa_id = :empresa_id
                """),
                {"empresa_id": empresa_id, "pacote_codigo": pacote_codigo, "pacote_nome": pacote_nome}
            )

    agora = agora_brasilia()

    db.execute(
        text("""
            UPDATE whatsapp_cloud_configuracoes
            SET status_comercial = :status,
                plano_ativo = :plano_ativo,
                ativo = :ativo,
                ativado_em = CASE
                    WHEN :status = 'ativo' AND ativado_em IS NULL THEN :agora
                    ELSE ativado_em
                END,
                atualizado_em = :agora
            WHERE empresa_id = :empresa_id
        """),
        {
            "empresa_id": empresa_id,
            "status": status,
            "plano_ativo": plano_ativo,
            "ativo": ativo,
            "agora": agora
        }
    )

    registrar_whatsapp_cloud_log(
        db=db,
        empresa_id=empresa_id,
        destino="",
        evento="configuracao_saas_owner",
        template="",
        status="sucesso",
        mensagem="Configuração técnica/comercial atualizada pelo painel do dono do SaaS."
    )

    db.commit()
    db.close()

    return RedirectResponse(url="/admin-saas/whatsapp?sucesso=whatsapp_salvo", status_code=303)


