@app.post("/admin-saas/empresas/{empresa_id}/plano")
async def atualizar_plano_empresa_saas(empresa_id: int, request: Request):
    redirecionamento = redirecionar_saas_login_se_necessario(request)
    if redirecionamento:
        return redirecionamento

    formulario = await request.form()

    acao = str(formulario.get("acao", "")).strip()
    status = str(formulario.get("plano_status", "ativo")).strip() or "ativo"

    try:
        valor_mensal = float(str(formulario.get("plano_valor_mensal", "0")).replace(",", ".") or 0)
    except ValueError:
        valor_mensal = 0

    try:
        dias = int(formulario.get("dias", "30") or 30)
    except ValueError:
        dias = 30

    try:
        dias_remover = int(formulario.get("dias_remover", "0") or 0)
    except ValueError:
        dias_remover = 0

    try:
        ajuste_dias = int(str(formulario.get("ajuste_dias", "0") or 0).replace("+", ""))
    except ValueError:
        ajuste_dias = 0

    vencimento_manual = str(formulario.get("vencimento_manual", "")).strip()
    motivo_bloqueio = str(formulario.get("motivo_bloqueio", "")).strip()
    bloqueio_acesso_solicitado = None

    db = SessionLocal()

    empresa = db.query(Empresa).filter(
        Empresa.id == empresa_id
    ).first()

    if not empresa:
        db.close()
        return {"error": "Empresa não encontrada"}

    empresa.plano_nome = "Plano Completo"
    empresa.plano_valor_mensal = valor_mensal

    if acao == "teste_10_dias":
        agora = agora_brasilia()
        empresa.assinatura_inicio = empresa.assinatura_inicio or agora
        empresa.assinatura_vencimento = agora + timedelta(days=10)
        empresa.plano_status = "teste"
        empresa.plano_motivo_bloqueio = None
        empresa.ativo = True

    elif acao == "renovar":
        base_data = empresa.assinatura_vencimento or agora_brasilia()

        if base_data.date() < agora_brasilia().date():
            base_data = agora_brasilia()

        empresa.assinatura_inicio = empresa.assinatura_inicio or agora_brasilia()
        empresa.assinatura_vencimento = base_data + timedelta(days=dias)
        empresa.plano_status = "ativo"
        empresa.plano_motivo_bloqueio = None
        empresa.ativo = True

    elif acao == "bloquear":
        empresa.plano_status = "bloqueado"
        bloqueio_acesso_solicitado = True
        empresa.plano_motivo_bloqueio = motivo_bloqueio or "Assinatura pendente. Entre em contato com o suporte."
        # Status apenas visual: não bloqueia o acesso da empresa.
        empresa.ativo = True

    elif acao == "ativar":
        empresa.plano_status = "ativo"
        bloqueio_acesso_solicitado = False
        empresa.plano_motivo_bloqueio = None
        empresa.ativo = True

        if not empresa.assinatura_vencimento or empresa.assinatura_vencimento.date() < agora_brasilia().date():
            empresa.assinatura_vencimento = agora_brasilia() + timedelta(days=30)

    elif acao == "remover_dias":
        base_data = empresa.assinatura_vencimento or agora_brasilia()
        dias_remover = max(0, dias_remover)

        empresa.assinatura_vencimento = base_data - timedelta(days=dias_remover)

        if empresa.assinatura_vencimento.date() < agora_brasilia().date():
            empresa.plano_status = "vencido"
            # Vencido apenas aparece no topo do painel; não bloqueia.
            empresa.ativo = True
        else:
            empresa.plano_status = "ativo"
            empresa.ativo = True

    elif acao == "aplicar_ajuste":
        base_data = empresa.assinatura_vencimento or agora_brasilia()
        empresa.assinatura_inicio = empresa.assinatura_inicio or agora_brasilia()
        empresa.assinatura_vencimento = base_data + timedelta(days=ajuste_dias)

        if empresa.assinatura_vencimento.date() < agora_brasilia().date():
            empresa.plano_status = "vencido"
        elif (empresa.plano_status or "").lower() not in ["teste", "cancelado", "bloqueado"]:
            empresa.plano_status = "ativo"

        # Ajuste de dias é apenas controle visual/comercial; não bloqueia o acesso.
        empresa.ativo = True

    elif acao in ["definir_vencimento", "definir_data"]:
        try:
            nova_data = datetime.strptime(vencimento_manual, "%Y-%m-%d")
        except ValueError:
            nova_data = None

        if nova_data:
            empresa.assinatura_vencimento = nova_data

            if nova_data.date() < agora_brasilia().date():
                empresa.plano_status = "vencido"
                # Vencido apenas aparece no topo do painel; não bloqueia.
                empresa.ativo = True
            else:
                empresa.plano_status = "ativo"
                empresa.ativo = True

    elif acao == "sem_vencimento":
        empresa.assinatura_vencimento = None
        empresa.plano_status = "ativo"
        empresa.plano_motivo_bloqueio = None
        empresa.ativo = True

    elif acao == "cancelar":
        empresa.plano_status = "cancelado"
        # Cancelado apenas aparece no topo do painel; não bloqueia automaticamente.
        empresa.ativo = True

    elif acao == "salvar_status":
        empresa.plano_status = status

        # Status apenas visual: aparece no painel da empresa, mas não bloqueia o acesso.
        empresa.ativo = True

        if status == "ativo" and (not empresa.assinatura_vencimento or empresa.assinatura_vencimento.date() < agora_brasilia().date()):
            empresa.assinatura_vencimento = agora_brasilia() + timedelta(days=30)

        if status in ["ativo", "teste"]:
            empresa.plano_motivo_bloqueio = None

    else:
        empresa.plano_status = status

        # Status apenas visual: aparece no painel da empresa, mas não bloqueia o acesso.
        empresa.ativo = True

    status_final = empresa.plano_status
    vencimento_final = empresa.assinatura_vencimento
    db.commit()
    db.close()
    if bloqueio_acesso_solicitado is not None:
        garantir_controle_saas_empresa(empresa_id)
        with engine.begin() as conexao:
            conexao.execute(text("""
                UPDATE saas_empresa_controles
                SET bloquear_acesso_painel = :bloqueado, atualizado_em = :agora
                WHERE empresa_id = :empresa_id
            """), {
                "empresa_id": empresa_id,
                "bloqueado": 1 if bloqueio_acesso_solicitado else 0,
                "agora": _agora_saas_texto(),
            })
    vencimento_texto = vencimento_final.strftime("%d/%m/%Y") if vencimento_final else "sem vencimento"
    registrar_atividade_saas(
        empresa_id,
        "Plano e assinatura atualizados",
        f"Ação: {acao or 'salvar'}. Status: {status_final}. Vencimento: {vencimento_texto}.",
    )

    return RedirectResponse(
        url=f"/admin-saas?sucesso=plano_salvo&empresa={empresa_id}&aba=plano#empresa-{empresa_id}",
        status_code=303
    )


