# UPLOAD DE IMAGEM
# ==================================================

@app.post("/upload-imagem")
async def upload_imagem(request: Request, file: UploadFile = File(...)):
    exigir_admin_logado_api(request)

    max_size = 8 * 1024 * 1024
    max_pixels = 40_000_000
    max_dimension = 12_000
    content = await file.read(max_size + 1)
    if not content:
        return JSONResponse({"error": "O arquivo está vazio."}, status_code=400)
    if len(content) > max_size:
        return JSONResponse({"error": "A imagem deve ter no máximo 8 MB."}, status_code=413)

    detected_extension = None
    if content.startswith(b"\xff\xd8\xff"):
        detected_extension = "jpg"
    elif content.startswith(b"\x89PNG\r\n\x1a\n"):
        detected_extension = "png"
    elif len(content) >= 12 and content[:4] == b"RIFF" and content[8:12] == b"WEBP":
        detected_extension = "webp"

    if not detected_extension:
        return JSONResponse(
            {"error": "Formato não permitido. Envie JPG, PNG ou WEBP."},
            status_code=415,
        )

    allowed_content_types = {
        "image/jpeg", "image/jpg", "image/pjpeg", "image/png", "image/webp",
        "application/octet-stream",
    }
    if file.content_type and file.content_type.lower() not in allowed_content_types:
        return JSONResponse({"error": "Tipo de arquivo não permitido."}, status_code=415)

    expected_formats = {"jpg": "JPEG", "png": "PNG", "webp": "WEBP"}
    try:
        Image.MAX_IMAGE_PIXELS = max_pixels
        with Image.open(io.BytesIO(content)) as image:
            image_format = str(image.format or "").upper()
            width, height = image.size
            image.verify()
        if image_format != expected_formats[detected_extension]:
            raise UnidentifiedImageError("Formato real divergente.")
        if width < 1 or height < 1 or width > max_dimension or height > max_dimension:
            return JSONResponse({"error": "As dimensões da imagem não são permitidas."}, status_code=415)
        if width * height > max_pixels:
            return JSONResponse({"error": "A imagem possui resolução excessiva."}, status_code=413)
    except (UnidentifiedImageError, OSError, ValueError, Image.DecompressionBombError):
        return JSONResponse({"error": "O conteúdo enviado não é uma imagem válida."}, status_code=415)
    except Image.DecompressionBombWarning:
        return JSONResponse({"error": "A imagem possui resolução excessiva."}, status_code=413)

    upload_directory = "backend/static/uploads"
    os.makedirs(upload_directory, mode=0o750, exist_ok=True)
    if os.name != "nt":
        try:
            os.chmod(upload_directory, 0o750)
        except OSError:
            pass

    filename = f"{uuid.uuid4().hex}.{detected_extension}"
    path = os.path.join(upload_directory, filename)
    with open(path, "xb") as buffer:
        buffer.write(content)
    if os.name != "nt":
        try:
            os.chmod(path, 0o640)
        except OSError:
            pass

    return {"url": f"/static/uploads/{filename}"}


