@app.post("/empresas")
def criar_empresa(empresa: EmpresaCreate, request: Request):
    if not saas_admin_logado(request):
        raise HTTPException(status_code=401, detail="Faça login como administrador do SaaS.")

    db = SessionLocal()
    try:
        nova_empresa = Empresa(**empresa.model_dump())
        db.add(nova_empresa)
        db.commit()
        return {"message": "Empresa criada com sucesso"}
    except IntegrityError:
        db.rollback()
        return JSONResponse({"error": "Já existe uma empresa com este endereço."}, status_code=409)
    finally:
        db.close()


@app.patch("/empresas/{empresa_id}")
def atualizar_empresa(empresa_id: int, empresa: EmpresaCreate, request: Request):
    exigir_admin_empresa_api(request, empresa_id)
    db = SessionLocal()

    empresa_db = db.query(Empresa).filter(
        Empresa.id == empresa_id
    ).first()

    if not empresa_db:
        db.close()
        return {"error": "Empresa não encontrada"}

    for campo, valor in empresa.dict().items():
        setattr(empresa_db, campo, valor)

    db.commit()
    db.close()

    return {"message": "Empresa atualizada com sucesso"}


