@app.patch("/itens/{item_id}")
async def atualizar_item(item_id: int, request: Request):
    db = None

    try:
        payload = await request.json()
        db = SessionLocal()

        item_db = db.query(Item).filter(
            Item.id == item_id
        ).first()

        if not item_db:
            return {"error": "Item não encontrado"}

        exigir_admin_empresa_api(request, item_db.empresa_id, "cardapio")

        # Em atualizações parciais, preserve a galeria atual quando o cliente
        # enviar somente um dos campos de foto.
        if "foto_url" in payload or "fotos_json" in payload:
            if "foto_url" not in payload:
                payload["foto_url"] = item_db.foto_url
            if "fotos_json" not in payload:
                payload["fotos_json"] = item_db.fotos_json

        dados_modelo = dados_item_para_modelo(payload)

        for campo, valor in dados_modelo.items():
            if campo != "id":
                setattr(item_db, campo, valor)

        db.commit()

        salvar_codigo_item_sqlite(db, item_id, payload)
        db.commit()

        return {"message": "Item atualizado com sucesso"}

    except Exception as erro:
        if db:
            db.rollback()
        return {"error": f"Erro ao atualizar item: {erro}"}

    finally:
        if db:
            db.close()


