@app.get("/menu/{slug}")
def ver_catalogo(slug: str, request: Request):
    db = SessionLocal()

    empresa = db.query(Empresa).filter(
        Empresa.slug == slug
    ).first()

    if not empresa:
        db.close()
        return {"error": "Empresa não encontrada"}

    anexar_idioma_empresa(db, empresa)

    if plano_empresa_bloqueado(empresa):
        db.close()
        return templates.TemplateResponse(
            request=request,
            name="empresa_bloqueada.html",
            context={
                "empresa": empresa,
                "suporte_whatsapp": SAAS_SUPPORT_WHATSAPP
            },
            status_code=403
        )

    aviso_plano_vencido = plano_empresa_vencido(empresa)

    negocio_encomenda = tipo_negocio_encomenda(empresa.tipo)
    if negocio_encomenda:
        garantir_categorias_encomendas_padrao(db, empresa.id)
        categorias, encomenda_itens = catalogo_encomendas_contexto(db, empresa.id)
        itens = []
    else:
        categorias = db.query(Categoria).filter(
            Categoria.empresa_id == empresa.id,
            Categoria.ativo == True
        ).order_by(Categoria.ordem).all()

        itens = db.query(Item).filter(
            Item.empresa_id == empresa.id,
            Item.disponivel == True
        ).all()
        encomenda_itens = []

    negocio_servico = tipo_negocio_servico(empresa.tipo)
    negocio_produto = tipo_negocio_produto(empresa.tipo)
    negocio_pedido = tipo_negocio_pedido(empresa.tipo)

    anexar_hero_empresa(db, empresa)
    menu_config = obter_menu_configuracoes(db, empresa.id)
    # v819: a apresentação institucional é global para todos os menus públicos.
    # A tabela/funções mantêm o nome histórico "encomendas_apresentacao" por compatibilidade.
    encomendas_apresentacao = obter_apresentacao_encomendas(db, empresa.id)
    pedidos_abertos, mensagem_pedidos_horario, horarios_funcionamento = verificar_pedidos_abertos(db, empresa.id)
    restricao_horarios_ativa = obter_restricao_horarios_ativa(db, empresa.id)
    entrega_config = obter_entrega_config_empresa(empresa)
    politicas_loja = obter_politicas_loja_empresa(empresa)

    # Renderiza enquanto os objetos ORM ainda estão ligados à sessão.
    # Algumas rotinas de configuração podem executar commit e expirar atributos;
    # fechar a sessão antes do Jinja fazia a demonstração de restaurante falhar.
    resposta = templates.TemplateResponse(
        request=request,
        name=template_menu_publico(empresa.tipo),
        context={
            "empresa": empresa,
            "categorias": categorias,
            "itens": itens,
            "negocio_servico": negocio_servico,
            "negocio_produto": negocio_produto,
            "negocio_encomenda": negocio_encomenda,
            "negocio_pedido": negocio_pedido,
            "encomenda_itens": encomenda_itens,
            "aviso_plano_vencido": aviso_plano_vencido,
            "menu_config": menu_config,
            "encomendas_apresentacao": encomendas_apresentacao,
            "horarios_funcionamento": horarios_funcionamento,
            "restricao_horarios_ativa": restricao_horarios_ativa,
            "pedidos_abertos": pedidos_abertos,
            "mensagem_pedidos_horario": mensagem_pedidos_horario,
            "entrega_config": entrega_config,
            "politicas_loja": politicas_loja,
            "agora_operacional_iso": agora_brasilia().isoformat()
        }
    )
    db.close()
    return resposta




@app.get("/menu/{slug}/mesa/{mesa_numero}/pedidos")
def pedidos_publicos_da_mesa(slug: str, mesa_numero: int):
    """Retorna a conta aberta da mesa para o cliente visualizar.
    Cliente só visualiza; finalizar continua sendo apenas pelo admin.
    """
    db = SessionLocal()

    empresa = db.query(Empresa).filter(Empresa.slug == slug).first()
    if not empresa:
        db.close()
        return {"error": "Empresa não encontrada"}

    hoje = agora_brasilia()
    inicio_dia = datetime.combine(hoje.date(), time(0, 0, 0))
    fim_dia = datetime.combine(hoje.date(), time(23, 59, 59))

    marcador = f"Mesa {mesa_numero}"

    pedidos = db.query(Pedido).filter(
        Pedido.empresa_id == empresa.id,
        Pedido.criado_em >= inicio_dia,
        Pedido.criado_em <= fim_dia,
        Pedido.status != "cancelado",
        Pedido.status != "finalizado",
        or_(
            Pedido.observacao.like(f"%[{marcador}%"),
            Pedido.observacao.like(f"%{marcador}%"),
            Pedido.tipo_pedido.like(f"%{marcador}%")
        )
    ).order_by(Pedido.id.desc()).all()

    resultado = []
    total_mesa = Decimal("0.00")
    total_itens = 0

    for pedido in pedidos:
        itens_db = db.query(PedidoItem).filter(PedidoItem.pedido_id == pedido.id).all()

        itens = []
        for item in itens_db:
            quantidade = int(item.quantidade or 0)
            subtotal = moeda(item.subtotal or 0)
            total_itens += quantidade

            nome_item = (getattr(item, "nome_item", None) or "").strip()
            if (not nome_item or nome_item.lower() == "item") and getattr(item, "item_id", None):
                item_original = db.query(Item).filter(
                    Item.id == item.item_id,
                    Item.empresa_id == empresa.id
                ).first()
                if item_original and getattr(item_original, "nome", None):
                    nome_item = item_original.nome
            if not nome_item:
                nome_item = "Item"

            itens.append({
                "nome": nome_item,
                "quantidade": quantidade,
                "subtotal": float(subtotal)
            })

        total_pedido = moeda(pedido.total or 0)
        total_mesa += total_pedido

        resultado.append({
            "id": pedido.id,
            "codigo": f"#{pedido.id:04d}",
            "status": pedido.status,
            "total": float(total_pedido),
            "criado_em": pedido.criado_em.strftime("%H:%M") if pedido.criado_em else "",
            "itens": itens
        })

    db.close()

    return {
        "mesa": mesa_numero,
        "pedidos": resultado,
        "total": float(total_mesa),
        "quantidade_pedidos": len(resultado),
        "quantidade_itens": total_itens
    }



