def preparar_chamadas_atendimento():
    """Fila simples de chamadas de garçom/atendente por empresa."""
    try:
        conn = engine.raw_connection()
        cursor = conn.cursor()
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS chamadas_atendimento (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                empresa_id INTEGER NOT NULL,
                origem TEXT,
                mesa TEXT,
                identificador TEXT,
                status TEXT DEFAULT 'pendente',
                observacao TEXT,
                criado_em DATETIME,
                resolvido_em DATETIME
            )
        """)
        conn.commit()
        conn.close()
    except Exception as erro:
        print("Aviso: não foi possível preparar chamadas_atendimento:", repr(erro))


def listar_chamadas_atendimento(db, empresa_id: int, limite: int = 20):
    preparar_chamadas_atendimento()
    try:
        linhas = db.execute(
            text("""
                SELECT id, empresa_id, origem, mesa, identificador, status, observacao, criado_em, resolvido_em
                FROM chamadas_atendimento
                WHERE empresa_id = :empresa_id
                  AND COALESCE(status, 'pendente') = 'pendente'
                ORDER BY criado_em DESC, id DESC
                LIMIT :limite
            """),
            {"empresa_id": empresa_id, "limite": limite}
        ).mappings().all()

        chamadas = []
        for linha in linhas:
            item = dict(linha)
            criado = item.get("criado_em")
            if hasattr(criado, "strftime"):
                item["criado_em_label"] = criado.strftime("%H:%M")
                item["criado_em"] = criado.strftime("%Y-%m-%d %H:%M:%S")
            else:
                texto = str(criado or "")
                item["criado_em_label"] = texto[11:16] if len(texto) >= 16 else texto
                item["criado_em"] = texto
            chamadas.append(item)
        return chamadas
    except Exception as erro:
        print("Erro ao listar chamadas de atendimento:", repr(erro))
        return []


def criar_chamada_atendimento(db, empresa_id: int, origem: str, mesa: str = "", identificador: str = "", observacao: str = ""):
    preparar_chamadas_atendimento()
    agora = agora_brasilia()
    origem = (origem or "Atendimento").strip()[:80]
    mesa = (mesa or "").strip()[:50]
    identificador = (identificador or origem).strip()[:80]
    observacao = (observacao or "").strip()[:250]

    # Evita duplicar se o cliente apertar várias vezes em poucos minutos.
    existente = db.execute(
        text("""
            SELECT id
            FROM chamadas_atendimento
            WHERE empresa_id = :empresa_id
              AND COALESCE(status, 'pendente') = 'pendente'
              AND COALESCE(origem, '') = :origem
              AND COALESCE(mesa, '') = :mesa
              AND COALESCE(identificador, '') = :identificador
              AND criado_em >= :limite
            ORDER BY id DESC
            LIMIT 1
        """),
        {
            "empresa_id": empresa_id,
            "origem": origem,
            "mesa": mesa,
            "identificador": identificador,
            "limite": agora - timedelta(minutes=3)
        }
    ).mappings().first()

    if existente:
        return int(existente["id"]), False

    resultado = db.execute(
        text("""
            INSERT INTO chamadas_atendimento
                (empresa_id, origem, mesa, identificador, status, observacao, criado_em)
            VALUES
                (:empresa_id, :origem, :mesa, :identificador, 'pendente', :observacao, :agora)
        """),
        {
            "empresa_id": empresa_id,
            "origem": origem,
            "mesa": mesa,
            "identificador": identificador,
            "observacao": observacao,
            "agora": agora
        }
    )
    return int(resultado.lastrowid or 0), True


@app.post("/menu/{slug}/chamar-atendente")
async def chamar_atendente_publico(slug: str, request: Request):
    """Recebe chamada de atendente vinda do menu, mesa, tablet ou terminal."""
    try:
        dados = await request.json()
    except Exception:
        dados = {}

    db = SessionLocal()
    empresa = db.query(Empresa).filter(Empresa.slug == slug).first()
    if not empresa:
        db.close()
        return {"ok": False, "erro": "Empresa não encontrada."}

    mesa = str(dados.get("mesa") or "").strip()
    terminal = str(dados.get("terminal") or dados.get("tablet") or dados.get("totem") or "").strip()
    modo = str(dados.get("modo") or "").strip().lower()
    identificador = str(dados.get("identificador") or "").strip()
    observacao = str(dados.get("observacao") or "").strip()

    if mesa:
        origem = f"Mesa {mesa}"
        identificador = identificador or origem
    elif terminal:
        origem = f"Tablet {terminal}"
        identificador = identificador or origem
    elif modo == "tablet":
        origem = "Tablet / Totem"
        identificador = identificador or origem
    else:
        origem = "Menu público"
        identificador = identificador or "Cliente"

    chamada_id, nova = criar_chamada_atendimento(
        db=db,
        empresa_id=empresa.id,
        origem=origem,
        mesa=mesa,
        identificador=identificador,
        observacao=observacao
    )
    db.commit()
    db.close()

    return {
        "ok": True,
        "id": chamada_id,
        "nova": nova,
        "mensagem": "Atendente chamado. Aguarde um instante."
    }


