@app.post("/pedidos")
def criar_pedido(pedido: PedidoCreate, request: Request):
    db = SessionLocal()
    stored_idempotency_key = None

    def success_payload(order, *, duplicate=False):
        numero_dia = getattr(order, "numero_dia", None)
        return {
            "message": "Pedido criado com sucesso",
            "total": float(order.total or 0),
            "subtotal_sem_iva": float(order.subtotal_sem_iva or 0),
            "total_iva": float(order.total_iva or 0),
            "taxa_entrega": float(order.taxa_entrega or 0),
            "frete_metodo": getattr(order, "frete_metodo", None),
            "frete_distancia_km": getattr(order, "frete_distancia_km", None),
            "frete_faixa_nome": getattr(order, "frete_faixa_nome", None),
            "frete_prazo": getattr(order, "frete_prazo", None),
            "pedido_id": order.id,
            "numero_dia": numero_dia,
            "numero_pedido": f"#{int(numero_dia):03d}" if numero_dia else None,
            "public_token": getattr(order, "public_token", None),
            "status": getattr(order, "status", None),
            "status_pagamento": getattr(order, "status_pagamento", None),
            "pix_manual": normalize_order_value(getattr(order, "pagamento", None)) in {
                "pix pela chave", "pix manual", "pix_manual", "pix chave", "pix_chave"
            },
            "duplicado": bool(duplicate),
        }

    try:
        empresa = db.query(Empresa).filter(Empresa.id == pedido.empresa_id).first()
        if not empresa:
            return JSONResponse({"error": "Empresa não encontrada."}, status_code=404)
        if plano_empresa_bloqueado(empresa):
            return JSONResponse(
                {"error": "Sistema bloqueado. Pedidos temporariamente indisponíveis."},
                status_code=403,
            )
        if getattr(empresa, "aceita_pedidos_online", True) is False:
            return JSONResponse(
                {"error": "Esta empresa não está aceitando pedidos online."},
                status_code=409,
            )

        pedidos_abertos, mensagem_pedidos_horario, _ = verificar_pedidos_abertos(db, empresa.id)
        if not pedidos_abertos:
            return JSONResponse({"error": mensagem_pedidos_horario}, status_code=409)

        validate_order_header(pedido)
        resolved_items = resolve_order_items(db, pedido.empresa_id, pedido.itens)

        explicit_key = request.headers.get("X-Idempotency-Key") or pedido.chave_idempotencia
        stored_idempotency_key, lookup_keys = idempotency_keys(
            pedido, resolved_items, explicit_key
        )
        existing_order = find_recent_idempotent_order(
            db, pedido.empresa_id, lookup_keys
        )
        if existing_order:
            return success_payload(existing_order, duplicate=True)

        total_final = Decimal("0.00")
        subtotal_sem_iva = Decimal("0.00")
        total_iva = Decimal("0.00")
        calculated_lines = []

        for line in resolved_items:
            item_db = line["item"]
            aliquota_item = (
                item_db.aliquota_iva
                if item_db.aliquota_iva is not None
                else v156_obter_aliquota_padrao_empresa(db, empresa, item_db.tipo)
            )
            calculo = calcular_iva_preco_final(
                preco_final=float(line["unit_price"]),
                quantidade=line["quantity"],
                empresa_usa_iva=True,
                item_aplica_iva=True,
                aliquota=aliquota_item,
            )
            calculated_lines.append((line, calculo))
            total_final += moeda(calculo["subtotal_final"])
            subtotal_sem_iva += moeda(calculo["subtotal_sem_iva"])
            total_iva += moeda(calculo["valor_iva"])

        entrega_config = obter_entrega_config_empresa(empresa)
        pedido_entrega = is_delivery(pedido.tipo_pedido)
        if pedido_entrega and not entrega_config["entrega_ativa"]:
            raise OrderValidationError("A entrega está indisponível no momento.")
        if not pedido_entrega and not entrega_config["retirada_ativa"]:
            raise OrderValidationError("A retirada no local está indisponível no momento.")

        frete_cotacao = {
            "metodo": None,
            "distancia_km": None,
            "faixa_nome": None,
            "prazo": None,
        }
        if pedido_entrega and tipo_negocio_entrega(empresa.tipo):
            try:
                cotacao = calcular_cotacao_frete_produtos(
                    empresa, total_final, pedido.cap_entrega
                )
            except ShippingQuoteError as erro:
                raise OrderValidationError(str(erro)) from erro
            if not cotacao.get("disponivel"):
                raise OrderValidationError(
                    str(cotacao.get("mensagem") or "Entrega indisponível para este CEP.")
                )
            taxa_entrega = moeda(cotacao.get("valor", 0))
            frete_cotacao = {
                "metodo": str(cotacao.get("metodo") or ""),
                "distancia_km": cotacao.get("distancia_km"),
                "faixa_nome": str(cotacao.get("faixa_nome") or "") or None,
                "prazo": str(cotacao.get("prazo") or "") or None,
            }
        elif pedido_entrega:
            # Restaurantes e outros menus mantêm a regra própria já existente.
            pedido_minimo = moeda(entrega_config.get("pedido_minimo_entrega", 0))
            if pedido_minimo > 0 and total_final < pedido_minimo:
                raise OrderValidationError(
                    f"O pedido mínimo para entrega é R$ {pedido_minimo:.2f}."
                )
            frete_gratis_acima = moeda(entrega_config.get("frete_gratis_acima", 0))
            taxa_entrega = moeda(getattr(empresa, "taxa_entrega_padrao", 0))
            if frete_gratis_acima > 0 and total_final >= frete_gratis_acima:
                taxa_entrega = Decimal("0.00")
            frete_cotacao["metodo"] = "taxa_fixa_menu"
        else:
            taxa_entrega = Decimal("0.00")

        total_final = moeda(total_final + taxa_entrega)

        if pedido.precisa_troco:
            if not is_cash(pedido.pagamento):
                raise OrderValidationError("Troco só pode ser solicitado para pagamento em dinheiro.")
            troco_para = order_money(pedido.troco_para)
            if troco_para <= total_final:
                raise OrderValidationError("O valor para troco deve ser maior que o total do pedido.")
        else:
            troco_para = None

        stock_reserved = reserve_stock(db, resolved_items)
        payment_normalized = normalize_order_value(pedido.pagamento)
        online_payment = payment_normalized in {
            "pagamento online", "cartao online", "pix online", "pix"
        }
        manual_pix_payment = payment_normalized in {
            "pix pela chave", "pix manual", "pix_manual", "pix chave", "pix_chave"
        }
        payment_hold = online_payment or manual_pix_payment
        if online_payment and not bool(getattr(empresa, "pagamentos_online_ativo", False)):
            raise OrderValidationError("Pagamentos online estão desativados para este estabelecimento.")
        if manual_pix_payment:
            if not bool(getattr(empresa, "aceita_pix_chave", False)):
                raise OrderValidationError("Pix pela chave está desativado para este estabelecimento.")
            if not str(getattr(empresa, "pix_manual_chave", "") or "").strip():
                raise OrderValidationError("Pix pela chave não está configurado para este estabelecimento.")
        if is_cash(pedido.pagamento) and not bool(getattr(empresa, "aceita_dinheiro", False)):
            raise OrderValidationError("Pagamento em dinheiro não está disponível.")
        if payment_normalized in {"cartao", "cartão", "cartao na entrega", "cartão na entrega"} and not bool(getattr(empresa, "aceita_cartao_entrega", False)):
            raise OrderValidationError("Pagamento presencial no cartão não está disponível.")
        operation_date = hoje_brasilia()

        new_order = Pedido(
            empresa_id=pedido.empresa_id,
            criado_em=agora_brasilia(),
            # Checkout online nasce como tentativa interna. O número operacional
            # só é atribuído quando o Mercado Pago confirmar o pagamento.
            numero_dia=(
                None
                if payment_hold
                else gerar_numero_dia(db, Pedido, pedido.empresa_id, operation_date)
            ),
            data_operacional=operation_date,
            nome_cliente=re.sub(r"\s+", " ", pedido.nome_cliente).strip(),
            telefone_cliente=(pedido.telefone_cliente or "").strip() or None,
            tipo_pedido=pedido.tipo_pedido.strip(),
            origem_menu=(
                "produto" if tipo_negocio_produto(empresa.tipo)
                else "servico" if tipo_negocio_servico(empresa.tipo)
                else "comida"
            ),
            horario=pedido.horario,
            pagamento=pedido.pagamento,
            precisa_troco=bool(pedido.precisa_troco),
            troco_para=float(troco_para) if troco_para is not None else None,
            endereco_entrega=(pedido.endereco_entrega or "").strip() or None,
            cap_entrega=(pedido.cap_entrega or "").strip() or None,
            cidade_entrega=(pedido.cidade_entrega or "").strip() or None,
            provincia_entrega=(pedido.provincia_entrega or "").strip() or None,
            referencia_entrega=(pedido.referencia_entrega or "").strip() or None,
            tempo_estimado_minutos=(
                empresa.tempo_entrega_minutos
                if is_delivery(pedido.tipo_pedido)
                else empresa.tempo_retirada_minutos
            ),
            taxa_entrega=float(taxa_entrega),
            frete_metodo=frete_cotacao.get("metodo"),
            frete_distancia_km=(
                float(frete_cotacao["distancia_km"])
                if frete_cotacao.get("distancia_km") is not None
                else None
            ),
            frete_faixa_nome=frete_cotacao.get("faixa_nome"),
            frete_prazo=frete_cotacao.get("prazo"),
            total=float(total_final),
            subtotal_sem_iva=float(moeda(subtotal_sem_iva + taxa_entrega)),
            total_iva=float(moeda(total_iva)),
            observacao=(pedido.observacao or "").strip() or None,
            status="aguardando_pagamento" if payment_hold else "novo",
            status_pagamento="pendente" if payment_hold else "nao_iniciado",
            gateway_pagamento=("mercadopago" if online_payment else "pix_manual" if manual_pix_payment else None),
            chave_idempotencia=stored_idempotency_key,
            estoque_reservado=bool(stock_reserved),
            estoque_devolvido=False,
            public_token=secrets.token_urlsafe(32),
        )
        db.add(new_order)
        db.flush()

        for line, calculo in calculated_lines:
            db.add(PedidoItem(
                pedido_id=new_order.id,
                item_id=line["item_id"],
                nome_item=line["name"],
                quantidade=line["quantity"],
                preco_unitario=calculo["preco_unitario_final"],
                subtotal=calculo["subtotal_final"],
                aplica_iva=calculo["aplica_iva"],
                aliquota_iva=calculo["aliquota_iva"],
                preco_unitario_sem_iva=calculo["preco_unitario_sem_iva"],
                subtotal_sem_iva=calculo["subtotal_sem_iva"],
                valor_iva=calculo["valor_iva"],
            ))

        db.commit()
        db.refresh(new_order)

        if new_order.status != "aguardando_pagamento":
            enviar_whatsapp_automatico_evento(
                db=db,
                empresa_id=new_order.empresa_id,
                destino=new_order.telefone_cliente or "",
                tipo="pedido",
                status_evento="pedido recebido",
                contexto={
                    "nome_cliente": new_order.nome_cliente,
                    "pedido_id": f"#{int(new_order.numero_dia or new_order.id):03d}",
                    "total": new_order.total,
                    "empresa_nome": empresa.nome,
                },
            )
            db.commit()

        if new_order.status != "aguardando_pagamento":
            enqueue_new_order(new_order.id)

        return success_payload(new_order)

    except OrderValidationError as error:
        db.rollback()
        return JSONResponse({"error": str(error)}, status_code=error.status_code)
    except IntegrityError:
        db.rollback()
        if stored_idempotency_key:
            existing_order = db.query(Pedido).filter(
                Pedido.empresa_id == pedido.empresa_id,
                Pedido.chave_idempotencia == stored_idempotency_key,
            ).first()
            if existing_order:
                return success_payload(existing_order, duplicate=True)
        return JSONResponse(
            {"error": "O pedido já foi recebido. Aguarde a confirmação."},
            status_code=409,
        )
    except Exception as error:
        db.rollback()
        print("ERRO AO CRIAR PEDIDO:", repr(error))
        return JSONResponse(
            {"error": "Não foi possível criar o pedido. Tente novamente."},
            status_code=500,
        )
    finally:
        db.close()


@app.patch("/pedidos/{pedido_id}/status")
def atualizar_status_pedido(
    pedido_id: int,
    dados: PedidoStatusUpdate,
    request: Request,
):
    db = SessionLocal()
    try:
        pedido = db.query(Pedido).filter(Pedido.id == pedido_id).first()
        if not pedido:
            return JSONResponse({"error": "Pedido não encontrado."}, status_code=404)

        origem_pedido = (getattr(pedido, "origem_menu", None) or "").strip().lower()
        if origem_pedido == "produto":
            area_pedido = "produtos"
        elif origem_pedido == "comida":
            area_pedido = "pedidos"
        else:
            empresa_pedido = db.query(Empresa).filter(Empresa.id == pedido.empresa_id).first()
            area_pedido = "produtos" if empresa_pedido and tipo_negocio_produto(empresa_pedido.tipo) else "pedidos"
        exigir_admin_empresa_api(request, pedido.empresa_id, area_pedido)

        new_status = re.sub(r"\s+", " ", str(dados.status or "")).strip().lower()
        if not new_status or len(new_status) > 80:
            return JSONResponse({"error": "Status inválido."}, status_code=400)

        previous_status = normalize_order_value(pedido.status)
        cancellation_states = {
            "cancelado", "pagamento cancelado", "pagamento_cancelado",
            "pagamento recusado", "pagamento_recusado",
        }
        manual_pix_order = normalize_order_value(getattr(pedido, "pagamento", None)) in {
            "pix pela chave", "pix manual", "pix_manual", "pix chave", "pix_chave"
        } or normalize_order_value(getattr(pedido, "gateway_pagamento", None)) == "pix_manual"
        manual_pix_pending = manual_pix_order and normalize_order_value(getattr(pedido, "status_pagamento", None)) in {
            "pendente", "aguardando pagamento", "aguardando_pagamento"
        }
        if manual_pix_pending and new_status not in cancellation_states | {"aguardando pagamento", "aguardando_pagamento"}:
            return JSONResponse(
                {"error": "Confirme o Pix pela chave antes de avançar este pedido."},
                status_code=409,
            )

        if new_status in cancellation_states and previous_status not in cancellation_states:
            restore_stock(db, pedido)
        elif previous_status in cancellation_states and new_status not in cancellation_states:
            reserve_existing_order_stock(db, pedido)

        pedido.status = new_status
        if new_status in cancellation_states:
            if previous_status not in cancellation_states:
                pedido.cancelamento_origem = "estabelecimento"
                pedido.cancelamento_em = agora_brasilia()
            pagamento_atual = normalize_order_value(pedido.status_pagamento)
            if pagamento_atual in {"pago", "aprovado", "approved", "confirmado", "confirmada"}:
                # O cancelamento operacional não apaga dinheiro já recebido.
                # Até existir estorno explícito, o Financeiro mantém o recebimento.
                pedido.reembolso_status = pedido.reembolso_status or "nao_realizado"
                pedido.reembolso_valor = max(0.0, float(getattr(pedido, "reembolso_valor", 0) or 0))
            elif pagamento_atual in {"pendente", "aguardando pagamento", "aguardando_pagamento"}:
                pedido.status_pagamento = "cancelado"
                pedido.gateway_status = "manual_cancelled" if manual_pix_order else "cancelled_by_merchant"
                pedido.reembolso_status = "nao_aplicavel"
                pedido.reembolso_valor = 0
        elif previous_status in cancellation_states and new_status not in cancellation_states:
            if normalize_order_value(pedido.status_pagamento) == "cancelado":
                payment_normalized = normalize_order_value(pedido.pagamento)
                if payment_normalized in {"pagamento online", "cartao online", "pix online", "pix"}:
                    pedido.status_pagamento = "pendente"
                    pedido.gateway_status = "pending"
                elif payment_normalized in {"pix pela chave", "pix manual", "pix_manual", "pix chave", "pix_chave"}:
                    pedido.status_pagamento = "pendente"
                    pedido.gateway_status = "manual_pending"
                else:
                    pedido.status_pagamento = "nao_iniciado"
                    pedido.gateway_status = None

        empresa = db.query(Empresa).filter(Empresa.id == pedido.empresa_id).first()
        enviar_whatsapp_automatico_evento(
            db=db,
            empresa_id=pedido.empresa_id,
            destino=pedido.telefone_cliente or "",
            tipo="pedido",
            status_evento=new_status,
            contexto={
                "nome_cliente": pedido.nome_cliente or "",
                "pedido_id": pedido.id,
                "total": pedido.total or 0,
                "empresa_nome": empresa.nome if empresa else "",
            },
        )
        db.commit()
        return {"message": "Status atualizado"}
    except OrderValidationError as error:
        db.rollback()
        return JSONResponse({"error": str(error)}, status_code=error.status_code)
    except HTTPException:
        db.rollback()
        raise
    except Exception as error:
        db.rollback()
        print("ERRO AO ATUALIZAR STATUS DO PEDIDO:", repr(error))
        return JSONResponse({"error": "Não foi possível atualizar o pedido."}, status_code=500)
    finally:
        db.close()


@app.post("/pedidos/{pedido_id}/confirmar-pagamento-manual")
def confirmar_pagamento_manual_pedido(pedido_id: int, request: Request):
    """Confirma Pix pela chave sem envolver o Mercado Pago.

    O pedido fica retido em aguardando_pagamento até o estabelecimento
    conferir o recebimento. Somente esta ação transforma o hold em pedido
    operacional, atribui o número diário e dispara as notificações.
    """
    db = SessionLocal()
    try:
        pedido = db.query(Pedido).filter(Pedido.id == pedido_id).first()
        if not pedido:
            return JSONResponse({"error": "Pedido não encontrado."}, status_code=404)

        origem_pedido = normalize_order_value(getattr(pedido, "origem_menu", None))
        area_pedido = "produtos" if origem_pedido == "produto" else "pedidos"
        exigir_admin_empresa_api(request, pedido.empresa_id, area_pedido)

        metodo = normalize_order_value(getattr(pedido, "pagamento", None))
        gateway = normalize_order_value(getattr(pedido, "gateway_pagamento", None))
        if metodo not in {"pix pela chave", "pix manual", "pix_manual", "pix chave", "pix_chave"} and gateway != "pix_manual":
            return JSONResponse({"error": "Este pedido não usa Pix pela chave."}, status_code=400)

        atual = normalize_order_value(getattr(pedido, "status_pagamento", None))
        if atual == "pago":
            return {
                "ok": True,
                "status": pedido.status,
                "status_pagamento": pedido.status_pagamento,
                "numero_dia": pedido.numero_dia,
            }
        if atual in {"cancelado", "recusado", "erro", "expirado"}:
            return JSONResponse({"error": "Este pagamento manual já foi encerrado."}, status_code=409)

        empresa = db.query(Empresa).filter(Empresa.id == pedido.empresa_id).first()
        if not empresa:
            return JSONResponse({"error": "Empresa não encontrada."}, status_code=404)

        pedido.status_pagamento = "pago"
        pedido.status = "novo"
        pedido.gateway_pagamento = "pix_manual"
        pedido.gateway_status = "manual_approved"
        pedido.gateway_status_detail = "pix_key_confirmed_by_admin"
        pedido.pago_em = agora_brasilia()
        _pedido_approved_callback(db, empresa, pedido)()
        db.commit()
        db.refresh(pedido)
        return {
            "ok": True,
            "status": pedido.status,
            "status_pagamento": pedido.status_pagamento,
            "numero_dia": pedido.numero_dia,
            "message": "Pix confirmado. Pedido liberado para operação.",
        }
    except HTTPException:
        db.rollback()
        raise
    except Exception:
        db.rollback()
        LOGGER.exception("Falha ao confirmar Pix manual do pedido %s", pedido_id)
        return JSONResponse({"error": "Não foi possível confirmar o pagamento."}, status_code=500)
    finally:
        db.close()


@app.post("/admin/{empresa_id}/mesas/finalizar")
async def finalizar_mesa_admin(
    empresa_id: int,
    request: Request
):
    """Fecha uma mesa pelo painel administrativo.
    Atualiza todos os pedidos abertos informados para finalizado e registra a forma
    de pagamento escolhida no fechamento da mesa.
    """
    exigir_admin_empresa_api(request, empresa_id)

    try:
        dados = await request.json()
    except Exception:
        return {"error": "Dados inválidos para finalizar a mesa."}

    ids = dados.get("pedido_ids") or []
    if not isinstance(ids, list):
        return {"error": "Lista de pedidos inválida."}

    try:
        ids = [int(x) for x in ids if str(x).strip()]
    except Exception:
        return {"error": "Pedidos inválidos."}

    if not ids:
        return {"error": "Nenhum pedido aberto encontrado para finalizar."}

    pagamento = str(dados.get("pagamento") or "").strip() or "Não informado"
    pagamentos_validos = {"Dinheiro", "Cartão", "Outro", "Não informado"}
    if pagamento not in pagamentos_validos:
        pagamento = "Outro"

    valor_recebido = dados.get("valor_recebido")
    troco = dados.get("troco")
    observacao_fechamento = str(dados.get("observacao") or "").strip()

    db = SessionLocal()
    try:
        pedidos = db.query(Pedido).filter(
            Pedido.empresa_id == empresa_id,
            Pedido.id.in_(ids),
            Pedido.status != "cancelado",
            Pedido.status != "finalizado"
        ).all()

        if not pedidos:
            db.close()
            return {"error": "Nenhum pedido aberto encontrado para finalizar."}

        total = Decimal("0.00")
        for pedido in pedidos:
            total += moeda(getattr(pedido, "total", 0) or 0)
            pedido.status = "finalizado"
            pedido.pagamento = pagamento

            obs_atual = getattr(pedido, "observacao", None) or ""
            linhas = [obs_atual.strip()] if obs_atual.strip() else []
            detalhes = [f"Fechamento da mesa: pagamento {pagamento}"]
            if valor_recebido not in (None, ""):
                detalhes.append(f"valor recebido R$ {moeda(valor_recebido):.2f}")
            if troco not in (None, ""):
                detalhes.append(f"troco R$ {moeda(troco):.2f}")
            if observacao_fechamento:
                detalhes.append(observacao_fechamento)
            linhas.append("[" + " · ".join(detalhes) + "]")
            pedido.observacao = "\n".join(linhas)

        db.commit()
        qtd = len(pedidos)
        db.close()

        return {
            "ok": True,
            "message": "Mesa finalizada com sucesso.",
            "pedidos_finalizados": qtd,
            "total": float(total),
            "pagamento": pagamento
        }
    except Exception as erro:
        db.rollback()
        db.close()
        return {"error": str(erro)}




def normalizar_data_reserva(valor: str) -> str:
    if not valor:
        return valor

    valor = str(valor).strip()

    try:
        if "/" in valor:
            return datetime.strptime(valor, "%d/%m/%Y").strftime("%Y-%m-%d")

        return datetime.strptime(valor, "%Y-%m-%d").strftime("%Y-%m-%d")
    except ValueError:
        return valor


def garantir_tokens_publicos_reservas(db, reservas) -> bool:
    """Cria tokens somente para reservas antigas que ainda não possuem link público.

    V922: o commit não pode expirar os objetos ORM já carregados na mesma
    requisição. A Agenda renderiza esses objetos depois de fechar a sessão; com
    ``expire_on_commit=True`` uma reserva antiga sem token podia provocar erro
    500 intermitente no primeiro acesso ao Admin.
    """
    alterado = False
    for reserva in reservas or []:
        if not str(getattr(reserva, "public_token", None) or "").strip():
            reserva.public_token = secrets.token_urlsafe(32)
            alterado = True
    if alterado:
        expire_on_commit_original = getattr(db, "expire_on_commit", True)
        try:
            db.expire_on_commit = False
            db.commit()
        finally:
            db.expire_on_commit = expire_on_commit_original
    return alterado


STATUS_RESERVA_SEM_OCUPAR_HORARIO = {
    "cancelada", "cancelado", "recusada", "recusado",
    "expirada", "expirado", "concluida", "concluido",
    "concluída", "concluído", "paga", "pago",
}


def status_reserva_chave(valor) -> str:
    texto = str(valor or "").strip().lower()
    return unicodedata.normalize("NFD", texto).encode("ascii", "ignore").decode("ascii").replace(" ", "_")


def reserva_ocupa_horario(reserva: Reserva) -> bool:
    if bool(getattr(reserva, "horario_liberado", False)):
        return False
    return status_reserva_chave(getattr(reserva, "status", "")) not in {
        "cancelada", "cancelado", "recusada", "recusado", "expirada", "expirado",
        "concluida", "concluido", "paga", "pago",
        "pagamento_recusado", "pagamento_cancelado",
    }


def _instante_reserva(reserva: Reserva):
    """Converte data e hora da reserva em datetime operacional de Brasília."""
    try:
        data_texto = normalizar_data_reserva(str(getattr(reserva, "data", "") or ""))
        hora_texto = str(getattr(reserva, "horario", "") or "").split(" - ", 1)[0].strip()[:5]
        return datetime.strptime(f"{data_texto} {hora_texto}", "%Y-%m-%d %H:%M")
    except Exception:
        return None


def _instante_horario(data_valor, horario_valor):
    """Retorna o instante de um slot no relógio operacional de Brasília."""
    try:
        data_texto = normalizar_data_reserva(str(data_valor or ""))
        hora_texto = str(horario_valor or "").split(" - ", 1)[0].strip()[:5]
        return datetime.strptime(f"{data_texto} {hora_texto}", "%Y-%m-%d %H:%M")
    except Exception:
        return None


def horario_ainda_futuro(data_valor, horario_valor, agora=None) -> bool:
    """Verdadeiro apenas quando o slot ainda não passou em Brasília."""
    instante = _instante_horario(data_valor, horario_valor)
    if instante is None:
        return False
    return instante > (agora or agora_brasilia())


def normalizar_agendamentos_passados(db, empresa_id: int | None = None) -> int:
    """Atualiza automaticamente agendamentos cujo horário já passou.

    * Pendente -> Expirado.
    * Confirmado -> Aguardando conclusão.

    A rotina não apaga registros e não recria vagas antigas como livres.
    """
    status_normalizado = func.lower(func.trim(func.replace(func.coalesce(Reserva.status, ""), " ", "_")))
    consulta = db.query(Reserva).filter(
        status_normalizado.in_([
            "pendente", "pending", "in_attesa",
            "aguardando_pagamento", "aguardando_sinal",
            "confirmada", "confirmado", "confirmed", "confermata",
        ])
    )
    if empresa_id is not None:
        consulta = consulta.filter(Reserva.empresa_id == empresa_id)

    agora = agora_brasilia()
    alteradas = 0
    tipos_empresa = {}
    for reserva in consulta.all():
        instante = _instante_reserva(reserva)
        if not instante or instante > agora:
            continue
        status_atual = str(getattr(reserva, "status", "") or "").strip().lower()
        status_chave = status_reserva_chave(status_atual)
        if status_chave in {"pendente", "pending", "in_attesa", "aguardando_pagamento", "aguardando_sinal"}:
            reserva.status = "expirada"
            reserva.gateway_status = "expired_automatically_brasilia"
            reserva.horario_liberado = False
            alteradas += 1
        elif status_chave in {"confirmada", "confirmado", "confirmed", "confermata"}:
            if reserva.empresa_id not in tipos_empresa:
                empresa_reserva = db.query(Empresa).filter(Empresa.id == reserva.empresa_id).first()
                tipos_empresa[reserva.empresa_id] = getattr(empresa_reserva, "tipo", "") if empresa_reserva else ""
            if tipo_negocio_servico(tipos_empresa.get(reserva.empresa_id, "")):
                reserva.status = "aguardando_conclusao"
                reserva.horario_liberado = False
                alteradas += 1

    if alteradas:
        db.commit()
    return alteradas


def expirar_reservas_pendentes_antigas(db, empresa_id: int | None = None) -> int:
    """Compatibilidade: normaliza todos os agendamentos passados em Brasília."""
    return normalizar_agendamentos_passados(db, empresa_id)


def expirar_holds_pagamento_online_reservas(db, empresa) -> int:
    """
    V903 — limpa holds de pagamento online abandonados sem transformá-los em
    agendamentos operacionais. O slot fica protegido apenas durante o prazo de
    pagamento configurado; ao vencer, reconciliamos/cancelamos no gateway e
    liberamos o horário com segurança.
    """
    if not empresa:
        return 0

    try:
        prazo_minutos = int(getattr(empresa, "sinal_prazo_minutos", 30) or 30)
    except (TypeError, ValueError):
        prazo_minutos = 30
    prazo_minutos = max(5, min(prazo_minutos, 120))
    limite = agora_brasilia() - timedelta(minutes=prazo_minutos)

    status_reserva = func.lower(func.trim(func.replace(func.coalesce(Reserva.status, ""), " ", "_")))
    status_pagamento = func.lower(func.trim(func.replace(func.coalesce(Reserva.status_pagamento, ""), " ", "_")))

    holds = db.query(Reserva).filter(
        Reserva.empresa_id == empresa.id,
        Reserva.criado_em <= limite,
        status_reserva == "aguardando_pagamento",
        status_pagamento.in_(["pendente", "aguardando_pagamento"]),
        func.lower(func.trim(func.coalesce(Reserva.gateway_pagamento, ""))) == "mercadopago",
    ).all()

    alteradas = 0
    for reserva in holds:
        try:
            # Se existe uma cobrança, primeiro perguntamos ao Mercado Pago.
            # Um pagamento aprovado nunca pode ser descartado por timeout local.
            if str(getattr(reserva, "gateway_payment_id", "") or "").strip():
                _cancelar_tentativa_gateway_v894(
                    db,
                    empresa,
                    reserva,
                    "reserva",
                    on_approved=_reserva_approved_callback(db, empresa, reserva),
                )
                if normalize_order_value(getattr(reserva, "status_pagamento", None)) == "pago":
                    continue

            reserva.status = "expirada"
            reserva.status_pagamento = "expirado"
            if not str(getattr(reserva, "gateway_status", "") or "").strip():
                reserva.gateway_status = "expired"
            reserva.gateway_status_detail = f"payment_hold_timeout_{prazo_minutos}m"
            reserva.horario_liberado = True
            alteradas += 1
        except PaymentError as error:
            # 409 pode significar que o pagamento acabou de ser aprovado durante
            # a reconciliação. Em qualquer outra incerteza de gateway, mantemos
            # o hold e tentamos novamente numa próxima consulta, sem risco de
            # liberar um horário já pago.
            if normalize_order_value(getattr(reserva, "status_pagamento", None)) == "pago":
                continue
            LOGGER.warning(
                "V903 não conseguiu expirar hold da reserva %s com segurança: %s",
                reserva.id,
                error,
            )

    if alteradas:
        db.commit()
    return alteradas


