@app.patch("/reservas/{reserva_id}/editar")
def editar_reserva_agenda(
    reserva_id: int,
    dados: ReservaEditarUpdate,
    request: Request
):
    db = SessionLocal()
    reserva = db.query(Reserva).filter(Reserva.id == reserva_id).first()
    if not reserva:
        db.close()
        return {"error": "Agendamento não encontrado"}

    exigir_admin_empresa_api(request, reserva.empresa_id, "reservas")

    data_nova = normalizar_data_reserva(dados.data)
    try:
        datetime.strptime(data_nova, "%Y-%m-%d")
    except Exception:
        db.close()
        return {"error": "Data inválida"}

    horario_novo = str(dados.horario or "").strip()
    try:
        datetime.strptime(horario_novo, "%H:%M")
    except Exception:
        db.close()
        return {"error": "Horário inválido"}

    if not horario_ainda_futuro(data_nova, horario_novo):
        db.close()
        return {"error": "Escolha um horário futuro no horário de Brasília."}

    profissional = None
    if dados.profissional_id:
        profissional = db.query(Profissional).filter(
            Profissional.id == dados.profissional_id,
            Profissional.empresa_id == reserva.empresa_id
        ).first()
        if not profissional:
            db.close()
            return {"error": "Profissional não encontrado"}

    horario_slot = db.query(HorarioReserva).filter(
        HorarioReserva.empresa_id == reserva.empresa_id,
        HorarioReserva.data == data_nova,
        HorarioReserva.horario == horario_novo,
        HorarioReserva.profissional_id == (dados.profissional_id or None)
    ).first()
    if not horario_slot:
        db.close()
        return {"error": "Esse horário não está cadastrado para o profissional e a data escolhidos"}

    if dados.servico_id:
        servico = db.query(Item).filter(
            Item.id == dados.servico_id,
            Item.empresa_id == reserva.empresa_id,
            Item.disponivel == True
        ).first()
        if not servico:
            db.close()
            return {"error": "Serviço não encontrado"}
        preco_br = f"{float(servico.preco or 0):,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
        obs_antiga = str(reserva.observacao or "")
        marcador = ""
        achou = re.search(r"FINANCEIRO_SERVICO.*", obs_antiga, flags=re.I)
        if achou:
            marcador = achou.group(0).strip()
        reserva.observacao = f"{servico.nome} — R$ {preco_br}" + (f"\n{marcador}" if marcador else "")

    reserva.data = data_nova
    reserva.horario = horario_novo
    reserva.profissional_id = dados.profissional_id or None
    reserva.horario_id = horario_slot.id
    try:
        reserva.data_operacional = datetime.strptime(data_nova, "%Y-%m-%d").date()
    except Exception:
        pass

    db.commit()
    db.refresh(reserva)
    resposta = {
        "ok": True,
        "id": reserva.id,
        "data": reserva.data,
        "horario": reserva.horario,
        "profissional_id": reserva.profissional_id,
        "profissional": profissional.nome if profissional else "",
        "servico": reserva.observacao or ""
    }
    db.close()
    return resposta


@app.patch("/reservas/{reserva_id}/status")
def atualizar_status_reserva(
    reserva_id: int,
    dados: ReservaStatusUpdate,
    request: Request
):
    db = SessionLocal()

    reserva = db.query(Reserva).filter(
        Reserva.id == reserva_id
    ).first()

    if not reserva:
        db.close()
        return {"error": "Reserva não encontrada"}

    exigir_admin_empresa_api(request, reserva.empresa_id, "reservas")

    status_recebido = (dados.status or "").strip().lower()
    mapa_status = {
        "confirmado": "confirmada",
        "confirmada": "confirmada",
        "pendente": "pendente",
        "cancelado": "cancelada",
        "cancelada": "cancelada",
        "recusado": "recusada",
        "recusada": "recusada",
        "concluir": "concluida",
        "concluído": "concluida",
        "concluido": "concluida",
        "concluida": "concluida",
        "finalizado": "concluida",
        "finalizada": "concluida",
        "pago": "concluida",
        "paga": "concluida",
        "pagamento": "concluida",
        "expirado": "expirada",
        "expirada": "expirada",
        "aguardando conclusão": "aguardando_conclusao",
        "aguardando_conclusao": "aguardando_conclusao",
    }

    novo_status = mapa_status.get(status_recebido, status_recebido)

    if novo_status not in ["pendente", "confirmada", "aguardando_conclusao", "concluida", "cancelada", "recusada", "expirada"]:
        db.close()
        return {"error": "Status inválido"}

    empresa_status = db.query(Empresa).filter(Empresa.id == reserva.empresa_id).first()
    status_atual = str(getattr(reserva, "status", "") or "").strip().lower()
    pagamento_atual = normalize_order_value(getattr(reserva, "status_pagamento", None))
    gateway_atual = str(getattr(reserva, "gateway_pagamento", "") or "").strip().lower()
    hold_online = (
        status_atual == "aguardando_pagamento"
        and pagamento_atual in {"pendente", "aguardando_pagamento"}
        and gateway_atual == "mercadopago"
    )
    hold_sinal_manual = (
        status_atual == "aguardando_pagamento"
        and pagamento_atual in {"pendente", "aguardando_pagamento", "comprovante_enviado"}
        and gateway_atual == "pix_manual"
        and float(getattr(reserva, "valor_sinal_recebido", 0) or 0)
            + 0.005 < float(getattr(reserva, "valor_sinal", 0) or 0)
    )
    if (
        hold_online
        and bool(getattr(empresa_status, "pedido_so_apos_pagamento", False))
        and novo_status in {"confirmada", "aguardando_conclusao", "concluida"}
    ):
        db.close()
        return {"error": "Este horário está apenas reservado para pagamento. Aguarde a confirmação do Mercado Pago ou cancele a tentativa."}
    if hold_sinal_manual and novo_status in {"confirmada", "aguardando_conclusao", "concluida"}:
        db.close()
        return {"error": "Confirme o recebimento do sinal por Pix antes de confirmar ou finalizar este agendamento."}

    reserva.status = novo_status
    reserva.horario_liberado = False

    # Salva primeiro no banco. Assim, se o WhatsApp falhar,
    # a reserva não volta para pendente após atualizar a página.
    db.commit()
    db.refresh(reserva)

    # WhatsApp é efeito secundário: não pode desfazer o status da reserva.
    empresa = db.query(Empresa).filter(Empresa.id == reserva.empresa_id).first()

    try:
        enviar_whatsapp_automatico_evento(
            db=db,
            empresa_id=reserva.empresa_id,
            destino=getattr(reserva, "telefone_cliente", ""),
            tipo="reserva",
            status_evento=novo_status,
            contexto={
                "nome_cliente": getattr(reserva, "nome_cliente", ""),
                "codigo": getattr(reserva, "codigo", ""),
                "data": getattr(reserva, "data", ""),
                "horario": getattr(reserva, "horario", ""),
                "empresa_nome": getattr(empresa, "nome", "") if empresa else ""
            }
        )
        db.commit()
    except Exception as erro_whatsapp:
        db.rollback()
        print("Aviso: status da reserva salvo, mas WhatsApp da reserva falhou:", erro_whatsapp)

    db.close()

    return {
        "message": "Status da reserva atualizado",
        "id": reserva_id,
        "status": novo_status
    }


@app.post("/reservas/{reserva_id}/liberar-horario")
def liberar_horario_reserva_admin(reserva_id: int, request: Request):
    db = SessionLocal()
    try:
        reserva = db.query(Reserva).filter(Reserva.id == reserva_id).first()
        if not reserva:
            return {"error": "Reserva não encontrada."}

        exigir_admin_empresa_api(request, reserva.empresa_id, "reservas")
        status = str(reserva.status or "pendente").strip().lower()
        permitidos = {"cancelada", "cancelado", "recusada", "recusado", "expirada", "expirado"}
        if status not in permitidos:
            return {"error": "O horário só pode ser liberado após cancelar, recusar ou expirar a reserva."}

        horario_futuro = horario_ainda_futuro(reserva.data, reserva.horario)
        reserva.horario_liberado = True
        db.commit()
        return {
            "ok": True,
            "message": (
                "Horário liberado e disponível novamente no menu público."
                if horario_futuro
                else "Registro mantido somente no histórico; o horário passado não volta à agenda."
            ),
            "horario_liberado": True,
            "horario_futuro": horario_futuro,
        }
    except Exception:
        db.rollback()
        raise
    finally:
        db.close()


def _contexto_resposta_publica_reserva(db, reserva_id: int, token: str):
    reserva = db.query(Reserva).filter(Reserva.id == reserva_id).first()
    esperado = str(getattr(reserva, "public_token", None) or "").strip() if reserva else ""
    informado = str(token or "").strip()
    if not reserva or not esperado or not informado or not hmac.compare_digest(esperado, informado):
        return None

    empresa = db.query(Empresa).filter(Empresa.id == reserva.empresa_id).first()
    profissional = None
    if getattr(reserva, "profissional_id", None):
        profissional = db.query(Profissional).filter(
            Profissional.id == reserva.profissional_id,
            Profissional.empresa_id == reserva.empresa_id
        ).first()

    data_br = str(reserva.data or "")
    try:
        data_br = datetime.strptime(data_br, "%Y-%m-%d").strftime("%d-%m-%Y")
    except ValueError:
        pass

    negocio_servico = tipo_negocio_servico(getattr(empresa, "tipo", "") if empresa else "")
    return {
        "reserva": reserva,
        "empresa": empresa,
        "profissional": profissional,
        "data_br": data_br,
        "negocio_servico": negocio_servico,
    }


@app.get("/reserva/{reserva_id}/responder")
def resposta_publica_reserva(
    reserva_id: int,
    request: Request,
    token: str = "",
    acao: str = "confirmar",
    resultado: str = ""
):
    db = SessionLocal()
    try:
        contexto = _contexto_resposta_publica_reserva(db, reserva_id, token)
        if not contexto:
            return templates.TemplateResponse(
                request=request,
                name="reserva_resposta_publica.html",
                context={"erro": "Este link é inválido ou não está mais disponível."},
                status_code=403
            )
        status_atual = str(contexto["reserva"].status or "pendente").strip().lower()
        contexto.update({
            "token": token,
            "acao": "cancelar" if str(acao).lower() == "cancelar" else "confirmar",
            "resultado": str(resultado or "").lower(),
            "resposta_bloqueada": status_atual in {
                "cancelada", "cancelado", "recusada", "recusado",
                "concluida", "concluída", "concluído", "concluido", "paga", "pago"
            },
            "erro": "",
        })
        return templates.TemplateResponse(
            request=request,
            name="reserva_resposta_publica.html",
            context=contexto
        )
    finally:
        db.close()


@app.post("/reserva/{reserva_id}/responder")
async def processar_resposta_publica_reserva(
    reserva_id: int,
    request: Request,
    token: str = ""
):
    corpo = (await request.body()).decode("utf-8", errors="ignore")
    formulario = parse_qs(corpo, keep_blank_values=True)
    acao_recebida = (formulario.get("acao") or [""])[0]
    acao = "cancelar" if str(acao_recebida).lower() == "cancelar" else "confirmar"
    db = SessionLocal()
    try:
        contexto = _contexto_resposta_publica_reserva(db, reserva_id, token)
        if not contexto:
            return templates.TemplateResponse(
                request=request,
                name="reserva_resposta_publica.html",
                context={"erro": "Este link é inválido ou não está mais disponível."},
                status_code=403
            )

        reserva = contexto["reserva"]
        status_atual = str(reserva.status or "pendente").strip().lower()
        bloqueados = {"concluida", "concluída", "concluído", "concluido", "paga", "pago", "recusada", "recusado"}

        if acao == "cancelar":
            if status_atual in bloqueados:
                resultado = "indisponivel"
            else:
                reserva.status = "cancelada"
                resultado = "cancelada"
                db.commit()
        else:
            if status_atual in bloqueados or status_atual in {"cancelada", "cancelado"}:
                resultado = "indisponivel"
            else:
                reserva.status = "confirmada"
                resultado = "confirmada"
                db.commit()

        destino = (
            f"/reserva/{reserva_id}/responder?token={quote_plus(token)}"
            f"&acao={acao}&resultado={resultado}"
        )
        return RedirectResponse(url=destino, status_code=303)
    finally:
        db.close()


def contar_horarios_profissional(db, profissional_id: int, data_agenda: str | None = None):
    consulta = db.query(HorarioReserva).filter(
        HorarioReserva.profissional_id == profissional_id,
        HorarioReserva.ativo == True
    )
    if data_agenda:
        consulta = consulta.filter(HorarioReserva.data == data_agenda)
    return consulta.count()


