@app.get("/empresas/{empresa_id}/profissionais")
def listar_profissionais(empresa_id: int):
    """Lista profissionais ativos da empresa para o menu público e admin."""
    db = SessionLocal()

    empresa = db.query(Empresa).filter(
        Empresa.id == empresa_id
    ).first()

    if not empresa:
        db.close()
        return {"error": "Empresa não encontrada"}

    profissionais = db.query(Profissional).filter(
        Profissional.empresa_id == empresa_id,
        Profissional.ativo == True
    ).order_by(Profissional.nome.asc()).all()

    contagens = dict(
        db.query(HorarioReserva.profissional_id, func.count(HorarioReserva.id))
        .filter(
            HorarioReserva.empresa_id == empresa_id,
            HorarioReserva.ativo == True,
            HorarioReserva.profissional_id != None
        )
        .group_by(HorarioReserva.profissional_id)
        .all()
    )

    resultado = [
        {
            "id": profissional.id,
            "empresa_id": profissional.empresa_id,
            "nome": profissional.nome,
            "telefone": profissional.telefone,
            "foto_url": profissional.foto_url,
            "ativo": profissional.ativo,
            "horarios_salvos": int(contagens.get(profissional.id, 0) or 0)
        }
        for profissional in profissionais
    ]

    db.close()
    return {"profissionais": resultado}


@app.post("/profissionais")
def criar_profissional(dados: ProfissionalCreate, request: Request):
    exigir_admin_empresa_api(request, dados.empresa_id, "reservas")
    db = SessionLocal()
    try:
        nome = (dados.nome or "").strip()
        if not nome:
            return JSONResponse({"error": "Informe o nome do profissional"}, status_code=400)

        existente = db.query(Profissional).filter(
            Profissional.empresa_id == dados.empresa_id,
            func.lower(func.trim(Profissional.nome)) == nome.lower()
        ).first()

        if existente:
            if not existente.ativo:
                permitido_saas, mensagem_saas, codigo_saas = validar_novo_profissional_saas(db, dados.empresa_id)
                if not permitido_saas:
                    return JSONResponse({"error": mensagem_saas, "code": "limite_profissionais"}, status_code=codigo_saas)
            existente.ativo = True
            existente.nome = nome
            if dados.telefone is not None:
                existente.telefone = dados.telefone
            if dados.foto_url is not None:
                existente.foto_url = dados.foto_url
            db.commit()
            db.refresh(existente)
            return {
                "message": "Profissional atualizado e ativado",
                "id": existente.id,
                "nome": existente.nome,
                "existente": True,
                "horarios_salvos": contar_horarios_profissional(db, existente.id)
            }

        permitido_saas, mensagem_saas, codigo_saas = validar_novo_profissional_saas(db, dados.empresa_id)
        if not permitido_saas:
            return JSONResponse({"error": mensagem_saas, "code": "limite_profissionais"}, status_code=codigo_saas)

        profissional = Profissional(
            empresa_id=dados.empresa_id,
            nome=nome,
            telefone=dados.telefone,
            foto_url=dados.foto_url,
            ativo=True
        )
        db.add(profissional)
        db.commit()
        db.refresh(profissional)
        return {
            "message": "Profissional criado com sucesso",
            "id": profissional.id,
            "nome": profissional.nome,
            "horarios_salvos": 0
        }
    except Exception as erro:
        db.rollback()
        LOGGER.exception("Erro ao salvar profissional da empresa %s", dados.empresa_id)
        return JSONResponse({"error": f"Não foi possível salvar o profissional: {erro}"}, status_code=500)
    finally:
        db.close()


@app.patch("/profissionais/{profissional_id}")
def atualizar_profissional(
    profissional_id: int,
    dados: ProfissionalUpdate,
    request: Request
):
    db = SessionLocal()

    profissional = db.query(Profissional).filter(
        Profissional.id == profissional_id
    ).first()

    if not profissional:
        db.close()
        return {"error": "Profissional não encontrado"}

    exigir_admin_empresa_api(request, profissional.empresa_id, "reservas")

    if dados.nome is not None:
        nome = dados.nome.strip()
        if not nome:
            db.close()
            return {"error": "Informe o nome do profissional"}
        profissional.nome = nome

    if dados.telefone is not None:
        profissional.telefone = dados.telefone

    if dados.foto_url is not None:
        profissional.foto_url = dados.foto_url

    if dados.ativo is not None:
        if bool(dados.ativo) and not bool(profissional.ativo):
            permitido_saas, mensagem_saas, codigo_saas = validar_novo_profissional_saas(db, profissional.empresa_id)
            if not permitido_saas:
                db.close()
                return JSONResponse({"error": mensagem_saas, "code": "limite_profissionais"}, status_code=codigo_saas)
        profissional.ativo = dados.ativo

    db.commit()
    db.close()

    return {"message": "Profissional atualizado com sucesso"}


@app.delete("/profissionais/{profissional_id}")
def deletar_profissional(profissional_id: int, request: Request):
    """Remoção segura: desativa o profissional, sem apagar histórico."""
    db = SessionLocal()

    profissional = db.query(Profissional).filter(
        Profissional.id == profissional_id
    ).first()

    if not profissional:
        db.close()
        return {"error": "Profissional não encontrado"}

    exigir_admin_empresa_api(request, profissional.empresa_id, "reservas")

    profissional.ativo = False
    db.commit()
    db.close()

    return {"message": "Profissional removido da agenda sem apagar histórico"}


# ==================================================
# HORÁRIOS DE RESERVA
# ==================================================

def normalizar_data_agenda(valor: str):
    texto_data = str(valor or "").strip()
    try:
        return datetime.strptime(texto_data, "%Y-%m-%d").strftime("%Y-%m-%d")
    except ValueError:
        return None


def normalizar_horario_agenda(valor: str):
    texto_hora = str(valor or "").strip().split(" - ", 1)[0].strip()
    try:
        return datetime.strptime(texto_hora, "%H:%M").strftime("%H:%M")
    except ValueError:
        return None


@app.post("/horarios-reserva")
def criar_horario_reserva(dados: HorarioReservaCreate, request: Request):
    exigir_admin_empresa_api(request, dados.empresa_id, "reservas")
    data_agenda = normalizar_data_agenda(dados.data)
    horario_agenda = normalizar_horario_agenda(dados.horario)
    if not data_agenda or not horario_agenda:
        return JSONResponse({"error": "Informe data e horário válidos."}, status_code=400)
    try:
        data_obj = datetime.strptime(data_agenda, "%Y-%m-%d").date()
    except ValueError:
        return JSONResponse({"error": "Informe uma data válida."}, status_code=400)
    if data_obj < hoje_brasilia():
        return JSONResponse({"error": "Não é possível cadastrar horários em dias anteriores."}, status_code=400)
    if data_obj == hoje_brasilia() and not horario_ainda_futuro(data_agenda, horario_agenda):
        return JSONResponse({"error": "Este horário já passou no horário de Brasília."}, status_code=400)

    db = SessionLocal()
    try:
        profissional_id = getattr(dados, "profissional_id", None)
        if profissional_id:
            profissional = db.query(Profissional).filter(
                Profissional.id == profissional_id,
                Profissional.empresa_id == dados.empresa_id,
                Profissional.ativo == True
            ).first()
            if not profissional:
                return JSONResponse({"error": "Profissional não encontrado ou inativo"}, status_code=404)

        consulta = db.query(HorarioReserva).filter(
            HorarioReserva.empresa_id == dados.empresa_id,
            HorarioReserva.data == data_agenda,
            HorarioReserva.horario == horario_agenda,
            HorarioReserva.profissional_id == profissional_id
        )
        existente = consulta.first()
        capacidade = max(1, int(getattr(dados, "capacidade_maxima", None) or 1))
        if existente:
            existente.ativo = True
            existente.capacidade_maxima = capacidade
            db.commit()
            return {"message": "Horário reativado e atualizado", "id": existente.id, "reativado": True}

        novo = HorarioReserva(
            empresa_id=dados.empresa_id,
            data=data_agenda,
            horario=horario_agenda,
            profissional_id=profissional_id,
            ativo=True,
            capacidade_maxima=capacidade
        )
        db.add(novo)
        db.commit()
        db.refresh(novo)
        return {"message": "Horário criado com sucesso", "id": novo.id}
    except Exception as erro:
        db.rollback()
        LOGGER.exception("Erro ao criar horário da empresa %s", dados.empresa_id)
        return JSONResponse({"error": f"Não foi possível salvar o horário: {erro}"}, status_code=500)
    finally:
        db.close()


@app.post("/horarios-reserva/salvar-lote")
def salvar_horarios_reserva_lote(dados: HorariosAgendaLote, request: Request):
    """Salva profissional e agenda juntos, sem copiar horários de outros cadastros."""
    exigir_admin_empresa_api(request, dados.empresa_id, "reservas")
    data_agenda = normalizar_data_agenda(dados.data)
    if not data_agenda:
        return JSONResponse({"error": "Informe uma data válida."}, status_code=400)
    data_obj = datetime.strptime(data_agenda, "%Y-%m-%d").date()
    if data_obj < hoje_brasilia():
        return JSONResponse({"error": "Não é possível cadastrar horários em dias anteriores."}, status_code=400)

    horarios_informados = []
    for valor in dados.horarios or []:
        horario = normalizar_horario_agenda(valor)
        if horario and horario not in horarios_informados:
            horarios_informados.append(horario)

    agora_operacional = agora_brasilia()
    horarios = [
        horario for horario in horarios_informados
        if data_obj > hoje_brasilia() or horario_ainda_futuro(data_agenda, horario, agora_operacional)
    ]
    horarios_ignorados = len(horarios_informados) - len(horarios)
    if not horarios:
        mensagem = (
            "Todos os horários informados já passaram no horário de Brasília."
            if horarios_informados and data_obj == hoje_brasilia()
            else "Selecione pelo menos um horário válido."
        )
        return JSONResponse({"error": mensagem}, status_code=400)

    db = SessionLocal()
    try:
        profissional = None
        if dados.profissional_id:
            profissional = db.query(Profissional).filter(
                Profissional.id == dados.profissional_id,
                Profissional.empresa_id == dados.empresa_id
            ).first()
        if not profissional and (dados.nome_profissional or "").strip():
            nome = dados.nome_profissional.strip()
            profissional = db.query(Profissional).filter(
                Profissional.empresa_id == dados.empresa_id,
                func.lower(func.trim(Profissional.nome)) == nome.lower()
            ).first()
            if not profissional:
                permitido_saas, mensagem_saas, codigo_saas = validar_novo_profissional_saas(db, dados.empresa_id)
                if not permitido_saas:
                    return JSONResponse({"error": mensagem_saas, "code": "limite_profissionais"}, status_code=codigo_saas)
                profissional = Profissional(empresa_id=dados.empresa_id, nome=nome, ativo=True)
                db.add(profissional)
                db.flush()
            profissional.nome = nome
        if not profissional:
            return JSONResponse({"error": "Escolha um profissional válido."}, status_code=400)

        if not bool(profissional.ativo):
            permitido_saas, mensagem_saas, codigo_saas = validar_novo_profissional_saas(db, dados.empresa_id)
            if not permitido_saas:
                return JSONResponse({"error": mensagem_saas, "code": "limite_profissionais"}, status_code=codigo_saas)
        profissional.ativo = True
        if dados.telefone_profissional is not None:
            profissional.telefone = dados.telefone_profissional
        if dados.foto_profissional is not None:
            profissional.foto_url = dados.foto_profissional

        capacidade = max(1, int(dados.capacidade_maxima or 1))
        existentes = db.query(HorarioReserva).filter(
            HorarioReserva.empresa_id == dados.empresa_id,
            HorarioReserva.data == data_agenda,
            HorarioReserva.profissional_id == profissional.id
        ).all()

        reservas_ativas = db.query(Reserva).filter(
            Reserva.empresa_id == dados.empresa_id,
            Reserva.data == data_agenda,
            Reserva.profissional_id == profissional.id,
            func.lower(func.trim(Reserva.status)).notin_(["cancelada", "cancelado", "recusada", "recusado", "expirada", "expirado", "concluida", "concluido", "concluída", "concluído", "paga", "pago", "pagamento_recusado", "pagamento_cancelado"])
        ).all()
        ids_ocupados = {r.horario_id for r in reservas_ativas if getattr(r, "horario_id", None)}
        horas_ocupadas = {normalizar_horario_agenda(r.horario) for r in reservas_ativas}

        por_hora = {}
        for registro in existentes:
            hora_registro = normalizar_horario_agenda(registro.horario)
            if hora_registro:
                por_hora.setdefault(hora_registro, []).append(registro)

        preservados = 0
        desativados = 0
        criados = 0
        reativados = 0
        desejados = set(horarios)
        principais = {}
        for hora_registro, registros in por_hora.items():
            # Prefere como registro principal o que já estiver associado a uma
            # reserva; duplicatas livres antigas são desativadas com segurança.
            registros.sort(key=lambda registro: (registro.id not in ids_ocupados, registro.id))
            registro = registros[0]
            principais[hora_registro] = registro
            for duplicado in registros[1:]:
                duplicado_ocupado = duplicado.id in ids_ocupados
                if duplicado_ocupado:
                    duplicado.ativo = True
                    preservados += 1
                elif duplicado.ativo:
                    duplicado.ativo = False
                    desativados += 1

            ocupado = registro.id in ids_ocupados or hora_registro in horas_ocupadas
            if hora_registro in desejados:
                if not registro.ativo:
                    reativados += 1
                registro.ativo = True
                registro.horario = hora_registro
                registro.capacidade_maxima = capacidade
            elif ocupado:
                registro.ativo = True
                preservados += 1
            elif registro.ativo:
                registro.ativo = False
                desativados += 1

        for horario in horarios:
            if horario in principais:
                continue
            db.add(HorarioReserva(
                empresa_id=dados.empresa_id,
                data=data_agenda,
                horario=horario,
                profissional_id=profissional.id,
                ativo=True,
                capacidade_maxima=capacidade
            ))
            criados += 1

        db.commit()
        total_salvo = contar_horarios_profissional(db, profissional.id, data_agenda)
        return {
            "message": "Agenda salva com sucesso",
            "profissional_id": profissional.id,
            "profissional_nome": profissional.nome,
            "horarios_salvos": total_salvo,
            "horarios_criados": criados,
            "horarios_reativados": reativados,
            "horarios_desativados": desativados,
            "horarios_ocupados_preservados": preservados,
            "horarios_ignorados_por_terem_passado": horarios_ignorados,
            "fuso_horario": "America/Sao_Paulo"
        }
    except Exception as erro:
        db.rollback()
        LOGGER.exception("Erro ao salvar agenda em lote da empresa %s", dados.empresa_id)
        return JSONResponse({"error": f"Não foi possível salvar a agenda: {erro}"}, status_code=500)
    finally:
        db.close()


@app.patch("/horarios-reserva/{horario_id}")
async def editar_horario_reserva_livre(horario_id: int, request: Request):
    """Edita rapidamente uma vaga livre sem alterar horários com reservas ativas."""
    dados = await request.json()
    db = SessionLocal()
    try:
        horario = db.query(HorarioReserva).filter(HorarioReserva.id == horario_id).first()
        if not horario:
            return JSONResponse({"error": "Horário não encontrado."}, status_code=404)

        exigir_admin_empresa_api(request, horario.empresa_id, "reservas")

        consulta_reservas = db.query(Reserva).filter(
            Reserva.empresa_id == horario.empresa_id,
            func.lower(func.trim(Reserva.status)).notin_([
                "cancelada", "cancelado", "recusada", "recusado", "expirada", "expirado",
                "concluida", "concluido", "concluída", "concluído", "paga", "pago"
            ])
        )
        if hasattr(Reserva, "horario_id"):
            consulta_reservas = consulta_reservas.filter(
                or_(
                    Reserva.horario_id == horario.id,
                    and_(
                        Reserva.horario_id == None,
                        Reserva.data == horario.data,
                        Reserva.horario == horario.horario
                    )
                )
            )
        else:
            consulta_reservas = consulta_reservas.filter(
                Reserva.data == horario.data,
                Reserva.horario == horario.horario
            )
        if getattr(horario, "profissional_id", None):
            consulta_reservas = consulta_reservas.filter(Reserva.profissional_id == horario.profissional_id)
        if consulta_reservas.first():
            return JSONResponse({"error": "Este horário possui agendamento ativo e não pode ser editado como livre."}, status_code=409)

        nova_data = normalizar_data_agenda(dados.get("data") or horario.data)
        novo_horario = normalizar_horario_agenda(dados.get("horario") or horario.horario)
        try:
            profissional_id = int(dados.get("profissional_id") or horario.profissional_id or 0)
        except (TypeError, ValueError):
            profissional_id = 0

        if not nova_data or not novo_horario or profissional_id <= 0:
            return JSONResponse({"error": "Informe data, horário e profissional válidos."}, status_code=400)
        data_obj = datetime.strptime(nova_data, "%Y-%m-%d").date()
        if data_obj < hoje_brasilia():
            return JSONResponse({"error": "Não é possível mover o horário para um dia anterior."}, status_code=400)
        if data_obj == hoje_brasilia() and not horario_ainda_futuro(nova_data, novo_horario):
            return JSONResponse({"error": "Este horário já passou no horário de Brasília."}, status_code=400)

        profissional = db.query(Profissional).filter(
            Profissional.id == profissional_id,
            Profissional.empresa_id == horario.empresa_id,
            Profissional.ativo == True
        ).first()
        if not profissional:
            return JSONResponse({"error": "Profissional não encontrado ou inativo."}, status_code=404)

        duplicado = db.query(HorarioReserva).filter(
            HorarioReserva.empresa_id == horario.empresa_id,
            HorarioReserva.data == nova_data,
            HorarioReserva.horario == novo_horario,
            HorarioReserva.profissional_id == profissional_id,
            HorarioReserva.id != horario.id,
            HorarioReserva.ativo == True
        ).first()
        if duplicado:
            return JSONResponse({"error": "Já existe um horário igual para este profissional nesta data."}, status_code=409)

        horario.data = nova_data
        horario.horario = novo_horario
        horario.profissional_id = profissional_id
        horario.ativo = True
        db.commit()
        return {
            "message": "Horário atualizado com sucesso",
            "id": horario.id,
            "data": horario.data,
            "horario": horario.horario,
            "profissional_id": horario.profissional_id,
            "profissional_nome": profissional.nome
        }
    except HTTPException:
        raise
    except Exception as erro:
        db.rollback()
        LOGGER.exception("Erro ao editar horário livre %s", horario_id)
        return JSONResponse({"error": f"Não foi possível editar o horário: {erro}"}, status_code=500)
    finally:
        db.close()


@app.post("/horarios-reserva/{horario_id}/capacidade")
async def atualizar_capacidade_horario_reserva(horario_id: int, request: Request):
    dados = await request.json()

    try:
        capacidade = int(dados.get("capacidade_maxima") or dados.get("capacidade") or 0)
    except (TypeError, ValueError):
        capacidade = 0

    if capacidade < 1:
        return {"error": "Informe uma capacidade válida."}

    db = SessionLocal()

    horario = db.query(HorarioReserva).filter(
        HorarioReserva.id == horario_id
    ).first()

    if not horario:
        db.close()
        return {"error": "Horário não encontrado."}

    empresa_sessao = request.session.get("empresa_id")

    try:
        empresa_sessao = int(empresa_sessao)
    except (TypeError, ValueError):
        db.close()
        return {"error": "Sessão expirada. Faça login novamente."}

    if empresa_sessao != horario.empresa_id:
        db.close()
        return {"error": "Você não tem permissão para alterar este horário."}
    if not sessao_admin_total(request) and not permissao_admin_sessao(request, "reservas"):
        db.close()
        return {"error": "Você não possui permissão para Reservas / Agendamentos."}

    # Não deixa reduzir abaixo da quantidade de pessoas já reservadas naquele horário.
    consulta = db.query(Reserva).filter(
        Reserva.empresa_id == horario.empresa_id,
        Reserva.data == horario.data,
        func.lower(func.trim(Reserva.status)).notin_(["cancelada", "cancelado", "recusada", "recusado", "expirada", "expirado", "concluida", "concluido", "concluída", "concluído", "paga", "pago", "pagamento_recusado", "pagamento_cancelado"])
    )

    if hasattr(Reserva, "horario_id"):
        consulta = consulta.filter(
            or_(
                Reserva.horario_id == horario.id,
                and_(Reserva.horario_id == None, Reserva.horario == horario.horario)
            )
        )
    else:
        consulta = consulta.filter(Reserva.horario == horario.horario)

    if getattr(horario, "profissional_id", None):
        consulta = consulta.filter(Reserva.profissional_id == horario.profissional_id)

    pessoas_reservadas = sum((r.pessoas or 0) for r in consulta.all())

    if capacidade < pessoas_reservadas:
        db.close()
        return {
            "error": f"Capacidade menor que as pessoas já reservadas ({pessoas_reservadas})."
        }

    horario.capacidade_maxima = capacidade
    db.commit()
    db.close()

    return {"message": "Capacidade atualizada com sucesso", "capacidade_maxima": capacidade}


@app.delete("/horarios-reserva/{horario_id}")
def deletar_horario_reserva(horario_id: int, request: Request):
    db = SessionLocal()

    horario = db.query(HorarioReserva).filter(
        HorarioReserva.id == horario_id
    ).first()

    if not horario:
        db.close()
        return {"error": "Horário não encontrado"}

    empresa_sessao = request.session.get("empresa_id")

    try:
        empresa_sessao = int(empresa_sessao)
    except (TypeError, ValueError):
        db.close()
        return {"error": "Sessão expirada. Faça login novamente."}

    if empresa_sessao != horario.empresa_id:
        db.close()
        return {"error": "Você não tem permissão para excluir este horário."}
    if not sessao_admin_total(request) and not permissao_admin_sessao(request, "reservas"):
        db.close()
        return {"error": "Você não possui permissão para Reservas / Agendamentos."}

    consulta_reservas = db.query(Reserva).filter(
        Reserva.empresa_id == horario.empresa_id,
        func.lower(func.trim(Reserva.status)).notin_(["cancelada", "cancelado", "recusada", "recusado", "expirada", "expirado", "concluida", "concluido", "concluída", "concluído", "paga", "pago", "pagamento_recusado", "pagamento_cancelado"])
    )

    if hasattr(Reserva, "horario_id"):
        consulta_reservas = consulta_reservas.filter(
            Reserva.horario_id == horario.id
        )
    else:
        consulta_reservas = consulta_reservas.filter(
            Reserva.data == horario.data,
            Reserva.horario == horario.horario
        )

    if getattr(horario, "profissional_id", None):
        consulta_reservas = consulta_reservas.filter(
            Reserva.profissional_id == horario.profissional_id
        )

    reservas_no_horario = consulta_reservas.count()

    if reservas_no_horario > 0:
        db.close()
        return {
            "error": "Este horário possui reservas ativas. Cancele ou recuse as reservas antes de excluir."
        }

    db.delete(horario)
    db.commit()
    db.close()

    return {"message": "Horário excluído com sucesso"}




@app.post("/horarios-reserva/limpar-dia")
async def limpar_horarios_reserva_dia(request: Request):
    dados = await request.json()

    try:
        empresa_id = int(dados.get("empresa_id"))
    except (TypeError, ValueError):
        return {"error": "Empresa inválida"}

    exigir_admin_empresa_api(request, empresa_id, "reservas")

    data = str(dados.get("data") or "").strip()
    if not data:
        return {"error": "Informe a data"}

    try:
        profissional_id = int(dados.get("profissional_id") or 0) or None
    except (TypeError, ValueError):
        profissional_id = None

    try:
        if "/" in data:
            data_iso = datetime.strptime(data, "%d/%m/%Y").strftime("%Y-%m-%d")
            data_br = data
        else:
            data_iso = data
            data_br = datetime.strptime(data, "%Y-%m-%d").strftime("%d/%m/%Y")
    except ValueError:
        data_iso = data
        data_br = data

    datas_possiveis = list(dict.fromkeys([data_iso, data_br, data]))

    db = SessionLocal()

    consulta = db.query(HorarioReserva).filter(
        HorarioReserva.empresa_id == empresa_id,
        HorarioReserva.data.in_(datas_possiveis),
        HorarioReserva.ativo == True
    )

    if profissional_id:
        consulta = consulta.filter(HorarioReserva.profissional_id == profissional_id)

    horarios = consulta.all()
    removidos = 0
    mantidos_com_reserva = 0

    for horario in horarios:
        consulta_reservas = db.query(Reserva).filter(
            Reserva.empresa_id == empresa_id,
            func.lower(func.trim(Reserva.status)).notin_(["cancelada", "cancelado", "recusada", "recusado", "expirada", "expirado", "concluida", "concluido", "concluída", "concluído", "paga", "pago", "pagamento_recusado", "pagamento_cancelado"])
        )

        if hasattr(Reserva, "horario_id"):
            consulta_reservas = consulta_reservas.filter(
                or_(
                    Reserva.horario_id == horario.id,
                    and_(
                        Reserva.horario_id == None,
                        Reserva.data.in_(datas_possiveis),
                        Reserva.horario == horario.horario
                    )
                )
            )
        else:
            consulta_reservas = consulta_reservas.filter(
                Reserva.data.in_(datas_possiveis),
                Reserva.horario == horario.horario
            )

        if getattr(horario, "profissional_id", None):
            consulta_reservas = consulta_reservas.filter(
                Reserva.profissional_id == horario.profissional_id
            )

        if consulta_reservas.first():
            mantidos_com_reserva += 1
            continue

        db.delete(horario)
        removidos += 1

    db.commit()
    db.close()

    return {
        "message": "Horários livres limpos com segurança",
        "removidos": removidos,
        "mantidos_com_reserva": mantidos_com_reserva
    }

