@app.patch("/horarios-reserva/{horario_id}/status")
def atualizar_status_horario_reserva(
    horario_id: int,
    dados: HorarioReservaStatusUpdate,
    request: Request
):
    db = SessionLocal()

    horario = db.query(HorarioReserva).filter(
        HorarioReserva.id == horario_id
    ).first()

    if not horario:
        db.close()
        return {"error": "Horário não encontrado"}

    exigir_admin_empresa_api(request, horario.empresa_id, "reservas")

    horario.ativo = dados.ativo

    db.commit()
    db.close()

    return {"message": "Horário atualizado com sucesso"}


@app.get("/empresas/{empresa_id}/horarios-disponiveis")
def horarios_disponiveis(empresa_id: int, data: str, profissional_id: int | None = None):
    db = SessionLocal()
    expirar_reservas_pendentes_antigas(db, empresa_id)

    empresa = db.query(Empresa).filter(
        Empresa.id == empresa_id
    ).first()

    if empresa:
        expirar_holds_pagamento_online_reservas(db, empresa)

    if empresa and plano_empresa_bloqueado(empresa):
        db.close()
        return {
            "fechado": True,
            "motivo": "Sistema bloqueado. Horários indisponíveis.",
            "horarios": []
        }

    data_original = data
    data_iso = data
    data_br = data

    try:
        if "/" in data:
            data_iso = datetime.strptime(data, "%d/%m/%Y").strftime("%Y-%m-%d")
            data_br = data
        else:
            data_br = datetime.strptime(data, "%Y-%m-%d").strftime("%d/%m/%Y")
            data_iso = data
    except ValueError:
        data_iso = data_original
        data_br = data_original

    datas_possiveis = list(dict.fromkeys([data_iso, data_br, data_original]))

    try:
        data_consulta = datetime.strptime(data_iso, "%Y-%m-%d").date()
    except ValueError:
        db.close()
        return {"fechado": True, "motivo": "Data inválida.", "horarios": []}

    # Dias anteriores nunca exibem vagas livres. A configuração permanece
    # salva no banco, mas não interfere na agenda ativa nem no menu público.
    if data_consulta < hoje_brasilia():
        db.close()
        return {"fechado": False, "motivo": None, "horarios": []}

    dia_fechado = db.query(DiaFechado).filter(
        DiaFechado.empresa_id == empresa_id,
        DiaFechado.data.in_(datas_possiveis)
    ).first()

    if dia_fechado:
        motivo = dia_fechado.motivo or "Estabelecimento fechado nesta data"
        db.close()
        return {
            "fechado": True,
            "motivo": motivo,
            "horarios": []
        }

    consulta_horarios = db.query(HorarioReserva).filter(
        HorarioReserva.empresa_id == empresa_id,
        HorarioReserva.data.in_(datas_possiveis),
        HorarioReserva.ativo == True
    )

    if profissional_id:
        consulta_horarios = consulta_horarios.filter(
            HorarioReserva.profissional_id == profissional_id
        )

    horarios = consulta_horarios.order_by(HorarioReserva.horario).all()

    resultado = []

    agora_operacional = agora_brasilia()
    for horario in horarios:
        # No dia atual, somente horários ainda futuros aparecem. Em datas
        # futuras todos os horários cadastrados continuam disponíveis.
        if data_consulta == hoje_brasilia() and not horario_ainda_futuro(horario.data, horario.horario, agora_operacional):
            continue

        consulta_reservas = db.query(Reserva).filter(
            Reserva.empresa_id == empresa_id,
            func.lower(func.trim(Reserva.status)).notin_(["cancelada", "cancelado", "recusada", "recusado", "expirada", "expirado", "concluida", "concluido", "concluída", "concluído", "paga", "pago", "pagamento_recusado", "pagamento_cancelado"])
        )

        if hasattr(Reserva, "horario_id"):
            consulta_reservas = consulta_reservas.filter(
                or_(
                    Reserva.horario_id == horario.id,
                    and_(
                        Reserva.horario_id == None,
                        Reserva.data.in_(datas_possiveis),
                        Reserva.horario == horario.horario
                    )
                )
            )
        else:
            consulta_reservas = consulta_reservas.filter(
                Reserva.data.in_(datas_possiveis),
                Reserva.horario == horario.horario
            )

        if getattr(horario, "profissional_id", None):
            consulta_reservas = consulta_reservas.filter(
                Reserva.profissional_id == horario.profissional_id
            )

        reservas_do_horario = consulta_reservas.all()

        pessoas_reservadas = sum((r.pessoas or 1) for r in reservas_do_horario)
        capacidade = horario.capacidade_maxima or 0

        # V92:
        # Restaurante continua usando capacidade/vagas.
        # Serviço/salão/barbearia usa agenda por profissional:
        # se existir reserva ativa no mesmo horário + profissional, o horário NÃO aparece no menu público.
        negocio_servico = tipo_negocio_servico(empresa.tipo if empresa else "")

        if negocio_servico:
            disponivel = len(reservas_do_horario) == 0
        else:
            disponivel = capacidade <= 0 or pessoas_reservadas < capacidade

        if disponivel:
            profissional_nome = None
            if horario.profissional_id:
                profissional = db.query(Profissional).filter(
                    Profissional.id == horario.profissional_id,
                    Profissional.empresa_id == empresa_id,
                    Profissional.ativo == True
                ).first()
                if not profissional:
                    continue
                profissional_nome = profissional.nome
            elif negocio_servico:
                continue

            resultado.append({
                "id": horario.id,
                "data": horario.data,
                "horario": horario.horario,
                "profissional_id": horario.profissional_id,
                "profissional_nome": profissional_nome,
                "ativo": horario.ativo,
                "capacidade_maxima": capacidade,
                "pessoas_reservadas": pessoas_reservadas,
                "vagas_disponiveis": None if capacidade <= 0 else max(0, capacidade - pessoas_reservadas)
            })

    db.close()

    return {
        "fechado": False,
        "motivo": None,
        "horarios": resultado
    }
@app.post("/dias-fechados")
def criar_dia_fechado(dados: DiaFechadoCreate, request: Request):
    exigir_admin_empresa_api(request, dados.empresa_id)
    db = SessionLocal()

    existente = db.query(DiaFechado).filter(
        DiaFechado.empresa_id == dados.empresa_id,
        DiaFechado.data == dados.data
    ).first()

    if existente:
        db.close()
        return {"error": "Dia já está bloqueado"}

    novo = DiaFechado(
        empresa_id=dados.empresa_id,
        data=dados.data,
        motivo=dados.motivo
    )

    db.add(novo)
    db.commit()
    db.close()

    return {"message": "Dia fechado com sucesso"}


@app.delete("/dias-fechados/{empresa_id}/{data}")
def remover_dia_fechado(empresa_id: int, data: str, request: Request):
    exigir_admin_empresa_api(request, empresa_id)
    db = SessionLocal()

    dia = db.query(DiaFechado).filter(
        DiaFechado.empresa_id == empresa_id,
        DiaFechado.data == data
    ).first()

    if not dia:
        db.close()
        return {"error": "Dia não encontrado"}

    db.delete(dia)

    db.commit()
    db.close()

    return {"message": "Dia reaberto"}




