@app.post("/admin/{empresa_id}/encomendas/itens/{item_id}/excluir", include_in_schema=False)
def admin_encomendas_item_excluir(empresa_id: int, item_id: int, request: Request):
    ajax = str(request.headers.get("x-requested-with", "")).lower() == "xmlhttprequest" or "application/json" in str(request.headers.get("accept", "")).lower()
    carregado, resposta = _empresa_encomendas_admin(empresa_id, request, "cardapio")
    if resposta:
        if ajax:
            return JSONResponse({"ok": False, "erro": "Sessão inválida ou acesso não autorizado."}, status_code=401)
        return resposta
    db, empresa = carregado
    item = db.query(ItemEncomenda).filter(
        ItemEncomenda.id == item_id,
        ItemEncomenda.empresa_id == empresa.id,
        ItemEncomenda.ativo == True,
    ).first()
    if not item:
        db.close()
        if ajax:
            return JSONResponse({"ok": False, "erro": "Produto não encontrado ou já excluído."}, status_code=404)
        return RedirectResponse(url=f"/admin/{empresa_id}/encomendas/cadastrar", status_code=303)

    categoria_id = int(item.categoria_id or 0)
    # Exclusão lógica: some do catálogo sem apagar o histórico de encomendas antigas.
    item.ativo = False
    opcoes = db.query(OpcaoEncomenda).filter(
        OpcaoEncomenda.empresa_id == empresa.id,
        OpcaoEncomenda.item_encomenda_id == item.id,
        OpcaoEncomenda.ativo == True,
    ).all()
    for opcao in opcoes:
        opcao.ativo = False

    db.commit()
    categoria_restantes = db.query(ItemEncomenda).filter(
        ItemEncomenda.empresa_id == empresa.id,
        ItemEncomenda.categoria_id == categoria_id,
        ItemEncomenda.ativo == True,
    ).count() if categoria_id else 0
    db.close()
    if ajax:
        return JSONResponse({
            "ok": True,
            "item_id": item_id,
            "categoria_id": categoria_id,
            "categoria_itens": int(categoria_restantes),
        })
    return RedirectResponse(
        url=f"/admin/{empresa_id}/encomendas/cadastrar?excluido=1",
        status_code=303,
    )


@app.post("/admin/{empresa_id}/encomendas/categorias/criar-v809", include_in_schema=False)
async def admin_encomendas_categoria_criar_v809(empresa_id: int, request: Request):
    """v809: endpoint exclusivo de CREATE; não recebe nem executa UPDATE."""
    carregado, resposta = _empresa_encomendas_admin(empresa_id, request, "cardapio")
    ajax = (
        str(request.headers.get("x-requested-with", "")).lower() == "xmlhttprequest"
        or "application/json" in str(request.headers.get("accept", "")).lower()
    )
    if resposta:
        if ajax:
            return JSONResponse({"ok": False, "erro": "Sessão inválida ou acesso não autorizado."}, status_code=401)
        return resposta

    db, empresa = carregado
    try:
        formulario = await request.form()
        # Nesta rota só aceitamos o campo de criação.
        nome = str(formulario.get("nome_nova_categoria", "") or "").strip()
        modo = str(formulario.get("modo", "criar") or "criar").strip().lower()
        if modo != "criar":
            if ajax:
                return JSONResponse({"ok": False, "erro": "Operação inválida para criação de categoria."}, status_code=400)
            return RedirectResponse(
                url=f"/admin/{empresa_id}/encomendas/cadastrar?categorias=1&categoria_erro=nome",
                status_code=303,
            )
        if not nome:
            if ajax:
                return JSONResponse({"ok": False, "erro": "Informe o nome da nova categoria."}, status_code=400)
            return RedirectResponse(
                url=f"/admin/{empresa_id}/encomendas/cadastrar?categorias=1&categoria_erro=nome",
                status_code=303,
            )

        duplicada = db.query(CategoriaEncomenda).filter(
            CategoriaEncomenda.empresa_id == empresa.id,
            func.lower(func.trim(CategoriaEncomenda.nome)) == nome.lower(),
            CategoriaEncomenda.ativo == True,
        ).first()
        if duplicada:
            if ajax:
                return JSONResponse({
                    "ok": False,
                    "erro": f'A categoria "{duplicada.nome}" já existe.',
                    "codigo": "categoria_duplicada",
                }, status_code=409)
            return RedirectResponse(
                url=f"/admin/{empresa_id}/encomendas/cadastrar?categorias=1&categoria_erro=duplicada",
                status_code=303,
            )

        total_antes = db.query(CategoriaEncomenda).filter(
            CategoriaEncomenda.empresa_id == empresa.id,
            CategoriaEncomenda.ativo == True,
        ).count()
        categorias_existentes = db.query(CategoriaEncomenda).filter(
            CategoriaEncomenda.empresa_id == empresa.id,
            CategoriaEncomenda.ativo == True,
        ).all()
        proxima_ordem = max((int(c.ordem or 0) for c in categorias_existentes), default=0) + 1
        nova_categoria = CategoriaEncomenda(
            empresa_id=empresa.id,
            nome=nome,
            descricao="",
            ordem=proxima_ordem,
            ativo=True,
        )
        db.add(nova_categoria)
        db.flush()
        novo_id = int(nova_categoria.id)
        db.commit()

        criada = db.query(CategoriaEncomenda).filter(
            CategoriaEncomenda.id == novo_id,
            CategoriaEncomenda.empresa_id == empresa.id,
            CategoriaEncomenda.ativo == True,
        ).first()
        total_depois = db.query(CategoriaEncomenda).filter(
            CategoriaEncomenda.empresa_id == empresa.id,
            CategoriaEncomenda.ativo == True,
        ).count()
        if not criada or int(total_depois) != int(total_antes) + 1:
            raise RuntimeError("A nova categoria não foi persistida corretamente.")

        payload = {
            "ok": True,
            "id": int(criada.id),
            "nome": str(criada.nome),
            "existente": False,
            "categorias_ativas": int(total_depois),
            "acao": "criada",
        }
        if ajax:
            return JSONResponse(payload, status_code=201)
        return RedirectResponse(
            url=f"/admin/{empresa_id}/encomendas/cadastrar?categorias=1&categoria_criada=1",
            status_code=303,
        )
    except Exception:
        db.rollback()
        raise
    finally:
        db.close()


@app.post("/admin/{empresa_id}/encomendas/categorias/nova", include_in_schema=False)
async def admin_encomendas_categoria_criar_nova(empresa_id: int, request: Request):
    """v808: rota exclusiva de CREATE. Nunca altera categoria existente."""
    carregado, resposta = _empresa_encomendas_admin(empresa_id, request, "cardapio")
    ajax = str(request.headers.get("x-requested-with", "")).lower() == "xmlhttprequest" or "application/json" in str(request.headers.get("accept", "")).lower()
    if resposta:
        if ajax:
            return JSONResponse({"ok": False, "erro": "Sessão inválida ou acesso não autorizado."}, status_code=401)
        return resposta

    db, empresa = carregado
    try:
        formulario = await request.form()
        nome = str(formulario.get("nome_nova_categoria", "") or formulario.get("nome", "")).strip()
        if not nome:
            if ajax:
                return JSONResponse({"ok": False, "erro": "Informe um nome para a nova categoria."}, status_code=400)
            return RedirectResponse(
                url=f"/admin/{empresa_id}/encomendas/cadastrar?categorias=1&categoria_erro=nome",
                status_code=303,
            )

        # CREATE deve ser inequívoco: se já existe uma categoria ativa com o mesmo nome,
        # não seleciona nem renomeia nada; apenas informa o conflito.
        duplicada = db.query(CategoriaEncomenda).filter(
            CategoriaEncomenda.empresa_id == empresa.id,
            func.lower(func.trim(CategoriaEncomenda.nome)) == nome.strip().lower(),
            CategoriaEncomenda.ativo == True,
        ).first()
        if duplicada:
            if ajax:
                return JSONResponse({
                    "ok": False,
                    "erro": f'A categoria "{duplicada.nome}" já existe.',
                    "codigo": "categoria_duplicada",
                }, status_code=409)
            return RedirectResponse(
                url=f"/admin/{empresa_id}/encomendas/cadastrar?categorias=1&categoria_erro=duplicada",
                status_code=303,
            )

        categorias_existentes = db.query(CategoriaEncomenda).filter(
            CategoriaEncomenda.empresa_id == empresa.id,
            CategoriaEncomenda.ativo == True,
        ).all()
        proxima_ordem = max((int(c.ordem or 0) for c in categorias_existentes), default=0) + 1
        nova_categoria = CategoriaEncomenda(
            empresa_id=empresa.id,
            nome=nome,
            descricao="",
            ordem=proxima_ordem,
            ativo=True,
        )
        db.add(nova_categoria)
        db.commit()
        db.refresh(nova_categoria)
        total_ativas = db.query(CategoriaEncomenda).filter(
            CategoriaEncomenda.empresa_id == empresa.id,
            CategoriaEncomenda.ativo == True,
        ).count()
        payload = {
            "ok": True,
            "id": int(nova_categoria.id),
            "nome": str(nova_categoria.nome),
            "existente": False,
            "categorias_ativas": int(total_ativas),
            "acao": "criada",
        }
        if ajax:
            return JSONResponse(payload, status_code=201)
        return RedirectResponse(
            url=f"/admin/{empresa_id}/encomendas/cadastrar?categorias=1&categoria_criada=1",
            status_code=303,
        )
    except Exception:
        db.rollback()
        raise
    finally:
        db.close()


