@app.post("/admin/{empresa_id}/encomendas/categorias/{categoria_id}/excluir", include_in_schema=False)
def admin_encomendas_categoria_excluir(empresa_id: int, categoria_id: int, request: Request):
    ajax = str(request.headers.get("x-requested-with", "")).lower() == "xmlhttprequest" or "application/json" in str(request.headers.get("accept", "")).lower()
    carregado, resposta = _empresa_encomendas_admin(empresa_id, request, "cardapio")
    origem_lista = str(request.query_params.get("origem", "")).strip().lower() == "lista"
    if resposta:
        if ajax:
            return JSONResponse({"ok": False, "erro": "Sessão inválida ou acesso não autorizado."}, status_code=401)
        return resposta
    db, empresa = carregado
    categoria = db.query(CategoriaEncomenda).filter(
        CategoriaEncomenda.id == categoria_id,
        CategoriaEncomenda.empresa_id == empresa.id,
        CategoriaEncomenda.ativo == True,
    ).first()
    if not categoria:
        db.close()
        if ajax:
            return JSONResponse({"ok": False, "erro": "Categoria não encontrada ou já excluída."}, status_code=404)
        return RedirectResponse(url=f"/admin/{empresa_id}/encomendas/cadastrar?categorias=1", status_code=303)

    em_uso = db.query(ItemEncomenda).filter(
        ItemEncomenda.empresa_id == empresa.id,
        ItemEncomenda.categoria_id == categoria.id,
        ItemEncomenda.ativo == True,
    ).count()
    if em_uso:
        db.close()
        if ajax:
            return JSONResponse({"ok": False, "erro": "Mova ou exclua os produtos desta categoria antes de excluí-la."}, status_code=409)
        return RedirectResponse(
            url=f"/admin/{empresa_id}/encomendas/cadastrar?categorias=1&categoria_erro=uso",
            status_code=303,
        )

    total_ativas = db.query(CategoriaEncomenda).filter(
        CategoriaEncomenda.empresa_id == empresa.id,
        CategoriaEncomenda.ativo == True,
    ).count()
    if total_ativas <= 1:
        db.close()
        if ajax:
            return JSONResponse({"ok": False, "erro": "Mantenha pelo menos uma categoria ativa."}, status_code=409)
        return RedirectResponse(
            url=f"/admin/{empresa_id}/encomendas/cadastrar?categorias=1&categoria_erro=ultima",
            status_code=303,
        )

    categoria.ativo = False
    db.commit()
    total_restante = max(0, int(total_ativas) - 1)
    db.close()
    if ajax:
        return JSONResponse({"ok": True, "categoria_id": categoria_id, "categorias_ativas": total_restante})
    destino = (
        f"/admin/{empresa_id}/encomendas/cadastrar?categoria_excluida=1"
        if origem_lista
        else f"/admin/{empresa_id}/encomendas/cadastrar?categorias=1&categoria_salva=1"
    )
    return RedirectResponse(url=destino, status_code=303)


@app.post("/admin/{empresa_id}/encomendas/{encomenda_id}/status", include_in_schema=False)
async def admin_encomenda_status(empresa_id: int, encomenda_id: int, request: Request):
    carregado, resposta = _empresa_encomendas_admin(empresa_id, request, "pedidos")
    ajax = str(request.headers.get("x-requested-with", "")).lower() == "xmlhttprequest" or "application/json" in str(request.headers.get("accept", "")).lower()
    if resposta:
        if ajax:
            return JSONResponse({"ok": False, "error": "Sessão inválida ou acesso não autorizado."}, status_code=401)
        return resposta
    db, empresa = carregado
    formulario = await request.form()
    status = str(formulario.get("status", "")).strip().lower()
    permitidos = {"nova", "confirmada", "producao", "pronta", "entregue", "cancelada", "recusada"}
    encomenda = db.query(Encomenda).filter(Encomenda.id == encomenda_id, Encomenda.empresa_id == empresa.id).first()
    status_retorno = "nova"
    if not encomenda or status not in permitidos:
        db.close()
        if ajax:
            return JSONResponse({"ok": False, "error": "Encomenda ou status inválido."}, status_code=400)
        return RedirectResponse(url=f"/admin/{empresa_id}/encomendas?status=nova", status_code=303)

    if status == "confirmada":
        metodo_pagamento = str(
            getattr(encomenda, "gateway_pagamento", "") or ""
        ).strip().lower()

        pix_manual_pendente = (
            metodo_pagamento in {"pix_sinal_manual", "pix_manual", "pix"}
            and _v792_pagamento_pendente(encomenda)
        )

        pagamento_online_pendente = (
            metodo_pagamento in {"pix_online", "cartao_online"}
            and _v792_pagamento_pendente(encomenda)
        )

        # Pix próprio/manual:
        # o lojista conferiu o recebimento ao clicar em
        # "Confirmar sinal e aceitar".
        if pix_manual_pendente:
            encomenda.pagamento_status = "sinal_pago"

        # Pagamentos online continuam dependendo da confirmação
        # automática do gateway quando o bloqueio está ativado.
        elif (
            bool(getattr(empresa, "pedido_so_apos_pagamento", False))
            and pagamento_online_pendente
        ):
            db.close()
            if ajax:
                return JSONResponse({
                    "ok": False,
                    "error": "A confirmação do pagamento online é obrigatória antes de aceitar.",
                    "status_retorno": "nova",
                }, status_code=409)
            return RedirectResponse(
                url=f"/admin/{empresa_id}/encomendas?status=nova&pagamento_pendente=1",
                status_code=303,
            )

    if status == "entregue":
        _, _, valor_pendente, _ = _v819_valores_financeiros_encomenda(encomenda)
        if valor_pendente > 0.005:
            mensagem = (
                f"Ainda falta receber {_preco_encomenda_texto(valor_pendente)}. "
                "Confirme o pagamento do saldo antes de finalizar."
            )
            db.close()
            if ajax:
                return JSONResponse({
                    "ok": False,
                    "error": mensagem,
                    "status_retorno": "pronta",
                }, status_code=409)
            return RedirectResponse(
                url=f"/admin/{empresa_id}/encomendas?status=pronta&saldo_pendente=1",
                status_code=303,
            )

    encomenda.status = status
    db.commit()
    status_retorno = {
        "recusada": "cancelada",
        "cancelada": "cancelada",
        "entregue": "finalizada",
    }.get(status, status)
    numero = str(getattr(encomenda, "id", encomenda_id) or encomenda_id)
    db.close()

    if ajax:
        return JSONResponse({
            "ok": True,
            "status": status,
            "status_retorno": status_retorno,
            "encomenda_id": encomenda_id,
            "numero": numero,
            "refresh_url": f"/admin/{empresa_id}/encomendas?status={status_retorno}",
        })
    return RedirectResponse(url=f"/admin/{empresa_id}/encomendas?status={status_retorno}", status_code=303)

# ==================================================
@app.post("/admin/{empresa_id}/encomendas/{encomenda_id}/quitar-saldo", include_in_schema=False)
async def admin_encomenda_quitar_saldo(
    empresa_id: int,
    encomenda_id: int,
    request: Request,
):
    carregado, resposta = _empresa_encomendas_admin(
        empresa_id,
        request,
        "pedidos",
    )

    ajax = (
        str(request.headers.get("x-requested-with", "")).lower()
        == "xmlhttprequest"
        or "application/json"
        in str(request.headers.get("accept", "")).lower()
    )

    if resposta:
        if ajax:
            return JSONResponse(
                {
                    "ok": False,
                    "error": "Sessão inválida ou acesso não autorizado.",
                },
                status_code=401,
            )
        return resposta

    db, empresa = carregado

    encomenda = db.query(Encomenda).filter(
        Encomenda.id == encomenda_id,
        Encomenda.empresa_id == empresa.id,
    ).first()

    if not encomenda:
        db.close()
        if ajax:
            return JSONResponse(
                {"ok": False, "error": "Encomenda não encontrada."},
                status_code=404,
            )
        return RedirectResponse(
            url=f"/admin/{empresa_id}/encomendas?status=finalizada",
            status_code=303,
        )

    status_operacional = str(
        getattr(encomenda, "status", "") or ""
    ).strip().lower()

    if status_operacional not in {"pronta", "entregue", "finalizada"}:
        db.close()
        if ajax:
            return JSONResponse(
                {
                    "ok": False,
                    "error": "O saldo deve ser confirmado quando a encomenda estiver pronta, antes de finalizar.",
                },
                status_code=409,
            )
        return RedirectResponse(
            url=f"/admin/{empresa_id}/encomendas",
            status_code=303,
        )

    total, recebido, pendente, sinal_recebido = (
        _v819_valores_financeiros_encomenda(encomenda)
    )

    saldo_original = round(
        max(
            0.0,
            float(getattr(encomenda, "total", 0) or 0)
            - float(getattr(encomenda, "sinal_valor", 0) or 0)
        ),
        2,
    )

    saldo_ja_registrado = round(
        max(
            0.0,
            float(getattr(encomenda, "saldo_pago_valor", 0) or 0)
        ),
        2,
    )

    pagamento_ja_confirmado = str(
        getattr(encomenda, "pagamento_status", "") or ""
    ).strip().lower() == "pago"

    if saldo_original > 0 and (
        pendente > 0
        or saldo_ja_registrado > 0
        or pagamento_ja_confirmado
    ):
        formulario = await request.form()

        forma_saldo = str(
            formulario.get("forma_saldo") or ""
        ).strip().lower()

        aliases = {
            "pix": "pix_chave",
            "cartao": "cartao_presencial",
        }
        forma_saldo = aliases.get(forma_saldo, forma_saldo)

        formas_saldo_validas = {
            "cartao_debito",
            "cartao_credito",
            "dinheiro",
            "pix_chave",
            "pix_online",
            "cartao_presencial",
            "cartao_online",
            "transferencia",
            "outro",
        }

        if forma_saldo not in formas_saldo_validas:
            db.close()
            if ajax:
                return JSONResponse(
                    {
                        "ok": False,
                        "error": "Informe como o saldo foi recebido.",
                    },
                    status_code=400,
                )
            return RedirectResponse(
                url=f"/admin/{empresa_id}/encomendas?status=finalizada",
                status_code=303,
            )

        valor_raw = str(
            formulario.get("valor_recebido") or ""
        ).strip()

        if valor_raw:
            try:
                valor_saldo = round(
                    float(
                        valor_raw
                        .replace("R$", "")
                        .replace(" ", "")
                        .replace(".", "")
                        .replace(",", ".")
                    ),
                    2,
                )
            except (TypeError, ValueError):
                valor_saldo = 0.0
        else:
            # Compatibilidade com o select simples que está na tela hoje.
            valor_saldo = saldo_original

        if abs(valor_saldo - saldo_original) > 0.01:
            db.close()
            if ajax:
                return JSONResponse(
                    {
                        "ok": False,
                        "error": "O valor deve corresponder ao saldo restante.",
                    },
                    status_code=400,
                )
            return RedirectResponse(
                url=f"/admin/{empresa_id}/encomendas?status=finalizada",
                status_code=303,
            )

        data_pagamento = agora_brasilia()

        data_hora_raw = str(
            formulario.get("data_hora") or ""
        ).strip()

        if data_hora_raw:
            try:
                from datetime import datetime as _dt
                data_pagamento = _dt.fromisoformat(data_hora_raw)
            except (TypeError, ValueError):
                data_pagamento = agora_brasilia()

        observacao_saldo = str(
            formulario.get("observacao_saldo") or ""
        ).strip()[:1000]

        # Saldo fica separado da forma original da encomenda/sinal.
        encomenda.saldo_forma_pagamento = forma_saldo
        encomenda.saldo_pago_valor = saldo_original
        encomenda.saldo_pago_em = data_pagamento
        encomenda.saldo_pagamento_observacao = observacao_saldo or None

        encomenda.pagamento_status = "pago"
        encomenda.saldo_valor = 0.0
        encomenda.pago_em = data_pagamento

        db.commit()

    status_retorno = "pronta" if status_operacional == "pronta" else "finalizada"
    db.close()

    if ajax:
        return JSONResponse({
            "ok": True,
            "encomenda_id": encomenda_id,
            "pagamento_status": "pago",
            "valor_total": total,
            "valor_recebido": total,
            "valor_pendente": 0.0,
            "status_retorno": status_retorno,
            "refresh_url": f"/admin/{empresa_id}/encomendas?status={status_retorno}",
        })

    return RedirectResponse(
        url=f"/admin/{empresa_id}/encomendas?status={status_retorno}",
        status_code=303,
    )


# ==================================================
# V769 — CHECKOUT PÚBLICO REAL DE ENCOMENDAS
# ==================================================

def _encomenda_sinal_calcular(empresa, total: float) -> float:
    total = max(0.0, round(float(total or 0), 2))
    if total <= 0 or not bool(getattr(empresa, "sinal_reserva_ativo", False)):
        return 0.0
    tipo = str(getattr(empresa, "sinal_tipo", "percentual") or "percentual").strip().lower()
    try:
        valor = float(getattr(empresa, "sinal_valor", 0) or 0)
    except (TypeError, ValueError):
        valor = 0.0
    if tipo == "integral":
        sinal = total
    elif tipo == "percentual":
        sinal = total * min(100.0, max(0.0, valor)) / 100.0
    else:
        sinal = valor
    return round(min(total, max(0.0, sinal)), 2)


def _encomenda_valor_pagamento(encomenda: Encomenda) -> float:
    sinal = round(float(getattr(encomenda, "sinal_valor", 0) or 0), 2)
    total = round(float(getattr(encomenda, "total", 0) or 0), 2)
    return sinal if sinal > 0 else total


def _encomenda_numero(db, empresa_id: int) -> str:
    hoje = hoje_brasilia()
    inicio = datetime.combine(hoje, time.min)
    fim = inicio + timedelta(days=1)
    quantidade = db.query(Encomenda).filter(
        Encomenda.empresa_id == empresa_id,
        Encomenda.criado_em >= inicio,
        Encomenda.criado_em < fim,
    ).count()
    return f"{quantidade + 1:04d}"


def _encomenda_modo_pagamento_presencial(empresa, tipo_recebimento: str) -> str:
    """Retorna o modo presencial configurado para retirada/entrega.

    Valores: nenhum, dinheiro, cartao, ambos. Bancos anteriores à v777
    usam os dois booleanos legados como fallback.
    """
    tipo = str(tipo_recebimento or "retirada").strip().lower()
    campo = "pagamento_entrega_modo" if tipo == "entrega" else "pagamento_retirada_modo"
    modo = str(getattr(empresa, campo, "") or "").strip().lower()
    if modo in {"nenhum", "dinheiro", "cartao", "ambos"}:
        return modo
    dinheiro = bool(getattr(empresa, "aceita_dinheiro", False))
    cartao = bool(getattr(empresa, "aceita_cartao_entrega", False))
    if dinheiro and cartao:
        return "ambos"
    if dinheiro:
        return "dinheiro"
    if cartao:
        return "cartao"
    return "nenhum"


def _encomenda_metodos_pagamento(empresa, tipo_recebimento: str = "retirada") -> set[str]:
    metodos = set()
    online = bool(getattr(empresa, "pagamentos_online_ativo", False))
    if online and bool(getattr(empresa, "aceita_pix_online", False)):
        metodos.add("pix_online")
    if online and bool(getattr(empresa, "aceita_cartao_online", False)):
        metodos.add("cartao_online")

    modo = _encomenda_modo_pagamento_presencial(empresa, tipo_recebimento)
    if modo in {"dinheiro", "ambos"}:
        metodos.add("dinheiro")
    if modo in {"cartao", "ambos"}:
        metodos.add("cartao_presencial")

    if bool(getattr(empresa, "sinal_reserva_ativo", False)) and getattr(empresa, "sinal_pix_chave", None):
        metodos.add("pix_sinal_manual")
    return metodos


def _encomenda_validar_data_horario(db, empresa_id: int, data_escolhida: date, horario: str) -> None:
    """Valida a retirada/entrega futura contra os horários configurados da empresa."""
    if not obter_restricao_horarios_ativa(db, empresa_id):
        return
    horarios = obter_horarios_funcionamento(db, empresa_id)
    linha = next((x for x in horarios if int(x.get("dia_semana", -1)) == data_escolhida.weekday()), None)
    if not linha:
        return
    if not bool(linha.get("aberto")):
        raise HTTPException(status_code=400, detail="O estabelecimento não atende encomendas nesta data.")
    inicio = _parse_hora_hhmm(linha.get("hora_inicio"))
    fim = _parse_hora_hhmm(linha.get("hora_fim"))
    escolhido = _parse_hora_hhmm(horario)
    if not escolhido or not inicio or not fim:
        return
    if inicio <= fim:
        dentro = inicio <= escolhido <= fim
    else:
        dentro = escolhido >= inicio or escolhido <= fim
    if not dentro:
        display = linha.get("display") or f"{linha.get('hora_inicio','')}–{linha.get('hora_fim','')}"
        raise HTTPException(status_code=400, detail=f"Escolha um horário dentro do funcionamento: {display}.")


@app.post("/api/publico/{slug}/encomendas")
async def criar_encomenda_publica(slug: str, request: Request):
    try:
        payload = await request.json()
    except Exception:
        raise HTTPException(status_code=400, detail="Dados da encomenda inválidos.")

    db = SessionLocal()
    try:
        empresa = db.query(Empresa).filter(Empresa.slug == slug).first()
        if not empresa or not tipo_negocio_encomenda(getattr(empresa, "tipo", "")):
            raise HTTPException(status_code=404, detail="Menu de encomendas não encontrado.")

        # v772 — uma encomenda pode conter vários itens. Mantém compatibilidade
        # com o payload antigo de item único para não quebrar versões anteriores.
        itens_payload = payload.get("itens")
        if not isinstance(itens_payload, list) or not itens_payload:
            itens_payload = [{
                "item_id": payload.get("item_id"),
                "opcao_id": payload.get("opcao_id"),
                "quantidade": payload.get("quantidade") or 1,
                "recheio_sabor": payload.get("recheio_sabor"),
                "personalizacao": payload.get("personalizacao"),
            }]
        if len(itens_payload) > 40:
            raise HTTPException(status_code=400, detail="A encomenda possui itens demais. Divida em duas encomendas.")

        linhas = []
        total = 0.0
        maior_antecedencia = 0
        regras_disponibilidade = []
        disponibilidade_mapa = obter_disponibilidades_encomendas(db, empresa.id)
        todos_permite_retirada = True
        todos_permite_entrega = True
        for bruto in itens_payload:
            if not isinstance(bruto, dict):
                raise HTTPException(status_code=400, detail="Um dos itens da encomenda é inválido.")
            try:
                item_id = int(bruto.get("item_id") or 0)
                opcao_id = int(bruto.get("opcao_id") or 0)
                quantidade = int(bruto.get("quantidade") or 1)
            except (TypeError, ValueError):
                raise HTTPException(status_code=400, detail="Produto, opção ou quantidade inválidos.")
            quantidade = max(1, min(99, quantidade))

            item = db.query(ItemEncomenda).filter(
                ItemEncomenda.id == item_id,
                ItemEncomenda.empresa_id == empresa.id,
                ItemEncomenda.ativo == True,
            ).first()
            opcao = db.query(OpcaoEncomenda).filter(
                OpcaoEncomenda.id == opcao_id,
                OpcaoEncomenda.item_encomenda_id == item_id,
                OpcaoEncomenda.empresa_id == empresa.id,
                OpcaoEncomenda.ativo == True,
            ).first()
            if not item or not opcao:
                raise HTTPException(status_code=400, detail="Um dos produtos ou opções não está mais disponível.")

            preco_unitario = round(float(opcao.preco or 0), 2)
            subtotal = round(preco_unitario * quantidade, 2)
            total = round(total + subtotal, 2)
            maior_antecedencia = max(maior_antecedencia, max(0, int(item.antecedencia_horas or 0)))
            meta_disp = disponibilidade_mapa.get(int(item.id), {
                "antecedencia_minutos": max(0, int(item.antecedencia_horas or 0)) * 60,
                "disponivel_hoje": False,
                "tempo_retirada_minutos": 30,
            })
            regras_disponibilidade.append(meta_disp)
            todos_permite_retirada = todos_permite_retirada and bool(item.permite_retirada)
            todos_permite_entrega = todos_permite_entrega and bool(item.permite_entrega)
            linhas.append({
                "item": item,
                "opcao": opcao,
                "quantidade": quantidade,
                "preco_unitario": preco_unitario,
                "subtotal": subtotal,
                "detalhes": {
                    "recheio_sabor": str(bruto.get("recheio_sabor") or "").strip()[:300],
                    "personalizacao": str(bruto.get("personalizacao") or "").strip()[:700],
                    "email": str(payload.get("email") or "").strip()[:254],
                },
            })

        if not linhas:
            raise HTTPException(status_code=400, detail="Adicione pelo menos um item à encomenda.")

        nome = str(payload.get("cliente_nome") or "").strip()[:160]
        telefone = re.sub(r"[^0-9+]", "", str(payload.get("telefone") or ""))[:30]
        if len(nome) < 2 or len(re.sub(r"\D", "", telefone)) < 8:
            raise HTTPException(status_code=400, detail="Informe nome e WhatsApp válidos.")

        try:
            data_retirada = date.fromisoformat(str(payload.get("data") or ""))
        except (TypeError, ValueError):
            raise HTTPException(status_code=400, detail="Escolha uma data válida.")
        horario = str(payload.get("horario") or "").strip()
        if not re.fullmatch(r"\d{2}:\d{2}", horario):
            raise HTTPException(status_code=400, detail="Escolha um horário válido.")

        agora_ref = agora_brasilia()
        # V926 — o prazo exibido no produto e o prazo validado no checkout usam
        # a mesma regra. Item marcado como "Disponível hoje" usa o seu tempo real
        # de retirada (ex.: 30 min) também quando esse tempo atravessa a meia-noite
        # ou quando o cliente escolhe uma data futura. Para carrinho misto, vale o
        # maior prazo efetivo entre os itens.
        espera_minutos = max((
            int(regra.get("tempo_retirada_minutos") or 0)
            if bool(regra.get("disponivel_hoje"))
            else int(regra.get("antecedencia_minutos") or 0)
            for regra in regras_disponibilidade
        ), default=maior_antecedencia * 60)
        minimo = agora_ref + timedelta(minutes=max(0, espera_minutos))
        momento_escolhido = datetime.combine(data_retirada, datetime.strptime(horario, "%H:%M").time())
        if momento_escolhido < minimo:
            detalhe_prazo = _enc_tempo_texto(espera_minutos)
            raise HTTPException(status_code=400, detail=f"A data/horário precisa respeitar o prazo mínimo de {detalhe_prazo} para todos os itens da encomenda.")
        _encomenda_validar_data_horario(db, empresa.id, data_retirada, horario)

        menu_config = obter_menu_configuracoes(db, empresa.id)
        entrega_config = obter_entrega_config_empresa(empresa)
        tipo_recebimento = str(payload.get("tipo_recebimento") or "retirada").strip().lower()
        if tipo_recebimento not in {"retirada", "entrega"}:
            tipo_recebimento = "retirada"
        if tipo_recebimento == "retirada" and (
            not todos_permite_retirada
            or not bool(menu_config.get("retirada", True))
            or not bool(entrega_config.get("retirada_ativa", True))
        ):
            raise HTTPException(status_code=400, detail="Retirada não está disponível para todos os itens desta encomenda.")
        if tipo_recebimento == "entrega" and (
            not todos_permite_entrega
            or not bool(menu_config.get("entrega", True))
            or not bool(entrega_config.get("entrega_ativa", True))
        ):
            raise HTTPException(status_code=400, detail="Entrega não está disponível para todos os itens desta encomenda.")

        endereco = str(payload.get("endereco") or "").strip()[:1200]
        if tipo_recebimento == "entrega" and len(endereco) < 8:
            raise HTTPException(status_code=400, detail="Informe o endereço de entrega.")

        sinal = _encomenda_sinal_calcular(empresa, total)
        saldo = round(max(0.0, total - sinal), 2)
        permitidos = _encomenda_metodos_pagamento(empresa, tipo_recebimento)
        forma_pagamento = str(payload.get("forma_pagamento") or "").strip().lower()
        sinal_metodo = str(payload.get("sinal_metodo") or "").strip().lower()
        gateway_pagamento = None

        pagamento_status = "pendente"
        status = "nova"
        if sinal > 0:
            metodos_sinal = set()
            if bool(getattr(empresa, "sinal_reserva_ativo", False)) and getattr(empresa, "sinal_pix_chave", None):
                metodos_sinal.add("pix_sinal_manual")
            online = bool(getattr(empresa, "pagamentos_online_ativo", False))
            if online and bool(getattr(empresa, "aceita_pix_online", False)):
                metodos_sinal.add("pix_online")
            if online and bool(getattr(empresa, "aceita_cartao_online", False)):
                metodos_sinal.add("cartao_online")
            if sinal_metodo not in metodos_sinal:
                raise HTTPException(status_code=400, detail="O sinal está ativo, mas a forma de pagamento do sinal não está disponível.")

            if saldo > 0:
                permitidos_saldo = {m for m in permitidos if m in {"dinheiro", "cartao_presencial"}}
                # v782 — quando o estabelecimento escolhe não aceitar pagamento
                # presencial para este tipo de recebimento, não obrigamos o cliente
                # a selecionar uma opção inexistente. A Central continua exibindo
                # claramente o sinal e o saldo pendente, sem inventar uma forma.
                if not permitidos_saldo:
                    forma_pagamento = "a_combinar"
                elif forma_pagamento not in permitidos_saldo:
                    raise HTTPException(status_code=400, detail="Escolha como deseja pagar o saldo restante: cartão ou dinheiro.")
            else:
                forma_pagamento = sinal_metodo

            gateway_pagamento = sinal_metodo
            if sinal_metodo == "pix_sinal_manual":
                pagamento_status = "aguardando_sinal"
            else:
                pagamento_status = "aguardando_pagamento"
                status = "nova"
        else:
            if forma_pagamento not in permitidos:
                raise HTTPException(status_code=400, detail="Escolha uma forma de pagamento disponível.")
            if forma_pagamento in {"pix_online", "cartao_online"}:
                gateway_pagamento = forma_pagamento
                pagamento_status = "aguardando_pagamento"
                status = "nova"
            else:
                pagamento_status = "pagar_no_recebimento"

        observacoes = str(payload.get("observacao") or "").strip()[:1500]
        encomenda = Encomenda(
            empresa_id=empresa.id,
            numero=_encomenda_numero(db, empresa.id),
            cliente_nome=nome,
            telefone=telefone,
            tipo_recebimento=tipo_recebimento,
            data_retirada=data_retirada,
            horario=horario,
            endereco=endereco or None,
            observacao=observacoes or None,
            status=status,
            total=total,
            sinal_valor=sinal,
            saldo_valor=saldo,
            pagamento_status=pagamento_status,
            forma_pagamento=forma_pagamento,
            gateway_pagamento=gateway_pagamento,
            public_token=secrets.token_urlsafe(24),
        )
        db.add(encomenda)
        db.flush()

        for linha in linhas:
            item = linha["item"]
            opcao = linha["opcao"]
            db.add(EncomendaItem(
                empresa_id=empresa.id,
                encomenda_id=encomenda.id,
                item_encomenda_id=item.id,
                nome_item=item.nome,
                opcao_nome=opcao.nome,
                quantidade=linha["quantidade"],
                preco_unitario=linha["preco_unitario"],
                subtotal=linha["subtotal"],
                detalhes_json=json.dumps(linha["detalhes"], ensure_ascii=False),
            ))

        db.commit()
        # v800 — a encomenda já é operacional quando o pagamento é presencial
        # ou o sinal é Pix manual. Para Pix/Cartão online, aguardamos a criação
        # bem-sucedida da cobrança antes do Push para não avisar tentativa recusada.
        if gateway_pagamento not in {"pix_online", "cartao_online"}:
            enqueue_new_encomenda(encomenda.id)
        return {
            "ok": True,
            "encomenda_id": encomenda.id,
            "numero": encomenda.numero,
            "public_token": encomenda.public_token,
            "status": encomenda.status,
            "status_pagamento": encomenda.pagamento_status,
            "forma_pagamento": encomenda.forma_pagamento,
            "sinal_metodo": gateway_pagamento if sinal > 0 else None,
            "total": total,
            "sinal_valor": sinal,
            "saldo_valor": saldo,
            "itens": len(linhas),
            "pix_manual": {
                "chave": getattr(empresa, "sinal_pix_chave", None),
                "titular": getattr(empresa, "sinal_pix_titular", None),
                "prazo_minutos": int(getattr(empresa, "sinal_prazo_minutos", 30) or 30),
                "politica": getattr(empresa, "sinal_politica", None),
            } if gateway_pagamento == "pix_sinal_manual" else None,
        }
    except HTTPException:
        db.rollback()
        raise
    except Exception:
        db.rollback()
        LOGGER.exception("Falha ao criar encomenda pública para %s", slug)
        return JSONResponse({"error": "Não foi possível confirmar a encomenda."}, status_code=500)
    finally:
        db.close()

def _encomenda_payment_callback(db, empresa, encomenda):
    status_anterior = str(getattr(encomenda, "status", "") or "nova").strip().lower()
    def callback():
        # v792 — confirmação financeira não deve regredir Confirmada/Produção/Pronta.
        if status_anterior in {"confirmada", "producao", "pronta", "entregue", "finalizada"}:
            encomenda.status = status_anterior
        else:
            _v792_normalizar_status_operacional(encomenda)
            if str(getattr(encomenda, "status", "") or "").strip().lower() not in {
                "cancelada", "recusada", "pagamento_cancelado", "pagamento_recusado"
            }:
                encomenda.status = "nova"
        encomenda.pagamento_status = "pago"
        if float(encomenda.sinal_valor or 0) > 0 and float(encomenda.saldo_valor or 0) > 0:
            encomenda.pagamento_status = "sinal_pago"
    return callback


def _v788_respeitar_liberacao_encomenda_online(empresa, encomenda):
    """Mantém pagamento online pendente fora da fila operacional quando a liberação depende da confirmação."""
    if not encomenda:
        return
    if _v792_pagamento_pendente(encomenda):
        if bool(getattr(empresa, "pedido_so_apos_pagamento", False)):
            encomenda.status = "aguardando_pagamento"
            return
        _v792_normalizar_status_operacional(encomenda)
        if str(getattr(encomenda, "status", "") or "").strip().lower() not in {
            "confirmada", "producao", "pronta", "entregue", "finalizada",
            "cancelada", "recusada", "pagamento_cancelado", "pagamento_recusado"
        }:
            encomenda.status = "nova"


def _v784_is_local_payment_debug_request(request: Request) -> bool:
    """Libera diagnóstico detalhado somente em acesso local de desenvolvimento."""
    try:
        url_host = str(request.url.hostname or "").strip().lower()
    except Exception:
        url_host = ""
    try:
        client_host = str(getattr(request.client, "host", "") or "").strip().lower()
    except Exception:
        client_host = ""
    local_hosts = {"127.0.0.1", "localhost", "::1"}
    return url_host in local_hosts or client_host in local_hosts


def _v784_safe_mercadopago_diagnostic(details):
    """Extrai apenas campos de erro úteis, sem tokens, credenciais ou dados de cartão."""
    if details is None:
        return None
    if isinstance(details, dict):
        safe = {}
        for key in ("message", "error", "status", "status_detail"):
            value = details.get(key)
            if value not in (None, "", [], {}):
                safe[key] = str(value)[:500]
        causes = details.get("cause") or details.get("causes")
        if isinstance(causes, list):
            safe_causes = []
            for cause in causes[:6]:
                if not isinstance(cause, dict):
                    safe_causes.append({"description": str(cause)[:300]})
                    continue
                row = {}
                for key in ("code", "description", "message"):
                    value = cause.get(key)
                    if value not in (None, ""):
                        row[key] = str(value)[:300]
                if row:
                    safe_causes.append(row)
            if safe_causes:
                safe["causes"] = safe_causes
        if not safe:
            # Fallback controlado: somente chaves conhecidamente não sensíveis.
            for key, value in list(details.items())[:8]:
                lower = str(key).lower()
                if any(secret in lower for secret in ("token", "authorization", "password", "card", "security_code", "public_key", "access")):
                    continue
                if isinstance(value, (str, int, float, bool)):
                    safe[str(key)[:80]] = str(value)[:300]
        return safe or {"message": "O gateway recusou a solicitação sem detalhes públicos adicionais."}
    if isinstance(details, list):
        return {"causes": [{"description": str(item)[:300]} for item in details[:6]]}
    return {"message": str(details)[:500]}


@app.post("/api/pagamentos/mercadopago/{empresa_id}/encomenda/processar")
async def processar_pagamento_encomenda_mercadopago(empresa_id: int, request: Request):
    db = SessionLocal()
    try:
        recebido = await _payment_json(request)
        encomenda_id = int(recebido.get("encomenda_id") or 0)
        empresa = db.query(Empresa).filter(Empresa.id == empresa_id).first()
        encomenda = db.query(Encomenda).filter(
            Encomenda.id == encomenda_id, Encomenda.empresa_id == empresa_id
        ).first()
        if not empresa or not encomenda:
            raise PaymentError("Encomenda não encontrada.", status_code=404)
        token = str(recebido.get("public_token") or request.headers.get("X-Public-Token") or "")
        if not token or not hmac.compare_digest(token, str(encomenda.public_token or "")):
            raise PaymentError("Acesso ao pagamento não autorizado.", status_code=403)
        metodo_online = str(getattr(encomenda, "gateway_pagamento", "") or encomenda.forma_pagamento or "").lower()
        if metodo_online not in {"pix_online", "cartao_online"}:
            raise PaymentError("Esta encomenda não utiliza pagamento online.")
        form_data_pagamento = dict(
            recebido.get("formData") or recebido.get("form_data") or {}
        )
        cardholder_name = str(recebido.get("cardholderName") or "").strip()
        device_id = str(recebido.get("deviceId") or "").strip()
        if cardholder_name:
            payer_data = dict(form_data_pagamento.get("payer") or {})
            payer_data["first_name"] = cardholder_name
            form_data_pagamento["payer"] = payer_data

        resultado = PaymentService.create_payment(
            company=empresa,
            origin=encomenda,
            origin_type="encomenda",
            amount=_encomenda_valor_pagamento(encomenda),
            form_data=form_data_pagamento,
            device_id=device_id or None,
            payer_email=recebido.get("email") or "cliente@menufacile.org",
            notification_url=_payment_notification_url(request, empresa_id),
            on_approved=_encomenda_payment_callback(db, empresa, encomenda),
        )
        _v788_respeitar_liberacao_encomenda_online(empresa, encomenda)
        resposta_pagamento = resultado.as_dict()
        status_gateway = str(
            resposta_pagamento.get("status")
            or getattr(encomenda, "gateway_status", "")
            or ""
        ).strip().lower()
        db.commit()
        # v800 — só notificamos como nova encomenda quando o gateway realmente
        # criou uma cobrança válida (aprovada ou aguardando processamento).
        liberar_so_apos_pagamento = bool(getattr(empresa, "pedido_so_apos_pagamento", False))
        if status_gateway == "approved" or (
            not liberar_so_apos_pagamento
            and status_gateway in {"pending", "in_process", "authorized"}
        ):
            enqueue_new_encomenda(encomenda.id)
        return resposta_pagamento
    except PaymentError as error:
        transient_create = bool(
            isinstance(error.details, dict)
            and error.details.get("transient_create")
        )
        if transient_create and "encomenda" in locals() and encomenda is not None:
            try:
                # V926 — preserva apenas o estado de tentativa ambígua. Não marca
                # como pago/recusado; isso permite reconciliar com segurança antes
                # de uma nova tentativa do cartão.
                encomenda.gateway_status = "unknown"
                encomenda.gateway_status_detail = "v926_create_timeout_reconcile_pending"
                db.commit()
            except Exception:
                db.rollback()
        else:
            db.rollback()
        if _v784_is_local_payment_debug_request(request):
            diagnostic = _v784_safe_mercadopago_diagnostic(error.details)
            LOGGER.warning(
                "v784 diagnóstico local Mercado Pago encomenda empresa=%s: %s",
                empresa_id,
                diagnostic,
            )
            return JSONResponse(
                {
                    "error": str(error),
                    "payment_debug_local": True,
                    "diagnostico": diagnostic,
                },
                status_code=error.status_code,
            )
        return _payment_error_response(error)
    except Exception:
        db.rollback()
        LOGGER.exception("Falha inesperada ao processar pagamento da encomenda %s", empresa_id)
        return JSONResponse({"error": "Não foi possível processar o pagamento."}, status_code=500)
    finally:
        db.close()


@app.post("/api/pagamentos/mercadopago/{empresa_id}/encomenda/{encomenda_id}/trocar-metodo")
async def trocar_metodo_pagamento_encomenda(empresa_id: int, encomenda_id: int, request: Request):
    """v786 — troca segura do método do sinal sem manter duas cobranças abertas."""
    db = SessionLocal()
    try:
        recebido = await _payment_json(request)
        novo_metodo = str(recebido.get("novo_metodo") or "").strip().lower()
        public_token = str(recebido.get("public_token") or request.headers.get("X-Public-Token") or "")

        empresa = db.query(Empresa).filter(Empresa.id == empresa_id).first()
        encomenda = db.query(Encomenda).filter(
            Encomenda.id == encomenda_id,
            Encomenda.empresa_id == empresa_id,
        ).first()
        if not empresa or not encomenda:
            raise PaymentError("Encomenda não encontrada.", status_code=404)
        if not public_token or not hmac.compare_digest(public_token, str(encomenda.public_token or "")):
            raise PaymentError("Acesso ao pagamento não autorizado.", status_code=403)

        metodos_permitidos = set()
        if float(getattr(encomenda, "sinal_valor", 0) or 0) > 0 and str(getattr(empresa, "sinal_pix_chave", "") or "").strip():
            metodos_permitidos.add("pix_sinal_manual")
        if bool(getattr(empresa, "pagamentos_online_ativo", False)):
            if bool(getattr(empresa, "aceita_pix_online", False)):
                metodos_permitidos.add("pix_online")
            if bool(getattr(empresa, "aceita_cartao_online", False)):
                metodos_permitidos.add("cartao_online")
        if novo_metodo not in metodos_permitidos:
            raise PaymentError("A forma de pagamento escolhida não está disponível.")

        payment_id = str(getattr(encomenda, "gateway_payment_id", "") or "").strip()
        if payment_id:
            mp = MercadoPagoService(PaymentService.ensure_company_enabled(empresa))
            consulta = mp.get_payment(payment_id)
            if not consulta.ok:
                raise PaymentError(
                    "Não foi possível verificar a cobrança atual antes da troca.",
                    status_code=409,
                    details=consulta.data,
                )
            status_atual = str(consulta.data.get("status") or "").strip().lower()
            if status_atual == "approved":
                PaymentService.update_origin(
                    encomenda,
                    consulta.data,
                    origin_type="encomenda",
                    on_approved=_encomenda_payment_callback(db, empresa, encomenda),
                )
                db.commit()
                raise PaymentError(
                    "O pagamento já foi aprovado e não pode ser trocado.",
                    status_code=409,
                )
            if status_atual in {"pending", "in_process", "authorized"}:
                cancelamento = mp.cancel_payment(payment_id)
                if not cancelamento.ok:
                    raise PaymentError(
                        "Não foi possível cancelar a cobrança pendente para trocar a forma de pagamento.",
                        status_code=409,
                        details=cancelamento.data,
                    )

        # A tentativa anterior já terminou/cancelou (ou ainda nem tinha sido criada).
        # Preparamos a mesma encomenda para uma nova forma, sem gerar uma segunda encomenda.
        encomenda.gateway_pagamento = novo_metodo
        encomenda.gateway_payment_id = None
        encomenda.gateway_status = "switching_method"
        encomenda.gateway_status_detail = f"v786_superseded:{payment_id}" if payment_id else "v786_switching"
        encomenda.pagamento_status = "pendente"
        encomenda.status = "aguardando_sinal" if novo_metodo == "pix_sinal_manual" else "aguardando_pagamento"
        if novo_metodo in {"pix_online", "cartao_online"}:
            _v788_respeitar_liberacao_encomenda_online(empresa, encomenda)
        db.commit()
        if novo_metodo == "pix_sinal_manual":
            enqueue_new_encomenda(encomenda.id)

        return {
            "ok": True,
            "novo_metodo": novo_metodo,
            "pix_manual": {
                "chave": getattr(empresa, "sinal_pix_chave", None),
                "titular": getattr(empresa, "sinal_pix_titular", None),
                "prazo_minutos": int(getattr(empresa, "sinal_prazo_minutos", 30) or 30),
                "politica": getattr(empresa, "sinal_politica", None),
            } if novo_metodo == "pix_sinal_manual" else None,
        }
    except PaymentError as error:
        db.rollback()
        if _v784_is_local_payment_debug_request(request) and error.details:
            return JSONResponse(
                {
                    "error": str(error),
                    "payment_debug_local": True,
                    "diagnostico": _v784_safe_mercadopago_diagnostic(error.details),
                },
                status_code=error.status_code,
            )
        return _payment_error_response(error)
    except Exception:
        db.rollback()
        LOGGER.exception("Falha ao trocar método de pagamento da encomenda %s", encomenda_id)
        return JSONResponse({"error": "Não foi possível trocar a forma de pagamento."}, status_code=500)
    finally:
        db.close()


@app.get("/api/pagamentos/mercadopago/{empresa_id}/encomenda/{encomenda_id}/status")
def status_pagamento_encomenda(empresa_id: int, encomenda_id: int, request: Request, token: str = ""):
    """v893 — status com sincronização de fallback no Mercado Pago.

    O webhook continua sendo o caminho principal. Enquanto a cobrança estiver
    pendente, esta consulta pública também verifica o gateway. Assim, um webhook
    atrasado ou perdido não deixa a encomenda presa indefinidamente em
    ``in_process``/``pending`` no banco local.
    """
    db = SessionLocal()
    try:
        empresa = db.query(Empresa).filter(Empresa.id == empresa_id).first()
        encomenda = db.query(Encomenda).filter(
            Encomenda.id == encomenda_id,
            Encomenda.empresa_id == empresa_id,
        ).first()
        valor_token = token or request.headers.get("X-Public-Token") or ""
        if (
            not empresa
            or not encomenda
            or not valor_token
            or not hmac.compare_digest(str(valor_token), str(encomenda.public_token or ""))
        ):
            raise HTTPException(status_code=404, detail="Pagamento não encontrado.")

        pagamento_status = str(getattr(encomenda, "pagamento_status", "") or "").strip().lower()
        gateway_status = str(getattr(encomenda, "gateway_status", "") or "").strip().lower()
        payment_id = str(getattr(encomenda, "gateway_payment_id", "") or "").strip()
        status_pendente = (
            pagamento_status in {"pendente", "aguardando_pagamento", "aguardando_sinal"}
            or gateway_status in {"pending", "in_process", "authorized"}
        )

        # V926 — se a criação do pagamento terminou em timeout antes de recebermos
        # o payment_id, tenta localizar a cobrança pelo external_reference.
        if not payment_id and status_pendente and gateway_status == "unknown":
            status_antes = pagamento_status
            try:
                pagamento = PaymentService.locate_payment(
                    company=empresa,
                    origin=encomenda,
                    origin_type="encomenda",
                    amount=_encomenda_valor_pagamento(encomenda),
                    timeout=8,
                )
                if pagamento is not None:
                    PaymentService.update_origin(
                        encomenda,
                        pagamento,
                        origin_type="encomenda",
                        on_approved=_encomenda_payment_callback(db, empresa, encomenda),
                    )
                    _v788_respeitar_liberacao_encomenda_online(empresa, encomenda)
                    db.commit()
                    payment_id = str(getattr(encomenda, "gateway_payment_id", "") or "").strip()
                    pagamento_status = str(getattr(encomenda, "pagamento_status", "") or "").strip().lower()
                    gateway_status = str(getattr(encomenda, "gateway_status", "") or "").strip().lower()
                    if (
                        gateway_status == "approved"
                        and status_antes not in {"pago", "sinal_pago"}
                        and pagamento_status in {"pago", "sinal_pago"}
                    ):
                        enqueue_new_encomenda(encomenda.id)
            except Exception:
                LOGGER.exception(
                    "v926 falha ao reconciliar criação ambígua da encomenda=%s",
                    encomenda_id,
                )
                db.rollback()
                encomenda = db.query(Encomenda).filter(
                    Encomenda.id == encomenda_id,
                    Encomenda.empresa_id == empresa_id,
                ).first()

        if payment_id and status_pendente:
            status_antes = pagamento_status
            try:
                mp = MercadoPagoService(PaymentService.ensure_company_enabled(empresa))
                resposta = mp.get_payment(payment_id)
                if resposta.ok:
                    pagamento = resposta.data
                    referencia = parse_external_reference(pagamento.get("external_reference"))
                    referencia_valida = bool(
                        referencia
                        and referencia.origin_type == "encomenda"
                        and referencia.company_id == int(empresa_id)
                        and referencia.origin_id == int(encomenda_id)
                    )
                    valor_valido = amounts_match(
                        _encomenda_valor_pagamento(encomenda),
                        pagamento.get("transaction_amount"),
                    )
                    if referencia_valida and valor_valido:
                        PaymentService.update_origin(
                            encomenda,
                            pagamento,
                            origin_type="encomenda",
                            on_approved=_encomenda_payment_callback(db, empresa, encomenda),
                        )
                        _v788_respeitar_liberacao_encomenda_online(empresa, encomenda)
                        db.commit()

                        status_gateway_atual = str(pagamento.get("status") or "").strip().lower()
                        status_depois = str(getattr(encomenda, "pagamento_status", "") or "").strip().lower()
                        if (
                            status_gateway_atual == "approved"
                            and status_antes not in {"pago", "sinal_pago"}
                            and status_depois in {"pago", "sinal_pago"}
                        ):
                            enqueue_new_encomenda(encomenda.id)
                    else:
                        LOGGER.warning(
                            "v893 sincronização ignorada por divergência encomenda=%s payment=%s referencia_ok=%s valor_ok=%s",
                            encomenda_id,
                            payment_id,
                            referencia_valida,
                            valor_valido,
                        )
                else:
                    LOGGER.warning(
                        "v893 Mercado Pago não respondeu status da encomenda=%s payment=%s http=%s",
                        encomenda_id,
                        payment_id,
                        resposta.status_code,
                    )
            except PaymentError as error:
                # Fallback: se o gateway estiver temporariamente indisponível,
                # devolvemos o último estado persistido em vez de quebrar o checkout.
                LOGGER.warning(
                    "v893 falha ao sincronizar status da encomenda=%s: %s",
                    encomenda_id,
                    error,
                )
                db.rollback()
                encomenda = db.query(Encomenda).filter(
                    Encomenda.id == encomenda_id,
                    Encomenda.empresa_id == empresa_id,
                ).first()
            except Exception:
                LOGGER.exception(
                    "v893 falha inesperada ao sincronizar status da encomenda=%s",
                    encomenda_id,
                )
                db.rollback()
                encomenda = db.query(Encomenda).filter(
                    Encomenda.id == encomenda_id,
                    Encomenda.empresa_id == empresa_id,
                ).first()

        return PaymentService.status_payload(encomenda, "encomenda")
    finally:
        db.close()


# ==================================================
# MINHAS ENCOMENDAS — CONSULTA E CANCELAMENTO PÚBLICO (V913)
# ==================================================

def _v913_encomenda_telefone(valor) -> str:
    numero = re.sub(r"\D", "", str(valor or ""))
    if numero.startswith("55") and len(numero) in (12, 13):
        numero = numero[2:]
    return numero


def _v913_encomenda_status_publico(encomenda: Encomenda) -> tuple[str, str]:
    status = str(getattr(encomenda, "status", "") or "nova").strip().lower()
    pagamento = normalize_order_value(getattr(encomenda, "pagamento_status", None))
    if status in {"cancelada", "pagamento_cancelado"}:
        if str(getattr(encomenda, "cancelamento_origem", "") or "").strip().lower() == "cliente":
            return "Cancelada pelo cliente", "cancelada"
        return "Cancelada", "cancelada"
    if status in {"recusada", "pagamento_recusado", "expirada", "expirado"}:
        return "Cancelada", "cancelada"
    if status in {"entregue", "finalizada"}:
        return "Finalizada", "finalizada"
    if status == "pronta":
        return "Pronta", "pronta"
    if status == "producao":
        return "Em produção", "producao"
    if status == "confirmada":
        return "Confirmada", "confirmada"
    if status in {"aguardando_pagamento", "aguardando_sinal"}:
        return ("Aguardando sinal" if float(getattr(encomenda, "sinal_valor", 0) or 0) > 0 else "Aguardando pagamento"), "aguardando"
    if pagamento in {"sinal_pago", "pago", "approved", "aprovado"}:
        return "Nova", "nova"
    return "Nova", "nova"


def _v913_encomenda_sinal_pago(encomenda: Encomenda) -> tuple[bool, float]:
    sinal = round(max(0.0, float(getattr(encomenda, "sinal_valor", 0) or 0)), 2)
    saldo = round(max(0.0, float(getattr(encomenda, "saldo_valor", 0) or 0)), 2)
    pagamento = normalize_order_value(getattr(encomenda, "pagamento_status", None))
    gateway = normalize_order_value(getattr(encomenda, "gateway_status", None))
    pago = bool(
        sinal > 0.005
        and saldo > 0.005
        and (pagamento in {"sinal_pago", "pago", "approved", "aprovado"} or gateway == "approved")
    )
    return pago, (sinal if pago else 0.0)


def _v913_encomenda_pagamento_integral(encomenda: Encomenda) -> bool:
    total = round(max(0.0, float(getattr(encomenda, "total", 0) or 0)), 2)
    sinal = round(max(0.0, float(getattr(encomenda, "sinal_valor", 0) or 0)), 2)
    saldo = round(max(0.0, float(getattr(encomenda, "saldo_valor", 0) or 0)), 2)
    pagamento = normalize_order_value(getattr(encomenda, "pagamento_status", None))
    gateway = normalize_order_value(getattr(encomenda, "gateway_status", None))
    confirmado = pagamento in {"pago", "approved", "aprovado"} or gateway == "approved"
    return bool(confirmado and total > 0.005 and (sinal <= 0.005 or saldo <= 0.005))


@app.post("/menu/{slug}/minhas-encomendas/buscar")
async def buscar_minhas_encomendas_publico(slug: str, request: Request):
    dados = await request.json()
    telefone = _v913_encomenda_telefone(dados.get("telefone"))
    if len(telefone) < 8:
        return JSONResponse({"error": "Informe o telefone usado na encomenda."}, status_code=400)

    db = SessionLocal()
    try:
        empresa = db.query(Empresa).filter(Empresa.slug == slug).first()
        if not empresa:
            return JSONResponse({"error": "Empresa não encontrada."}, status_code=404)

        candidatas = db.query(Encomenda).filter(
            Encomenda.empresa_id == empresa.id,
            Encomenda.telefone.isnot(None),
        ).order_by(Encomenda.criado_em.desc(), Encomenda.id.desc()).limit(120).all()
        encomendas = [e for e in candidatas if _v913_encomenda_telefone(e.telefone) == telefone][:30]

        alterou = False
        itens = []
        bloqueados = {
            "producao", "pronta", "entregue", "finalizada",
            "cancelada", "pagamento_cancelado", "recusada",
            "pagamento_recusado", "expirada", "expirado",
        }
        for encomenda in encomendas:
            if not str(getattr(encomenda, "public_token", "") or "").strip():
                encomenda.public_token = secrets.token_urlsafe(24)
                alterou = True
            status_key = str(getattr(encomenda, "status", "") or "nova").strip().lower()
            status_label, status_classe = _v913_encomenda_status_publico(encomenda)
            sinal_pago, sinal_pago_valor = _v913_encomenda_sinal_pago(encomenda)
            pagamento_integral = _v913_encomenda_pagamento_integral(encomenda)
            total = round(max(0.0, float(getattr(encomenda, "total", 0) or 0)), 2)
            saldo = round(max(0.0, total - sinal_pago_valor), 2) if sinal_pago else round(max(0.0, float(getattr(encomenda, "saldo_valor", 0) or 0)), 2)
            itens.append({
                "id": encomenda.id,
                "numero": encomenda.numero or f"{encomenda.id:04d}",
                "data": _data_encomenda_legivel(encomenda.data_retirada),
                "data_iso": encomenda.data_retirada.isoformat() if encomenda.data_retirada else "",
                "horario": str(encomenda.horario or ""),
                "tipo": "Entrega" if str(encomenda.tipo_recebimento or "").lower() == "entrega" else "Retirada",
                "status": status_label,
                "status_classe": status_classe,
                "total": total,
                "sinal_pago": sinal_pago,
                "sinal_pago_valor": sinal_pago_valor,
                "saldo": saldo,
                "pode_cancelar": bool(status_key not in bloqueados and not pagamento_integral),
                "cancelamento_bloqueado_motivo": (
                    "A encomenda já entrou em produção. Entre em contato com o estabelecimento."
                    if status_key in {"producao", "pronta"}
                    else ("O pagamento integral já foi confirmado. Entre em contato com o estabelecimento." if pagamento_integral else "")
                ),
                "public_token": encomenda.public_token,
            })
        if alterou:
            db.commit()
        return {"ok": True, "encomendas": itens}
    finally:
        db.close()


@app.post("/menu/{slug}/minhas-encomendas/{encomenda_id}/cancelar")
async def cancelar_minha_encomenda_publico(slug: str, encomenda_id: int, request: Request):
    dados = await request.json()
    telefone = _v913_encomenda_telefone(dados.get("telefone"))
    token = str(dados.get("token") or "").strip()

    db = SessionLocal()
    try:
        empresa = db.query(Empresa).filter(Empresa.slug == slug).first()
        encomenda = db.query(Encomenda).filter(
            Encomenda.id == encomenda_id,
            Encomenda.empresa_id == (empresa.id if empresa else -1),
        ).first()
        if not empresa or not encomenda:
            return JSONResponse({"error": "Encomenda não encontrada."}, status_code=404)
        if not token or not str(getattr(encomenda, "public_token", "") or "") or not hmac.compare_digest(token, str(encomenda.public_token or "")):
            return JSONResponse({"error": "Não foi possível validar esta encomenda."}, status_code=403)
        if _v913_encomenda_telefone(encomenda.telefone) != telefone:
            return JSONResponse({"error": "Os dados da consulta não conferem."}, status_code=403)

        status_atual = str(getattr(encomenda, "status", "") or "nova").strip().lower()
        if status_atual in {"cancelada", "pagamento_cancelado", "recusada", "pagamento_recusado", "expirada", "expirado", "entregue", "finalizada"}:
            return JSONResponse({"error": "Esta encomenda não pode mais ser cancelada."}, status_code=409)
        if status_atual in {"producao", "pronta"}:
            return JSONResponse({"error": "Esta encomenda já entrou em produção. Entre em contato com o estabelecimento para solicitar o cancelamento."}, status_code=409)

        # Reconciliamos a cobrança antes da decisão. Se o sinal tiver sido pago
        # segundos antes do clique, ele será preservado e nunca estornado aqui.
        if getattr(encomenda, "gateway_payment_id", None):
            try:
                sync_origin(
                    empresa,
                    encomenda,
                    "encomenda",
                    on_approved=_encomenda_payment_callback(db, empresa, encomenda),
                )
                _v788_respeitar_liberacao_encomenda_online(empresa, encomenda)
                db.flush()
            except PaymentError as error:
                db.rollback()
                return _payment_error_response(error)

        if _v913_encomenda_pagamento_integral(encomenda):
            db.rollback()
            return JSONResponse(
                {"error": "O pagamento integral já foi confirmado. Entre em contato com o estabelecimento para solicitar o cancelamento."},
                status_code=409,
            )

        sinal_pago, sinal_pago_valor = _v913_encomenda_sinal_pago(encomenda)
        if getattr(encomenda, "gateway_payment_id", None) and not sinal_pago:
            try:
                _cancelar_tentativa_gateway_v894(
                    db,
                    empresa,
                    encomenda,
                    "encomenda",
                    on_approved=_encomenda_payment_callback(db, empresa, encomenda),
                )
            except PaymentError as error:
                db.rollback()
                return _payment_error_response(error)
            if _v913_encomenda_pagamento_integral(encomenda):
                db.rollback()
                return JSONResponse({"error": "O pagamento foi aprovado durante o cancelamento. Entre em contato com o estabelecimento."}, status_code=409)
            sinal_pago, sinal_pago_valor = _v913_encomenda_sinal_pago(encomenda)

        encomenda.status = "cancelada"
        encomenda.cancelamento_origem = "cliente"
        encomenda.cancelamento_em = agora_brasilia().replace(tzinfo=None)
        encomenda.reembolso_status = "nao_realizado" if sinal_pago else "nao_aplicavel"
        if not sinal_pago:
            encomenda.pagamento_status = "cancelado_cliente"
            if not getattr(encomenda, "gateway_payment_id", None):
                encomenda.gateway_status = "cancelled_by_customer"
                encomenda.gateway_status_detail = "customer_cancelled_encomenda"
        db.commit()

        enqueue_encomenda_cancelled_by_customer(encomenda.id)

        if sinal_pago:
            mensagem = (
                f"Encomenda cancelada. O sinal pago de R$ {sinal_pago_valor:.2f} não será reembolsado. "
                "O estabelecimento foi avisado."
            )
        else:
            mensagem = "Encomenda cancelada. O estabelecimento foi avisado."
        return {
            "ok": True,
            "message": mensagem,
            "status": "Cancelada pelo cliente",
            "sinal_pago": sinal_pago,
            "sinal_pago_valor": round(sinal_pago_valor, 2),
            "reembolso_automatico": False,
        }
    except Exception:
        db.rollback()
        LOGGER.exception("Falha ao cancelar encomenda pública %s", encomenda_id)
        return JSONResponse({"error": "Não foi possível cancelar a encomenda."}, status_code=500)
    finally:
        db.close()


