def _v761_empresa_preview(empresa_id: int, request: Request):
    redirecionamento = redirecionar_area_admin_se_necessario(request, empresa_id, "dashboard")
    if redirecionamento:
        return None, redirecionamento
    db = SessionLocal()
    empresa = db.query(Empresa).filter(Empresa.id == empresa_id).first()
    if not empresa:
        db.close()
        return None, RedirectResponse(url="/login", status_code=303)
    anexar_idioma_empresa(db, empresa)
    return (db, empresa), None


