@app.get("/admin/{empresa_id}")
def admin_empresa(empresa_id: int, request: Request):
    redirecionamento = redirecionar_area_admin_se_necessario(request, empresa_id, "dashboard")
    if redirecionamento:
        return redirecionamento
    db = SessionLocal()

    empresa = db.query(Empresa).filter(
        Empresa.id == empresa_id
    ).first()

    if not empresa:
        db.close()
        return {"error": "Empresa não encontrada"}

    usuario_painel = db.query(UsuarioAdmin).filter(
        UsuarioAdmin.id == usuario_admin_sessao(request),
        UsuarioAdmin.empresa_id == empresa_id,
        UsuarioAdmin.ativo == True
    ).first()
    admin_nome_painel = (
        (usuario_painel.nome if usuario_painel else None)
        or request.session.get("admin_nome")
        or "Equipe"
    )
    admin_email_painel = usuario_painel.email if usuario_painel else ""

    aviso_plano_vencido = plano_empresa_vencido(empresa)

    # ==============================================
    # CONTADORES GERAIS
    # ==============================================

    total_categorias = db.query(Categoria).filter(
        Categoria.empresa_id == empresa_id
    ).count()

    total_itens = db.query(Item).filter(
        Item.empresa_id == empresa_id
    ).count()

    total_pedidos = db.query(Pedido).filter(
        Pedido.empresa_id == empresa_id
    ).count()

    total_reservas = db.query(Reserva).filter(
        Reserva.empresa_id == empresa_id
    ).count()

    # ==============================================
    # PEDIDOS RECENTES
    # ==============================================

    pedidos_recentes_db = db.query(Pedido).filter(
        Pedido.empresa_id == empresa_id
    ).order_by(Pedido.id.desc()).limit(5).all()

    # Evita DetachedInstanceError no template depois do db.close()
    pedidos_recentes = [
        {
            "id": pedido.id,
            "nome_cliente": pedido.nome_cliente,
            "total": pedido.total or 0,
            "status": pedido.status
        }
        for pedido in pedidos_recentes_db
    ]

    # ==============================================
    # DASHBOARD FINANCEIRO
    # Regra atual:
    # somente pedidos FINALIZADOS entram no faturamento
    # ==============================================

    pedidos_finalizados = db.query(Pedido).filter(
        Pedido.empresa_id == empresa_id,
        Pedido.status == "finalizado"
    ).all()

    total_pedidos_finalizados = len(pedidos_finalizados)

    faturamento_total = sum(
        pedido.total or 0
        for pedido in pedidos_finalizados
    )

    faturamento_sem_iva = sum(
        pedido.subtotal_sem_iva or 0
        for pedido in pedidos_finalizados
    )

    iva_acumulada = sum(
        pedido.total_iva or 0
        for pedido in pedidos_finalizados
    )

    ticket_medio = (
        faturamento_total / total_pedidos_finalizados
        if total_pedidos_finalizados > 0
        else 0
    )

    # ==============================================
    # PLANO ÚNICO DO SAAS
    # ==============================================

    if not getattr(empresa, "plano_nome", None):
        empresa.plano_nome = "Plano Completo"

    if not getattr(empresa, "plano_status", None):
        empresa.plano_status = "ativo"

    if getattr(empresa, "plano_valor_mensal", None) is None:
        empresa.plano_valor_mensal = 0

    if not getattr(empresa, "assinatura_inicio", None):
        empresa.assinatura_inicio = agora_brasilia()

    if not getattr(empresa, "assinatura_vencimento", None):
        empresa.assinatura_vencimento = agora_brasilia() + timedelta(days=30)

    db.commit()
    db.refresh(empresa)

    plano_dias_restantes = None
    if empresa.assinatura_vencimento:
        plano_dias_restantes = max(
            0,
            (empresa.assinatura_vencimento.date() - agora_brasilia().date()).days
        )

    pedidos_novos = db.query(Pedido).filter(
        Pedido.empresa_id == empresa_id,
        Pedido.status == "novo"
    ).count()

    reservas_pendentes = db.query(Reserva).filter(
        Reserva.empresa_id == empresa_id,
        Reserva.status == "pendente"
    ).count()

    reservas_recentes_db = db.query(Reserva).filter(
        Reserva.empresa_id == empresa_id
    ).order_by(Reserva.id.desc()).limit(5).all()

    reservas_recentes = [
        {
            "id": reserva.id,
            "nome_cliente": reserva.nome_cliente,
            "data": reserva.data,
            "horario": reserva.horario,
            "pessoas": getattr(reserva, "pessoas", 0) or 0,
            "status": reserva.status
        }
        for reserva in reservas_recentes_db
    ]

    anexar_idioma_empresa(db, empresa)

    negocio_servico = tipo_negocio_servico(getattr(empresa, "tipo", ""))
    negocio_produto = tipo_negocio_produto(getattr(empresa, "tipo", ""))
    negocio_encomenda = tipo_negocio_encomenda(getattr(empresa, "tipo", ""))
    if negocio_encomenda:
        garantir_categorias_encomendas_padrao(db, empresa_id)
        total_categorias = db.query(CategoriaEncomenda).filter(CategoriaEncomenda.empresa_id == empresa_id).count()
        total_itens = db.query(ItemEncomenda).filter(ItemEncomenda.empresa_id == empresa_id, ItemEncomenda.ativo == True).count()
        total_pedidos = db.query(Encomenda).filter(Encomenda.empresa_id == empresa_id).count()
        total_reservas = 0
        pedidos_novos = db.query(Encomenda).filter(Encomenda.empresa_id == empresa_id, Encomenda.status == "nova").count()
        reservas_pendentes = 0
    onboarding_estado = str(getattr(empresa, "onboarding_estado", "") or "").strip().lower()
    if onboarding_estado not in {"pendente", "concluido"}:
        # Migração segura para empresas antigas: negócios ainda vazios recebem o guia
        # uma única vez; empresas já configuradas permanecem como concluídas.
        onboarding_estado = (
            "pendente"
            if total_categorias == 0 and total_itens == 0 and total_reservas == 0
            else "concluido"
        )
        empresa.onboarding_estado = onboarding_estado
        empresa.onboarding_concluido = onboarding_estado == "concluido"
        db.commit()
        db.refresh(empresa)
    onboarding_pendente = onboarding_estado == "pendente"

    db.close()

    return templates.TemplateResponse(
        request=request,
        name="admin.html",
        context={
            "empresa": empresa,

            "total_categorias": total_categorias,
            "total_itens": total_itens,
            "total_pedidos": total_pedidos,
            "total_reservas": total_reservas,
            "pedidos_novos": pedidos_novos,
            "reservas_pendentes": reservas_pendentes,

            "pedidos_recentes": pedidos_recentes,
            "reservas_recentes": reservas_recentes,

            "total_pedidos_finalizados": total_pedidos_finalizados,
            "faturamento_total": faturamento_total,
            "faturamento_sem_iva": faturamento_sem_iva,
            "iva_acumulada": iva_acumulada,
            "ticket_medio": ticket_medio,
            "plano_dias_restantes": plano_dias_restantes,
            "aviso_plano_vencido": aviso_plano_vencido,
            "admin_nome_painel": admin_nome_painel,
            "admin_email_painel": admin_email_painel,
            "troca_senha_obrigatoria": bool(request.session.get("troca_senha_obrigatoria")),
            "negocio_servico": negocio_servico,
            "negocio_produto": negocio_produto,
            "negocio_encomenda": negocio_encomenda,
            "onboarding_pendente": onboarding_pendente
        }
    )


@app.post("/admin/{empresa_id}/onboarding-concluir")
def concluir_onboarding_admin(empresa_id: int, request: Request):
    redirecionamento = redirecionar_area_admin_se_necessario(request, empresa_id, "dashboard")
    if redirecionamento:
        return redirecionamento

    db = SessionLocal()
    empresa = db.query(Empresa).filter(Empresa.id == empresa_id).first()
    if not empresa:
        db.close()
        return RedirectResponse(url="/login", status_code=303)

    empresa.onboarding_concluido = True
    empresa.onboarding_estado = "concluido"
    db.commit()
    db.close()
    return RedirectResponse(url=f"/admin/{empresa_id}?onboarding=concluido", status_code=303)


