@app.post("/admin/{empresa_id}/perfil-atualizar")
async def atualizar_perfil_admin(empresa_id: int, request: Request):
    redirecionamento = redirecionar_login_se_necessario(request, empresa_id)
    if redirecionamento:
        return redirecionamento

    formulario = await request.form()
    nome = str(formulario.get("admin_nome", "")).strip()
    email = str(formulario.get("admin_email", "")).strip().lower()
    senha_atual = str(formulario.get("senha_atual", ""))
    nova_senha = str(formulario.get("nova_senha", ""))
    confirmar_senha = str(formulario.get("confirmar_senha", ""))
    alterar_senha = str(formulario.get("alterar_senha", "0")).strip() == "1"
    troca_obrigatoria = bool(request.session.get("troca_senha_obrigatoria"))

    if not nome or not email:
        return RedirectResponse(url=f"/admin/{empresa_id}?perfil=campos", status_code=303)

    if troca_obrigatoria:
        alterar_senha = True
        if not nova_senha or not confirmar_senha:
            return RedirectResponse(url=f"/admin/{empresa_id}?perfil=troca_obrigatoria", status_code=303)

    # Navegadores e gerenciadores de senha podem preencher o campo de nova
    # senha automaticamente. Só tratamos senha quando a pessoa iniciou
    # explicitamente a alteração no modal.
    if alterar_senha:
        if not nova_senha and not confirmar_senha:
            alterar_senha = False
        elif nova_senha != confirmar_senha:
            return RedirectResponse(url=f"/admin/{empresa_id}?perfil=senhas", status_code=303)
        elif len(nova_senha) < 8:
            return RedirectResponse(url=f"/admin/{empresa_id}?perfil=senha_curta", status_code=303)

    db = SessionLocal()
    try:
        usuario = db.query(UsuarioAdmin).filter(
            UsuarioAdmin.id == usuario_admin_sessao(request),
            UsuarioAdmin.empresa_id == empresa_id,
            UsuarioAdmin.ativo == True
        ).first()
        if not usuario:
            return RedirectResponse(url="/login", status_code=303)

        email_em_uso = db.query(UsuarioAdmin).filter(
            UsuarioAdmin.email == email,
            UsuarioAdmin.id != usuario.id
        ).first()
        if email_em_uso:
            return RedirectResponse(url=f"/admin/{empresa_id}?perfil=email_em_uso", status_code=303)

        # v711: nenhuma troca de senha é aceita sem confirmar a senha atual.
        if alterar_senha:
            if not senha_atual:
                return RedirectResponse(url=f"/admin/{empresa_id}?perfil=senha_atual", status_code=303)
            if not validar_senha(senha_atual, usuario.senha_hash):
                return RedirectResponse(url=f"/admin/{empresa_id}?perfil=senha_atual_incorreta", status_code=303)

        usuario.nome = nome
        usuario.email = email
        if alterar_senha and nova_senha:
            usuario.senha_hash = gerar_hash_senha(nova_senha)

        db.commit()
        if alterar_senha and nova_senha:
            definir_troca_senha_obrigatoria_saas(usuario.id, empresa_id, False)
            request.session["troca_senha_obrigatoria"] = False
        request.session["admin_nome"] = usuario.nome or "Equipe"
        request.session["admin_perfil"] = getattr(usuario, "perfil", "administrador") or "administrador"
        request.session["admin_permissoes"] = serializar_permissoes(permissoes_do_usuario(usuario))
        return RedirectResponse(url=f"/admin/{empresa_id}?perfil=salvo", status_code=303)
    except Exception:
        db.rollback()
        raise
    finally:
        db.close()


