# ==================================================
# MEUS AGENDAMENTOS — CONSULTA PÚBLICA
# ==================================================


def _somente_digitos(valor) -> str:
    return re.sub(r"\D", "", str(valor or ""))


def _telefone_local_comparacao(valor) -> str:
    """Normaliza telefone para comparar números com ou sem DDI 55."""
    numero = _somente_digitos(valor)
    if numero.startswith("55") and len(numero) in (12, 13):
        numero = numero[2:]
    return numero


def _status_publico_agendamento(reserva: Reserva) -> tuple[str, str]:
    status = str(getattr(reserva, "status", None) or "pendente").strip().lower()
    pagamento = str(getattr(reserva, "status_pagamento", None) or "").strip().lower()
    valor_sinal = float(getattr(reserva, "valor_sinal", 0) or 0)

    if status in {"aguardando_pagamento", "aguardando sinal", "aguardando_sinal"}:
        if pagamento == "comprovante_enviado":
            return "Comprovante enviado", "comprovante"
        return "Aguardando sinal", "aguardando"
    if status in {"confirmada", "confirmado"}:
        if valor_sinal > 0 and pagamento in {"pago", "aprovado", "approved"}:
            return "Confirmado — sinal recebido", "confirmado-sinal"
        return "Confirmado", "confirmado"
    if status in {"aguardando_conclusao", "aguardando conclusão", "aguardando-conclusao"}:
        return "Aguardando conclusão", "aguardando-conclusao"
    if status in {"cancelada", "cancelado"}:
        return "Cancelado", "cancelado"
    if status in {"recusada", "recusado"}:
        return "Recusado", "recusado"
    if status in {"concluida", "concluída", "concluido", "concluído", "paga", "pago"}:
        return "Concluído", "concluido"
    if status in {"expirada", "expirado"}:
        return "Expirado", "expirado"
    return "Pendente", "pendente"


def _agendamento_ainda_futuro(reserva: Reserva) -> bool:
    try:
        data_texto = normalizar_data_reserva(str(reserva.data or ""))
        hora_texto = str(reserva.horario or "").split(" - ", 1)[0].strip()
        instante = datetime.strptime(f"{data_texto} {hora_texto}", "%Y-%m-%d %H:%M")
        return instante > agora_brasilia()
    except Exception:
        return True


def _servico_publico_reserva(reserva: Reserva) -> str:
    texto = str(getattr(reserva, "observacao", None) or "").strip()
    if not texto:
        return "Serviço não informado"
    texto = re.split(r"\s*\|\s*(?:Obs\.|Nota|Note)\s*:\s*", texto, maxsplit=1, flags=re.I)[0].strip()
    return texto or "Serviço não informado"


@app.post("/menu/{slug}/meus-agendamentos/buscar")
async def buscar_meus_agendamentos_publico(slug: str, request: Request):
    dados = await request.json()
    cpf = _somente_digitos(dados.get("cpf"))

    if len(cpf) != 11:
        return {"error": "Informe um CPF com 11 números."}

    db = SessionLocal()
    try:
        empresa = db.query(Empresa).filter(Empresa.slug == slug).first()
        if not empresa:
            return {"error": "Empresa não encontrada."}
        expirar_reservas_pendentes_antigas(db, empresa.id)

        # V281 — em “Meus agendamentos”, a consulta pública deve mostrar
        # primeiro o agendamento criado mais recentemente. A data marcada para
        # o atendimento não define a ordem de criação e podia empurrar o último
        # agendamento para o fim da lista.
        reservas_cpf = db.query(Reserva).filter(
            Reserva.empresa_id == empresa.id,
            Reserva.cpf_cliente == cpf,
        ).order_by(Reserva.criado_em.desc(), Reserva.id.desc()).limit(60).all()

        reservas = reservas_cpf

        garantir_tokens_publicos_reservas(db, reservas)

        profissional_ids = {r.profissional_id for r in reservas if getattr(r, "profissional_id", None)}
        profissionais = {}
        if profissional_ids:
            profissionais = {
                p.id: p.nome
                for p in db.query(Profissional).filter(
                    Profissional.empresa_id == empresa.id,
                    Profissional.id.in_(profissional_ids),
                ).all()
            }

        itens = []
        bloqueados = {"cancelada", "cancelado", "recusada", "recusado", "concluida", "concluída", "concluido", "concluído", "paga", "pago", "expirada", "expirado"}
        for reserva in reservas:
            status_br, status_classe = _status_publico_agendamento(reserva)
            status_original = str(reserva.status or "pendente").strip().lower()
            pode_cancelar = status_original not in bloqueados and _agendamento_ainda_futuro(reserva)
            data_br = str(reserva.data or "")
            try:
                data_br = datetime.strptime(normalizar_data_reserva(data_br), "%Y-%m-%d").strftime("%d/%m/%Y")
            except Exception:
                pass

            valor_sinal = max(0.0, float(getattr(reserva, "valor_sinal", 0) or 0))
            valor_sinal_recebido = max(0.0, float(getattr(reserva, "valor_sinal_recebido", 0) or 0))
            pagamento_norm = normalize_order_value(getattr(reserva, "status_pagamento", None))
            sinal_pago = bool(
                valor_sinal > 0
                and (
                    valor_sinal_recebido > 0.005
                    or pagamento_norm in {"pago", "aprovado", "approved", "parcial", "sinal_pago"}
                )
            )
            sinal_pago_valor = valor_sinal_recebido if valor_sinal_recebido > 0.005 else (valor_sinal if sinal_pago else 0.0)

            itens.append({
                "id": reserva.id,
                "codigo": reserva.codigo or f"RSV-{reserva.id:03d}",
                "servico": _servico_publico_reserva(reserva),
                "profissional": profissionais.get(reserva.profissional_id, "Não informado"),
                "data": data_br,
                "horario": str(reserva.horario or "").split(" - ", 1)[0],
                "status": status_br,
                "status_classe": status_classe,
                "status_pagamento": str(getattr(reserva, "status_pagamento", None) or ""),
                "valor_total": float(getattr(reserva, "valor_total", 0) or 0),
                "valor_sinal": valor_sinal,
                "valor_sinal_recebido": round(valor_sinal_recebido, 2),
                "sinal_pago": sinal_pago,
                "sinal_pago_valor": round(sinal_pago_valor, 2),
                "pode_cancelar": pode_cancelar,
                "public_token": reserva.public_token,
                "sinal_pix_chave": getattr(empresa, "sinal_pix_chave", None) if status_classe in {"aguardando", "comprovante"} else None,
                "sinal_whatsapp": (getattr(empresa, "sinal_whatsapp", None) or getattr(empresa, "telefone_whatsapp", None)) if status_classe in {"aguardando", "comprovante"} else None,
            })

        return {"ok": True, "agendamentos": itens}
    finally:
        db.close()


@app.post("/menu/{slug}/meus-agendamentos/{reserva_id}/cancelar")
async def cancelar_meu_agendamento_publico(slug: str, reserva_id: int, request: Request):
    dados = await request.json()
    cpf = _somente_digitos(dados.get("cpf"))
    telefone_final4 = _somente_digitos(dados.get("telefone_final4"))[-4:]
    token = str(dados.get("token") or "").strip()

    db = SessionLocal()
    try:
        empresa = db.query(Empresa).filter(Empresa.slug == slug).first()
        reserva = db.query(Reserva).filter(
            Reserva.id == reserva_id,
            Reserva.empresa_id == (empresa.id if empresa else -1),
        ).first()
        if not empresa or not reserva:
            return {"error": "Agendamento não encontrado."}

        esperado = str(getattr(reserva, "public_token", None) or "").strip()
        if not token or not esperado or not hmac.compare_digest(token, esperado):
            return {"error": "Não foi possível validar este agendamento."}
        if _somente_digitos(getattr(reserva, "cpf_cliente", "")) != cpf:
            return {"error": "Dados de consulta inválidos."}
        telefone_reserva = _telefone_local_comparacao(getattr(reserva, "telefone_cliente", ""))
        if len(telefone_final4) != 4 or not telefone_reserva.endswith(telefone_final4):
            return {"error": "Os 4 últimos números do telefone não conferem."}

        status_atual = str(reserva.status or "pendente").strip().lower()
        pagamento_atual = normalize_order_value(getattr(reserva, "status_pagamento", None))
        bloqueados = {"cancelada", "cancelado", "recusada", "recusado", "concluida", "concluída", "concluido", "concluído", "paga", "pago", "expirada", "expirado"}
        if status_atual in bloqueados:
            return {"error": "Este agendamento não pode mais ser cancelado."}
        valor_sinal = max(0.0, float(getattr(reserva, "valor_sinal", 0) or 0))
        valor_sinal_recebido = max(0.0, float(getattr(reserva, "valor_sinal_recebido", 0) or 0))
        sinal_pago = bool(
            valor_sinal > 0
            and (
                valor_sinal_recebido > 0.005
                or pagamento_atual in {"pago", "aprovado", "approved", "parcial", "sinal_pago"}
            )
        )
        sinal_pago_valor = valor_sinal_recebido if valor_sinal_recebido > 0.005 else (valor_sinal if sinal_pago else 0.0)

        # V912 — o cliente pode cancelar um horário mesmo com sinal já recebido.
        # O cancelamento não executa estorno: o sinal permanece no histórico.
        if pagamento_atual in {"pago", "aprovado", "approved"} and not sinal_pago:
            return JSONResponse(
                {"error": "Este agendamento possui pagamento integral aprovado. Entre em contato com o estabelecimento para solicitar o cancelamento."},
                status_code=409,
            )
        if not _agendamento_ainda_futuro(reserva):
            return {"error": "O horário já passou e não pode ser cancelado pelo menu."}

        # Cobrança online ainda pendente deve ser encerrada no gateway antes
        # de liberar o slot. Sinal já aprovado não é cancelado/estornado aqui.
        if getattr(reserva, "gateway_payment_id", None) and not sinal_pago:
            try:
                _cancelar_tentativa_gateway_v894(
                    db,
                    empresa,
                    reserva,
                    "reserva",
                    on_approved=_reserva_approved_callback(db, empresa, reserva),
                )
            except PaymentError as error:
                db.rollback()
                return JSONResponse({"error": str(error)}, status_code=error.status_code)

        reserva.status = "cancelada"
        reserva.horario_liberado = True
        reserva.cancelamento_origem = "cliente"
        reserva.cancelamento_em = agora_brasilia().replace(tzinfo=None)
        reserva.reembolso_status = "nao_realizado" if sinal_pago else "nao_aplicavel"
        if not sinal_pago:
            reserva.gateway_status = "cancelled_by_customer"
            if str(getattr(reserva, "status_pagamento", None) or "").lower() not in {"pago", "aprovado", "approved", "parcial", "sinal_pago"}:
                reserva.status_pagamento = "cancelado_cliente"
        db.commit()

        # Só avisa o estabelecimento depois que o horário está realmente livre.
        enqueue_reservation_cancelled_by_customer(reserva.id)

        mensagem = "Agendamento cancelado. O horário voltou a ficar disponível."
        if sinal_pago:
            mensagem = (
                f"Agendamento cancelado. O sinal pago de R$ {sinal_pago_valor:.2f} não foi estornado e não será reembolsado. "
                "O horário voltou a ficar disponível."
            )

        return {
            "ok": True,
            "message": mensagem,
            "status": "Cancelado",
            "sinal_pago": sinal_pago,
            "sinal_pago_valor": round(sinal_pago_valor, 2),
            "reembolso_automatico": False,
            "horario_liberado": True,
        }
    except Exception:
        db.rollback()
        raise
    finally:
        db.close()



