def configuracao_sinal_aplicavel(empresa: Empresa) -> bool:
    if not empresa or not getattr(empresa, "sinal_reserva_ativo", False):
        return False
    if not (getattr(empresa, "sinal_pix_chave", None) and getattr(empresa, "sinal_pix_titular", None)):
        return False
    if tipo_negocio_servico(getattr(empresa, "tipo", "")):
        return bool(getattr(empresa, "sinal_aplicar_agendamentos", True))
    return bool(getattr(empresa, "sinal_aplicar_reservas", True))


def calcular_sinal_manual(empresa: Empresa, valor_total: float, pessoas: int = 1) -> tuple[float, float]:
    """Retorna (valor_sinal, percentual_equivalente) usando a configuração da empresa."""
    if not configuracao_sinal_aplicavel(empresa):
        return 0.0, 0.0
    try:
        total = max(0.0, float(valor_total or 0))
    except (TypeError, ValueError):
        total = 0.0
    try:
        quantidade = max(1, int(pessoas or 1))
    except (TypeError, ValueError):
        quantidade = 1
    tipo = (getattr(empresa, "sinal_tipo", None) or "percentual").strip().lower()
    try:
        valor = float(getattr(empresa, "sinal_valor", 0) or 0)
    except (TypeError, ValueError):
        valor = 0.0

    percentual = 0.0
    if tipo == "integral":
        sinal = total
        percentual = 100.0 if total > 0 else 0.0
    elif tipo == "fixo":
        sinal = valor
        percentual = (sinal / total * 100.0) if total > 0 else 0.0
    elif tipo == "por_pessoa":
        sinal = valor * quantidade
        percentual = (sinal / total * 100.0) if total > 0 else 0.0
    else:
        percentual = min(100.0, max(1.0, valor or 50.0))
        sinal = total * percentual / 100.0

    if total > 0:
        sinal = min(sinal, total) if tipo != "por_pessoa" else sinal
    return round(max(0.0, sinal), 2), round(max(0.0, percentual), 2)


def normalizar_forma_pagamento_reserva(valor: str | None) -> str:
    texto = re.sub(r"[^a-z0-9]+", "_", str(valor or "").strip().lower()).strip("_")
    aliases = {
        "pix": "pix_online",
        "pix_mercado_pago": "pix_online",
        "cartao": "cartao_credito_online",
        "cartao_online": "cartao_credito_online",
        "credito_online": "cartao_credito_online",
        "cartao_credito": "cartao_credito_online",
        "cartao_credito_online": "cartao_credito_online",
        "debito_online": "cartao_debito_online",
        "cartao_debito": "cartao_debito_online",
        "cartao_debito_online": "cartao_debito_online",
        "pix_manual": "pix_manual",
        "dinheiro": "dinheiro_atendimento",
        "dinheiro_atendimento": "dinheiro_atendimento",
        "dinheiro_local": "dinheiro_atendimento",
        "cartao_atendimento": "cartao_atendimento",
        "cartao_local": "cartao_atendimento",
        "maquininha": "cartao_atendimento",
    }
    return aliases.get(texto, texto)


def validar_forma_pagamento_reserva(
    empresa: Empresa,
    forma: str,
    *,
    exige_sinal: bool,
    valor_cobranca: float,
) -> str:
    forma = normalizar_forma_pagamento_reserva(forma)
    online_ativo = bool(getattr(empresa, "pagamentos_online_ativo", False))
    aceita_pix = bool(getattr(empresa, "aceita_pix_online", False))
    aceita_cartao = bool(getattr(empresa, "aceita_cartao_online", False))
    aceita_dinheiro = bool(getattr(empresa, "aceita_dinheiro", False))
    aceita_cartao_local = bool(getattr(empresa, "aceita_cartao_entrega", False))
    pix_manual_disponivel = bool(
        exige_sinal
        and getattr(empresa, "sinal_pix_chave", None)
        and getattr(empresa, "sinal_pix_titular", None)
    )

    if not forma:
        if valor_cobranca > 0 and online_ativo and aceita_pix:
            forma = "pix_online"
        elif valor_cobranca > 0 and online_ativo and aceita_cartao:
            forma = "cartao_credito_online"
        elif pix_manual_disponivel:
            forma = "pix_manual"
        elif not exige_sinal and aceita_dinheiro:
            forma = "dinheiro_atendimento"
        elif not exige_sinal and aceita_cartao_local:
            forma = "cartao_atendimento"

    if forma == "pix_online":
        if valor_cobranca <= 0:
            raise ValueError("Não existe valor para cobrar por Pix online.")
        if not online_ativo or not aceita_pix:
            raise ValueError("Pix online não está disponível para este estabelecimento.")
    elif forma in {"cartao_credito_online", "cartao_debito_online"}:
        if valor_cobranca <= 0:
            raise ValueError("Não existe valor para cobrar por cartão online.")
        if not online_ativo or not aceita_cartao:
            raise ValueError("Cartão online não está disponível para este estabelecimento.")
    elif forma == "pix_manual":
        if not pix_manual_disponivel:
            raise ValueError("O sinal por Pix manual não está disponível.")
    elif forma == "dinheiro_atendimento":
        if exige_sinal:
            raise ValueError("O sinal precisa ser pago antes do atendimento.")
        if not aceita_dinheiro:
            raise ValueError("Dinheiro no atendimento não está disponível.")
    elif forma == "cartao_atendimento":
        if exige_sinal:
            raise ValueError("O sinal precisa ser pago antes do atendimento.")
        if not aceita_cartao_local:
            raise ValueError("Cartão no atendimento não está disponível.")
    elif forma:
        raise ValueError("Escolha uma forma de pagamento disponível.")
    elif exige_sinal:
        raise ValueError("Escolha uma forma para pagar o sinal.")

    return forma or "a_definir"


@app.post("/reservas")
async def criar_reserva(request: Request):
    dados = await request.json()

    db = SessionLocal()

    try:
        empresa_id = int(dados.get("empresa_id"))
    except (TypeError, ValueError):
        db.close()
        return {"error": "Empresa inválida"}

    empresa = db.query(Empresa).filter(
        Empresa.id == empresa_id
    ).first()

    if not empresa:
        db.close()
        return {"error": "Empresa não encontrada"}

    expirar_reservas_pendentes_antigas(db, empresa_id)

    if plano_empresa_bloqueado(empresa):
        db.close()
        return {"error": "Sistema bloqueado. Reservas temporariamente indisponíveis."}

    data = normalizar_data_reserva(
        dados.get("data") or dados.get("data_reserva") or ""
    )

    horario = (
        dados.get("horario")
        or dados.get("horario_reserva")
        or dados.get("hora")
        or ""
    )

    try:
        profissional_id = int(dados.get("profissional_id") or 0) or None
    except (TypeError, ValueError):
        profissional_id = None

    nome_cliente = (
        dados.get("nome_cliente")
        or dados.get("nome")
        or dados.get("cliente")
        or ""
    ).strip()

    telefone_cliente = (
        dados.get("telefone_cliente")
        or dados.get("telefone")
        or ""
    ).strip()

    cpf_cliente = re.sub(r"\D", "", str(dados.get("cpf_cliente") or dados.get("cpf") or ""))
    if cpf_cliente and len(cpf_cliente) > 11:
        cpf_cliente = cpf_cliente[-11:]

    try:
        pessoas = int(
            dados.get("pessoas")
            or dados.get("numero_pessoas")
            or dados.get("qtd_pessoas")
            or 0
        )
    except (TypeError, ValueError):
        pessoas = 0

    observacao = (
        dados.get("observacao")
        or dados.get("observacoes")
        or ""
    ).strip()

    try:
        valor_total_reserva = round(max(0.0, float(dados.get("valor_total") or 0)), 2)
    except (TypeError, ValueError):
        valor_total_reserva = 0.0

    if not data:
        db.close()
        return {"error": "Informe a data da reserva"}

    if not horario:
        db.close()
        return {"error": "Informe o horário da reserva"}

    if not nome_cliente:
        db.close()
        return {"error": "Informe o nome do cliente"}

    if not telefone_cliente:
        db.close()
        return {"error": "Informe o telefone do cliente"}

    if pessoas <= 0:
        db.close()
        return {"error": "Informe o número de pessoas"}

    if not horario_ainda_futuro(data, horario):
        db.close()
        return {"error": "Este horário já passou no horário de Brasília."}

    data_br = data
    try:
        data_br = datetime.strptime(data, "%Y-%m-%d").strftime("%d/%m/%Y")
    except ValueError:
        pass

    dia_fechado = db.query(DiaFechado).filter(
        DiaFechado.empresa_id == empresa_id,
        DiaFechado.data.in_([data, data_br])
    ).first()

    if dia_fechado:
        db.close()
        return {
            "error": "Estabelecimento fechado nesta data"
        }

    horarios_possiveis = db.query(HorarioReserva).filter(
        HorarioReserva.empresa_id == empresa_id,
        HorarioReserva.data.in_([data, data_br]),
        HorarioReserva.horario == horario,
        HorarioReserva.ativo == True
    )

    if profissional_id:
        horarios_possiveis = horarios_possiveis.filter(
            HorarioReserva.profissional_id == profissional_id
        )

    horarios_possiveis = horarios_possiveis.order_by(
        HorarioReserva.capacidade_maxima.desc(),
        HorarioReserva.id.asc()
    ).all()

    if not horarios_possiveis:
        db.close()
        return {
            "error": "Horário não disponível para esta data"
        }

    horario_existe = None
    melhor_vagas = 0

    # Restaurante pode ter mais de uma mesa/área no mesmo horário.
    # Se o menu público não envia profissional_id, escolhemos automaticamente
    # o horário/mesa com vagas suficientes.
    for horario_opcao in horarios_possiveis:
        capacidade = horario_opcao.capacidade_maxima or 0

        consulta_reservas = db.query(Reserva).filter(
            Reserva.empresa_id == empresa_id,
            Reserva.data.in_([data, data_br]),
            Reserva.horario == horario,
            func.lower(func.trim(Reserva.status)).notin_(["cancelada", "cancelado", "recusada", "recusado", "expirada", "expirado", "concluida", "concluido", "concluída", "concluído", "paga", "pago", "pagamento_recusado", "pagamento_cancelado"])
        )

        if hasattr(Reserva, "horario_id"):
            consulta_reservas = consulta_reservas.filter(
                or_(
                    Reserva.horario_id == horario_opcao.id,
                    and_(
                        Reserva.horario_id == None,
                        Reserva.profissional_id == horario_opcao.profissional_id
                    )
                )
            )

        if getattr(horario_opcao, "profissional_id", None):
            consulta_reservas = consulta_reservas.filter(
                Reserva.profissional_id == horario_opcao.profissional_id
            )

        pessoas_reservadas = sum((r.pessoas or 0) for r in consulta_reservas.all())

        if capacidade <= 0:
            horario_existe = horario_opcao
            break

        vagas = max(0, capacidade - pessoas_reservadas)
        melhor_vagas = max(melhor_vagas, vagas)

        if pessoas <= vagas:
            horario_existe = horario_opcao
            profissional_id = horario_opcao.profissional_id
            break

    if not horario_existe:
        db.close()
        return {
            "error": f"Horário lotado. Vagas disponíveis: {melhor_vagas}"
        }

    data_operacional_reserva = mf_parse_data_operacional(data)
    numero_dia_reserva = gerar_numero_dia(db, Reserva, empresa_id, data_operacional_reserva)
    # `codigo` é único no banco inteiro, enquanto `numero_dia` reinicia por
    # empresa e data. Usar o número diário diretamente causava colisões entre
    # empresas ou em dias diferentes. Mantemos o código curto com sequência
    # global e preservamos `numero_dia` para a operação diária.
    proximo_codigo_numero = int(db.query(func.max(Reserva.id)).scalar() or 0) + 1
    codigo = f"RSV-{proximo_codigo_numero:03d}"
    while db.query(Reserva.id).filter(Reserva.codigo == codigo).first():
        proximo_codigo_numero += 1
        codigo = f"RSV-{proximo_codigo_numero:03d}"

    valor_sinal, percentual_sinal = calcular_sinal_manual(
        empresa, valor_total_reserva, pessoas
    )
    exige_sinal = valor_sinal > 0 and configuracao_sinal_aplicavel(empresa)
    valor_cobranca = valor_sinal if exige_sinal else valor_total_reserva
    try:
        forma_pagamento = validar_forma_pagamento_reserva(
            empresa,
            dados.get("forma_pagamento") or dados.get("pagamento"),
            exige_sinal=exige_sinal,
            valor_cobranca=valor_cobranca,
        )
    except ValueError as erro_pagamento:
        db.close()
        return {"error": str(erro_pagamento)}

    pagamento_online = forma_pagamento in {"pix_online", "cartao_credito_online", "cartao_debito_online"}
    sinal_manual = exige_sinal and forma_pagamento == "pix_manual"

    nova_reserva = Reserva(
        empresa_id=empresa_id,
        criado_em=agora_brasilia(),
        numero_dia=numero_dia_reserva,
        data_operacional=data_operacional_reserva,
        codigo=codigo,
        data=data,
        horario=horario,
        profissional_id=profissional_id,
        horario_id=horario_existe.id if hasattr(Reserva, "horario_id") else None,
        pessoas=pessoas,
        nome_cliente=nome_cliente,
        telefone_cliente=telefone_cliente,
        cpf_cliente=cpf_cliente or None,
        observacao=observacao,
        status="aguardando_pagamento" if (pagamento_online or sinal_manual) else "pendente",
        status_pagamento=(
            "pendente" if pagamento_online
            else "aguardando_pagamento" if sinal_manual
            else "nao_iniciado"
        ),
        gateway_pagamento=(
            "mercadopago" if pagamento_online
            else "pix_manual" if sinal_manual
            else None
        ),
        forma_pagamento=forma_pagamento,
        valor_total=valor_total_reserva,
        valor_sinal=valor_sinal,
        sinal_percentual=percentual_sinal,
        sinal_tipo=(getattr(empresa, "sinal_tipo", None) or "percentual") if exige_sinal else None,
        public_token=secrets.token_urlsafe(32)
    )

    db.add(nova_reserva)
    db.commit()
    db.refresh(nova_reserva)

    # V908: reservas que aguardam pagamento não podem disparar o fluxo
    # operacional como se já estivessem confirmadas. Pix pela chave envia
    # somente um aviso de "aguardando sinal"; lembretes e a notificação normal
    # de novo agendamento ficam para depois da confirmação manual do sinal.
    # V929: qualquer pagamento online fica em hold operacional até a aprovação.
    # Assim o estabelecimento não recebe um "novo agendamento" antes do sinal
    # realmente entrar no gateway. Pix pela chave continua com aviso próprio.
    if sinal_manual:
        enqueue_reservation_awaiting_signal(nova_reserva.id)
    elif not pagamento_online:
        enqueue_new_reservation(nova_reserva.id)

    resposta = {
        "message": "Reserva enviada com sucesso! O estabelecimento irá confirmar a disponibilidade.",
        "id": nova_reserva.id,
        "codigo": nova_reserva.codigo,
        "numero_dia": nova_reserva.numero_dia,
        "data": nova_reserva.data,
        "horario": nova_reserva.horario,
        "profissional_id": nova_reserva.profissional_id,
        "status": nova_reserva.status,
        "status_pagamento": nova_reserva.status_pagamento,
        "valor_total": float(nova_reserva.valor_total or 0),
        "valor_sinal": float(nova_reserva.valor_sinal or 0),
        "valor_pagamento_online": float(valor_cobranca or 0),
        "forma_pagamento": nova_reserva.forma_pagamento,
        "pagamento_online_necessario": bool(pagamento_online),
        "confirmacao_automatica": bool(getattr(empresa, "pedido_so_apos_pagamento", False)),
        "sinal_necessario": bool(sinal_manual),
        "sinal_pix_tipo": getattr(empresa, "sinal_pix_tipo", None),
        "sinal_pix_chave": getattr(empresa, "sinal_pix_chave", None),
        "sinal_pix_titular": getattr(empresa, "sinal_pix_titular", None),
        "sinal_whatsapp": getattr(empresa, "sinal_whatsapp", None) or getattr(empresa, "telefone_whatsapp", None),
        "sinal_prazo_minutos": int(getattr(empresa, "sinal_prazo_minutos", 30) or 30),
        "public_token": nova_reserva.public_token
    }

    db.close()

    return resposta


@app.post("/reservas/{reserva_id}/comprovante-enviado")
async def marcar_comprovante_sinal_enviado(reserva_id: int, request: Request):
    dados = await request.json()
    token = (dados.get("token") or "").strip()
    db = SessionLocal()
    try:
        reserva = db.query(Reserva).filter(Reserva.id == reserva_id).first()
        if not reserva or not token or not hmac.compare_digest(token, reserva.public_token or ""):
            raise HTTPException(status_code=404, detail="Agendamento não encontrado")
        if (reserva.status_pagamento or "").strip().lower() in {"aguardando_pagamento", "pendente"}:
            reserva.status_pagamento = "comprovante_enviado"
            reserva.gateway_status = "proof_sent"
            db.commit()
        return {"ok": True, "status_pagamento": reserva.status_pagamento}
    finally:
        db.close()


@app.post("/admin/{empresa_id}/reservas/{reserva_id}/confirmar-sinal")
def confirmar_sinal_reserva_admin(empresa_id: int, reserva_id: int, request: Request):
    redirecionamento = redirecionar_area_admin_se_necessario(request, empresa_id, "reservas")
    if redirecionamento:
        return redirecionamento
    db = SessionLocal()
    try:
        reserva = db.query(Reserva).filter(
            Reserva.id == reserva_id,
            Reserva.empresa_id == empresa_id,
        ).first()
        if not reserva:
            raise HTTPException(status_code=404, detail="Agendamento não encontrado")
        valor_total = max(0.0, float(getattr(reserva, "valor_total", 0) or 0))
        valor_sinal = max(0.0, float(getattr(reserva, "valor_sinal", 0) or 0))
        if valor_sinal <= 0:
            raise HTTPException(status_code=400, detail="Este agendamento não possui sinal configurado.")
        if str(getattr(reserva, "gateway_pagamento", "") or "").strip().lower() != "pix_manual":
            raise HTTPException(status_code=400, detail="Este agendamento não usa Pix pela chave.")

        agora = agora_brasilia()
        recebido = min(valor_total if valor_total > 0 else valor_sinal, valor_sinal)
        reserva.valor_recebido = recebido
        reserva.valor_sinal_recebido = recebido
        reserva.pagamento_tipo = "sinal"
        reserva.forma_pagamento = "pix_manual"
        reserva.pagamento_registrado_em = agora
        reserva.status_pagamento = "pago" if valor_total > 0 and recebido >= valor_total - 0.005 else "parcial"
        reserva.gateway_status = "manual_approved"
        reserva.gateway_status_detail = "pix_key_signal_confirmed"
        reserva.pago_em = agora if reserva.status_pagamento == "pago" else None
        reserva.status = "confirmada"
        reserva.horario_liberado = False

        historico_anterior = str(getattr(reserva, "pagamento_observacao", "") or "").strip()
        linha = f"{agora.strftime('%d/%m/%Y %H:%M')} · R$ {recebido:.2f} · Pix pela chave · sinal"
        reserva.pagamento_observacao = f"{historico_anterior}\n{linha}".strip() if historico_anterior else linha

        db.commit()
        db.refresh(reserva)

        # O agendamento só se torna operacional agora: dispara a notificação
        # normal e agenda o lembrete somente após a conferência manual do sinal.
        enqueue_new_reservation(reserva.id)

        return {
            "ok": True,
            "status": reserva.status,
            "status_pagamento": reserva.status_pagamento,
            "valor_recebido": round(float(reserva.valor_recebido or 0), 2),
            "valor_sinal_recebido": round(float(reserva.valor_sinal_recebido or 0), 2),
            "valor_restante": round(max(0.0, valor_total - float(reserva.valor_recebido or 0)), 2),
        }
    except Exception:
        db.rollback()
        raise
    finally:
        db.close()


@app.get("/admin/{empresa_id}/reservas/debug-json")
def debug_reservas_admin(empresa_id: int, request: Request):
    redirecionamento = redirecionar_login_se_necessario(request, empresa_id)
    if redirecionamento:
        return {"error": "Faça login novamente"}

    db = SessionLocal()

    reservas = db.query(Reserva).filter(
        Reserva.empresa_id == empresa_id
    ).order_by(Reserva.id.desc()).limit(20).all()

    resultado = [
        {
            "id": r.id,
            "codigo": r.codigo,
            "data": r.data,
            "horario": r.horario,
            "horario_id": getattr(r, "horario_id", None),
            "nome_cliente": r.nome_cliente,
            "pessoas": r.pessoas,
            "status": r.status,
            "criado_em": r.criado_em.isoformat() if getattr(r, "criado_em", None) else None
        }
        for r in reservas
    ]

    db.close()

    return resultado


@app.get("/admin/{empresa_id}/reservas/imprimir")
def imprimir_reservas_dia(
    empresa_id: int,
    request: Request,
    data: str | None = None
):
    redirecionamento = redirecionar_area_admin_se_necessario(request, empresa_id, "reservas")
    if redirecionamento:
        return redirecionamento

    data = normalizar_data_reserva(data or agora_brasilia().strftime("%Y-%m-%d"))

    db = SessionLocal()

    empresa = db.query(Empresa).filter(
        Empresa.id == empresa_id
    ).first()

    if not empresa:
        db.close()
        return {"error": "Empresa não encontrada"}

    reservas = db.query(Reserva).filter(
        Reserva.empresa_id == empresa_id,
        Reserva.data == data,
        func.lower(func.trim(Reserva.status)).notin_(["cancelada", "cancelado", "recusada", "recusado", "expirada", "expirado", "concluida", "concluido", "concluída", "concluído", "paga", "pago", "pagamento_recusado", "pagamento_cancelado"])
    ).order_by(
        Reserva.horario.asc(),
        Reserva.nome_cliente.asc()
    ).all()

    reservas_por_horario = {}

    for reserva in reservas:
        if reserva.horario not in reservas_por_horario:
            reservas_por_horario[reserva.horario] = []
        reservas_por_horario[reserva.horario].append(reserva)

    profissionais = db.query(Profissional).filter(
        Profissional.empresa_id == empresa_id
    ).order_by(Profissional.nome.asc()).all()

    negocio_servico = tipo_negocio_servico(empresa.tipo if empresa else "")
    negocio_pedido = tipo_negocio_pedido(empresa.tipo if empresa else "")

    db.close()

    return templates.TemplateResponse(
        request=request,
        name="admin_reservas_impressao.html",
        context={
            "empresa": empresa,
            "data": data,
            "reservas": reservas,
            "reservas_por_horario": reservas_por_horario,
            "profissionais": profissionais,
            "negocio_servico": negocio_servico,
            "negocio_pedido": negocio_pedido
        }
    )


@app.get("/admin/{empresa_id}/reservas")
def admin_reservas(empresa_id: int, request: Request, data: str | None = None, profissional: str | None = None):
    redirecionamento = redirecionar_area_admin_se_necessario(request, empresa_id, "reservas")
    if redirecionamento:
        return redirecionamento
    db = SessionLocal()

    empresa = db.query(Empresa).filter(
        Empresa.id == empresa_id
    ).first()

    if not empresa:
        db.close()
        return {"error": "Empresa não encontrada"}

    expirar_reservas_pendentes_antigas(db, empresa_id)
    expirar_holds_pagamento_online_reservas(db, empresa)

    # Garante idioma correto na tela Reservas/Agendamentos
    anexar_idioma_empresa(db, empresa)

    # V209 — segurança multi-negócio:
    # O template de reservas usa rotas diferentes para restaurante e serviço.
    # Sem estas flags, empresas de serviço (ex.: Studio Bella) caíam no modo restaurante
    # e scripts antigos podiam travar a tela.
    negocio_servico = tipo_negocio_servico(empresa.tipo if empresa else "")
    negocio_pedido = tipo_negocio_pedido(empresa.tipo if empresa else "")

    dias_fechados = db.query(DiaFechado).filter(
        DiaFechado.empresa_id == empresa_id
    ).order_by(DiaFechado.data.desc()).all()

    profissionais = db.query(Profissional).filter(
        Profissional.empresa_id == empresa_id
    ).order_by(Profissional.nome.asc()).all()

    data_selecionada = data or agora_brasilia().strftime("%Y-%m-%d")
    try:
        datetime.strptime(data_selecionada, "%Y-%m-%d")
    except Exception:
        data_selecionada = agora_brasilia().strftime("%Y-%m-%d")

    profissional_filtro = (profissional or request.query_params.get("profissional") or "").strip()

    consulta_reservas = db.query(Reserva).filter(
        Reserva.empresa_id == empresa_id
    )

    # v291:
    # A lista de "Agendamentos" no admin deve mostrar todos os agendamentos da empresa.
    # O parâmetro ?profissional=... fica somente para a "Agenda do dia" no frontend.
    # Não filtramos consulta_reservas por profissional aqui para não zerar/duplicar cards
    # no bloco de Agendamentos.
    # profissional_filtro é mantido acima apenas para compatibilidade com a URL.

    reservas = consulta_reservas.order_by(
        Reserva.data.desc(),
        Reserva.horario.asc()
    ).all()
    garantir_tokens_publicos_reservas(db, reservas)

    reservas_por_dia = {}

    for reserva in reservas:
        if reserva.data not in reservas_por_dia:
            reservas_por_dia[reserva.data] = []

        reservas_por_dia[reserva.data].append(reserva)

    profissionais_ativos_ids = [p.id for p in profissionais if getattr(p, "ativo", True)]
    horarios = db.query(HorarioReserva).filter(
        HorarioReserva.empresa_id == empresa_id,
        or_(HorarioReserva.profissional_id == None, HorarioReserva.profissional_id.in_(profissionais_ativos_ids))
    ).order_by(
        HorarioReserva.data.desc(),
        HorarioReserva.horario.asc()
    ).all()

    # V278 — horários livres passados desaparecem da agenda ativa, sem serem
    # apagados do banco. Slots passados com atendimento ainda aguardando
    # conclusão permanecem visíveis para a equipe finalizar corretamente.
    reservas_ocupantes = [reserva for reserva in reservas if reserva_ocupa_horario(reserva)]
    horarios_ocupados_ids = {
        int(reserva.horario_id) for reserva in reservas_ocupantes
        if getattr(reserva, "horario_id", None)
    }
    chaves_ocupadas = {
        (
            normalizar_data_reserva(str(getattr(reserva, "data", "") or "")),
            normalizar_horario_agenda(getattr(reserva, "horario", "")),
            int(getattr(reserva, "profissional_id", 0) or 0),
        )
        for reserva in reservas_ocupantes
    }
    agora_operacional = agora_brasilia()
    horarios = [
        horario for horario in horarios
        if horario_ainda_futuro(horario.data, horario.horario, agora_operacional)
        or horario.id in horarios_ocupados_ids
        or (
            normalizar_data_reserva(str(horario.data or "")),
            normalizar_horario_agenda(horario.horario),
            int(horario.profissional_id or 0),
        ) in chaves_ocupadas
    ]

    horarios_por_dia = {}

    for horario in horarios:
        if horario.data not in horarios_por_dia:
            horarios_por_dia[horario.data] = []

        horarios_por_dia[horario.data].append(horario)

    estatisticas_por_horario = {}

    for horario in horarios:
        consulta_reservas = db.query(Reserva).filter(
            Reserva.empresa_id == empresa_id,
            func.lower(func.trim(Reserva.status)).notin_(["cancelada", "cancelado", "recusada", "recusado", "expirada", "expirado", "concluida", "concluido", "concluída", "concluído", "paga", "pago", "pagamento_recusado", "pagamento_cancelado"])
        )

        if hasattr(Reserva, "horario_id"):
            consulta_reservas = consulta_reservas.filter(
                or_(
                    Reserva.horario_id == horario.id,
                    and_(
                        Reserva.horario_id == None,
                        Reserva.data == horario.data,
                        Reserva.horario == horario.horario
                    )
                )
            )
        else:
            consulta_reservas = consulta_reservas.filter(
                Reserva.data == horario.data,
                Reserva.horario == horario.horario
            )

        if getattr(horario, "profissional_id", None):
            consulta_reservas = consulta_reservas.filter(
                Reserva.profissional_id == horario.profissional_id
            )

        reservas_do_horario = consulta_reservas.all()

        pessoas_reservadas = sum((r.pessoas or 0) for r in reservas_do_horario)
        capacidade = horario.capacidade_maxima or 0

        estatistica = {
            "reservas": len(reservas_do_horario),
            "pessoas": pessoas_reservadas,
            "capacidade": capacidade,
            "vagas": None if capacidade <= 0 else max(0, capacidade - pessoas_reservadas),
            "lotado": capacidade > 0 and pessoas_reservadas >= capacidade,
            "profissional_id": horario.profissional_id
        }

        # Mantém a chave antiga para não quebrar templates existentes.
        estatisticas_por_horario[f"{horario.data}_{horario.horario}"] = estatistica

        # Nova chave opcional para diferenciar o mesmo horário por profissional.
        estatisticas_por_horario[f"{horario.data}_{horario.horario}_{horario.profissional_id or 'sem_profissional'}"] = estatistica

    servicos_agenda = db.query(Item).filter(
        Item.empresa_id == empresa_id,
        func.lower(func.trim(Item.tipo)).in_(["servico", "serviço", "servicos", "serviços", "service", "services", "servizi"]),
        Item.disponivel == True
    ).order_by(Item.nome.asc()).all()

    # V276 — prepara os dados detalhados usados apenas no modal da Agenda.
    # A frente dos cards/horários permanece enxuta e sem novas informações.
    servicos_ordenados = sorted(
        servicos_agenda,
        key=lambda item: len(str(getattr(item, "nome", "") or "")),
        reverse=True,
    )
    for reserva in reservas:
        setattr(reserva, "mf_horario_passado", not horario_ainda_futuro(reserva.data, reserva.horario))
        observacao_reserva = str(getattr(reserva, "observacao", "") or "")
        observacao_normalizada = observacao_reserva.casefold()
        servico_encontrado = next(
            (item for item in servicos_ordenados
             if str(getattr(item, "nome", "") or "").strip()
             and str(getattr(item, "nome", "") or "").strip().casefold() in observacao_normalizada),
            None,
        )

        valor_total_modal = max(0.0, float(getattr(reserva, "valor_total", 0) or 0))
        if valor_total_modal <= 0 and servico_encontrado is not None:
            valor_total_modal = max(0.0, float(getattr(servico_encontrado, "preco", 0) or 0))
        if valor_total_modal <= 0:
            try:
                valor_total_modal = max(0.0, financeiro_valor_reserva_observacao(reserva))
            except Exception:
                valor_total_modal = 0.0

        valor_recebido_modal = max(0.0, float(getattr(reserva, "valor_recebido", 0) or 0))
        status_pagamento_modal = str(getattr(reserva, "status_pagamento", "") or "").strip().lower()
        if valor_recebido_modal <= 0 and status_pagamento_modal in FINANCEIRO_V273_STATUS_PAGOS:
            valor_sinal_modal = max(0.0, float(getattr(reserva, "valor_sinal", 0) or 0))
            valor_recebido_modal = valor_sinal_modal if valor_sinal_modal > 0 else valor_total_modal
        if valor_total_modal > 0:
            valor_recebido_modal = min(valor_total_modal, valor_recebido_modal)

        setattr(reserva, "mf_servico_nome",
                str(getattr(servico_encontrado, "nome", "") or "").strip()
                if servico_encontrado is not None else observacao_reserva.strip())
        setattr(reserva, "mf_duracao_minutos",
                int(getattr(servico_encontrado, "duracao_minutos", 0) or 0)
                if servico_encontrado is not None else 0)
        setattr(reserva, "mf_valor_total", round(valor_total_modal, 2))
        setattr(reserva, "mf_valor_recebido", round(valor_recebido_modal, 2))
        setattr(reserva, "mf_valor_restante", round(max(0.0, valor_total_modal - valor_recebido_modal), 2))

    db.close()

    return templates.TemplateResponse(
        request=request,
        name="admin_reservas.html",
        context={
            "empresa": empresa,
            "reservas_por_dia": reservas_por_dia,
            "horarios_por_dia": horarios_por_dia,
            "estatisticas_por_horario": estatisticas_por_horario,
            "dias_fechados": dias_fechados,
            "profissionais": profissionais,
            "servicos_agenda": servicos_agenda,
            "data_selecionada": data_selecionada,
            "data_hoje_brasilia": hoje_brasilia().strftime("%Y-%m-%d"),
            "profissional_filtro": profissional_filtro,
            "negocio_servico": negocio_servico,
            "negocio_pedido": negocio_pedido
        }
    )



