# ==================================================
# PAINEL FUNCIONÁRIO — ROTAS LIMPAS
# ==================================================

def _funcionario_redirecionamento(request: Request, empresa_id: int, area: str | None = None):
    redirecionamento = redirecionar_login_se_necessario(request, empresa_id)
    if redirecionamento:
        return redirecionamento

    if area and not permissao_admin_sessao(request, area):
        return RedirectResponse(
            url=f"/funcionario/{empresa_id}?status=sem_permissao",
            status_code=303
        )

    return None


def _empresa_funcionario_contexto(db, empresa_id: int):
    empresa = db.query(Empresa).filter(Empresa.id == empresa_id).first()
    if empresa:
        anexar_idioma_empresa(db, empresa)
    return empresa


@app.get("/funcionario/{empresa_id}")
def funcionario_dashboard(empresa_id: int, request: Request, lang: str | None = None):
    return RedirectResponse(url=url_area_admin(empresa_id, primeira_area_permitida(request)), status_code=303)

    redirecionamento = _funcionario_redirecionamento(request, empresa_id)
    if redirecionamento:
        return redirecionamento

    db = SessionLocal()
    empresa = _empresa_funcionario_contexto(db, empresa_id)
    if not empresa:
        db.close()
        return {"error": "Empresa não encontrada"}

    lang_url = ""
    if lang_url in ["pt", "it", "en"]:
        salvar_idioma_empresa_sql(db, empresa, lang_url)
        db.commit()
        request.session["idioma_empresa"] = lang_url
        anexar_idioma_empresa(db, empresa)

    hoje = agora_brasilia()
    inicio_dia = datetime.combine(hoje.date(), time(0, 0, 0))
    fim_dia = datetime.combine(hoje.date(), time(23, 59, 59))
    data_hoje = hoje.strftime("%Y-%m-%d")

    consulta_pedidos_hoje = db.query(Pedido).filter(
        Pedido.empresa_id == empresa_id,
        Pedido.criado_em >= inicio_dia,
        Pedido.criado_em <= fim_dia,
    )
    consulta_produtos_hoje = db.query(Pedido).filter(
        Pedido.empresa_id == empresa_id,
        Pedido.criado_em >= inicio_dia,
        Pedido.criado_em <= fim_dia,
    )
    if tipo_negocio_produto(empresa.tipo):
        consulta_pedidos_hoje = consulta_pedidos_hoje.filter(Pedido.origem_menu == "comida")
        consulta_produtos_hoje = consulta_produtos_hoje.filter(
            or_(Pedido.origem_menu == "produto", Pedido.origem_menu == None)
        )
    else:
        consulta_pedidos_hoje = consulta_pedidos_hoje.filter(
            or_(Pedido.origem_menu == "comida", Pedido.origem_menu == None)
        )
        consulta_produtos_hoje = consulta_produtos_hoje.filter(Pedido.origem_menu == "produto")

    total_pedidos_hoje = consulta_pedidos_hoje.count()
    total_produtos_hoje = consulta_produtos_hoje.count()

    total_reservas_hoje = db.query(Reserva).filter(
        Reserva.empresa_id == empresa_id,
        Reserva.data == data_hoje
    ).count()

    db.close()

    return templates.TemplateResponse(
        request=request,
        name="funcionario_dashboard.html",
        context={
            "empresa": empresa,
            "agora": hoje,
            "total_pedidos_hoje": total_pedidos_hoje,
            "total_produtos_hoje": total_produtos_hoje,
            "total_reservas_hoje": total_reservas_hoje,
        }
    )


@app.get("/funcionario/{empresa_id}/reservas")
def funcionario_reservas(empresa_id: int, request: Request, data: str | None = None, profissional: str | None = None, lang: str | None = None):
    return RedirectResponse(url=f"/admin/{empresa_id}/reservas", status_code=303)

    redirecionamento = _funcionario_redirecionamento(request, empresa_id, "reservas")
    if redirecionamento:
        return redirecionamento

    db = SessionLocal()
    empresa = _empresa_funcionario_contexto(db, empresa_id)
    if not empresa:
        db.close()
        return {"error": "Empresa não encontrada"}

    lang_url = ""
    lang_sessao = normalizar_idioma(request.session.get("idioma_empresa") or idioma_empresa(empresa))

    if lang_url in ["pt", "it", "en"]:
        # Se trocar idioma dentro de Reservas, salva como idioma global.
        salvar_idioma_empresa_sql(db, empresa, lang_url)
        db.commit()
        request.session["idioma_empresa"] = lang_url
        anexar_idioma_empresa(db, empresa)
        lang_atual = lang_url
    else:
        # Se o idioma foi escolhido no painel funcionário principal,
        # Reservas precisa respeitar esse idioma também.
        lang_atual = lang_sessao
        try:
            setattr(empresa, "idioma", lang_atual)
        except Exception:
            pass

    hoje = agora_brasilia()
    data_selecionada = data or hoje.strftime("%Y-%m-%d")
    profissional_filtro = (profissional or "").strip()
    try:
        datetime.strptime(data_selecionada, "%Y-%m-%d")
    except ValueError:
        data_selecionada = hoje.strftime("%Y-%m-%d")

    negocio_servico = tipo_negocio_servico(empresa.tipo if empresa else "")
    negocio_pedido = tipo_negocio_pedido(empresa.tipo if empresa else "")

    # No painel do funcionário, a "Agenda do dia" continua usando a data selecionada,
    # mas a lista "Agendamentos" deve seguir o mesmo padrão do admin:
    # mostrar todos os agendamentos da empresa, separados pelos filtros de status.
    reservas = db.query(Reserva).filter(
        Reserva.empresa_id == empresa_id
    ).order_by(
        Reserva.data.desc(),
        Reserva.horario.asc()
    ).all()
    garantir_tokens_publicos_reservas(db, reservas)

    profissionais = db.query(Profissional).filter(
        Profissional.empresa_id == empresa_id
    ).order_by(Profissional.nome.asc()).all()
    profissionais_ativos_ids = [p.id for p in profissionais if getattr(p, "ativo", True)]

    horarios = db.query(HorarioReserva).filter(
        HorarioReserva.empresa_id == empresa_id,
        HorarioReserva.data == data_selecionada,
        or_(HorarioReserva.profissional_id == None, HorarioReserva.profissional_id.in_(profissionais_ativos_ids))
    ).order_by(HorarioReserva.horario.asc()).all()

    reservas_por_dia = {}
    for reserva in reservas:
        if reserva.data not in reservas_por_dia:
            reservas_por_dia[reserva.data] = []
        reservas_por_dia[reserva.data].append(reserva)

    horarios_por_dia = {data_selecionada: horarios}

    estatisticas_por_horario = {}
    for horario in horarios:
        consulta = db.query(Reserva).filter(
            Reserva.empresa_id == empresa_id,
            Reserva.data == horario.data,
            func.lower(func.trim(Reserva.status)).notin_(["cancelada", "cancelado", "recusada", "recusado", "expirada", "expirado", "concluida", "concluido", "concluída", "concluído", "paga", "pago", "pagamento_recusado", "pagamento_cancelado"])
        )
        if hasattr(Reserva, "horario_id"):
            consulta = consulta.filter(
                or_(
                    Reserva.horario_id == horario.id,
                    and_(Reserva.horario_id == None, Reserva.horario == horario.horario)
                )
            )
        else:
            consulta = consulta.filter(Reserva.horario == horario.horario)

        if getattr(horario, "profissional_id", None):
            consulta = consulta.filter(Reserva.profissional_id == horario.profissional_id)

        reservas_do_horario = consulta.all()
        pessoas = sum((r.pessoas or 0) for r in reservas_do_horario)
        capacidade = getattr(horario, "capacidade_maxima", 0) or getattr(horario, "capacidade", 0) or 0
        estatistica = {
            "reservas": len(reservas_do_horario),
            "pessoas": pessoas,
            "capacidade": capacidade,
            "vagas": None if capacidade <= 0 else max(0, capacidade - pessoas),
            "lotado": capacidade > 0 and pessoas >= capacidade,
            "profissional_id": getattr(horario, "profissional_id", None),
        }
        estatisticas_por_horario[f"{horario.data}_{horario.horario}"] = estatistica
        estatisticas_por_horario[f"{horario.data}_{horario.horario}_{getattr(horario, 'profissional_id', None) or 'sem_profissional'}"] = estatistica

    db.close()

    return templates.TemplateResponse(
        request=request,
        name="funcionario_reservas.html",
        context={
            "empresa": empresa,
            "data_selecionada": data_selecionada,
            "reservas_por_dia": reservas_por_dia,
            "horarios_por_dia": horarios_por_dia,
            "estatisticas_por_horario": estatisticas_por_horario,
            "profissionais": profissionais,
            "data_selecionada": data_selecionada,
            "profissional_filtro": profissional_filtro,
            "negocio_servico": negocio_servico,
            "negocio_pedido": negocio_pedido,
            "lang": lang_atual,
        }
    )


@app.get("/funcionario/{empresa_id}/pedidos")
def funcionario_pedidos(empresa_id: int, request: Request, data: str | None = None):
    return RedirectResponse(url=f"/admin/{empresa_id}/pedidos", status_code=303)

    redirecionamento = _funcionario_redirecionamento(request, empresa_id, "pedidos")
    if redirecionamento:
        return redirecionamento

    db = SessionLocal()
    empresa = _empresa_funcionario_contexto(db, empresa_id)
    if not empresa:
        db.close()
        return {"error": "Empresa não encontrada"}

    hoje = agora_brasilia()
    data_selecionada = data or hoje.strftime("%Y-%m-%d")
    try:
        data_obj = datetime.strptime(data_selecionada, "%Y-%m-%d")
    except ValueError:
        data_obj = hoje
        data_selecionada = hoje.strftime("%Y-%m-%d")

    inicio_dia = datetime.combine(data_obj.date(), time(0, 0, 0))
    fim_dia = datetime.combine(data_obj.date(), time(23, 59, 59))

    consulta_pedidos = db.query(Pedido).filter(
        Pedido.empresa_id == empresa_id,
        Pedido.criado_em >= inicio_dia,
        Pedido.criado_em <= fim_dia,
    )
    if tipo_negocio_produto(empresa.tipo):
        consulta_pedidos = consulta_pedidos.filter(Pedido.origem_menu == "comida")
    else:
        consulta_pedidos = consulta_pedidos.filter(
            or_(Pedido.origem_menu == "comida", Pedido.origem_menu == None)
        )
    pedidos = consulta_pedidos.order_by(Pedido.id.desc()).all()

    # v23: carregar os itens reais do pedido também no painel funcionário.
    # A tela do admin já fazia isso, mas a rota do funcionário só enviava Pedido sem PedidoItem.
    for pedido in pedidos:
        itens_db = db.query(PedidoItem).filter(
            PedidoItem.pedido_id == pedido.id
        ).all()

        itens_funcionario = []
        for pedido_item in itens_db:
            quantidade = getattr(pedido_item, "quantidade", None) or 1
            subtotal = getattr(pedido_item, "subtotal", None) or 0
            preco_unitario = getattr(pedido_item, "preco_unitario", None) or 0

            nome_item = (getattr(pedido_item, "nome_item", None) or "").strip()

            # Se por algum motivo o nome não estiver salvo no PedidoItem,
            # busca o item original no cardápio pelo item_id.
            if (not nome_item or nome_item.lower() == "item") and getattr(pedido_item, "item_id", None):
                item_original = db.query(Item).filter(
                    Item.id == pedido_item.item_id,
                    Item.empresa_id == empresa_id
                ).first()
                if item_original and getattr(item_original, "nome", None):
                    nome_item = item_original.nome

            if not nome_item:
                nome_item = "Item"

            itens_funcionario.append({
                "quantidade": quantidade,
                "nome_item": nome_item,
                "preco_unitario": preco_unitario,
                "subtotal": subtotal,
                "observacao": getattr(pedido_item, "observacao", None) or ""
            })

        setattr(pedido, "itens_funcionario", itens_funcionario)

        # v24: forma de pagamento para o painel funcionário.
        # Alguns pedidos salvam como forma_pagamento, outros como metodo_pagamento/pagamento.
        pagamento_funcionario = (
            getattr(pedido, "forma_pagamento", None)
            or getattr(pedido, "metodo_pagamento", None)
            or getattr(pedido, "tipo_pagamento", None)
            or getattr(pedido, "pagamento", None)
            or getattr(pedido, "payment_method", None)
            or getattr(pedido, "payment_type", None)
            or ""
        )

        pagamento_txt = str(pagamento_funcionario or "").strip().lower()
        if pagamento_txt in ["contanti", "dinheiro", "cash", "denaro"]:
            pagamento_funcionario = "contanti"
        elif pagamento_txt in ["carta", "cartao", "cartão", "card", "credito", "crédito", "debito", "débito"]:
            pagamento_funcionario = "carta"

        setattr(pedido, "pagamento_funcionario", pagamento_funcionario or "-")

    db.close()

    return templates.TemplateResponse(
        request=request,
        name="funcionario_pedidos.html",
        context={
            "empresa": empresa,
            "pedidos": pedidos,
            "data_selecionada": data_selecionada,
        }
    )


