    if redirecionamento:
        return JSONResponse({"error": "Sem permissão"}, status_code=403)

    db = SessionLocal()
    empresa = db.query(Empresa).filter(Empresa.id == empresa_id).first()
    consulta_pedido = db.query(Pedido).filter(
        Pedido.id == pedido_id,
        Pedido.empresa_id == empresa_id,
    )
    if empresa and tipo_negocio_produto(empresa.tipo):
        consulta_pedido = consulta_pedido.filter(
            or_(Pedido.origem_menu == "produto", Pedido.origem_menu == None)
        )
    else:
        consulta_pedido = consulta_pedido.filter(Pedido.origem_menu == "produto")
    pedido = consulta_pedido.first()
    if not pedido:
        db.close()
        return JSONResponse({"error": "Pedido não encontrado"}, status_code=404)

