    resultado = {
        "id": pedido.id,
        "numero": f"#{int(pedido.numero_dia or pedido.id):03d}",
        "cliente": pedido.nome_cliente,
        "telefone": pedido.telefone_cliente,
        "tipo_pedido": pedido.tipo_pedido,
        "pagamento": pedido.pagamento,
        "status": pedido.status,
        "status_pagamento": pedido.status_pagamento,
        "total": pedido.total or 0,
        "endereco": pedido.endereco_entrega,
        "cep": pedido.cap_entrega,
        "cidade": pedido.cidade_entrega,
        "estado": pedido.provincia_entrega,
        "complemento": pedido.referencia_entrega,
        "observacao": pedido.observacao,
        "criado_em": pedido.criado_em.isoformat() if pedido.criado_em else None,
        "itens": [{
            "nome": item.nome_item,
            "quantidade": item.quantidade,
            "preco": item.preco_unitario,
            "subtotal": item.subtotal,
        } for item in itens],
    }
    db.close()
    return resultado


