def preparar_tabelas_integracoes():
    try:
        conn = engine.raw_connection()
        cursor = conn.cursor()

        cursor.execute("""
            CREATE TABLE IF NOT EXISTS integracao_configuracoes (
                empresa_id INTEGER PRIMARY KEY,
                webhook_token TEXT,
                webhook_ativo INTEGER DEFAULT 1,
                criado_em DATETIME,
                atualizado_em DATETIME
            )
        """)

        cursor.execute("""
            CREATE TABLE IF NOT EXISTS integracao_eventos (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                empresa_id INTEGER NOT NULL,
                plataforma TEXT,
                status TEXT,
                mensagem TEXT,
                pedido_id INTEGER,
                payload TEXT,
                criado_em DATETIME
            )
        """)

        conn.commit()
        conn.close()
    except Exception:
        pass




def _v161_adicionar_coluna_integracao(cursor, coluna: str, ddl: str):
    try:
        cursor.execute("PRAGMA table_info(integracao_configuracoes)")
        colunas = {linha[1] for linha in cursor.fetchall()}
        if coluna not in colunas:
            cursor.execute(f"ALTER TABLE integracao_configuracoes ADD COLUMN {coluna} {ddl}")
    except Exception:
        pass


def preparar_entrega_externa_integracoes():
    """
    V161 — deixa a estrutura de courier sob demanda pronta por empresa.
    API real fica preparada, mas só executa quando houver credenciais e conector ativo.
    """
    try:
        preparar_tabelas_integracoes()
        conn = engine.raw_connection()
        cursor = conn.cursor()

        for coluna, ddl in [
            ("entrega_externa_modo", "TEXT DEFAULT 'manual'"),
            ("entrega_externa_ativo", "INTEGER DEFAULT 0"),
            ("entrega_manual_nome", "TEXT"),
            ("entrega_manual_telefone", "TEXT"),
            ("entrega_manual_observacao", "TEXT"),
            ("uber_direct_ativo", "INTEGER DEFAULT 0"),
            ("uber_direct_ambiente", "TEXT DEFAULT 'teste'"),
            ("uber_direct_client_id", "TEXT"),
            ("uber_direct_client_secret", "TEXT"),
            ("uber_direct_customer_id", "TEXT"),
            ("uber_direct_status", "TEXT DEFAULT 'requer_credenciais'"),
            ("glovo_ativo", "INTEGER DEFAULT 0"),
            ("glovo_ambiente", "TEXT DEFAULT 'teste'"),
            ("glovo_store_id", "TEXT"),
            ("glovo_api_key", "TEXT"),
            ("glovo_api_url", "TEXT"),
            ("glovo_status", "TEXT DEFAULT 'requer_credenciais'"),
            ("stuart_ativo", "INTEGER DEFAULT 0"),
            ("stuart_ambiente", "TEXT DEFAULT 'teste'"),
            ("stuart_client_id", "TEXT"),
            ("stuart_client_secret", "TEXT"),
            ("stuart_store_id", "TEXT"),
            ("stuart_status", "TEXT DEFAULT 'requer_credenciais'"),
            ("outro_delivery_ativo", "INTEGER DEFAULT 0"),
            ("outro_delivery_nome", "TEXT"),
            ("outro_delivery_api_url", "TEXT"),
            ("outro_delivery_token", "TEXT"),
            ("outro_delivery_header", "TEXT DEFAULT 'Authorization'"),
            ("outro_delivery_status", "TEXT DEFAULT 'requer_configuracao'"),
            ("entrega_externa_atualizado_em", "DATETIME"),
        ]:
            _v161_adicionar_coluna_integracao(cursor, coluna, ddl)

        conn.commit()
        conn.close()
    except Exception:
        pass


def obter_config_entrega_externa(db, empresa_id: int, expose_secrets: bool = True):
    preparar_entrega_externa_integracoes()

    linha = db.execute(
        text("""
            SELECT *
            FROM integracao_configuracoes
            WHERE empresa_id = :empresa_id
        """),
        {"empresa_id": empresa_id}
    ).mappings().first()

    if not linha:
        agora = agora_brasilia()
        db.execute(
            text("""
                INSERT INTO integracao_configuracoes
                    (empresa_id, webhook_ativo, entrega_externa_modo, entrega_externa_ativo, criado_em, atualizado_em, entrega_externa_atualizado_em)
                VALUES
                    (:empresa_id, 1, 'manual', 0, :agora, :agora, :agora)
            """),
            {"empresa_id": empresa_id, "agora": agora}
        )
        db.flush()
        linha = db.execute(
            text("SELECT * FROM integracao_configuracoes WHERE empresa_id = :empresa_id"),
            {"empresa_id": empresa_id}
        ).mappings().first()

    dados = dict(linha or {})
    defaults = {
        "entrega_externa_modo": "manual",
        "entrega_externa_ativo": 0,
        "entrega_manual_nome": "",
        "entrega_manual_telefone": "",
        "entrega_manual_observacao": "",
        "uber_direct_ativo": 0,
        "uber_direct_ambiente": "teste",
        "uber_direct_client_id": "",
        "uber_direct_client_secret": "",
        "uber_direct_customer_id": "",
        "uber_direct_status": "requer_credenciais",
        "glovo_ativo": 0,
        "glovo_ambiente": "teste",
        "glovo_store_id": "",
        "glovo_api_key": "",
        "glovo_api_url": "",
        "glovo_status": "requer_credenciais",
        "stuart_ativo": 0,
        "stuart_ambiente": "teste",
        "stuart_client_id": "",
        "stuart_client_secret": "",
        "stuart_store_id": "",
        "stuart_status": "requer_credenciais",
        "outro_delivery_ativo": 0,
        "outro_delivery_nome": "",
        "outro_delivery_api_url": "",
        "outro_delivery_token": "",
        "outro_delivery_header": "Authorization",
        "outro_delivery_status": "requer_configuracao",
    }
    for chave, valor in defaults.items():
        dados.setdefault(chave, valor)

    secret_fields = (
        "uber_direct_client_secret",
        "glovo_api_key",
        "stuart_client_secret",
        "outro_delivery_token",
    )
    migrated = {}
    for field in secret_fields:
        stored = dados.get(field) or ""
        try:
            plain = decrypt_secret(stored)
        except SecretProtectionError:
            LOGGER.exception("Credencial de integração inválida: empresa=%s campo=%s", empresa_id, field)
            plain = ""
        if stored and not str(stored).startswith("enc:v1:") and plain:
            migrated[field] = encrypt_secret(plain)
        dados[f"{field}_configurado"] = bool(plain)
        dados[field] = plain if expose_secrets else ""

    if migrated:
        assignments = ", ".join(f"{field} = :{field}" for field in migrated)
        params = {"empresa_id": empresa_id, **migrated}
        db.execute(text(f"UPDATE integracao_configuracoes SET {assignments} WHERE empresa_id = :empresa_id"), params)
        db.commit()
    return dados


def anexar_entrega_externa_pedidos(db, pedidos):
    if not pedidos:
        return

    ids = [p.id for p in pedidos]
    if not ids:
        return

    try:
        rows = db.execute(
            text("""
                SELECT
                    id,
                    entrega_externa_provider,
                    entrega_externa_status,
                    entrega_externa_id,
                    entrega_externa_tracking_url,
                    entrega_externa_courier_name,
                    entrega_externa_courier_phone,
                    entrega_externa_requested_at,
                    entrega_externa_last_error
                FROM pedidos
                WHERE id IN :ids
            """).bindparams(__import__('sqlalchemy').bindparam("ids", expanding=True)),
            {"ids": ids}
        ).mappings().all()
        por_id = {r["id"]: dict(r) for r in rows}
    except Exception:
        por_id = {}

    for pedido in pedidos:
        dados = por_id.get(pedido.id, {})
        setattr(pedido, "entrega_externa_provider", dados.get("entrega_externa_provider") or "")
        setattr(pedido, "entrega_externa_status", dados.get("entrega_externa_status") or "nao_solicitada")
        setattr(pedido, "entrega_externa_id", dados.get("entrega_externa_id") or "")
        setattr(pedido, "entrega_externa_tracking_url", dados.get("entrega_externa_tracking_url") or "")
        setattr(pedido, "entrega_externa_courier_name", dados.get("entrega_externa_courier_name") or "")
        setattr(pedido, "entrega_externa_courier_phone", dados.get("entrega_externa_courier_phone") or "")
        setattr(pedido, "entrega_externa_requested_at", dados.get("entrega_externa_requested_at"))
        setattr(pedido, "entrega_externa_last_error", dados.get("entrega_externa_last_error") or "")



