def _v161_post_json_externo(url: str, payload: dict, token: str = "", header_name: str = "Authorization"):
    """Conector genérico para parceiro local/outro delivery que aceite POST JSON."""
    if not url:
        return {"ok": False, "erro": "URL do parceiro não configurada."}
    headers = {"Content-Type": "application/json"}
    if token:
        header_name = (header_name or "Authorization").strip()
        headers[header_name] = f"Bearer {token}" if header_name.lower() == "authorization" else token
    req = urllib.request.Request(
        url,
        data=json.dumps(payload, ensure_ascii=False).encode("utf-8"),
        headers=headers,
        method="POST"
    )
    try:
        with urllib.request.urlopen(req, timeout=12) as resp:
            raw = resp.read().decode("utf-8", "ignore")
            try:
                body = json.loads(raw) if raw else {}
            except Exception:
                body = {"raw": raw}
            return {"ok": 200 <= resp.status < 300, "status_code": resp.status, "body": body}
    except urllib.error.HTTPError as exc:
        raw = exc.read().decode("utf-8", "ignore")
        return {"ok": False, "status_code": exc.code, "erro": raw[:500] or str(exc)}
    except Exception as exc:
        return {"ok": False, "erro": str(exc)}


