async def pedido_entrega_externa(empresa_id: int, pedido_id: int, request: Request):
    exigir_admin_empresa_api(request, empresa_id)

    dados = await request.json()
    acao = str(dados.get("acao") or "manual").strip()
    provider = str(dados.get("provider") or "manual").strip()
    courier_nome = str(dados.get("courier_nome") or "").strip()
    courier_telefone = str(dados.get("courier_telefone") or "").strip()

    db = SessionLocal()

    pedido = db.query(Pedido).filter(
        Pedido.id == pedido_id,
        Pedido.empresa_id == empresa_id
    ).first()

    if not pedido:
        db.close()
        return {"ok": False, "erro": "Pedido não encontrado."}

    if pedido.tipo_pedido != "Entrega":
        db.close()
        return {"ok": False, "erro": "Entrega externa só aparece para pedidos de entrega."}

    config = obter_config_entrega_externa(db, empresa_id)
    agora = agora_brasilia()

    status = "solicitado"
    erro = ""
    externo_id = ""
    tracking = ""

    if acao == "api":
        if provider == "sandbox":
            status = "solicitado"
            externo_id = f"SIM-{pedido.id}-{int(agora.timestamp())}"
            tracking = f"https://rastreamento-teste.local/{externo_id}"
            erro = ""
        elif provider == "uber_direct":
            tem_credenciais = bool(config.get("uber_direct_client_id") and config.get("uber_direct_client_secret") and config.get("uber_direct_customer_id"))
            if not tem_credenciais:
                db.close()
                return {"ok": False, "erro": "Uber Direct ainda não tem credenciais cadastradas para esta empresa."}
            status = "api_preparada"
            externo_id = f"uber-pendente-{pedido.id}"
            erro = "Credenciais cadastradas. Conector específico Uber Direct fica pronto para ativar quando a API/escopo estiver liberado."
        elif provider == "glovo":
            tem_credenciais = bool(config.get("glovo_api_key") and (config.get("glovo_store_id") or config.get("glovo_api_url")))
            if not tem_credenciais:
                db.close()
                return {"ok": False, "erro": "Glovo ainda não tem credenciais cadastradas para esta empresa."}
            status = "api_preparada"
            externo_id = f"glovo-pendente-{pedido.id}"
            erro = "Credenciais cadastradas. Conector específico Glovo fica pronto para ativar quando a API estiver liberada."
        elif provider == "stuart":
            tem_credenciais = bool(config.get("stuart_client_id") and config.get("stuart_client_secret"))
            if not tem_credenciais:
                db.close()
                return {"ok": False, "erro": "Stuart ainda não tem credenciais cadastradas para esta empresa."}
            status = "api_preparada"
            externo_id = f"stuart-pendente-{pedido.id}"
            erro = "Credenciais cadastradas. Conector específico Stuart fica pronto para ativar quando a API estiver liberada."
        elif provider == "outro":
            if not config.get("outro_delivery_api_url"):
                db.close()
                return {"ok": False, "erro": "Outro parceiro ainda não tem URL/API configurada."}
            payload = _v161_payload_entrega_pedido(pedido, provider, courier_nome, courier_telefone)
            resultado = _v161_post_json_externo(
                config.get("outro_delivery_api_url"),
                payload,
                config.get("outro_delivery_token") or "",
                config.get("outro_delivery_header") or "Authorization"
            )
            if not resultado.get("ok"):
                db.close()
                return {"ok": False, "erro": f"Parceiro externo recusou a entrega: {resultado.get('erro') or resultado.get('status_code') or 'erro desconhecido'}"}
            status = "solicitado"
            externo_id = str((resultado.get("body") or {}).get("id") or (resultado.get("body") or {}).get("delivery_id") or f"outro-{pedido.id}")
            tracking = str((resultado.get("body") or {}).get("tracking_url") or "")
        else:
            db.close()
            return {"ok": False, "erro": "Provedor de entrega externa inválido."}

    db.execute(
        text("""
            UPDATE pedidos
            SET
                entrega_externa_provider = :provider,
                entrega_externa_status = :status,
                entrega_externa_id = :externo_id,
                entrega_externa_tracking_url = :tracking,
                entrega_externa_courier_name = :courier_nome,
                entrega_externa_courier_phone = :courier_telefone,
                entrega_externa_requested_at = :agora,
                entrega_externa_last_error = :erro
            WHERE id = :pedido_id AND empresa_id = :empresa_id
        """),
        {
            "pedido_id": pedido_id,
            "empresa_id": empresa_id,
            "provider": provider,
            "status": status,
            "externo_id": externo_id,
            "tracking": tracking,
            "courier_nome": courier_nome,
            "courier_telefone": courier_telefone,
            "agora": agora,
            "erro": erro,
        }
    )

    registrar_evento_integracao(
        db,
        empresa_id,
        "Entrega externa",
        "sucesso" if not erro else "info",
        f"Entrega externa do pedido #{pedido_id} marcada como {status} via {provider}.",
        pedido_id=pedido_id,
        payload={"provider": provider, "status": status, "erro": erro}
    )

    db.commit()
    db.close()

    return {
        "ok": True,
        "pedido_id": pedido_id,
        "provider": provider,
        "status": status,
        "mensagem": erro or "Entrega externa registrada com sucesso."
    }




