def financeiro_origem_pedido(pedido):
    """Classifica a origem operacional do pedido para o relatório Vendas/Caixa."""
    origem_forcada = getattr(pedido, "_financeiro_origem_forcada", None)
    if origem_forcada:
        return origem_forcada

    tipo = (pedido.tipo_pedido or "").strip()
    obs = (pedido.observacao or "").strip()
    texto = f"{tipo} {obs}".lower()

    if (
        "serviço" in texto
        or "servico" in texto
        or "servizi" in texto
        or "service" in texto
        or "agendamento" in texto
        or "appuntamento" in texto
    ):
        return "Serviços"

    if "tablet" in texto:
        return "Tablet / Balcão"

    if "mesa" in texto:
        return "Mesa"

    if "entrega" in texto:
        return "Entrega"

    if "retirada" in texto or "balcão" in texto or "balcao" in texto:
        return "Retirada / Balcão"

    return "Retirada / Balcão"


def financeiro_origem_key(nome):
    mapa = {
        "Retirada / Balcão": "retirada",
        "Entrega": "entrega",
        "Mesa": "mesa",
        "Tablet / Balcão": "tablet",
        "Serviços": "servicos",
        "Servicos": "servicos",
        "Servizi": "servicos",
        "Services": "servicos"
    }
    return mapa.get(nome, "retirada")


def financeiro_montar_resumo(pedidos_filtrados):
    """Monta resumo operacional simples, sem virar fluxo de caixa completo."""
    total_pedidos_finalizados = len(pedidos_filtrados)

    faturamento_total = sum(pedido.total or 0 for pedido in pedidos_filtrados)
    faturamento_sem_iva = sum(pedido.subtotal_sem_iva or 0 for pedido in pedidos_filtrados)
    iva_acumulada = sum(pedido.total_iva or 0 for pedido in pedidos_filtrados)
    taxas_entrega_total = sum(pedido.taxa_entrega or 0 for pedido in pedidos_filtrados)
    produtos_total = faturamento_total - taxas_entrega_total

    if produtos_total < 0:
        produtos_total = 0

    ticket_medio = (
        faturamento_total / total_pedidos_finalizados
        if total_pedidos_finalizados > 0
        else 0
    )

    resumo_pagamentos = {}

    for pedido in pedidos_filtrados:
        forma = (pedido.pagamento or "Não informado").strip() or "Não informado"

        if forma not in resumo_pagamentos:
            resumo_pagamentos[forma] = {
                "quantidade": 0,
                "total": 0,
                "sem_iva": 0,
                "iva": 0
            }

        resumo_pagamentos[forma]["quantidade"] += 1
        resumo_pagamentos[forma]["total"] += pedido.total or 0
        resumo_pagamentos[forma]["sem_iva"] += pedido.subtotal_sem_iva or 0
        resumo_pagamentos[forma]["iva"] += pedido.total_iva or 0

    resumo_origens = {
        "Retirada / Balcão": {"quantidade": 0, "total": 0, "taxa_entrega": 0},
        "Entrega": {"quantidade": 0, "total": 0, "taxa_entrega": 0},
        "Mesa": {"quantidade": 0, "total": 0, "taxa_entrega": 0},
        "Tablet / Balcão": {"quantidade": 0, "total": 0, "taxa_entrega": 0},
        "Serviços": {"quantidade": 0, "total": 0, "taxa_entrega": 0}
    }

    for pedido in pedidos_filtrados:
        origem_nome = financeiro_origem_pedido(pedido)

        if origem_nome not in resumo_origens:
            resumo_origens[origem_nome] = {"quantidade": 0, "total": 0, "taxa_entrega": 0}

        resumo_origens[origem_nome]["quantidade"] += 1
        resumo_origens[origem_nome]["total"] += pedido.total or 0
        resumo_origens[origem_nome]["taxa_entrega"] += pedido.taxa_entrega or 0

    return {
        "total_pedidos_finalizados": total_pedidos_finalizados,
        "faturamento_total": faturamento_total,
        "faturamento_sem_iva": faturamento_sem_iva,
        "iva_acumulada": iva_acumulada,
        "ticket_medio": ticket_medio,
        "taxas_entrega_total": taxas_entrega_total,
        "produtos_total": produtos_total,
        "resumo_pagamentos": resumo_pagamentos,
        "resumo_origens": resumo_origens
    }



def financeiro_ids_pedidos_com_servicos(db, pedido_ids):
    """
    Retorna IDs de pedidos que possuem pelo menos um item do tipo serviço.
    Funciona para salão/barbearia/serviços onde o item vem do cardápio.
    """
    if not pedido_ids:
        return set()

    try:
        linhas = (
            db.query(PedidoItem.pedido_id)
            .join(Item, PedidoItem.item_id == Item.id)
            .filter(PedidoItem.pedido_id.in_(pedido_ids))
            .filter(
                or_(
                    func.lower(Item.tipo).in_(["servico", "serviço", "servicos", "serviços", "servizi", "service", "services"]),
                    func.lower(Item.tipo).like("%serv%")
                )
            )
            .distinct()
            .all()
        )
        return {linha[0] for linha in linhas}
    except Exception:
        return set()


def financeiro_marcar_pedidos_servicos(db, pedidos):
    """
    Marca em memória os pedidos que têm itens de serviço para o resumo e filtros.
    Não altera o banco.
    """
    ids = [p.id for p in pedidos]
    ids_servicos = financeiro_ids_pedidos_com_servicos(db, ids)

    for pedido in pedidos:
        if pedido.id in ids_servicos:
            setattr(pedido, "_financeiro_origem_forcada", "Serviços")

    return ids_servicos


def financeiro_filtrar_pedidos(
    db,
    empresa_id: int,
    data_inicio: str | None = None,
    data_fim: str | None = None,
    pagamento: str | None = None,
    origem: str | None = None,
    ordem_desc: bool = True
):
    consulta = db.query(Pedido).filter(
        Pedido.empresa_id == empresa_id,
        Pedido.status == "finalizado"
    )

    data_inicio_obj = None
    data_fim_obj = None
    erro_filtro = None

    try:
        if data_inicio:
            data_inicio_obj = datetime.strptime(data_inicio, "%Y-%m-%d")
            consulta = consulta.filter(Pedido.criado_em >= data_inicio_obj)

        if data_fim:
            data_fim_obj = datetime.strptime(data_fim, "%Y-%m-%d")
            data_fim_final = datetime.combine(data_fim_obj.date(), time(23, 59, 59))
            consulta = consulta.filter(Pedido.criado_em <= data_fim_final)

        if data_inicio_obj and data_fim_obj and data_inicio_obj.date() > data_fim_obj.date():
            erro_filtro = "A data inicial não pode ser maior que a data final."

    except ValueError:
        erro_filtro = "Formato de data inválido."

    pagamento_aplicado = pagamento or "todos"

    if pagamento_aplicado != "todos":
        consulta = consulta.filter(Pedido.pagamento == pagamento_aplicado)

    ordem = Pedido.criado_em.desc() if ordem_desc else Pedido.criado_em.asc()
    ordem_id = Pedido.id.desc() if ordem_desc else Pedido.id.asc()

    pedidos_filtrados = consulta.order_by(ordem, ordem_id).all()

    origem_aplicada = origem or "todos"
    origens_validas = ["todos", "retirada", "entrega", "mesa", "tablet", "servicos", "serviços", "servizi", "services"]

    if origem_aplicada not in origens_validas:
        origem_aplicada = "todos"

    ids_servicos = financeiro_marcar_pedidos_servicos(db, pedidos_filtrados)

    if origem_aplicada in ["serviços", "servizi", "services"]:
        origem_aplicada = "servicos"

    if origem_aplicada != "todos":
        pedidos_filtrados = [
            pedido for pedido in pedidos_filtrados
            if financeiro_origem_key(financeiro_origem_pedido(pedido)) == origem_aplicada
        ]

    if erro_filtro:
        pedidos_filtrados = []

    return pedidos_filtrados, pagamento_aplicado, origem_aplicada, erro_filtro




