# FINANCEIRO — SERVIÇOS DE RESERVAS CONCLUÍDAS
# ==================================================

def financeiro_valor_reserva_observacao(reserva):
    """
    Busca valor do atendimento na observação.
    Formatos aceitos:
    FINANCEIRO_SERVICO valor=35.00 pagamento=Dinheiro
    Serviço: 1x Corte masculino — R$ 18,00
    valor=35
    total=35
    R$ 35
    """
    partes = [
        getattr(reserva, "observacao", "") or "",
        getattr(reserva, "servico", "") or "",
        getattr(reserva, "servico_nome", "") or "",
        getattr(reserva, "descricao", "") or "",
    ]
    texto = " ".join(str(p) for p in partes if p)

    for padrao in [
        r"valor\s*=\s*([0-9]+(?:[\.,][0-9]+)?)",
        r"total\s*=\s*([0-9]+(?:[\.,][0-9]+)?)",
        r"r\$\s*([0-9]+(?:[\.,][0-9]+)?)",
        # Mantém compatibilidade com observações históricas gravadas em euro.
        r"€\s*([0-9]+(?:[\.,][0-9]+)?)",
        r"eur\s*([0-9]+(?:[\.,][0-9]+)?)",
    ]:
        m = re.search(padrao, texto, flags=re.I)
        if m:
            try:
                return float(m.group(1).replace(",", "."))
            except Exception:
                pass

    # fallback: se houver campo de preço direto no banco
    for campo in ["preco", "valor", "total", "valor_servico", "preco_servico"]:
        try:
            valor = getattr(reserva, campo, None)
            if valor:
                return float(str(valor).replace(",", "."))
        except Exception:
            pass

    return 0.0


def financeiro_pagamento_reserva_observacao(reserva):
    texto = (getattr(reserva, "observacao", "") or "")
    m = re.search(r"pagamento\s*=\s*([A-Za-zÀ-ÿ ]+)", texto, flags=re.I)
    if m:
        return m.group(1).strip()
    return "Dinheiro"


def financeiro_reservas_servicos_como_financeiro(db, empresa_id, data_inicio=None, data_fim=None, pagamento=None):
    """
    Transforma reservas confirmadas/concluídas em lançamentos de serviço para o financeiro.
    Não altera o banco; apenas monta objetos compatíveis com o template.
    """
    consulta = db.query(Reserva).filter(
        Reserva.empresa_id == empresa_id,
        func.lower(func.trim(Reserva.status)).in_(["confirmada", "confirmado", "concluida", "concluido", "finalizada", "finalizado", "paga", "pago"])
    )

    if data_inicio:
        consulta = consulta.filter(Reserva.data >= data_inicio)
    if data_fim:
        consulta = consulta.filter(Reserva.data <= data_fim)

    reservas = consulta.order_by(Reserva.data.desc(), Reserva.horario.desc()).all()
    saida = []

    for r in reservas:
        forma = financeiro_pagamento_reserva_observacao(r)
        if pagamento and pagamento != "todos" and forma != pagamento:
            continue

        total = financeiro_valor_reserva_observacao(r)

        criado = None
        try:
            criado = datetime.strptime(f"{r.data} {r.horario}", "%Y-%m-%d %H:%M")
        except Exception:
            criado = getattr(r, "criado_em", None) or agora_brasilia()

        obs = (getattr(r, "observacao", "") or "")
        if "Serviços" not in obs:
            obs = (obs + " Serviços").strip()

        saida.append(SimpleNamespace(
            id=getattr(r, "id", 0),
            reserva_id=getattr(r, "id", 0),
            numero_dia=getattr(r, "numero_dia", None),
            nome_cliente=getattr(r, "nome_cliente", ""),
            tipo_pedido="Serviços",
            observacao=obs,
            pagamento=forma,
            total=total,
            taxa_entrega=0,
            subtotal_sem_iva=total,
            total_iva=0,
            criado_em=criado,
            status="finalizado",
            _financeiro_origem_forcada="Serviços"
        ))

    return saida


@app.post("/reservas/{reserva_id}/concluir")
async def concluir_reserva_financeiro(reserva_id: int, request: Request):
    """
    Conclui atendimento de salão/serviço e registra valor/pagamento na observação.
    JSON esperado:
    {"valor": 35.00, "pagamento": "Dinheiro"}
    """
    db = SessionLocal()
    reserva = db.query(Reserva).filter(Reserva.id == reserva_id).first()

    if not reserva:
        db.close()
        return {"error": "Reserva não encontrada"}

    exigir_admin_empresa_api(request, reserva.empresa_id, "reservas")

    try:
        dados = await request.json()
    except Exception:
        dados = {}

    valor = dados.get("valor") or dados.get("total") or 0
    pagamento = (dados.get("pagamento") or "Dinheiro").strip()

    try:
        valor_float = float(str(valor).replace(",", "."))
    except Exception:
        valor_float = 0.0

    reserva.status = "concluida"

    marcador = f"FINANCEIRO_SERVICO valor={valor_float:.2f} pagamento={pagamento}"
    obs = (getattr(reserva, "observacao", "") or "").strip()
    if "FINANCEIRO_SERVICO" not in obs:
        reserva.observacao = (obs + "\\n" + marcador).strip()
    else:
        reserva.observacao = re.sub(
            r"FINANCEIRO_SERVICO.*",
            marcador,
            obs,
            flags=re.I
        )

    db.commit()
    db.refresh(reserva)
    db.close()

    return {
        "ok": True,
        "message": "Atendimento concluído e enviado ao financeiro.",
        "id": reserva_id,
        "status": "concluida",
        "valor": valor_float,
        "pagamento": pagamento
    }


# ==================================================
# V276 — PAGAMENTO MANUAL DA AGENDA
# ==================================================

@app.post("/reservas/{reserva_id}/registrar-pagamento")
async def registrar_pagamento_manual_reserva(reserva_id: int, request: Request):
    """Registra recebimento sem alterar o status operacional do atendimento.

    O agendamento pode continuar pendente, confirmado ou concluído. Somente o
    status financeiro é atualizado para não confundir "finalizar atendimento"
    com "pagamento recebido".
    """
    db = SessionLocal()
    try:
        reserva = db.query(Reserva).filter(Reserva.id == reserva_id).first()
        if not reserva:
            return JSONResponse({"error": "Agendamento não encontrado."}, status_code=404)

        exigir_admin_empresa_api(request, reserva.empresa_id, "reservas")

        status_operacional = str(reserva.status or "pendente").strip().lower()
        if status_operacional in {"cancelada", "cancelado", "recusada", "recusado", "expirada", "expirado"}:
            return JSONResponse(
                {"error": "Não é possível registrar pagamento em um agendamento encerrado."},
                status_code=400,
            )

        try:
            dados = await request.json()
        except Exception:
            dados = {}

        tipo = str(dados.get("tipo") or "parcial").strip().lower()
        if tipo not in {"sinal", "parcial", "total"}:
            tipo = "parcial"
        modo_ajuste = bool(dados.get("ajuste"))

        forma = str(dados.get("forma_pagamento") or dados.get("pagamento") or "").strip()
        if not forma:
            return JSONResponse({"error": "Escolha a forma de pagamento."}, status_code=400)

        valor_total = max(0.0, financeiro_v273_float(getattr(reserva, "valor_total", 0)))
        if valor_total <= 0:
            valor_total = max(0.0, financeiro_valor_reserva_observacao(reserva))
        if valor_total <= 0:
            return JSONResponse(
                {"error": "Este agendamento não possui um valor total válido."},
                status_code=400,
            )

        valor_recebido_atual = max(0.0, financeiro_v273_float(getattr(reserva, "valor_recebido", 0)))
        status_pagamento_atual = financeiro_v273_status_normalizado(getattr(reserva, "status_pagamento", ""))
        if valor_recebido_atual <= 0 and status_pagamento_atual in FINANCEIRO_V273_STATUS_PAGOS:
            valor_sinal = max(0.0, financeiro_v273_float(getattr(reserva, "valor_sinal", 0)))
            valor_recebido_atual = valor_sinal if valor_sinal > 0 else valor_total

        valor_recebido_atual = min(valor_total, valor_recebido_atual)
        restante_antes = max(0.0, valor_total - valor_recebido_atual)
        if restante_antes <= 0.005 and not modo_ajuste:
            return JSONResponse({"error": "Este atendimento já está totalmente pago."}, status_code=400)

        if modo_ajuste:
            # Ajuste administrativo substitui o total recebido, em vez de somar
            # um novo lançamento. Isso permite corrigir forma/valor após a
            # conclusão sem reabrir o atendimento.
            valor_lancamento = financeiro_v273_float(dados.get("valor"), valor_recebido_atual)
        elif tipo == "total":
            valor_lancamento = restante_antes
        else:
            valor_lancamento = financeiro_v273_float(dados.get("valor"), 0)

        valor_lancamento = round(max(0.0, valor_lancamento), 2)
        if valor_lancamento <= 0:
            return JSONResponse({"error": "Informe um valor recebido maior que zero."}, status_code=400)
        limite_pagamento = valor_total if modo_ajuste else restante_antes
        if valor_lancamento > limite_pagamento + 0.005:
            return JSONResponse(
                {"error": f"O valor não pode ultrapassar R$ {limite_pagamento:.2f}."},
                status_code=400,
            )

        agora = agora_brasilia()
        data_hora_informada = str(dados.get("data_hora") or "").strip()
        if data_hora_informada:
            try:
                agora = datetime.fromisoformat(data_hora_informada)
            except ValueError:
                pass
        novo_recebido = round(
            min(valor_total, valor_lancamento if modo_ajuste else valor_recebido_atual + valor_lancamento),
            2,
        )
        novo_restante = round(max(0.0, valor_total - novo_recebido), 2)

        reserva.valor_total = valor_total
        reserva.valor_recebido = novo_recebido
        if tipo == "sinal":
            reserva.valor_sinal_recebido = round(
                min(
                    novo_recebido,
                    valor_lancamento if modo_ajuste else max(0.0, financeiro_v273_float(getattr(reserva, "valor_sinal_recebido", 0))) + valor_lancamento,
                ),
                2,
            )
        elif modo_ajuste:
            reserva.valor_sinal_recebido = min(
                novo_recebido,
                max(0.0, financeiro_v273_float(getattr(reserva, "valor_sinal_recebido", 0))),
            )
        reserva.pagamento_tipo = tipo
        reserva.forma_pagamento = forma
        reserva.pagamento_registrado_em = agora
        reserva.status_pagamento = "pago" if novo_restante <= 0.005 else "parcial"
        # V281 — qualquer valor efetivamente recebido confirma também os
        # agendamentos que estavam aguardando pagamento/sinal. No menu público
        # esses estados apareciam como “Pendente”, mas a regra anterior só
        # reconhecia o valor literal “pendente”.
        status_confirmavel = status_reserva_chave(status_operacional) in {
            "pendente", "pending", "in_attesa",
            "aguardando_pagamento", "aguardando_sinal",
            "comprovante_enviado",
        }
        if status_confirmavel and valor_lancamento > 0:
            reserva.status = "confirmada"
            reserva.horario_liberado = False
        if novo_restante <= 0.005:
            reserva.pago_em = agora

        observacao_pagamento = str(dados.get("observacao") or "").strip()
        linha_historico = (
            f"{agora.strftime('%d/%m/%Y %H:%M')} · "
            f"{'AJUSTE · ' if modo_ajuste else ''}R$ {valor_lancamento:.2f} · {forma} · {tipo}"
        )
        if observacao_pagamento:
            linha_historico += f" · {observacao_pagamento}"
        historico_anterior = str(getattr(reserva, "pagamento_observacao", "") or "").strip()
        reserva.pagamento_observacao = (
            f"{historico_anterior}\n{linha_historico}".strip()
            if historico_anterior else linha_historico
        )

        db.commit()
        db.refresh(reserva)

        return {
            "ok": True,
            "message": (
                "Pagamento ajustado com sucesso."
                if modo_ajuste
                else "Pagamento registrado e agendamento confirmado."
                if status_confirmavel
                else "Pagamento registrado com sucesso."
            ),
            "reserva_id": reserva.id,
            "status_atendimento": reserva.status,
            "status_pagamento": reserva.status_pagamento,
            "forma_pagamento": reserva.forma_pagamento,
            "valor_total": round(valor_total, 2),
            "valor_lancamento": valor_lancamento,
            "valor_recebido": novo_recebido,
            "valor_sinal_recebido": round(max(0.0, financeiro_v273_float(getattr(reserva, "valor_sinal_recebido", 0))), 2),
            "valor_restante": novo_restante,
            "registrado_em": agora.isoformat(),
        }
    except HTTPException:
        db.rollback()
        raise
    except Exception:
        db.rollback()
        LOGGER.exception("Erro ao registrar pagamento manual da reserva %s", reserva_id)
        return JSONResponse({"error": "Não foi possível registrar o pagamento."}, status_code=500)
    finally:
        db.close()


# ==================================================
# ADMIN FINANCEIRO / RESUMO FISCAL INTERNO
# ==================================================

# ==================================================
# V273 — NOVO FINANCEIRO POR TIPO DE NEGÓCIO
# ==================================================

FINANCEIRO_V273_STATUS_PAGOS = {
    "pago", "paga", "aprovado", "approved", "confirmado", "confirmada"
}
FINANCEIRO_V273_STATUS_CANCELADOS = {
    "cancelado", "cancelada", "recusado", "recusada", "expirado", "expirada",
    "pagamento_recusado", "refunded", "cancelled", "charged_back"
}
FINANCEIRO_V273_STATUS_CONCLUIDOS = {
    "concluido", "concluida", "concluído", "concluída", "finalizado", "finalizada",
    "pago", "paga"
}


def financeiro_v273_texto(valor) -> str:
    return str(valor or "").strip()


def financeiro_v273_status_normalizado(valor) -> str:
    return financeiro_v273_texto(valor).lower()


def financeiro_v273_float(valor, padrao=0.0) -> float:
    try:
        return float(str(valor if valor is not None else padrao).replace(",", "."))
    except (TypeError, ValueError):
        return float(padrao or 0)


def financeiro_v273_data_reserva(reserva) -> datetime:
    data_texto = financeiro_v273_texto(getattr(reserva, "data", ""))
    horario_texto = financeiro_v273_texto(getattr(reserva, "horario", ""))
    horario_texto = horario_texto.split(" - ", 1)[0].strip()
    for formato in ("%Y-%m-%d %H:%M", "%Y-%m-%d"):
        try:
            texto = f"{data_texto} {horario_texto}".strip() if "%H" in formato else data_texto
            return datetime.strptime(texto, formato)
        except (TypeError, ValueError):
            continue
    return getattr(reserva, "criado_em", None) or agora_brasilia()


def financeiro_v312_chave_forma_pagamento(valor) -> str:
    """Normaliza nomes equivalentes para comparar formas sem depender de caixa/texto."""
    texto = re.sub(r"[^a-z0-9]+", "_", financeiro_v273_texto(valor).lower()).strip("_")
    aliases = {
        "pix": "pix_online",
        "pix_online": "pix_online",
        "pix_mercado_pago": "pix_online",
        "pix_manual": "pix_manual",
        "pix_pela_chave": "pix_manual",
        "pix_pela_chave_cpf": "pix_manual",
        "dinheiro": "dinheiro_atendimento",
        "dinheiro_atendimento": "dinheiro_atendimento",
        "dinheiro_local": "dinheiro_atendimento",
        "cartao": "cartao_atendimento",
        "cartao_presencial": "cartao_atendimento",
        "cartao_atendimento": "cartao_atendimento",
        "cartao_local": "cartao_atendimento",
        "maquininha": "cartao_atendimento",
        "cartao_online": "cartao_credito_online",
        "credito_online": "cartao_credito_online",
        "cartao_credito_online": "cartao_credito_online",
        "cartao_debito_online": "cartao_debito_online",
        "transferencia": "transferencia",
        "transferencia_bancaria": "transferencia",
    }
    return aliases.get(texto, texto)

def financeiro_v312_formas_historico(objeto) -> list[str]:
    """Extrai as formas efetivamente registradas no histórico de recebimentos."""
    historico = financeiro_v273_texto(getattr(objeto, "pagamento_observacao", ""))
    formas = []
    for linha in historico.splitlines():
        # Formato atual: data · R$ valor · forma · tipo [· observação]
        partes = [parte.strip() for parte in linha.split("·")]
        indice_valor = next((i for i, parte in enumerate(partes) if re.search(r"R\$\s*[0-9]", parte, re.I)), -1)
        if indice_valor >= 0 and len(partes) > indice_valor + 1:
            forma = partes[indice_valor + 1].strip()
            if forma:
                formas.append(forma)
    return formas

def financeiro_v312_forma_consolidada(objeto, forma_fallback="") -> str:
    """
    Uma forma distinta mantém seu nome; duas ou mais formas distintas viram
    Pagamento misto. A quantidade de parcelas, sozinha, nunca define mistura.
    """
    formas_historico = financeiro_v312_formas_historico(objeto)
    if formas_historico:
        chaves = []
        primeira_por_chave = {}
        for forma in formas_historico:
            chave = financeiro_v312_chave_forma_pagamento(forma)
            if not chave:
                continue
            if chave not in primeira_por_chave:
                primeira_por_chave[chave] = forma
                chaves.append(chave)
        if len(chaves) > 1:
            return "Pagamento misto"
        if len(chaves) == 1:
            # Retorna a chave canônica para aproveitar os rótulos existentes.
            return chaves[0]

    forma = financeiro_v273_texto(forma_fallback or getattr(objeto, "forma_pagamento", ""))
    return financeiro_v312_chave_forma_pagamento(forma) or forma

def financeiro_v273_forma_reserva(reserva) -> str:
    forma_consolidada = financeiro_v312_forma_consolidada(
        reserva,
        financeiro_v273_texto(getattr(reserva, "forma_pagamento", "")),
    )
    if forma_consolidada:
        return forma_consolidada

    # Compatibilidade somente quando a observação antiga realmente contém
    # o marcador de pagamento. Não assumir Dinheiro quando nada foi informado.
    observacao = financeiro_v273_texto(getattr(reserva, "observacao", ""))
    encontrado = re.search(r"pagamento\s*=\s*([A-Za-zÀ-ÿ _-]+)", observacao, flags=re.I)
    if encontrado:
        return financeiro_v312_chave_forma_pagamento(encontrado.group(1).strip())
    return "Não informado"

def financeiro_v273_descricao_reserva(reserva, negocio_servico: bool, profissional_nome: str = "") -> str:
    if not negocio_servico:
        pessoas = int(getattr(reserva, "pessoas", 0) or 0)
        if pessoas > 0:
            return f"Reserva de mesa · {pessoas} pessoa{'s' if pessoas != 1 else ''}"
        return "Reserva de mesa"

    observacao = financeiro_v273_texto(getattr(reserva, "observacao", ""))
    descricao = "Agendamento"
    padroes = (
        r"(?:serviço|servico|service|servizio)\s*:\s*([^\n|]+)",
        r"(?:item|procedimento)\s*:\s*([^\n|]+)",
    )
    for padrao in padroes:
        encontrado = re.search(padrao, observacao, flags=re.I)
        if encontrado:
            candidato = encontrado.group(1).strip(" -–—")
            if candidato:
                descricao = candidato[:90]
                break
    if profissional_nome:
        descricao = f"{descricao} · {profissional_nome}"
    return descricao


def financeiro_v273_valores_reserva(reserva) -> tuple[float, float, float, float]:
    """Retorna (valor_total, recebido, pendente, sinal_recebido).

    Os campos próprios da Reserva são a fonte principal. O marcador histórico em
    observação é usado apenas para registros antigos concluídos antes da V273.
    """
    valor_total = max(0.0, financeiro_v273_float(getattr(reserva, "valor_total", 0)))
    valor_sinal = max(0.0, financeiro_v273_float(getattr(reserva, "valor_sinal", 0)))
    valor_recebido_manual = max(0.0, financeiro_v273_float(getattr(reserva, "valor_recebido", 0)))
    valor_sinal_recebido_manual = max(0.0, financeiro_v273_float(getattr(reserva, "valor_sinal_recebido", 0)))
    status_operacional = financeiro_v273_status_normalizado(getattr(reserva, "status", ""))
    status_pagamento = financeiro_v273_status_normalizado(getattr(reserva, "status_pagamento", ""))
    observacao = financeiro_v273_texto(getattr(reserva, "observacao", ""))

    valor_historico = financeiro_valor_reserva_observacao(reserva)
    tem_marcador_historico = "financeiro_servico" in observacao.lower()
    if valor_total <= 0 and valor_historico > 0:
        valor_total = valor_historico

    cancelado = status_operacional in FINANCEIRO_V273_STATUS_CANCELADOS
    recebido = valor_recebido_manual
    sinal_recebido = valor_sinal_recebido_manual

    if sinal_recebido <= 0 and valor_recebido_manual > 0 and financeiro_v273_status_normalizado(getattr(reserva, "pagamento_tipo", "")) == "sinal":
        sinal_recebido = valor_recebido_manual

    if status_pagamento in FINANCEIRO_V273_STATUS_PAGOS:
        # V314 — pagamento quitado representa o total consolidado, não apenas o sinal.
        # Preserva o valor manual já acumulado e completa até o total quando o status é pago.
        recebido = max(recebido, valor_total if valor_total > 0 else valor_sinal)
        if valor_sinal > 0:
            sinal_recebido = min(valor_sinal, recebido)

    # Registros antigos concluídos gravavam valor e pagamento na observação.
    if tem_marcador_historico and valor_historico > 0:
        recebido = max(recebido, valor_historico)

    # Atendimento concluído e pago localmente, sem gateway.
    forma = financeiro_v273_forma_reserva(reserva)
    forma_normalizada = normalizar_forma_pagamento_reserva(forma)
    if (
        status_operacional in FINANCEIRO_V273_STATUS_CONCLUIDOS
        and valor_total > 0
        and forma_normalizada in {"dinheiro_atendimento", "cartao_atendimento"}
    ):
        recebido = max(recebido, valor_total)

    recebido = min(recebido, valor_total) if valor_total > 0 else recebido
    sinal_recebido = min(sinal_recebido, recebido)
    if valor_total > 0:
        sinal_recebido = min(sinal_recebido, valor_total)
    pendente = 0.0 if cancelado else max(0.0, valor_total - recebido)
    return round(valor_total, 2), round(recebido, 2), round(pendente, 2), round(sinal_recebido, 2)

def financeiro_v273_status_movimento(status_operacional: str, recebido: float, pendente: float) -> str:
    status = financeiro_v273_status_normalizado(status_operacional)
    if status in FINANCEIRO_V273_STATUS_CANCELADOS:
        return "cancelado"
    if recebido > 0 and pendente > 0:
        return "parcial"
    if recebido > 0 and pendente <= 0:
        return "recebido"
    if pendente > 0:
        return "pendente"
    if status in FINANCEIRO_V273_STATUS_CONCLUIDOS:
        return "concluido"
    return "sem_valor"


def financeiro_v273_registro_pedido(pedido, financeiro_tipo: str):
    origem = "vendas" if financeiro_tipo == "produtos" else "pedidos"
    tipo_pedido = financeiro_v273_texto(getattr(pedido, "tipo_pedido", ""))
    if financeiro_tipo == "restaurante":
        origem_nome = financeiro_origem_pedido(pedido)
        descricao = tipo_pedido or "Pedido"
    else:
        origem_nome = "Vendas"
        descricao = "Venda de produtos"

    total = max(0.0, financeiro_v273_float(getattr(pedido, "total", 0)))
    status_operacional = financeiro_v273_texto(getattr(pedido, "status", ""))
    cancelado = financeiro_v273_status_normalizado(status_operacional) in FINANCEIRO_V273_STATUS_CANCELADOS
    status_pagamento_norm = financeiro_v273_status_normalizado(getattr(pedido, "status_pagamento", ""))
    gateway_status_norm = financeiro_v273_status_normalizado(getattr(pedido, "gateway_status", ""))
    reembolso_status_norm = financeiro_v273_status_normalizado(getattr(pedido, "reembolso_status", ""))
    reembolso_valor = max(0.0, financeiro_v273_float(getattr(pedido, "reembolso_valor", 0)))
    pago_confirmado = (
        status_pagamento_norm in FINANCEIRO_V273_STATUS_PAGOS
        or gateway_status_norm in {"approved", "accredited"}
    )
    reembolso_realizado = (
        reembolso_status_norm in {"realizado", "reembolsado", "refunded", "estornado"}
        or gateway_status_norm in {"refunded", "charged_back"}
    )

    if cancelado:
        if pago_confirmado and not reembolso_realizado:
            # V923 — pedido cancelado, mas pagamento ainda pertence ao caixa.
            valor_recebido = total
        elif pago_confirmado and reembolso_realizado:
            valor_recebido = max(0.0, total - (reembolso_valor or total))
        else:
            valor_recebido = 0.0
        status_financeiro = "cancelado"
    else:
        # Só entram aqui pedidos finalizados; preserva o comportamento histórico.
        valor_recebido = total
        status_financeiro = "recebido"
    data_movimento = getattr(pedido, "criado_em", None) or agora_brasilia()
    numero_dia = getattr(pedido, "numero_dia", None)
    data_operacional = getattr(pedido, "data_operacional", None)
    if not data_operacional:
        data_operacional = data_movimento.date()

    return SimpleNamespace(
        chave_registro=f"pedido:{pedido.id}",
        registro_id=pedido.id,
        origem_tipo=origem,
        origem_nome=origem_nome,
        numero_dia=numero_dia,
        data_operacional=data_operacional,
        codigo_interno=None,
        profissional_id=None,
        profissional_nome="",
        cliente=financeiro_v273_texto(getattr(pedido, "nome_cliente", "")) or "Cliente não informado",
        descricao=descricao,
        forma_pagamento=financeiro_v312_forma_consolidada(
            pedido,
            financeiro_v273_texto(getattr(pedido, "pagamento", "")),
        ) or "Não informado",
        status_operacional=status_operacional,
        status_pagamento=financeiro_v273_texto(getattr(pedido, "status_pagamento", "")),
        reembolso_status=financeiro_v273_texto(getattr(pedido, "reembolso_status", "")),
        reembolso_valor=round(reembolso_valor, 2),
        status_financeiro=status_financeiro,
        valor_total=round(total, 2),
        valor_recebido=round(valor_recebido, 2),
        valor_pendente=0.0,
        valor_sinal_recebido=0.0,
        taxa_entrega=round(max(0.0, financeiro_v273_float(getattr(pedido, "taxa_entrega", 0))), 2),
        subtotal_sem_iva=round(max(0.0, financeiro_v273_float(getattr(pedido, "subtotal_sem_iva", 0))), 2),
        total_iva=round(max(0.0, financeiro_v273_float(getattr(pedido, "total_iva", 0))), 2),
        data_movimento=data_movimento,
        imprimir_url=f"/admin/{pedido.empresa_id}/financeiro/imprimir/{origem}/{pedido.id}",
    )

def financeiro_v273_registro_reserva(reserva, financeiro_tipo: str, profissional_nome: str = ""):
    negocio_servico = financeiro_tipo == "servicos"
    valor_total, recebido, pendente, sinal_recebido = financeiro_v273_valores_reserva(reserva)
    data_movimento = financeiro_v273_data_reserva(reserva)
    status_operacional = financeiro_v273_texto(getattr(reserva, "status", ""))
    origem_tipo = "agendamentos" if negocio_servico else "reservas"
    origem_nome = "Agendamentos" if negocio_servico else "Reservas"
    data_operacional = getattr(reserva, "data_operacional", None)
    if not data_operacional:
        try:
            data_operacional = datetime.strptime(financeiro_v273_texto(reserva.data), "%Y-%m-%d").date()
        except (TypeError, ValueError):
            data_operacional = data_movimento.date()

    return SimpleNamespace(
        chave_registro=f"reserva:{reserva.id}",
        registro_id=reserva.id,
        origem_tipo=origem_tipo,
        origem_nome=origem_nome,
        numero_dia=getattr(reserva, "numero_dia", None),
        data_operacional=data_operacional,
        codigo_interno=getattr(reserva, "codigo", None),
        profissional_id=getattr(reserva, "profissional_id", None),
        profissional_nome=profissional_nome or "Não informado",
        cliente=financeiro_v273_texto(getattr(reserva, "nome_cliente", "")) or "Cliente não informado",
        descricao=financeiro_v273_descricao_reserva(reserva, negocio_servico, profissional_nome),
        forma_pagamento=financeiro_v273_forma_reserva(reserva) or "Não informado",
        status_operacional=status_operacional,
        status_pagamento=financeiro_v273_texto(getattr(reserva, "status_pagamento", "")),
        status_financeiro=financeiro_v273_status_movimento(status_operacional, recebido, pendente),
        valor_total=valor_total,
        valor_recebido=recebido,
        valor_pendente=pendente,
        valor_sinal_recebido=sinal_recebido,
        taxa_entrega=0.0,
        subtotal_sem_iva=valor_total,
        total_iva=0.0,
        data_movimento=data_movimento,
        imprimir_url=f"/admin/{reserva.empresa_id}/financeiro/imprimir/{origem_tipo}/{reserva.id}",
    )

def financeiro_v819_forma_encomenda(encomenda) -> str:
    # V849 — a forma exibida no Financeiro é a mesma consolidada na Central.
    info = _v849_pagamento_encomenda_info(encomenda)
    return info.get("forma_consolidada", "Não informado") or "Não informado"



def financeiro_v819_registro_encomenda(encomenda):
    total, recebido, pendente, sinal_recebido = (
        _v819_valores_financeiros_encomenda(encomenda)
    )
