    status_operacional = financeiro_v273_texto(
        getattr(encomenda, "status", "")
    )

    data_movimento = (
        getattr(encomenda, "pago_em", None)
        or getattr(encomenda, "criado_em", None)
        or agora_brasilia()
    )

    data_operacional = getattr(encomenda, "data_retirada", None)
    if not data_operacional:
        data_operacional = data_movimento.date()

    numero = (
        financeiro_v273_texto(getattr(encomenda, "numero", ""))
        or str(encomenda.id)
    )

