        profissional_id=None,
        profissional_nome="",
        cliente=financeiro_v273_texto(
            getattr(encomenda, "cliente_nome", "")
        ) or "Cliente não informado",
        descricao=descricao,
        forma_pagamento=financeiro_v819_forma_encomenda(encomenda),
        forma_pagamento_label=pagamento_info.get("forma_consolidada_label", "Não informado"),
        pagamento_detalhe=pagamento_info.get("detalhe_texto", ""),
