    iva_sheet=v159_montar_sheet_tabela(v159_tr(idioma,"vat_by_rate"),v159_tr(idioma,"vat_by_rate_subtitle"),[v159_tr(idioma,"rate"),v159_tr(idioma,"base_without_vat"),v159_tr(idioma,"vat_value"),v159_tr(idioma,"gross_total")],linhas_iva,tipos_colunas={2:"number",3:"number",4:"number"},larguras=[16,18,18,18],idioma=idioma)
    linhas_pedidos=[]
