def v200_data_relatorio(valor):
    if not valor:
        return ""
    if isinstance(valor, datetime):
        return valor.strftime("%d-%m-%Y %H:%M")
    if isinstance(valor, date):
        return valor.strftime("%d-%m-%Y")
    texto_valor = str(valor).strip()
    for formato in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d", "%d/%m/%Y"):
        try:
            data_obj = datetime.strptime(texto_valor[:19] if "%H" in formato else texto_valor[:10], formato)
            return data_obj.strftime("%d-%m-%Y %H:%M" if "%H" in formato else "%d-%m-%Y")
        except Exception:
            pass
    return texto_valor


def v200_data_obj(valor):
    if isinstance(valor, datetime):
        return valor
    if isinstance(valor, date):
        return datetime.combine(valor, time.min)
    texto_valor = str(valor or "").strip()
    for formato in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d", "%d/%m/%Y"):
        try:
            base = texto_valor[:19] if "%H" in formato else texto_valor[:10]
            return datetime.strptime(base, formato)
        except Exception:
            pass
    return None


def v200_no_periodo(valor, data_inicio=None, data_fim=None):
    data_obj = v200_data_obj(valor)
    if not data_obj:
        return True
    try:
        inicio = datetime.strptime(data_inicio, "%Y-%m-%d") if data_inicio else None
        fim = datetime.combine(datetime.strptime(data_fim, "%Y-%m-%d").date(), time(23, 59, 59)) if data_fim else None
    except Exception:
        inicio = fim = None
    return (not inicio or data_obj >= inicio) and (not fim or data_obj <= fim)


def v200_status_pedido(valor):
    chave = str(valor or "novo").strip().lower()
    return {
        "aguardando_pagamento": "Aguardando pagamento",
        "novo": "Novo",
        "pagamento confirmado": "Pagamento confirmado",
        "recebido": "Recebido",
        "em separacao": "Em separação",
        "em separação": "Em separação",
        "cozinha": "Em preparo",
        "preparando": "Em preparo",
        "em preparo": "Em preparo",
        "enviado": "Enviado",
        "saiu para entrega": "Saiu para entrega",
        "pronto para retirada": "Pronto para retirada",
        "finalizado": "Concluído",
        "concluido": "Concluído",
        "concluído": "Concluído",
        "cancelado": "Cancelado",
    }.get(chave, str(valor or "Não informado").strip().capitalize())


