@app.get("/admin/{empresa_id}/financeiro/relatorio.csv")
def exportar_relatorio_financeiro_csv(
    empresa_id: int,
    request: Request,
    data_inicio: str | None = None,
    data_fim: str | None = None,
    pagamento: str | None = None,
    origem: str | None = None,
    idioma: str | None = None,
    lang: str | None = None
):
    exigir_admin_empresa_api(request, empresa_id)

    db = SessionLocal()

    empresa = db.query(Empresa).filter(Empresa.id == empresa_id).first()

    if not empresa:
        db.close()
        return {"error": "Empresa não encontrada"}

    idioma_relatorio = v159_idioma_relatorio(empresa, idioma=idioma, lang=lang)

    pedidos_filtrados, pagamento_aplicado, origem_aplicada, erro_filtro = financeiro_filtrar_pedidos(
        db=db,
        empresa_id=empresa_id,
        data_inicio=data_inicio,
        data_fim=data_fim,
        pagamento=pagamento,
        origem=origem,
        ordem_desc=False
    )

    resumo = financeiro_montar_resumo(pedidos_filtrados)

    pedido_ids = [pedido.id for pedido in pedidos_filtrados]
    resumo_iva_por_aliquota = {}

    if pedido_ids:
        itens_filtrados = db.query(PedidoItem).filter(PedidoItem.pedido_id.in_(pedido_ids)).all()

        for item in itens_filtrados:
            aliquota = float(item.aliquota_iva or 0)
            chave = f"{aliquota:.2f}"

            if chave not in resumo_iva_por_aliquota:
                resumo_iva_por_aliquota[chave] = {
                    "aliquota": aliquota,
                    "base_sem_iva": 0,
                    "iva": 0,
                    "total": 0
                }

            resumo_iva_por_aliquota[chave]["base_sem_iva"] += item.subtotal_sem_iva or 0
            resumo_iva_por_aliquota[chave]["iva"] += item.valor_iva or 0
            resumo_iva_por_aliquota[chave]["total"] += item.subtotal or 0

    resumo_iva_lista = sorted(resumo_iva_por_aliquota.values(), key=lambda registro: registro["aliquota"])

    arquivo = io.StringIO()
    writer = csv.writer(arquivo, delimiter=";")

    periodo_inicio = data_inicio or "Sem data inicial"
    periodo_fim = data_fim or "Sem data final"

    writer.writerow(["VENDAS / CAIXA"])
    writer.writerow(["Empresa", empresa.nome or ""])
    writer.writerow(["Período", f"{periodo_inicio} até {periodo_fim}"])
    writer.writerow(["Filtro de pagamento", pagamento_aplicado])
    writer.writerow(["Filtro de origem", origem_aplicada])
    writer.writerow(["Gerado em", agora_brasilia().strftime("%d/%m/%Y %H:%M")])
    writer.writerow([])

    writer.writerow(["DADOS FISCAIS DA EMPRESA"])
    writer.writerow(["Campo", "Valor"])
    writer.writerow(["Nome comercial", empresa.nome or ""])
    writer.writerow(["Razão social", getattr(empresa, "razao_social", None) or getattr(empresa, "ragione_sociale", None) or empresa.nome or ""])
    writer.writerow(["CNPJ", getattr(empresa, "cnpj", None) or ""])
    writer.writerow(["Inscrição estadual", getattr(empresa, "inscricao_estadual", None) or ""])
    writer.writerow(["Inscrição municipal", getattr(empresa, "inscricao_municipal", None) or ""])
    writer.writerow(["Regime tributário", getattr(empresa, "regime_tributario", None) or ""])
    writer.writerow(["E-mail", empresa.email or ""])
    writer.writerow(["Telefone/WhatsApp", empresa.telefone_whatsapp or empresa.telefone_fixo or ""])
    writer.writerow(["Endereço", empresa.endereco or ""])
    writer.writerow(["Cidade", empresa.cidade or ""])
    writer.writerow(["País", "Brasil"])
    writer.writerow(["CNAE principal", getattr(empresa, "cnae_principal", None) or ""])
    writer.writerow(["Aviso", "Relatório de apoio para conferência interna. A apuração e as obrigações fiscais oficiais devem ser validadas pelo contador da empresa."])
    writer.writerow([])

    writer.writerow(["RESUMO DO PERÍODO"])
    writer.writerow(["Indicador", "Valor"])
    writer.writerow(["Pedidos finalizados", resumo["total_pedidos_finalizados"]])
    writer.writerow(["Faturamento bruto", f"{resumo['faturamento_total']:.2f}"])
    writer.writerow(["Produtos / itens", f"{resumo['produtos_total']:.2f}"])
    writer.writerow(["Taxas de entrega", f"{resumo['taxas_entrega_total']:.2f}"])
    writer.writerow(["Base de cálculo registrada", f"{resumo['faturamento_sem_iva']:.2f}"])
    writer.writerow(["Impostos registrados", f"{resumo['iva_acumulada']:.2f}"])
    writer.writerow(["Ticket médio", f"{resumo['ticket_medio']:.2f}"])
    writer.writerow([])

    writer.writerow(["RESUMO POR ORIGEM DO PEDIDO"])
    writer.writerow(["Origem", "Pedidos", "Total vendido", "Taxas de entrega"])
    for origem_nome, dados in resumo["resumo_origens"].items():
        writer.writerow([
            origem_nome,
            dados["quantidade"],
            f"{dados['total']:.2f}",
            f"{dados['taxa_entrega']:.2f}"
        ])
    writer.writerow([])

    writer.writerow(["RESUMO POR FORMA DE PAGAMENTO"])
    writer.writerow(["Pagamento", "Pedidos", "Total bruto", "Base de cálculo", "Impostos"])
    for forma, dados in resumo["resumo_pagamentos"].items():
        writer.writerow([
            forma,
            dados["quantidade"],
            f"{dados['total']:.2f}",
            f"{dados['sem_iva']:.2f}",
            f"{dados['iva']:.2f}"
        ])
    writer.writerow([])

    writer.writerow(["IMPOSTOS POR ALÍQUOTA"])
    writer.writerow(["Alíquota", "Base de cálculo", "Impostos", "Total bruto"])
    if resumo_iva_lista:
        for linha in resumo_iva_lista:
            writer.writerow([
                f"{linha['aliquota']:.2f}%",
                f"{linha['base_sem_iva']:.2f}",
                f"{linha['iva']:.2f}",
                f"{linha['total']:.2f}"
            ])
    else:
        writer.writerow(["Sem dados", "", "", ""])
    writer.writerow([])

    writer.writerow(["PEDIDOS FINALIZADOS DO PERÍODO"])
    writer.writerow([
        "Pedido",
        "Data",
        "Cliente",
        "Origem",
        "Pagamento",
        "Total bruto",
        "Taxa entrega",
        "Base de cálculo",
        "Impostos"
    ])

    if pedidos_filtrados:
        for pedido in pedidos_filtrados:
            writer.writerow([
                pedido.id,
                pedido.criado_em.strftime("%d-%m-%Y %H:%M") if pedido.criado_em else "",
                pedido.nome_cliente or "",
                financeiro_origem_pedido(pedido),
                pedido.pagamento or "",
                f"{(pedido.total or 0):.2f}",
                f"{(pedido.taxa_entrega or 0):.2f}",
                f"{(pedido.subtotal_sem_iva or 0):.2f}",
                f"{(pedido.total_iva or 0):.2f}"
            ])
    else:
        writer.writerow(["Nenhum pedido finalizado encontrado", "", "", "", "", "", "", "", ""])

    db.close()

    conteudo_csv = "\ufeff" + arquivo.getvalue()

    nome_arquivo = v159_nome_arquivo_financeiro(
        empresa_id=empresa_id,
        data_inicio=data_inicio,
        data_fim=data_fim,
        pagamento=pagamento_aplicado,
        origem=origem_aplicada,
        idioma=idioma_relatorio,
        extensao="csv"
    )

    return Response(
        content=conteudo_csv,
        media_type="text/csv; charset=utf-8",
        headers={"Content-Disposition": f'attachment; filename="{nome_arquivo}"'}
    )





# ==================================================
# ADMIN FECHAMENTO DE CAIXA DIÁRIO
# ==================================================

def calcular_movimento_caixa_do_dia(db, empresa_id: int, data_caixa: str):
    """
    Calcula o movimento atual do dia selecionado.
    Considera:
    - faturamento: pedidos finalizados
    - cancelamentos: pedidos cancelados
    """
    try:
        data_obj = datetime.strptime(data_caixa, "%Y-%m-%d")
    except ValueError:
        return None

    inicio = datetime.combine(data_obj.date(), time(0, 0, 0))
    fim = datetime.combine(data_obj.date(), time(23, 59, 59))

    pedidos_finalizados = db.query(Pedido).filter(
        Pedido.empresa_id == empresa_id,
        Pedido.status == "finalizado",
        Pedido.criado_em >= inicio,
        Pedido.criado_em <= fim
    ).all()

    pedidos_cancelados = db.query(Pedido).filter(
        Pedido.empresa_id == empresa_id,
        Pedido.status == "cancelado",
        Pedido.criado_em >= inicio,
        Pedido.criado_em <= fim
    ).count()

    faturamento_total = sum(
        pedido.total or 0
        for pedido in pedidos_finalizados
    )

    faturamento_sem_iva = sum(
        pedido.subtotal_sem_iva or 0
        for pedido in pedidos_finalizados
    )

    iva_acumulada = sum(
        pedido.total_iva or 0
        for pedido in pedidos_finalizados
    )

    total_cartao = sum(
        pedido.total or 0
        for pedido in pedidos_finalizados
        if pedido.pagamento == "Cartão"
    )

    total_dinheiro = sum(
        pedido.total or 0
        for pedido in pedidos_finalizados
        if pedido.pagamento == "Dinheiro"
    )

    total_pedidos_finalizados = len(pedidos_finalizados)

    ticket_medio = (
        faturamento_total / total_pedidos_finalizados
        if total_pedidos_finalizados > 0
        else 0
    )

    return {
        "data": data_caixa,
        "faturamento_total": faturamento_total,
        "faturamento_sem_iva": faturamento_sem_iva,
        "iva_acumulada": iva_acumulada,
        "total_cartao": total_cartao,
        "total_dinheiro": total_dinheiro,
        "pedidos_finalizados": total_pedidos_finalizados,
        "pedidos_cancelados": pedidos_cancelados,
        "ticket_medio": ticket_medio
    }


@app.get("/admin/{empresa_id}/caixa")
def admin_caixa(
    empresa_id: int,
    request: Request,
    data: str | None = None
):
    redirecionamento = redirecionar_area_admin_se_necessario(request, empresa_id, "financeiro")
    if redirecionamento:
        return redirecionamento

    db = SessionLocal()

    empresa = db.query(Empresa).filter(
        Empresa.id == empresa_id
    ).first()

    if not empresa:
        db.close()
        return {"error": "Empresa não encontrada"}

    anexar_idioma_empresa(db, empresa)

    data_selecionada = data or agora_brasilia().strftime("%Y-%m-%d")

    movimento = calcular_movimento_caixa_do_dia(
        db=db,
        empresa_id=empresa_id,
        data_caixa=data_selecionada
    )

    if movimento is None:
        db.close()
        return {"error": "Data inválida. Use o formato YYYY-MM-DD."}

    fechamento = db.query(FechamentoCaixa).filter(
        FechamentoCaixa.empresa_id == empresa_id,
        FechamentoCaixa.data == data_selecionada
    ).first()

    fechamento_alterado = False

    if fechamento:
        fechamento_alterado = any([
            round(fechamento.total_bruto or 0, 2) != round(movimento["faturamento_total"] or 0, 2),
            round(fechamento.base_sem_iva or 0, 2) != round(movimento["faturamento_sem_iva"] or 0, 2),
            round(fechamento.total_iva or 0, 2) != round(movimento["iva_acumulada"] or 0, 2),
            round(fechamento.total_cartao or 0, 2) != round(movimento["total_cartao"] or 0, 2),
            round(fechamento.total_dinheiro or 0, 2) != round(movimento["total_dinheiro"] or 0, 2),
            int(fechamento.pedidos_finalizados or 0) != int(movimento["pedidos_finalizados"] or 0),
            int(fechamento.pedidos_cancelados or 0) != int(movimento["pedidos_cancelados"] or 0)
        ])

    fechamentos_recentes = db.query(FechamentoCaixa).filter(
        FechamentoCaixa.empresa_id == empresa_id
    ).order_by(
        FechamentoCaixa.data.desc(),
        FechamentoCaixa.id.desc()
    ).limit(12).all()

    db.close()

    return templates.TemplateResponse(
        request=request,
        name="admin_caixa.html",
        context={
            "empresa": empresa,
            "data_selecionada": data_selecionada,
            "movimento": movimento,
            "fechamento": fechamento,
            "fechamento_alterado": fechamento_alterado,
            "fechamentos_recentes": fechamentos_recentes
        }
    )


@app.post("/admin/{empresa_id}/caixa/fechar")
def fechar_caixa_dia(
    empresa_id: int,
    dados: FechamentoCaixaCreate,
    request: Request
):
    exigir_admin_empresa_api(request, empresa_id)
    db = SessionLocal()

    empresa = db.query(Empresa).filter(
        Empresa.id == empresa_id
    ).first()

    if not empresa:
        db.close()
        return {"error": "Empresa não encontrada"}

    existente = db.query(FechamentoCaixa).filter(
        FechamentoCaixa.empresa_id == empresa_id,
        FechamentoCaixa.data == dados.data
    ).first()

    if existente:
        db.close()
        return {"error": "O caixa deste dia já foi fechado."}

    movimento = calcular_movimento_caixa_do_dia(
        db=db,
        empresa_id=empresa_id,
        data_caixa=dados.data
    )

    if movimento is None:
        db.close()
        return {"error": "Data inválida. Use o formato YYYY-MM-DD."}

    fechamento = FechamentoCaixa(
        empresa_id=empresa_id,
        data=dados.data,
        total_bruto=movimento["faturamento_total"],
        base_sem_iva=movimento["faturamento_sem_iva"],
        total_iva=movimento["iva_acumulada"],
        total_cartao=movimento["total_cartao"],
        total_dinheiro=movimento["total_dinheiro"],
        pedidos_finalizados=movimento["pedidos_finalizados"],
        pedidos_cancelados=movimento["pedidos_cancelados"],
        ticket_medio=movimento["ticket_medio"],
        observacao=dados.observacao
    )

    db.add(fechamento)
    db.commit()
    db.close()

    return {"message": "Caixa fechado com sucesso."}


@app.delete("/admin/{empresa_id}/caixa/{data}")
def reabrir_caixa_dia(empresa_id: int, data: str, request: Request):
    exigir_admin_empresa_api(request, empresa_id)
    db = SessionLocal()

    fechamento = db.query(FechamentoCaixa).filter(
        FechamentoCaixa.empresa_id == empresa_id,
        FechamentoCaixa.data == data
    ).first()

    if not fechamento:
        db.close()
        return {"error": "Fechamento não encontrado."}

    db.delete(fechamento)
    db.commit()
    db.close()

    return {"message": "Fechamento reaberto com sucesso."}






