@app.patch("/admin/{empresa_id}/pedidos/tempos")
def atualizar_tempos_pedidos(
    empresa_id: int,
    dados: TempoPedidosUpdate,
    request: Request
):
    exigir_admin_empresa_api(request, empresa_id)

    if dados.tempo_retirada_minutos < 0 or dados.tempo_entrega_minutos < 0:
        return {"error": "Os tempos devem ser maiores ou iguais a zero."}

    if dados.tempo_retirada_minutos > 1440 or dados.tempo_entrega_minutos > 1440:
        return {"error": "Informe um tempo menor ou igual a 1440 minutos."}

    db = SessionLocal()

    empresa = db.query(Empresa).filter(
        Empresa.id == empresa_id
    ).first()

    if not empresa:
        db.close()
        return {"error": "Empresa não encontrada"}

    empresa.tempo_retirada_minutos = dados.tempo_retirada_minutos
    empresa.tempo_entrega_minutos = dados.tempo_entrega_minutos

    db.commit()
    db.close()

    return {"message": "Tempos atualizados com sucesso."}



@app.patch("/admin/{empresa_id}/pedidos/taxa-entrega")
async def atualizar_taxa_entrega_pedidos(
    empresa_id: int,
    request: Request
):
    exigir_admin_empresa_api(request, empresa_id)

    dados = await request.json()
    taxa = dados.get("taxa_entrega_padrao", 0)

    try:
        taxa_decimal = moeda(taxa)
    except Exception:
        return {"error": "Informe uma taxa de entrega válida."}

    if taxa_decimal < 0:
        return {"error": "A taxa de entrega não pode ser negativa."}

    if taxa_decimal > Decimal("9999"):
        return {"error": "Informe uma taxa menor."}

    db = SessionLocal()

    empresa = db.query(Empresa).filter(
        Empresa.id == empresa_id
    ).first()

    if not empresa:
        db.close()
        return {"error": "Empresa não encontrada"}

    empresa.taxa_entrega_padrao = float(taxa_decimal)

    db.commit()
    db.close()

    return {
        "message": "Taxa de entrega atualizada com sucesso.",
        "taxa_entrega_padrao": float(taxa_decimal)
    }


