@app.get("/admin/{empresa_id}/produtos-pedidos")
def admin_produtos_pedidos(
    empresa_id: int,
    request: Request,
    data: str | None = None,
    filtro: str | None = None,
):
    redirecionamento = redirecionar_area_admin_se_necessario(request, empresa_id, "produtos")
    if redirecionamento:
        return redirecionamento

    db = SessionLocal()
    empresa = db.query(Empresa).filter(Empresa.id == empresa_id).first()
    if not empresa:
        db.close()
        return {"error": "Empresa não encontrada"}
    if not tipo_negocio_produto(empresa.tipo):
        db.close()
        return RedirectResponse(url=f"/admin/{empresa_id}/pedidos", status_code=303)

    anexar_idioma_empresa(db, empresa)
    agora = agora_brasilia()
    hoje = agora.date()

    filtros_validos = {
        "todos",
        "ativos",
        "pendentes",
        "concluidos",
        "cancelados",
        "valor_pendente",
        "novos",
        "aguardando_pagamento",
        "pagos",
        "separacao",
        "envio",
        "pronto_retirada",
    }
    filtro_selecionado = (filtro or "todos").strip().lower()
    if filtro_selecionado not in filtros_validos:
        filtro_selecionado = "todos"

    data_obj = None
    data_selecionada = ""
    if data:
        try:
            data_obj = datetime.strptime(data, "%Y-%m-%d")
            data_selecionada = data_obj.strftime("%Y-%m-%d")
        except ValueError:
            data_obj = None
            data_selecionada = ""

    consulta_base = db.query(Pedido).filter(
        Pedido.empresa_id == empresa_id,
        or_(Pedido.origem_menu == "produto", Pedido.origem_menu == None),
    )

    if data_obj is not None:
        inicio_dia = datetime.combine(data_obj.date(), time.min)
        fim_dia = datetime.combine(data_obj.date(), time.max)
        consulta_base = consulta_base.filter(
            Pedido.criado_em >= inicio_dia,
            Pedido.criado_em <= fim_dia,
        )

    status_normalizado = func.lower(
        func.trim(func.replace(func.coalesce(Pedido.status, ""), "_", " "))
    )
    pagamento_normalizado = func.lower(
        func.trim(func.replace(func.coalesce(Pedido.status_pagamento, ""), "_", " "))
    )

    status_concluidos = ["finalizado", "concluido", "concluído"]
    status_encerrados = [*status_concluidos, "cancelado"]
    pagamentos_pendentes = ["pendente", "aguardando pagamento"]

    filtro_ativos = ~status_normalizado.in_(status_encerrados)
    filtro_pendentes = or_(
        status_normalizado.in_(["novo", "aguardando pagamento"]),
        and_(
            status_normalizado != "cancelado",
            pagamento_normalizado.in_(pagamentos_pendentes),
        ),
    )
    filtro_concluidos = status_normalizado.in_(status_concluidos)
    filtro_cancelados = status_normalizado == "cancelado"
    filtro_valor_pendente = and_(
        status_normalizado != "cancelado",
        pagamento_normalizado.in_(pagamentos_pendentes),
    )
    filtro_novos = status_normalizado.in_(["novo", "recebido"])
    filtro_aguardando_pagamento = and_(
        status_normalizado != "cancelado",
        or_(
            status_normalizado == "aguardando pagamento",
            pagamento_normalizado.in_(pagamentos_pendentes),
        ),
    )
    filtro_pagos = and_(
        status_normalizado != "cancelado",
        or_(
            status_normalizado == "pagamento confirmado",
            pagamento_normalizado == "pago",
        ),
    )
    filtro_separacao = status_normalizado.in_(["em separacao", "em preparo"])
    filtro_envio = status_normalizado.in_(["enviado", "saiu para entrega"])
    filtro_pronto_retirada = status_normalizado == "pronto para retirada"

    filtros_consulta = {
        "ativos": filtro_ativos,
        "pendentes": filtro_pendentes,
        "concluidos": filtro_concluidos,
        "cancelados": filtro_cancelados,
        "valor_pendente": filtro_valor_pendente,
        "novos": filtro_novos,
        "aguardando_pagamento": filtro_aguardando_pagamento,
        "pagos": filtro_pagos,
        "separacao": filtro_separacao,
        "envio": filtro_envio,
        "pronto_retirada": filtro_pronto_retirada,
    }

    total_todos = consulta_base.count()
    total_ativos = consulta_base.filter(filtro_ativos).count()
    total_pendentes = consulta_base.filter(filtro_pendentes).count()
    total_concluidos = consulta_base.filter(filtro_concluidos).count()
    total_cancelados = consulta_base.filter(filtro_cancelados).count()
    valor_pendente = (
        consulta_base.filter(filtro_valor_pendente)
        .with_entities(func.coalesce(func.sum(Pedido.total), 0))
        .scalar()
        or 0
    )
    contagens_status = {
        "todos": total_todos,
        "novos": consulta_base.filter(filtro_novos).count(),
        "aguardando_pagamento": consulta_base.filter(filtro_aguardando_pagamento).count(),
        "pagos": consulta_base.filter(filtro_pagos).count(),
        "separacao": consulta_base.filter(filtro_separacao).count(),
        "envio": consulta_base.filter(filtro_envio).count(),
        "pronto_retirada": consulta_base.filter(filtro_pronto_retirada).count(),
        "cancelados": total_cancelados,
    }

    # Data e status são filtros independentes: sem data, consulta todas as datas.
    consulta = consulta_base
    filtro_ativo = filtro_selecionado
    if filtro_selecionado in filtros_consulta:
        consulta = consulta.filter(filtros_consulta[filtro_selecionado])
    # filtro "todos": não aplica status; exibe todos os pedidos da data escolhida
    # ou de todas as datas quando o calendário está limpo.

    pedidos = consulta.order_by(Pedido.id.desc()).all()

    normalized_payment_state = False
    for pedido in pedidos:
        if (
            (pedido.status or "").strip().lower() == "cancelado"
            and (pedido.status_pagamento or "").strip().lower()
            in {"pendente", "aguardando_pagamento"}
        ):
            pedido.status_pagamento = "cancelado"
            pedido.gateway_status = pedido.gateway_status or "cancelled_by_merchant"
            normalized_payment_state = True
        elif _mp_apply_expiration(pedido, db, company=empresa, origin_type="pedido"):
            normalized_payment_state = True
    if normalized_payment_state:
        db.commit()

    pedidos_com_itens = []
    for pedido in pedidos:
        dias_pendente = 0
        rotulo_pendencia = ""
        rotulo_data = ""
        if pedido.criado_em:
            data_pedido = pedido.criado_em.date()
            dias_pendente = max((hoje - data_pedido).days, 0)
            if data_pedido == hoje:
                rotulo_data = "Hoje"
            elif dias_pendente == 1:
                rotulo_data = "Ontem"
            else:
                rotulo_data = pedido.criado_em.strftime("%d/%m/%Y")

            status_pedido = (pedido.status or "").strip().lower().replace("_", " ")
            status_pagamento = (pedido.status_pagamento or "").strip().lower().replace("_", " ")
            pedido_pendente = (
                status_pedido in {"novo", "aguardando pagamento"}
                or (
                    status_pedido != "cancelado"
                    and status_pagamento in {"pendente", "aguardando pagamento"}
                )
            )
            if pedido_pendente and dias_pendente > 0:
                if dias_pendente == 1:
                    rotulo_pendencia = "Pedido de ontem · pendente há 1 dia"
                else:
                    rotulo_pendencia = (
                        f"Pedido de {pedido.criado_em.strftime('%d/%m')} · "
                        f"pendente há {dias_pendente} dias"
                    )

        pedidos_com_itens.append(
            {
                "pedido": pedido,
                "itens": db.query(PedidoItem).filter(PedidoItem.pedido_id == pedido.id).all(),
                "dias_pendente": dias_pendente,
                "rotulo_data": rotulo_data,
                "rotulo_pendencia": rotulo_pendencia,
            }
        )

    def formatar_moeda_br(valor: float) -> str:
        return f"{float(valor):,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")

    db.close()
    return templates.TemplateResponse(
        request=request,
        name="admin_produtos_pedidos.html",
        context={
            "empresa": empresa,
            "pedidos_com_itens": pedidos_com_itens,
            "data_selecionada": data_selecionada,
            "data_formatada": data_obj.strftime("%d/%m/%Y") if data_obj else "",
            "modo_visao": filtro_ativo,
            "filtro_ativo": filtro_ativo,
            "filtro_selecionado": filtro_selecionado,
            "metricas_pedidos": {
                "todos": total_todos,
                "ativos": total_ativos,
                "pendentes": total_pendentes,
                "concluidos": total_concluidos,
                "cancelados": total_cancelados,
                "valor_pendente": formatar_moeda_br(valor_pendente),
            },
            "contagens_status": contagens_status,
            "negocio_produto": True,
        },
    )

