@app.get("/admin/{empresa_id}/pedidos")
def admin_pedidos(
    empresa_id: int,
    request: Request,
    data: str | None = None
):
    redirecionamento = redirecionar_area_admin_se_necessario(request, empresa_id, "pedidos")
    if redirecionamento:
        return redirecionamento

    db = SessionLocal()

    empresa = db.query(Empresa).filter(
        Empresa.id == empresa_id
    ).first()

    if not empresa:
        db.close()
        return {"error": "Empresa não encontrada"}
    
    anexar_idioma_empresa(db, empresa)

    hoje = agora_brasilia()
    data_selecionada = data or hoje.strftime("%Y-%m-%d")
    erro_data = None

    try:
        data_obj = datetime.strptime(data_selecionada, "%Y-%m-%d")
    except ValueError:
        data_obj = hoje
        data_selecionada = hoje.strftime("%Y-%m-%d")
        erro_data = "Data inválida. Exibindo os pedidos de hoje."

    inicio_dia = datetime.combine(
        data_obj.date(),
        time(0, 0, 0)
    )

    fim_dia = datetime.combine(
        data_obj.date(),
        time(23, 59, 59)
    )

    consulta_pedidos = db.query(Pedido).filter(
        Pedido.empresa_id == empresa_id,
        Pedido.criado_em >= inicio_dia,
        Pedido.criado_em <= fim_dia
    )

    # A central tradicional nunca recebe vendas da loja de produtos.
    # Registros antigos sem origem continuam válidos apenas para negócios de comida.
    if tipo_negocio_produto(empresa.tipo):
        consulta_pedidos = consulta_pedidos.filter(Pedido.origem_menu == "comida")
    else:
        consulta_pedidos = consulta_pedidos.filter(
            or_(Pedido.origem_menu == "comida", Pedido.origem_menu == None)
        )

    # v907 — tentativas de checkout online continuam ocultas da Central, porém
    # Pix pela chave é um pedido real aguardando conferência manual e precisa
    # aparecer no painel para o estabelecimento confirmar o recebimento.
    status_operacional_normalizado = func.lower(
        func.trim(func.replace(func.coalesce(Pedido.status, ""), "_", " "))
    )
    gateway_operacional_normalizado = func.lower(
        func.trim(func.replace(func.coalesce(Pedido.gateway_pagamento, ""), "_", " "))
    )
    metodo_operacional_normalizado = func.lower(
        func.trim(func.replace(func.coalesce(Pedido.pagamento, ""), "_", " "))
    )
    pix_manual_aguardando = and_(
        status_operacional_normalizado == "aguardando pagamento",
        or_(
            gateway_operacional_normalizado.in_(["pix manual", "pix chave"]),
            metodo_operacional_normalizado.in_(["pix pela chave", "pix manual", "pix chave"]),
        ),
    )
    status_checkout_ocultos = [
        "aguardando pagamento",
        "pagamento recusado",
        "pagamento cancelado",
        "pagamento erro",
    ]
    consulta_pedidos = consulta_pedidos.filter(
        or_(
            ~status_operacional_normalizado.in_(status_checkout_ocultos),
            pix_manual_aguardando,
        )
    )

    pedidos = consulta_pedidos.order_by(
        Pedido.id.desc()
    ).all()

    pedidos_com_itens = []

    resumo_status = {
        "todos": 0,
        "novo": 0,
        "em preparo": 0,
        "pronto para retirada": 0,
        "saiu para entrega": 0,
        "finalizado": 0,
        "cancelado": 0
    }

    for pedido in pedidos:
        itens = db.query(PedidoItem).filter(
            PedidoItem.pedido_id == pedido.id
        ).all()

        pedidos_com_itens.append({
            "pedido": pedido,
            "itens": itens
        })

        resumo_status["todos"] += 1

        # v907 — Pix pela chave aguardando confirmação fica na coluna Novos,
        # sem virar pedido operacional antes da confirmação manual.
        _status_pedido = str(getattr(pedido, "status", "") or "").strip().lower().replace("_", " ")
        _gateway_pedido = str(getattr(pedido, "gateway_pagamento", "") or "").strip().lower().replace("_", " ")
        _metodo_pedido = str(getattr(pedido, "pagamento", "") or "").strip().lower().replace("_", " ")
        _pix_manual_pendente = (
            _status_pedido == "aguardando pagamento"
            and (
                _gateway_pedido in {"pix manual", "pix chave"}
                or _metodo_pedido in {"pix pela chave", "pix manual", "pix chave"}
            )
        )
        if _pix_manual_pendente:
            resumo_status["novo"] += 1
        elif pedido.status in resumo_status:
            resumo_status[pedido.status] += 1

    data_formatada = data_obj.strftime("%d/%m/%Y")
    entrega_externa_config = obter_config_entrega_externa(db, empresa_id)
    entregadores_externos = listar_entregadores_externos(db, empresa_id)
    anexar_entrega_externa_pedidos(db, pedidos)

    db.close()

    return templates.TemplateResponse(
        request=request,
        name="admin_pedidos.html",
        context={
            "empresa": empresa,
            "pedidos_com_itens": pedidos_com_itens,
            "resumo_status": resumo_status,
            "data_selecionada": data_selecionada,
            "data_formatada": data_formatada,
            "erro_data": erro_data,
            "entrega_externa_config": entrega_externa_config,
            "entregadores_externos": entregadores_externos
        }
    )

