@app.get("/admin/{empresa_id}/cardapio")
def admin_cardapio(empresa_id: int, request: Request):
    redirecionamento = redirecionar_area_admin_se_necessario(request, empresa_id, "cardapio")
    if redirecionamento:
        return redirecionamento
    db = SessionLocal()

    empresa = db.query(Empresa).filter(
        Empresa.id == empresa_id
    ).first()

    if not empresa:
        db.close()
        return {"error": "Empresa não encontrada"}

    anexar_idioma_empresa(db, empresa)

    categorias = db.query(Categoria).filter(
        Categoria.empresa_id == empresa_id
    ).order_by(Categoria.ordem).all()

    itens = db.query(Item).filter(
        Item.empresa_id == empresa_id
    ).all()

    anexar_codigo_itens_cardapio(db, itens)

    mapa_categorias = {
        categoria.id: categoria.nome
        for categoria in categorias
    }

    for item in itens:
        setattr(
            item,
            "categoria_nome",
            mapa_categorias.get(item.categoria_id, "Sem categoria")
        )

    db.close()

    return templates.TemplateResponse(
        request=request,
        name="admin_cardapio.html",
        context={
            "empresa": empresa,
            "categorias": categorias,
            "itens": itens,
            "negocio_produto": tipo_negocio_produto(empresa.tipo),
            "negocio_servico": tipo_negocio_servico(empresa.tipo),
            "negocio_pedido": tipo_negocio_pedido(empresa.tipo)
        }
    )


