def preparar_tabelas_whatsapp_cloud():
    try:
        conn = engine.raw_connection()
        cursor = conn.cursor()

        cursor.execute("""
            CREATE TABLE IF NOT EXISTS whatsapp_cloud_configuracoes (
                empresa_id INTEGER PRIMARY KEY,
                ativo INTEGER DEFAULT 0,
                plano_ativo INTEGER DEFAULT 0,
                phone_number_id TEXT,
                business_account_id TEXT,
                access_token TEXT,
                template_pedido_recebido TEXT DEFAULT 'hello_world',
                template_pedido_em_preparo TEXT DEFAULT 'hello_world',
                template_pronto_retirada TEXT DEFAULT 'hello_world',
                template_saiu_entrega TEXT DEFAULT 'hello_world',
                template_reserva_confirmada TEXT DEFAULT 'hello_world',
                template_lembrete_reserva TEXT DEFAULT 'hello_world',
                template_idioma TEXT DEFAULT 'en_US',
                limite_mensal INTEGER DEFAULT 500,
                mensagens_enviadas_mes INTEGER DEFAULT 0,
                criado_em DATETIME,
                atualizado_em DATETIME
            )
        """)

        cursor.execute("""
            CREATE TABLE IF NOT EXISTS whatsapp_cloud_logs (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                empresa_id INTEGER NOT NULL,
                destino TEXT,
                evento TEXT,
                template TEXT,
                status TEXT,
                mensagem TEXT,
                resposta TEXT,
                criado_em DATETIME
            )
        """)

        conn.commit()
        conn.close()
    except Exception:
        pass


def obter_whatsapp_cloud_config(db, empresa_id: int):
    preparar_tabelas_whatsapp_cloud()

    linha = db.execute(
        text("""
            SELECT *
            FROM whatsapp_cloud_configuracoes
            WHERE empresa_id = :empresa_id
        """),
        {"empresa_id": empresa_id}
    ).mappings().first()

    if linha:
        dados = dict(linha)
        stored = dados.get("access_token") or ""
        try:
            plain = decrypt_secret(stored)
        except SecretProtectionError:
            LOGGER.exception("Token WhatsApp inválido para empresa %s", empresa_id)
            plain = ""
        if stored and not str(stored).startswith("enc:v1:") and plain:
            db.execute(
                text("UPDATE whatsapp_cloud_configuracoes SET access_token = :token WHERE empresa_id = :empresa_id"),
                {"token": encrypt_secret(plain), "empresa_id": empresa_id},
            )
            db.commit()
        dados["access_token"] = plain
        dados["access_token_configurado"] = bool(plain)
        return dados

    agora = agora_brasilia()

    db.execute(
        text("""
            INSERT INTO whatsapp_cloud_configuracoes
                (empresa_id, ativo, plano_ativo, template_idioma, limite_mensal, mensagens_enviadas_mes, criado_em, atualizado_em)
            VALUES
                (:empresa_id, 0, 0, 'en_US', 500, 0, :agora, :agora)
        """),
        {"empresa_id": empresa_id, "agora": agora}
    )

    db.commit()

    linha = db.execute(
        text("""
            SELECT *
            FROM whatsapp_cloud_configuracoes
            WHERE empresa_id = :empresa_id
        """),
        {"empresa_id": empresa_id}
    ).mappings().first()

    dados = dict(linha)
    dados["access_token"] = ""
    dados["access_token_configurado"] = False
    return dados


def salvar_whatsapp_cloud_config(db, empresa_id: int, formulario):
    preparar_tabelas_whatsapp_cloud()
    obter_whatsapp_cloud_config(db, empresa_id)

    def valor(nome, padrao=""):
        return str(formulario.get(nome, padrao) or "").strip()

    def inteiro(nome, padrao=0):
        try:
            return int(valor(nome, padrao))
        except Exception:
            return padrao

    config_atual = obter_whatsapp_cloud_config(db, empresa_id)
    ativo = 1 if valor("wa_auto_ativo") == "1" else 0
    plano_ativo = 1 if valor("wa_auto_plano_ativo") == "1" else 0
    access_token_final = valor("wa_access_token") or str(config_atual.get("access_token") or "").strip()
    access_token_armazenado = encrypt_secret(access_token_final) if access_token_final else ""

    db.execute(
        text("""
            UPDATE whatsapp_cloud_configuracoes
            SET ativo = :ativo,
                plano_ativo = :plano_ativo,
                phone_number_id = :phone_number_id,
                business_account_id = :business_account_id,
                access_token = :access_token,
                template_pedido_recebido = :template_pedido_recebido,
                template_pedido_em_preparo = :template_pedido_em_preparo,
                template_pronto_retirada = :template_pronto_retirada,
                template_saiu_entrega = :template_saiu_entrega,
                template_reserva_confirmada = :template_reserva_confirmada,
                template_lembrete_reserva = :template_lembrete_reserva,
                template_idioma = :template_idioma,
                modo_envio = :modo_envio,
                limite_mensal = :limite_mensal,
                status_comercial = :status_comercial,
                valor_mensal = :valor_mensal,
                inclui_mensagens = :inclui_mensagens,
                observacao_suporte = :observacao_suporte,
                atualizado_em = :agora
            WHERE empresa_id = :empresa_id
        """),
        {
            "empresa_id": empresa_id,
            "ativo": ativo,
            "plano_ativo": plano_ativo,
            "phone_number_id": valor("wa_phone_number_id"),
            "business_account_id": valor("wa_business_account_id"),
            "access_token": access_token_armazenado,
            "modo_envio": valor("wa_modo_envio", config_atual.get("modo_envio") or "teste") or "teste",
            "template_pedido_recebido": valor("wa_template_pedido_recebido", "hello_world") or "hello_world",
            "template_pedido_em_preparo": valor("wa_template_pedido_em_preparo", "hello_world") or "hello_world",
            "template_pronto_retirada": valor("wa_template_pronto_retirada", "hello_world") or "hello_world",
            "template_saiu_entrega": valor("wa_template_saiu_entrega", "hello_world") or "hello_world",
            "template_reserva_confirmada": valor("wa_template_reserva_confirmada", "hello_world") or "hello_world",
            "template_lembrete_reserva": valor("wa_template_lembrete_reserva", "hello_world") or "hello_world",
            "template_idioma": valor("wa_template_idioma", "en_US") or "en_US",
            "limite_mensal": inteiro("wa_limite_mensal", 500),
            "status_comercial": valor("wa_status_comercial", "nao_contratado") or "nao_contratado",
            "valor_mensal": float(valor("wa_valor_mensal", "25").replace(",", ".") or 25),
            "inclui_mensagens": inteiro("wa_inclui_mensagens", 500),
            "observacao_suporte": valor("wa_observacao_suporte", ""),
            "agora": agora_brasilia()
        }
    )


def listar_whatsapp_cloud_logs(db, empresa_id: int, limite: int = 8):
    preparar_tabelas_whatsapp_cloud()

    try:
        return db.execute(
            text("""
                SELECT id, destino, evento, template, status, mensagem, criado_em
                FROM whatsapp_cloud_logs
                WHERE empresa_id = :empresa_id
                ORDER BY id DESC
                LIMIT :limite
            """),
            {"empresa_id": empresa_id, "limite": limite}
        ).mappings().all()
    except Exception:
        return []


def registrar_whatsapp_cloud_log(db, empresa_id: int, destino: str, evento: str, template: str, status: str, mensagem: str, resposta=None):
    preparar_tabelas_whatsapp_cloud()

    try:
        db.execute(
            text("""
                INSERT INTO whatsapp_cloud_logs
                    (empresa_id, destino, evento, template, status, mensagem, resposta, criado_em)
                VALUES
                    (:empresa_id, :destino, :evento, :template, :status, :mensagem, :resposta, :criado_em)
            """),
            {
                "empresa_id": empresa_id,
                "destino": destino or "",
                "evento": evento or "",
                "template": template or "",
                "status": status or "",
                "mensagem": mensagem or "",
                "resposta": json.dumps(resposta, ensure_ascii=False)[:5000] if isinstance(resposta, (dict, list)) else str(resposta or "")[:5000],
                "criado_em": agora_brasilia()
            }
        )
    except Exception:
        pass


def normalizar_telefone_whatsapp(numero: str):
    numero = str(numero or "").strip()
    numero = numero.replace("+", "")
    numero = re.sub(r"\D", "", numero)
    return numero


def enviar_template_whatsapp_cloud(config: dict, destino: str, template_nome: str, idioma: str = "en_US", parametros_body: list | None = None):
    phone_number_id = str(config.get("phone_number_id") or "").strip()
    token = str(config.get("access_token") or "").strip()
    destino = normalizar_telefone_whatsapp(destino)
    template_nome = str(template_nome or "hello_world").strip()
    idioma = str(idioma or "en_US").strip()

    if not phone_number_id:
        return False, "Phone Number ID não configurado.", {}

    if not token:
        return False, "Token da Meta não configurado.", {}

    if not destino:
        return False, "Telefone de destino inválido.", {}

    payload = {
        "messaging_product": "whatsapp",
        "to": destino,
        "type": "template",
        "template": {
            "name": template_nome,
            "language": {
                "code": idioma
            }
        }
    }

    parametros_body = [str(valor if valor is not None else "-") for valor in (parametros_body or [])]
    if parametros_body:
        payload["template"]["components"] = [
            {
                "type": "body",
                "parameters": [
                    {"type": "text", "text": valor[:1024]}
                    for valor in parametros_body
                ]
            }
        ]

    url = f"https://graph.facebook.com/v20.0/{phone_number_id}/messages"
    dados = json.dumps(payload).encode("utf-8")

    req = urllib.request.Request(
        url=url,
        data=dados,
        method="POST",
        headers={
            "Authorization": f"Bearer {token}",
            "Content-Type": "application/json"
        }
    )

    try:
        with urllib.request.urlopen(req, timeout=20) as response:
            body = response.read().decode("utf-8")
            resposta = json.loads(body or "{}")
            return True, "Mensagem enviada com sucesso.", resposta
    except urllib.error.HTTPError as erro:
        body = erro.read().decode("utf-8", errors="ignore")
        try:
            resposta = json.loads(body)
        except Exception:
            resposta = {"raw": body}
        return False, f"Erro Meta {erro.code}: {resposta}", resposta
    except Exception as erro:
        return False, str(erro), {}


@app.post("/admin/{empresa_id}/configuracoes/whatsapp/teste")
async def testar_whatsapp_cloud_empresa(empresa_id: int, request: Request):
    exigir_admin_empresa_api(request, empresa_id)

    dados = await request.json()

    db = SessionLocal()
    empresa = db.query(Empresa).filter(Empresa.id == empresa_id).first()

    if not empresa:
        db.close()
        return {"ok": False, "message": "Empresa não encontrada."}

    config = obter_whatsapp_cloud_config(db, empresa_id)

    destino = dados.get("destino") or dados.get("telefone") or ""
    evento = dados.get("evento") or "teste"
    template = dados.get("template") or config.get("template_pedido_em_preparo") or "hello_world"
    idioma = dados.get("idioma") or config.get("template_idioma") or "en_US"

    sucesso, mensagem, resposta = enviar_template_whatsapp_cloud(
        config=config,
        destino=destino,
        template_nome=template,
        idioma=idioma
    )

    registrar_whatsapp_cloud_log(
        db=db,
        empresa_id=empresa_id,
        destino=normalizar_telefone_whatsapp(destino),
        evento=evento,
        template=template,
        status="sucesso" if sucesso else "erro",
        mensagem=mensagem,
        resposta=resposta
    )

    if sucesso:
        try:
            db.execute(
                text("""
                    UPDATE whatsapp_cloud_configuracoes
                    SET mensagens_enviadas_mes = COALESCE(mensagens_enviadas_mes, 0) + 1,
                        excedentes_mes = CASE
                            WHEN COALESCE(mensagens_enviadas_mes, 0) + 1 > COALESCE(limite_mensal, 500)
                            THEN COALESCE(mensagens_enviadas_mes, 0) + 1 - COALESCE(limite_mensal, 500)
                            ELSE 0
                        END
                    WHERE empresa_id = :empresa_id
                """),
                {"empresa_id": empresa_id}
            )
        except Exception:
            pass

    db.commit()
    db.close()

    return {
        "ok": sucesso,
        "message": mensagem,
        "response": resposta
    }


