def whatsapp_config_ativo_para_envio(config: dict):
    if not config:
        return False, "Configuração de WhatsApp não encontrada."

    status = str(config.get("status_comercial") or "").strip().lower()
    if status not in {"ativo", "teste", "em_teste"} and not config.get("plano_ativo"):
        return False, "WhatsApp não está contratado/ativo."

    if not config.get("ativo"):
        return False, "Envio automático do WhatsApp está desativado."

    limite = int(config.get("limite_mensal") or 0)
    usadas = int(config.get("mensagens_enviadas_mes") or 0)
    if limite > 0 and usadas >= limite:
        return False, "Limite mensal de mensagens atingido."

    return True, "OK"




def validar_whatsapp_producao_real(config: dict):
    """Valida se a configuração está completa antes de ativar produção real."""
    faltando = []

    def vazio(campo):
        valor = str(config.get(campo) or "").strip()
        return not valor

    obrigatorios = {
        "phone_number_id": "Phone Number ID real",
        "business_account_id": "Business Account ID / WABA ID real",
        "access_token": "token permanente",
        "template_idioma": "idioma dos templates",
        "template_pedido_recebido": "template pedido recebido",
        "template_pedido_em_preparo": "template pedido em preparo",
        "template_pronto_retirada": "template pronto para retirada",
        "template_saiu_entrega": "template saiu para entrega",
        "template_reserva_confirmada": "template reserva confirmada",
    }

    for campo, nome in obrigatorios.items():
        if vazio(campo):
            faltando.append(nome)

    limite = int(config.get("limite_mensal") or 0)
    if limite <= 0:
        faltando.append("limite mensal")

    templates_teste = {WHATSAPP_TEST_TEMPLATE, "hello_world"}
    for campo in [
        "template_pedido_recebido",
        "template_pedido_em_preparo",
        "template_pronto_retirada",
        "template_saiu_entrega",
        "template_reserva_confirmada",
    ]:
        if str(config.get(campo) or "").strip() in templates_teste:
            faltando.append("templates reais aprovados na Meta")
            break

    if faltando:
        return False, "Produção real incompleta: " + ", ".join(dict.fromkeys(faltando))

    return True, "Produção real pronta."

def normalizar_status_whatsapp(status: str) -> str:
    """Normaliza status vindos do painel para evitar juntar etapas diferentes."""
    status = str(status or "").strip().lower()
    status = status.replace("_", "-")
    status = re.sub(r"\s+", " ", status)
    return status


def template_whatsapp_para_evento(config: dict, tipo: str, status: str):
    status = normalizar_status_whatsapp(status)
    tipo = str(tipo or "").strip().lower()

    if tipo == "pedido":
        mapa = {
            # 1) Pedido recebido
            "novo": "template_pedido_recebido",
            "pedido recebido": "template_pedido_recebido",
            "recebido": "template_pedido_recebido",
            "criado": "template_pedido_recebido",

            # 2) Pedido em preparo
            "em preparo": "template_pedido_em_preparo",
            "preparo": "template_pedido_em_preparo",
            "pedido em preparo": "template_pedido_em_preparo",
            "aceito": "template_pedido_em_preparo",

            # 3A) Retirada no local
            "pronto": "template_pronto_retirada",
            "pedido pronto": "template_pronto_retirada",
            "pronto para retirada": "template_pronto_retirada",
            "pedido pronto para retirada": "template_pronto_retirada",
            "retirada": "template_pronto_retirada",

            # 3B) Delivery/entrega
            "entrega": "template_saiu_entrega",
            "saiu para entrega": "template_saiu_entrega",
            "pedido saiu para entrega": "template_saiu_entrega",
            "enviado": "template_saiu_entrega",
            "enviado para entrega": "template_saiu_entrega",
        }
    else:
        mapa = {
            "confirmada": "template_reserva_confirmada",
            "confirmado": "template_reserva_confirmada",
            "reserva confirmada": "template_reserva_confirmada",
            "lembrete": "template_lembrete_reserva",
            "lembrete reserva": "template_lembrete_reserva",
        }

    campo = mapa.get(status)
    if not campo:
        return None

    return str(config.get(campo) or WHATSAPP_TEST_TEMPLATE or "hello_world").strip() or "hello_world"


def registrar_incremento_whatsapp(db, empresa_id: int):
    db.execute(
        text("""
            UPDATE whatsapp_cloud_configuracoes
            SET mensagens_enviadas_mes = COALESCE(mensagens_enviadas_mes, 0) + 1,
                excedentes_mes = CASE
                    WHEN COALESCE(mensagens_enviadas_mes, 0) + 1 > COALESCE(limite_mensal, 500)
                    THEN COALESCE(mensagens_enviadas_mes, 0) + 1 - COALESCE(limite_mensal, 500)
                    ELSE 0
                END,
                atualizado_em = :agora
            WHERE empresa_id = :empresa_id
        """),
        {"empresa_id": empresa_id, "agora": agora_brasilia()}
    )


def moeda_whatsapp(valor):
    try:
        return f"{float(valor or 0):.2f}".replace(".", ",")
    except Exception:
        return "0,00"


def montar_parametros_whatsapp(tipo: str, status_evento: str, contexto: dict | None):
    """Monta parâmetros na mesma ordem dos templates de produção listados no README v182.
    Templates teste hello_world não usam parâmetros.
    """
    contexto = contexto or {}
    tipo = str(tipo or "").strip().lower()
    status = normalizar_status_whatsapp(status_evento)

    nome_cliente = str(contexto.get("nome_cliente") or "Cliente").strip() or "Cliente"
    empresa_nome = str(contexto.get("empresa_nome") or "nossa empresa").strip() or "nossa empresa"

    if tipo == "pedido":
        pedido_id = str(contexto.get("pedido_id") or contexto.get("codigo") or "-").strip() or "-"
        total = moeda_whatsapp(contexto.get("total"))

        if status in {"novo", "pedido recebido", "recebido", "criado"}:
            # {{1}} cliente, {{2}} pedido, {{3}} empresa, {{4}} total
            return [nome_cliente, pedido_id, empresa_nome, total]

        if status in {"em preparo", "preparo", "pedido em preparo", "aceito"}:
            # {{1}} cliente, {{2}} pedido, {{3}} empresa
            return [nome_cliente, pedido_id, empresa_nome]

        if status in {"pronto", "pedido pronto", "pronto para retirada", "pedido pronto para retirada", "retirada"}:
            # {{1}} cliente, {{2}} pedido, {{3}} empresa
            return [nome_cliente, pedido_id, empresa_nome]

        if status in {"entrega", "saiu para entrega", "pedido saiu para entrega", "enviado", "enviado para entrega"}:
            # {{1}} cliente, {{2}} pedido, {{3}} empresa
            return [nome_cliente, pedido_id, empresa_nome]

    if tipo == "reserva":
        data = str(contexto.get("data") or "-").strip() or "-"
        horario = str(contexto.get("horario") or "-").strip() or "-"
        codigo = str(contexto.get("codigo") or "-").strip() or "-"

        if status in {"confirmada", "confirmado", "reserva confirmada"}:
            # {{1}} cliente, {{2}} empresa, {{3}} data, {{4}} horário, {{5}} código
            return [nome_cliente, empresa_nome, data, horario, codigo]

        if status in {"lembrete", "lembrete reserva"}:
            # {{1}} cliente, {{2}} empresa, {{3}} data, {{4}} horário
            return [nome_cliente, empresa_nome, data, horario]

    return []


def enviar_whatsapp_automatico_evento(db, empresa_id: int, destino: str, tipo: str, status_evento: str, contexto: dict | None = None):
    """Envia WhatsApp automaticamente quando pedido/reserva muda de status."""
    try:
        preparar_colunas_whatsapp_v164()
        config = obter_whatsapp_cloud_config(db, empresa_id)

        pode_enviar, motivo = whatsapp_config_ativo_para_envio(config)
        if not pode_enviar:
            registrar_whatsapp_cloud_log(
                db=db,
                empresa_id=empresa_id,
                destino=normalizar_telefone_whatsapp(destino),
                evento=f"{tipo}:{status_evento}",
                template="",
                status="ignorado",
                mensagem=motivo
            )
            return False, motivo

        template = template_whatsapp_para_evento(config, tipo, status_evento)
        if not template:
            registrar_whatsapp_cloud_log(
                db=db,
                empresa_id=empresa_id,
                destino=normalizar_telefone_whatsapp(destino),
                evento=f"{tipo}:{status_evento}",
                template="",
                status="ignorado",
                mensagem="Status sem notificação configurada. Nenhuma mensagem enviada."
            )
            return False, "Status sem notificação configurada."

        idioma = str(config.get("template_idioma") or WHATSAPP_TEST_TEMPLATE_LANG or "en_US").strip()

        modo_envio = str(config.get("modo_envio") or "teste").strip().lower()
        parametros = []
        if modo_envio == "producao" and template != WHATSAPP_TEST_TEMPLATE:
            parametros = montar_parametros_whatsapp(tipo, status_evento, contexto)

        sucesso, mensagem, resposta = enviar_template_whatsapp_cloud(
            config=config,
            destino=destino,
            template_nome=template,
            idioma=idioma,
            parametros_body=parametros
        )

        registrar_whatsapp_cloud_log(
            db=db,
            empresa_id=empresa_id,
            destino=normalizar_telefone_whatsapp(destino),
            evento=f"{tipo}:{status_evento}",
            template=template,
            status="sucesso" if sucesso else "erro",
            mensagem=mensagem,
            resposta=resposta
        )

        if sucesso:
            registrar_incremento_whatsapp(db, empresa_id)

        return sucesso, mensagem
    except Exception as erro:
        try:
            registrar_whatsapp_cloud_log(
                db=db,
                empresa_id=empresa_id,
                destino=normalizar_telefone_whatsapp(destino),
                evento=f"{tipo}:{status_evento}",
                template="",
                status="erro",
                mensagem=f"Erro interno ao enviar WhatsApp: {erro}"
            )
        except Exception:
            pass
        return False, str(erro)


@app.post("/admin-saas/whatsapp/{empresa_id}/ativar-teste-meta")
async def ativar_teste_meta_whatsapp_saas(empresa_id: int, request: Request):
    redirecionamento = redirecionar_saas_login_se_necessario(request)
    if redirecionamento:
        return redirecionamento

    formulario = await request.form()
    token = str(formulario.get("wa_access_token_teste", "") or "").strip()

    db = SessionLocal()
    try:
        empresa = db.query(Empresa).filter(Empresa.id == empresa_id).first()
        if not empresa:
            db.close()
            return RedirectResponse(url="/admin-saas/whatsapp?erro=empresa_nao_encontrada", status_code=303)

        # V184: usa apenas parâmetros nomeados no SQL interno.
        # Isso evita o erro do SQLAlchemy quando o SQLite recebe '?' com dicionário.
        aplicar_modo_teste_meta_whatsapp(db, empresa_id, token)
        db.commit()
        db.close()
        return RedirectResponse(url="/admin-saas/whatsapp?sucesso=ambiente_teste_interno_ativo", status_code=303)
    except Exception as erro:
        db.rollback()
        db.close()
        print("ERRO AO ATIVAR AMBIENTE DE TESTE INTERNO:", repr(erro))
        return RedirectResponse(url="/admin-saas/whatsapp?erro=ambiente_teste_interno", status_code=303)


@app.post("/admin-saas/whatsapp/{empresa_id}/aplicar-producao")
async def aplicar_templates_producao_whatsapp_saas(empresa_id: int, request: Request):
    redirecionamento = redirecionar_saas_login_se_necessario(request)
    if redirecionamento:
        return redirecionamento

