@app.post("/admin-saas/whatsapp/{empresa_id}/teste-envio")
async def testar_envio_whatsapp_saas(empresa_id: int, request: Request):
    redirecionamento = redirecionar_saas_login_se_necessario(request)
    if redirecionamento:
        return redirecionamento

    formulario = await request.form()
    destino = str(formulario.get("wa_teste_destino", "") or "").strip()
    token_form = (
        str(formulario.get("wa_access_token_teste", "") or "").strip()
        or str(formulario.get("wa_access_token", "") or "").strip()
    )

    db = SessionLocal()
    preparar_colunas_whatsapp_v164()
    obter_whatsapp_cloud_config(db, empresa_id)

    # Se o token veio no formulário, reativa o modo teste antes de enviar.
    # Isso evita o caso em que o token sumiu visualmente ou não foi salvo antes do teste.
    if token_form:
        aplicar_modo_teste_meta_whatsapp(db, empresa_id, token_form)
        db.commit()

    config = obter_whatsapp_cloud_config(db, empresa_id)

    if not destino:
        destino = str(config.get("responsavel_telefone") or config.get("numero_whatsapp_empresa") or "").strip()

    template = str(config.get("template_pedido_recebido") or config.get("template_pedido_em_preparo") or "hello_world")
    idioma = str(config.get("template_idioma") or "en_US")

    sucesso, mensagem, resposta = enviar_template_whatsapp_cloud(
        config=config,
        destino=destino,
        template_nome=template,
        idioma=idioma
    )

    registrar_whatsapp_cloud_log(
        db=db,
        empresa_id=empresa_id,
        destino=normalizar_telefone_whatsapp(destino),
        evento="teste_manual_saas",
        template=template,
        status="sucesso" if sucesso else "erro",
        mensagem=mensagem,
        resposta=resposta
    )

    if sucesso:
        registrar_incremento_whatsapp(db, empresa_id)

    db.commit()
    db.close()

    if sucesso:
        return RedirectResponse(url="/admin-saas/whatsapp?sucesso=teste_enviado", status_code=303)

    detalhe = str(mensagem or "Erro no teste")[:180].replace("&", "e").replace("?", " ").replace("#", " ")
    return RedirectResponse(url=f"/admin-saas/whatsapp?erro=teste_erro&detalhe={detalhe}", status_code=303)


