def preparar_colunas_whatsapp_v163():
    preparar_tabelas_whatsapp_cloud()

    try:
        conn = engine.raw_connection()
        cursor = conn.cursor()

        cursor.execute("PRAGMA table_info(whatsapp_cloud_configuracoes)")
        colunas = [linha[1] for linha in cursor.fetchall()]

        novas_colunas = {
            "status_comercial": "TEXT DEFAULT 'nao_contratado'",
            "solicitado_em": "DATETIME",
            "ativado_em": "DATETIME",
            "valor_mensal": "FLOAT DEFAULT 25",
            "inclui_mensagens": "INTEGER DEFAULT 500",
            "excedentes_mes": "INTEGER DEFAULT 0",
            "observacao_suporte": "TEXT",
            "template_pedido_recebido": "TEXT DEFAULT 'hello_world'",
            "template_lembrete_reserva": "TEXT DEFAULT 'hello_world'"
        }

        for nome, definicao in novas_colunas.items():
            if nome not in colunas:
                cursor.execute(f"ALTER TABLE whatsapp_cloud_configuracoes ADD COLUMN {nome} {definicao}")

        conn.commit()
        conn.close()
    except Exception:
        pass


def obter_status_whatsapp_v163(config):
    if not config:
        return "nao_contratado"

    status = str(config.get("status_comercial") or "").strip()

    if status:
        return status

    if config.get("plano_ativo"):
        return "ativo"

    return "nao_contratado"


