@app.post("/admin/{empresa_id}/configuracoes")
async def salvar_configuracoes_empresa(empresa_id: int, request: Request):
    redirecionamento = redirecionar_login_se_necessario(request, empresa_id)
    if redirecionamento:
        return redirecionamento

    formulario = await request.form()
    db = SessionLocal()

    empresa = db.query(Empresa).filter(
        Empresa.id == empresa_id
    ).first()

    if not empresa:
        db.close()
        return {"error": "Empresa não encontrada"}

    # Apenas dados públicos usados no menu público
    empresa.nome = str(formulario.get("nome", "")).strip() or empresa.nome
    empresa.tipo = str(formulario.get("tipo", "")).strip() or empresa.tipo
    empresa.email = str(formulario.get("email", "")).strip() or None
    empresa.telefone_whatsapp = str(formulario.get("telefone_whatsapp", "")).strip() or None
    empresa.telefone_fixo = str(formulario.get("telefone_fixo", "")).strip() or None
    empresa.telefone_secundario = str(formulario.get("telefone_secundario", "")).strip() or None
    empresa.endereco = str(formulario.get("endereco", "")).strip() or None
    empresa.cidade = str(formulario.get("cidade", "")).strip() or None
    empresa.pais = str(formulario.get("pais", "")).strip() or "Italia"
    # v776: localização pública reaproveita os campos fiscais já existentes,
    # evitando criar colunas paralelas apenas para CEP/número/bairro/UF.
    if "cep_fiscal" in formulario:
        empresa.cep_fiscal = str(formulario.get("cep_fiscal", "")).strip() or None
    if "numero_fiscal" in formulario:
        empresa.numero_fiscal = str(formulario.get("numero_fiscal", "")).strip() or None
    if "complemento_fiscal" in formulario:
        empresa.complemento_fiscal = str(formulario.get("complemento_fiscal", "")).strip() or None
    if "bairro_fiscal" in formulario:
        empresa.bairro_fiscal = str(formulario.get("bairro_fiscal", "")).strip() or None
    if "uf_fiscal" in formulario:
        empresa.uf_fiscal = str(formulario.get("uf_fiscal", "")).strip().upper()[:2] or None
    empresa.instagram = str(formulario.get("instagram", "")).strip() or None
    empresa.facebook = str(formulario.get("facebook", "")).strip() or None
    empresa.logo_url = str(formulario.get("logo_url", "")).strip() or None
    empresa.descricao = str(formulario.get("descricao", "")).strip() or None

    idioma = normalizar_idioma(formulario.get("idioma") or formulario.get("idioma_principal") or getattr(empresa, "idioma", "pt"))
    salvar_idioma_empresa_sql(db, empresa, idioma)

    salvar_hero_empresa_sqlite(db, empresa_id, formulario)
    salvar_menu_configuracoes(db, empresa_id, formulario)
    # v817: "Nossa história" é uma configuração comum a todos os segmentos.
    salvar_apresentacao_encomendas(db, empresa_id, formulario)
    salvar_restricao_horarios(db, empresa_id, _bool_formulario(formulario, "restricao_horarios_ativa"))
    salvar_horarios_funcionamento(db, empresa_id, formulario)

    campos_impressao = {
        "impressao_modo", "impressao_conexao", "impressao_largura",
        "impressora_nome", "impressora_ip", "impressora_porta",
        "impressora_porta_serial", "impressora_baud_rate", "impressora_modelo",
        "qz_ativo", "impressao_automatica", "imprimir_comanda",
        "imprimir_recibo", "imprimir_entregador"
    }
    if any(campo in formulario for campo in campos_impressao):
        salvar_impressao_config(db, empresa_id, formulario)

    campos_whatsapp_cloud = {
        "wa_auto_ativo", "wa_auto_plano_ativo", "wa_phone_number_id",
        "wa_business_account_id", "wa_access_token", "wa_modo_envio",
        "wa_template_pedido_recebido", "wa_template_pedido_em_preparo",
        "wa_template_pronto_retirada", "wa_template_saiu_entrega",
        "wa_template_reserva_confirmada", "wa_template_lembrete_reserva",
        "wa_template_idioma", "wa_limite_mensal", "wa_status_comercial",
        "wa_valor_mensal", "wa_inclui_mensagens", "wa_observacao_suporte"
    }
    if any(campo in formulario for campo in campos_whatsapp_cloud):
        salvar_whatsapp_cloud_config(db, empresa_id, formulario)

    db.commit()
    db.close()

    return RedirectResponse(
        url=f"/admin/{empresa_id}/configuracoes",
        status_code=303
    )


@app.get("/admin/{empresa_id}/configuracoes")
def admin_configuracoes(empresa_id: int, request: Request):
    redirecionamento = redirecionar_area_admin_se_necessario(request, empresa_id, "configuracoes")
    if redirecionamento:
        return redirecionamento
    db = SessionLocal()

    empresa = db.query(Empresa).filter(
        Empresa.id == empresa_id
    ).first()

    if not empresa:
        db.close()
        return {"error": "Empresa não encontrada"}

    anexar_idioma_empresa(db, empresa)

    anexar_hero_empresa(db, empresa)
    menu_config = obter_menu_configuracoes(db, empresa_id)
    # v817: editor "Nossa história" disponível em todos os tipos de negócio
    encomendas_apresentacao = obter_apresentacao_encomendas(db, empresa_id)
    horarios_funcionamento = obter_horarios_funcionamento(db, empresa_id)
    restricao_horarios_ativa = obter_restricao_horarios_ativa(db, empresa_id)
    impressao_config = obter_impressao_config(db, empresa_id)
    preparar_colunas_whatsapp_v164()
    whatsapp_cloud_config = obter_whatsapp_cloud_config(db, empresa_id)
    whatsapp_cloud_logs = listar_whatsapp_cloud_logs(db, empresa_id)
    whatsapp_status_comercial = obter_status_whatsapp_v163(whatsapp_cloud_config)

    # V162: obter_whatsapp_cloud_config pode criar a configuração inicial e dar commit.
    # O commit expira o objeto Empresa no SQLAlchemy; se fecharmos a sessão antes do render,
    # o template tenta acessar empresa.nome e gera DetachedInstanceError.
    # Recarregamos os atributos antes de fechar.
    db.refresh(empresa)

    db.close()

    return templates.TemplateResponse(
        request=request,
        name="admin_configuracoes.html",
        context={
            "empresa": empresa,
            "menu_config": menu_config,
            "encomendas_apresentacao": encomendas_apresentacao,
            "horarios_funcionamento": horarios_funcionamento,
            "restricao_horarios_ativa": restricao_horarios_ativa,
            "impressao_config": impressao_config,
            "whatsapp_cloud_config": whatsapp_cloud_config,
            "whatsapp_cloud_logs": whatsapp_cloud_logs,
            "whatsapp_status_comercial": whatsapp_status_comercial
        }
    )


