@app.get("/admin/{empresa_id}/funcionarios")
def admin_funcionarios(empresa_id: int, request: Request):
    redirecionamento = redirecionar_area_admin_se_necessario(request, empresa_id, "funcionarios")
    if redirecionamento:
        return redirecionamento

    db = SessionLocal()

    empresa = db.query(Empresa).filter(Empresa.id == empresa_id).first()
    if not empresa:
        db.close()
        return {"error": "Empresa não encontrada"}

    anexar_idioma_empresa(db, empresa)

    usuarios = db.query(UsuarioAdmin).filter(
        UsuarioAdmin.empresa_id == empresa_id
    ).order_by(UsuarioAdmin.id.asc()).all()

    cargos_visuais = ler_cargos_funcionarios(empresa_id)

    for usuario in usuarios:
        perfil_atual = getattr(usuario, "perfil", "administrador")
        cargo_visual = cargos_visuais.get(int(usuario.id), {})
        setattr(usuario, "perfil_label", label_perfil_funcionario(perfil_atual))
        setattr(usuario, "cargo_nome", cargo_visual.get("cargo_nome") or label_perfil_funcionario(perfil_atual))
        setattr(usuario, "cargo_icone", normalizar_cargo_icone(cargo_visual.get("cargo_icone") or ("fa-crown" if perfil_atual == "administrador" else "fa-user")))
        usuario_permissoes = permissoes_do_usuario(usuario)
        setattr(usuario, "permissoes_set", usuario_permissoes)
        setattr(usuario, "permissoes_label", ", ".join([nome for chave, nome in PERMISSOES_FUNCIONARIOS.items() if chave in usuario_permissoes]))

    sucesso_msg = None
    erro_msg = None
    status = request.query_params.get("status")
    if status == "criado":
        sucesso_msg = "Acesso criado com sucesso."
    elif status == "atualizado":
        sucesso_msg = "Funcionário atualizado com sucesso."
    elif status == "senha_atualizada":
        sucesso_msg = "Senha atualizada com sucesso."
    elif status == "excluido":
        sucesso_msg = "Funcionário excluído com sucesso."
    elif status == "email_em_uso":
        erro_msg = "Este e-mail já está em uso."
    elif status == "dados_invalidos":
        erro_msg = "Preencha os campos obrigatórios."
    elif status == "usuario_nao_encontrado":
        erro_msg = "Funcionário não encontrado."
    elif status == "nao_pode_excluir_voce":
        erro_msg = "Você não pode excluir o próprio acesso enquanto está logado."
    elif status == "nao_pode_rebaixar_voce":
        erro_msg = "Você não pode remover seu próprio perfil de Administrador enquanto está logado."
    elif status == "sem_permissao":
        erro_msg = "Você não possui permissão para alterar este acesso."
    elif status == "limite_funcionarios":
        controle_saas = obter_controles_saas_empresa(db, empresa_id)
        uso_saas = contar_funcionarios_saas(db, empresa_id)
        erro_msg = f"Limite de funcionários atingido ({uso_saas}/{controle_saas['limite_funcionarios']}). Entre em contato com o suporte para ampliar."
    elif status == "cadastro_funcionarios_bloqueado":
        erro_msg = "O cadastro de novos funcionários foi bloqueado pelo administrador do MenuFacile."

    admin_user_id = usuario_admin_sessao(request)
    db.close()

    return templates.TemplateResponse(
        request=request,
        name="admin_funcionarios.html",
        context={
            "empresa": empresa,
            "usuarios": usuarios,
            "sucesso": sucesso_msg,
            "erro": erro_msg,
            "perfis_funcionarios": PERFIS_FUNCIONARIOS,
            "permissoes_funcionarios": PERMISSOES_FUNCIONARIOS,
            "permissoes_funcionarios_icones": PERMISSOES_FUNCIONARIOS_ICONES,
            "permissoes_funcionarios_descricoes": PERMISSOES_FUNCIONARIOS_DESCRICOES,
            "permissoes_padrao_funcionario": PERMISSOES_PADRAO_FUNCIONARIO,
            "funcionario_icones": sorted(FUNCIONARIO_ICONES_PERMITIDOS),
            "admin_user_id": admin_user_id
        }
    )


@app.post("/admin/{empresa_id}/funcionarios/criar")
async def criar_funcionario_acesso(empresa_id: int, request: Request):
    redirecionamento = redirecionar_area_admin_se_necessario(request, empresa_id, "funcionarios")
    if redirecionamento:
        return redirecionamento

    formulario = await request.form()
    nome = str(formulario.get("nome", "")).strip()
    email = str(formulario.get("email", "")).strip().lower()
    senha = str(formulario.get("senha", ""))
    perfil = normalizar_perfil_funcionario(str(formulario.get("perfil", "atendente")))
    cargo_nome = normalizar_cargo_nome(str(formulario.get("cargo_nome", "")), perfil)
    cargo_icone = normalizar_cargo_icone(str(formulario.get("cargo_icone", "fa-user")))
    permissoes = permissoes_padrao_para_perfil(perfil) if perfil == "administrador" else limpar_permissoes(formulario.getlist("permissoes"))
    if not sessao_admin_total(request):
        perfil = "atendente"
        permissoes &= permissoes_admin_sessao(request)

    if not nome or not email or not senha:
        return RedirectResponse(
            url=f"/admin/{empresa_id}/funcionarios?status=dados_invalidos",
            status_code=303
        )

    db = SessionLocal()

    empresa = db.query(Empresa).filter(Empresa.id == empresa_id).first()
    if not empresa:
        db.close()
        return {"error": "Empresa não encontrada"}

    permitido_saas, mensagem_saas, codigo_saas = validar_novo_funcionario_saas(db, empresa_id)
    if not permitido_saas:
        db.close()
        status_limite = "cadastro_funcionarios_bloqueado" if codigo_saas == 403 else "limite_funcionarios"
        return RedirectResponse(
            url=f"/admin/{empresa_id}/funcionarios?status={status_limite}",
            status_code=303
        )

    email_existente = db.query(UsuarioAdmin).filter(
        UsuarioAdmin.email == email
    ).first()

    if email_existente:
        db.close()
        return RedirectResponse(
            url=f"/admin/{empresa_id}/funcionarios?status=email_em_uso",
            status_code=303
        )

    novo_usuario = UsuarioAdmin(
        empresa_id=empresa_id,
        nome=nome,
        email=email,
        senha_hash=gerar_hash_senha(senha),
        perfil=perfil,
        permissoes=serializar_permissoes(permissoes),
        ativo=True
    )

    db.add(novo_usuario)
    db.commit()
    db.refresh(novo_usuario)
    novo_usuario_id = int(novo_usuario.id)
    db.close()

    salvar_cargo_funcionario(novo_usuario_id, cargo_nome, cargo_icone)

    return RedirectResponse(
        url=f"/admin/{empresa_id}/funcionarios?status=criado",
        status_code=303
    )


@app.post("/admin/{empresa_id}/funcionarios/{usuario_id}/editar")
async def editar_funcionario_acesso(empresa_id: int, usuario_id: int, request: Request):
    redirecionamento = redirecionar_area_admin_se_necessario(request, empresa_id, "funcionarios")
    if redirecionamento:
        return redirecionamento

    formulario = await request.form()
    nome = str(formulario.get("nome", "")).strip()
    email = str(formulario.get("email", "")).strip().lower()
    perfil = normalizar_perfil_funcionario(str(formulario.get("perfil", "atendente")))
    cargo_nome = normalizar_cargo_nome(str(formulario.get("cargo_nome", "")), perfil)
    cargo_icone = normalizar_cargo_icone(str(formulario.get("cargo_icone", "fa-user")))
    permissoes = permissoes_padrao_para_perfil(perfil) if perfil == "administrador" else limpar_permissoes(formulario.getlist("permissoes"))
    if not sessao_admin_total(request):
        perfil = "atendente"
        permissoes &= permissoes_admin_sessao(request)

    if not nome or not email:
        return RedirectResponse(
            url=f"/admin/{empresa_id}/funcionarios?status=dados_invalidos",
            status_code=303
        )

    db = SessionLocal()

    usuario = db.query(UsuarioAdmin).filter(
        UsuarioAdmin.id == usuario_id,
        UsuarioAdmin.empresa_id == empresa_id
    ).first()

    if not usuario:
        db.close()
        return RedirectResponse(
            url=f"/admin/{empresa_id}/funcionarios?status=usuario_nao_encontrado",
            status_code=303
        )

    if not sessao_admin_total(request) and usuario_eh_admin_principal(usuario):
        db.close()
        return RedirectResponse(
            url=f"/admin/{empresa_id}/funcionarios?status=sem_permissao",
            status_code=303
        )

    email_existente = db.query(UsuarioAdmin).filter(
        UsuarioAdmin.email == email,
        UsuarioAdmin.id != usuario_id
    ).first()

    if email_existente:
        db.close()
        return RedirectResponse(
            url=f"/admin/{empresa_id}/funcionarios?status=email_em_uso",
            status_code=303
        )

    if (
        usuario_admin_sessao(request) == usuario_id
        and usuario_eh_admin_principal(usuario)
        and perfil != "administrador"
    ):
        db.close()
        return RedirectResponse(
            url=f"/admin/{empresa_id}/funcionarios?status=nao_pode_rebaixar_voce",
            status_code=303
        )

    usuario.nome = nome
    usuario.email = email
    usuario.perfil = perfil
    usuario.permissoes = serializar_permissoes(permissoes)

    db.commit()
    db.close()

    salvar_cargo_funcionario(usuario_id, cargo_nome, cargo_icone)

    return RedirectResponse(
        url=f"/admin/{empresa_id}/funcionarios?status=atualizado",
        status_code=303
    )


