@app.post("/admin/{empresa_id}/entrega-politicas")
async def salvar_entrega_politicas(empresa_id: int, request: Request):
    redirecionamento = redirecionar_area_admin_se_necessario(
        request, empresa_id, "entrega_politicas"
    )
    if redirecionamento:
        return redirecionamento

    formulario = await request.form()
    db = SessionLocal()
    try:
        empresa = db.query(Empresa).filter(Empresa.id == empresa_id).first()
        if not empresa:
            raise HTTPException(status_code=404, detail="Empresa não encontrada")

        negocio_entrega = tipo_negocio_entrega(empresa.tipo)

        def dinheiro_form(campo: str, limite: str = "999999.99") -> float:
            bruto = str(formulario.get(campo) or "0").strip().replace(" ", "")
            if "," in bruto and "." in bruto:
                bruto = bruto.replace(".", "").replace(",", ".")
            else:
                bruto = bruto.replace(",", ".")
            valor = moeda(bruto or 0)
            if valor < 0 or valor > Decimal(limite):
                raise ValueError(f"Valor inválido em {campo.replace('_', ' ')}.")
            return float(valor)

        def inteiro_form(campo: str, padrao: int, limite: int = 1440) -> int:
            bruto = str(formulario.get(campo) or padrao).strip()
            valor = int(bruto)
            if valor < 0 or valor > limite:
                raise ValueError(
                    f"O campo {campo.replace('_', ' ')} deve ficar entre 0 e {limite}."
                )
            return valor

        def numero_form(campo: str, limite: str = "999999.99") -> float:
            bruto = str(formulario.get(campo) or "0").strip().replace(",", ".")
            valor = Decimal(bruto or "0")
            if not valor.is_finite() or valor < 0 or valor > Decimal(limite):
                raise ValueError(f"Valor inválido em {campo.replace('_', ' ')}.")
            return float(valor)

        if negocio_entrega:
            entrega_ativa = formulario.get("entrega_ativa") == "on"
            retirada_ativa = formulario.get("retirada_ativa") == "on"
            if not entrega_ativa and not retirada_ativa:
                raise ValueError("Ative entrega ou retirada para continuar recebendo pedidos.")

            modelo_frete = str(formulario.get("modelo_frete") or "taxa_fixa").strip()
            if modelo_frete not in {"taxa_fixa", "cidade_regiao", "distancia", "whatsapp"}:
                raise ValueError("Modelo de frete inválido.")

            fallback_sem_local = str(
                formulario.get("fallback_sem_local") or "distancia"
            ).strip()
            if fallback_sem_local not in {"distancia", "taxa_fixa", "whatsapp", "bloquear"}:
                raise ValueError("Ação para local não cadastrado inválida.")

            nomes = formulario.getlist("local_nome")
            ufs = formulario.getlist("local_uf")
            cidades = formulario.getlist("local_cidade")
            bairros = formulario.getlist("local_bairro")
            valores = formulario.getlist("local_valor")
            prazos = formulario.getlist("local_prazo")
            minimos = formulario.getlist("local_pedido_minimo")
            ativas = formulario.getlist("local_ativa")
            quantidade_locais = max(
                len(nomes), len(ufs), len(cidades), len(bairros), len(valores),
                len(prazos), len(minimos), len(ativas),
            )
            locais_brutos = []
            for indice in range(quantidade_locais):
                def item(lista, padrao=""):
                    return lista[indice] if indice < len(lista) else padrao

                nome = str(item(nomes)).strip()
                uf = str(item(ufs)).strip()
                cidade = str(item(cidades)).strip()
                bairro = str(item(bairros)).strip()
                valor = str(item(valores)).strip()
                prazo = str(item(prazos)).strip()
                pedido_minimo = str(item(minimos)).strip()
                ativa = str(item(ativas, "1")).strip() != "0"
                linha_vazia = (
                    not any((nome, cidade, bairro, prazo))
                    and moeda(valor or 0) == Decimal("0.00")
                    and moeda(pedido_minimo or 0) == Decimal("0.00")
                )
                if linha_vazia:
                    continue
                locais_brutos.append({
                    "nome": nome,
                    "uf": uf,
                    "cidade": cidade,
                    "bairro": bairro,
                    "valor": valor or 0,
                    "prazo": prazo,
                    "pedido_minimo": pedido_minimo or 0,
                    "ativa": ativa,
                })
            locais_entrega = normalize_shipping_locations(locais_brutos)
            if modelo_frete == "cidade_regiao" and not any(
                local.get("ativa", True) for local in locais_entrega
            ):
                raise ValueError(
                    "Adicione ao menos uma cidade ou bairro ativo para usar esse modelo."
                )

            cep_origem_bruto = str(formulario.get("cep_origem") or "").strip()
            cep_origem = re.sub(r"\D", "", cep_origem_bruto)
            if cep_origem and len(cep_origem) != 8:
                raise ValueError("O CEP de origem deve conter 8 números.")
            usa_distancia = (
                modelo_frete == "distancia"
                or (modelo_frete == "cidade_regiao" and fallback_sem_local == "distancia")
            )
            if usa_distancia and not (
                cep_origem or re.sub(r"\D", "", str(empresa.cep_fiscal or ""))
            ):
                raise ValueError(
                    "Informe o CEP de origem para usar o cálculo por distância."
                )

            empresa.taxa_entrega_padrao = dinheiro_form(
                "taxa_entrega_padrao", "9999.99"
            )
            empresa.tempo_entrega_minutos = inteiro_form(
                "tempo_entrega_minutos", 50
            )
            empresa.tempo_retirada_minutos = inteiro_form(
                "tempo_retirada_minutos", 30
            )

            entrega_config = {
                "entrega_ativa": entrega_ativa,
                "retirada_ativa": retirada_ativa,
                "pedido_minimo_entrega": dinheiro_form("pedido_minimo_entrega"),
                "frete_gratis_acima": dinheiro_form("frete_gratis_acima"),
                "modelo_frete": modelo_frete,
                "locais_entrega": locais_entrega,
                "faixas_cep": [],
                "fallback_sem_local": fallback_sem_local,
                "fallback_sem_faixa": fallback_sem_local,
                "cep_origem": cep_origem,
                "taxa_base_km": dinheiro_form("taxa_base_km", "9999.99"),
                "valor_por_km": dinheiro_form("valor_por_km", "9999.99"),
                "frete_minimo": dinheiro_form("frete_minimo", "9999.99"),
                "frete_maximo": dinheiro_form("frete_maximo", "99999.99"),
                "distancia_maxima_km": numero_form("distancia_maxima_km", "5000"),
                "frete_gratis_limite_km": numero_form(
                    "frete_gratis_limite_km", "5000"
                ),
                "prazo_distancia_dias": inteiro_form(
                    "prazo_distancia_dias", 1, 365
                ),
                "regioes_atendidas": str(
                    formulario.get("regioes_atendidas") or ""
                ).strip()[:5000],
                "mensagem_entrega": str(
                    formulario.get("mensagem_entrega") or ""
                ).strip()[:2000],
                "instrucoes_retirada": str(
                    formulario.get("instrucoes_retirada") or ""
                ).strip()[:2000],
            }
            # Validação final única antes de persistir.
            entrega_config = normalize_shipping_config(entrega_config)
            empresa.entrega_config_json = json.dumps(
                entrega_config, ensure_ascii=False
            )


        politicas = {}
        for tipo in ("privacidade", "entrega", "trocas", "termos"):
            politicas[tipo] = {
                "ativa": formulario.get(f"politica_{tipo}_ativa") == "on",
                "pt": str(formulario.get(f"politica_{tipo}_pt") or "").strip()[:20000],
                "it": str(formulario.get(f"politica_{tipo}_it") or "").strip()[:20000],
                "en": str(formulario.get(f"politica_{tipo}_en") or "").strip()[:20000],
            }
        empresa.politicas_loja_json = json.dumps(politicas, ensure_ascii=False)

        db.commit()
        return RedirectResponse(
            url=f"/admin/{empresa_id}/entrega-politicas?salvo=1",
            status_code=303,
        )
    except HTTPException:
        db.rollback()
        raise
    except Exception as erro:
        db.rollback()
        return RedirectResponse(
            url=f"/admin/{empresa_id}/entrega-politicas?erro={quote_plus(str(erro))}",
            status_code=303,
        )
    finally:
        db.close()


