@app.post("/admin/{empresa_id}/pagamentos-online")
async def salvar_pagamentos_online(empresa_id: int, request: Request):
    redirecionamento = redirecionar_area_admin_se_necessario(request, empresa_id, "pagamentos_online")
    if redirecionamento:
        return redirecionamento

    formulario = await request.form()
    db = SessionLocal()
    try:
        empresa = db.query(Empresa).filter(Empresa.id == empresa_id).first()
        if not empresa:
            raise HTTPException(status_code=404, detail="Empresa não encontrada")

        negocio_servico = tipo_negocio_servico(getattr(empresa, "tipo", ""))
        negocio_produto = tipo_negocio_produto(getattr(empresa, "tipo", ""))
        negocio_encomenda = tipo_negocio_encomenda(getattr(empresa, "tipo", ""))
        negocio_pedido_comida = not negocio_servico and not negocio_produto and not negocio_encomenda

        empresa.pagamentos_online_ativo = formulario.get("pagamentos_online_ativo") == "on"
        empresa.gateway_pagamento = (formulario.get("gateway_pagamento") or "mercadopago").strip()
        empresa.gateway_ambiente = (formulario.get("gateway_ambiente") or "sandbox").strip()
        empresa.aceita_pix_online = formulario.get("aceita_pix_online") == "on"
        empresa.aceita_cartao_online = formulario.get("aceita_cartao_online") == "on"

        # V906: Pix pela chave é uma forma manual independente do Pix online.
        # Só se aplica ao checkout de Produtos e Comida/Pedidos; sinal de Serviços/Reservas continua separado.
        if negocio_produto or negocio_pedido_comida:
            pix_manual_ativo = formulario.get("aceita_pix_chave") == "on"
            pix_manual_tipo = (formulario.get("pix_manual_tipo") or "cnpj").strip().lower()
            if pix_manual_tipo not in {"cpf", "cnpj", "telefone", "email", "aleatoria"}:
                pix_manual_tipo = "cnpj"
            pix_manual_chave = (formulario.get("pix_manual_chave") or "").strip()
            pix_manual_titular = (formulario.get("pix_manual_titular") or "").strip()
            if pix_manual_ativo and (not pix_manual_chave or not pix_manual_titular):
                db.rollback()
                return RedirectResponse(
                    url=f"/admin/{empresa_id}/pagamentos-online?erro_pix_manual=1",
                    status_code=303,
                )
            empresa.aceita_pix_chave = pix_manual_ativo
            empresa.pix_manual_tipo = pix_manual_tipo
            empresa.pix_manual_chave = pix_manual_chave or None
            empresa.pix_manual_titular = pix_manual_titular or None
        else:
            empresa.aceita_pix_chave = False

        if tipo_negocio_encomenda(getattr(empresa, "tipo", "")):
            modos_validos = {"nenhum", "dinheiro", "cartao", "ambos"}
            modo_retirada = str(formulario.get("pagamento_retirada_modo") or "ambos").strip().lower()
            modo_entrega = str(formulario.get("pagamento_entrega_modo") or "ambos").strip().lower()
            if modo_retirada not in modos_validos:
                modo_retirada = "ambos"
            if modo_entrega not in modos_validos:
                modo_entrega = "ambos"
            empresa.pagamento_retirada_modo = modo_retirada
            empresa.pagamento_entrega_modo = modo_entrega
            # Mantém os campos antigos coerentes para rotinas compartilhadas/relatórios.
            empresa.aceita_dinheiro = any(m in {"dinheiro", "ambos"} for m in (modo_retirada, modo_entrega))
            empresa.aceita_cartao_entrega = any(m in {"cartao", "ambos"} for m in (modo_retirada, modo_entrega))
        else:
            empresa.aceita_dinheiro = formulario.get("aceita_dinheiro") == "on"
            empresa.aceita_cartao_entrega = formulario.get("aceita_cartao_entrega") == "on"
        empresa.pedido_so_apos_pagamento = formulario.get("pedido_so_apos_pagamento") == "on"

        sinal_ativo = formulario.get("sinal_reserva_ativo") == "on"
        sinal_tipo = (formulario.get("sinal_tipo") or "percentual").strip().lower()
        if sinal_tipo not in {"percentual", "fixo", "por_pessoa", "integral"}:
            sinal_tipo = "percentual"
        try:
            sinal_valor = float(str(formulario.get("sinal_valor") or "0").replace(",", "."))
        except (TypeError, ValueError):
            sinal_valor = 0.0
        if sinal_tipo == "percentual":
            sinal_valor = min(100.0, max(1.0, sinal_valor or 50.0))
        elif sinal_tipo == "integral":
            sinal_valor = 100.0
        else:
            sinal_valor = max(0.01, sinal_valor or 0.01)

        try:
            sinal_prazo = int(formulario.get("sinal_prazo_minutos") or 30)
        except (TypeError, ValueError):
            sinal_prazo = 30
        sinal_prazo = min(1440, max(5, sinal_prazo))

        pix_chave = (formulario.get("sinal_pix_chave") or "").strip()
        pix_titular = (formulario.get("sinal_pix_titular") or "").strip()
        if sinal_ativo and (not pix_chave or not pix_titular):
            db.rollback()
            return RedirectResponse(
                url=f"/admin/{empresa_id}/pagamentos-online?erro_sinal=pix",
                status_code=303,
            )

        if negocio_produto:
            sinal_ativo = False
            aplicar_agendamentos = False
            aplicar_reservas = False
        elif negocio_encomenda:
            aplicar_agendamentos = False
            aplicar_reservas = False
            if sinal_tipo == "por_pessoa":
                sinal_tipo = "fixo"
        elif negocio_servico:
            aplicar_agendamentos = formulario.get("sinal_aplicar_agendamentos") == "on"
            aplicar_reservas = False
            if sinal_tipo == "por_pessoa":
                sinal_tipo = "fixo"
        else:
            aplicar_agendamentos = False
            aplicar_reservas = formulario.get("sinal_aplicar_reservas") == "on"
            if sinal_tipo not in {"fixo", "por_pessoa"}:
                sinal_tipo = "fixo"

        empresa.sinal_reserva_ativo = sinal_ativo
        empresa.sinal_aplicar_agendamentos = aplicar_agendamentos
        empresa.sinal_aplicar_reservas = aplicar_reservas
        empresa.sinal_tipo = sinal_tipo
        empresa.sinal_valor = sinal_valor
        empresa.sinal_pix_tipo = (formulario.get("sinal_pix_tipo") or "cnpj").strip().lower()
        empresa.sinal_pix_chave = pix_chave or None
        empresa.sinal_pix_titular = pix_titular or None
        empresa.sinal_whatsapp = (formulario.get("sinal_whatsapp") or "").strip() or None
        empresa.sinal_prazo_minutos = sinal_prazo
        empresa.sinal_politica = (formulario.get("sinal_politica") or "").strip() or None

        public_key = (formulario.get("mercadopago_public_key") or "").strip()
        access_token = (formulario.get("mercadopago_access_token") or "").strip()
        webhook_secret = (formulario.get("mercadopago_webhook_secret") or "").strip()
        if public_key:
            empresa.mercadopago_public_key = public_key
        if access_token:
            empresa.mercadopago_access_token = encrypt_secret(access_token)
        if webhook_secret:
            empresa.mercadopago_webhook_secret = encrypt_secret(webhook_secret)

        db.commit()
        return RedirectResponse(url=f"/admin/{empresa_id}/pagamentos-online?salvo=1", status_code=303)
    except Exception:
        db.rollback()
        raise
    finally:
        db.close()


@app.get("/admin/{empresa_id}/fiscal")
def admin_fiscal(empresa_id: int, request: Request):
    redirecionamento = redirecionar_area_admin_se_necessario(request, empresa_id, "fiscal")
    if redirecionamento:
        return redirecionamento

    db = SessionLocal()

    empresa = db.query(Empresa).filter(
        Empresa.id == empresa_id
    ).first()

    if not empresa:
        db.close()
        return {"error": "Empresa não encontrada"}

    anexar_idioma_empresa(db, empresa)

    # V158: o modelo antigo não tem aliquota_iva_servicos mapeado.
    # Então anexamos o valor da coluna manualmente antes de fechar a sessão.
    v156_anexar_aliquota_servicos(db, empresa)

    db.close()

    return templates.TemplateResponse(
        request=request,
        name="admin_fiscal.html",
        context={
            "empresa": empresa
        }
    )


@app.post("/admin/{empresa_id}/fiscal")
async def salvar_fiscal_empresa(empresa_id: int, request: Request):
    redirecionamento = redirecionar_login_se_necessario(request, empresa_id)
    if redirecionamento:
        return redirecionamento

    formulario = await request.form()
    db = SessionLocal()

    try:
        empresa = db.query(Empresa).filter(
            Empresa.id == empresa_id
        ).first()

        if not empresa:
            db.close()
            return {"error": "Empresa não encontrada"}

        empresa.cnpj = re.sub(r"[^A-Z0-9]", "", str(formulario.get("cnpj", "")).upper()) or None
        if empresa.cnpj and not validar_cnpj_brasileiro(empresa.cnpj):
            raise HTTPException(status_code=400, detail="CNPJ inválido.")
        for campo in (
            "razao_social", "nome_fantasia", "inscricao_estadual", "inscricao_municipal",
            "regime_tributario", "cnae_principal", "situacao_cadastral", "cep_fiscal",
            "logradouro_fiscal", "numero_fiscal", "complemento_fiscal", "bairro_fiscal",
            "municipio_fiscal", "uf_fiscal", "email_fiscal",
        ):
            setattr(empresa, campo, str(formulario.get(campo, "")).strip() or None)
        empresa.pais = "Brasil"
        empresa.ragione_sociale = empresa.razao_social
        empresa.partita_iva = empresa.cnpj
        empresa.codice_fiscale = empresa.inscricao_estadual
        empresa.codice_destinatario = empresa.inscricao_municipal
        empresa.pec = empresa.email_fiscal
        empresa.regime_fiscale = empresa.regime_tributario
        empresa.regime_iva = empresa.nome_fantasia
        empresa.endereco = " ".join(filter(None, [empresa.logradouro_fiscal, empresa.numero_fiscal])).strip() or empresa.endereco
        empresa.cidade = " / ".join(filter(None, [empresa.municipio_fiscal, empresa.uf_fiscal])) or empresa.cidade

        # V157: IVA sempre ativo internamente.
        # Não fazemos UPDATE separado aqui para evitar lock do SQLite.
        empresa.usa_iva = True

        try:
            empresa.aliquota_iva_padrao = float(
                str(formulario.get("aliquota_iva_padrao") or 0).replace(",", ".")
            )
        except ValueError:
            empresa.aliquota_iva_padrao = 0

        # Salva a alíquota de serviços na mesma transação, usando o formulário correto.
        v156_salvar_aliquota_servicos_sqlite(db, empresa_id, formulario)

        db.commit()
        db.close()

        return RedirectResponse(
            url=f"/admin/{empresa_id}/fiscal",
            status_code=303
        )

    except Exception:
        db.rollback()
        db.close()
        raise

