# INICIO v28: migração automática SQLite para campos multilíngues
def mf_v28_add_column_sqlite(table, column, coltype="VARCHAR(255)"):
    try:
        from backend.database import engine
    except Exception:
        try:
            from .database import engine
        except Exception:
            engine = globals().get("engine")
    if not engine:
        return
    try:
        with engine.connect() as conn:
            cols = [row[1] for row in conn.exec_driver_sql(f"PRAGMA table_info({table})").fetchall()]
            if column not in cols:
                conn.exec_driver_sql(f"ALTER TABLE {table} ADD COLUMN {column} {coltype}")
                conn.commit()
    except Exception:
        pass

@app.on_event("startup")
def mf_v28_migrar_multilingue_cardapio():
    for c in ["nome_pt","nome_it","nome_en"]:
        mf_v28_add_column_sqlite("categorias", c, "VARCHAR(255)")
    for c in ["nome_pt","nome_it","nome_en"]:
        mf_v28_add_column_sqlite("itens", c, "VARCHAR(255)")
    for c in ["descricao_pt","descricao_it","descricao_en"]:
        mf_v28_add_column_sqlite("itens", c, "TEXT")
# FIM v28









# INICIO v741: usar somente menus existentes na landing

def mf_v741_remover_bella_food_criada_automaticamente():
    """Remove somente a empresa Bella Food criada pelas versões v739/v740.

    Os três menus escolhidos pelo usuário (bella-pizza, studio-bella e iphone)
    nunca são alterados. A limpeza também remove registros dependentes da empresa
    automática para não deixar dados órfãos no SQLite.
    """
    db = SessionLocal()
    try:
        empresas = (
            db.query(Empresa)
            .filter(
                Empresa.nome == "Bella Food",
                Empresa.slug.in_(["bella-food", "bella-food-demo"]),
            )
            .all()
        )
        if not empresas:
            return

        bind = db.get_bind()
        schema = inspect(bind)
        table_names = schema.get_table_names()

        def quoted(identifier: str) -> str:
            return '"' + str(identifier).replace('"', '""') + '"'

        for empresa in empresas:
            empresa_id = int(empresa.id)

            # pedido_itens não possui empresa_id; depende do pedido.
            if "pedido_itens" in table_names and "pedidos" in table_names:
                db.execute(
                    text(
                        'DELETE FROM "pedido_itens" '
                        'WHERE pedido_id IN ('
                        'SELECT id FROM "pedidos" WHERE empresa_id = :empresa_id'
                        ')'
                    ),
                    {"empresa_id": empresa_id},
                )

            for table_name in table_names:
                if table_name == "empresas":
                    continue
                columns = {column["name"] for column in schema.get_columns(table_name)}
                if "empresa_id" not in columns:
                    continue
                db.execute(
                    text(
                        f"DELETE FROM {quoted(table_name)} "
                        "WHERE empresa_id = :empresa_id"
                    ),
                    {"empresa_id": empresa_id},
                )

            db.execute(
                text('DELETE FROM "empresas" WHERE id = :empresa_id'),
                {"empresa_id": empresa_id},
            )

        db.commit()
        LOGGER.info("Empresa Bella Food criada automaticamente foi removida pela v741.")
    except Exception:
        db.rollback()
        LOGGER.exception("Falha ao remover a empresa Bella Food automática na v741")
        raise
    finally:
        db.close()


@app.on_event("startup")
def mf_v741_limpar_bella_food_automatica():
    mf_v741_remover_bella_food_criada_automaticamente()

# FIM v741


