# INICIO v29: traduzir cardápio existente sem recriar itens/fotos
@app.post("/admin/{empresa_id}/cardapio/traduzir-existente")
def traduzir_cardapio_existente_v29(request: Request, empresa_id: int):
    db = SessionLocal()
    try:
        empresa = db.query(Empresa).filter(Empresa.id == empresa_id).first()
        if not empresa:
            db.close()
            return RedirectResponse(url="/login", status_code=303)

        categorias = db.query(Categoria).filter(Categoria.empresa_id == empresa_id).all()
        itens = db.query(Item).filter(Item.empresa_id == empresa_id).all()

        total_categorias = 0
        total_itens = 0

        for categoria in categorias:
            antes = (
                getattr(categoria, "nome_pt", None),
                getattr(categoria, "nome_it", None),
                getattr(categoria, "nome_en", None),
            )
            mf_auto_translate_fields_v28(categoria)
            depois = (
                getattr(categoria, "nome_pt", None),
                getattr(categoria, "nome_it", None),
                getattr(categoria, "nome_en", None),
            )
            if antes != depois:
                total_categorias += 1

        for item in itens:
            antes = (
                getattr(item, "nome_pt", None),
                getattr(item, "nome_it", None),
                getattr(item, "nome_en", None),
                getattr(item, "descricao_pt", None),
                getattr(item, "descricao_it", None),
                getattr(item, "descricao_en", None),
            )
            mf_auto_translate_fields_v28(item)
            depois = (
                getattr(item, "nome_pt", None),
                getattr(item, "nome_it", None),
                getattr(item, "nome_en", None),
                getattr(item, "descricao_pt", None),
                getattr(item, "descricao_it", None),
                getattr(item, "descricao_en", None),
            )
            if antes != depois:
                total_itens += 1

        db.commit()
        db.close()

        return RedirectResponse(url=f"/admin/{empresa_id}/cardapio", status_code=303)
    except Exception:
        db.rollback()
        db.close()
        return RedirectResponse(url=f"/admin/{empresa_id}/cardapio", status_code=303)
