def _mp_only_digits(value: str) -> str:
    return re.sub(r"\D+", "", value or "")


def _mp_first_name(value: str) -> str:
    return (value or "").strip().split(" ")[0].casefold()


_MP_PUBLIC_LOOKUPS = defaultdict(list)
_MP_LOOKUP_WINDOW_SECONDS = 10 * 60
_MP_LOOKUP_LIMIT = 12


def _mp_limit_public_lookup(request: Request, slug: str) -> None:
    client_ip = request.client.host if request.client else "unknown"
    key = f"{client_ip}:{slug}"
    now = datetime.utcnow().timestamp()
    recent = [
        timestamp for timestamp in _MP_PUBLIC_LOOKUPS.get(key, [])
        if now - timestamp < _MP_LOOKUP_WINDOW_SECONDS
    ]
    if len(recent) >= _MP_LOOKUP_LIMIT:
        _MP_PUBLIC_LOOKUPS[key] = recent
        raise HTTPException(
            status_code=429,
            detail="Muitas consultas. Aguarde alguns minutos e tente novamente.",
        )
    recent.append(now)
    _MP_PUBLIC_LOOKUPS[key] = recent


def _mp_recovery_token(kind: str, origin_id: int, company_id: int) -> str:
    return public_recovery_token(kind, origin_id, company_id)


def _mp_payment_label(payment: str, status_payment: str) -> tuple[str, str]:
    status = (status_payment or "nao_iniciado").strip().lower()
    method = (payment or "").strip().lower()
    if status == "pago": return "Pagamento confirmado", "ok"
    if status in {"cancelado", "recusado", "erro", "expirado"}: return ({"cancelado":"Pagamento cancelado","recusado":"Pagamento recusado","erro":"Erro no pagamento","expirado":"Pagamento expirado"}.get(status, "Pagamento não concluído"), "bad")
    if status in {"pendente", "aguardando_pagamento"}: return "Aguardando pagamento", "wait"
    if "dinheiro" in method: return "Pagamento em dinheiro", "wait"
    if "cart" in method: return "Pagamento com cartão", "wait"
    if "retirada" in method or "local" in method or "balcao" in method: return "Pagamento na retirada", "wait"
    if "pix" in method: return "Pix", "wait"
    return "Pagamento no atendimento", "wait"


def _mp_order_label(status: str) -> tuple[str, str]:
    value = (status or "novo").strip().lower()
    labels = {
        "novo": "Pedido recebido", "confirmado": "Confirmado", "em_preparo": "Em preparo",
        "preparando": "Em preparo", "pronto": "Pronto", "saiu_entrega": "Saiu para entrega",
        "saiu_para_entrega": "Saiu para entrega", "entregue": "Entregue", "finalizado": "Finalizado",
        "concluido": "Concluído", "pendente": "Agendamento pendente", "aguardando_pagamento": "Aguardando pagamento",
        "cancelado": "Cancelado", "pagamento_cancelado": "Cancelado", "pagamento_recusado": "Pagamento recusado",
    }
    text_label = labels.get(value, value.replace("_", " ").title())
    if value in {"entregue", "finalizado", "concluido", "confirmado", "pronto"}: return text_label, "ok"
    if value in {"cancelado", "pagamento_cancelado", "pagamento_recusado"}: return text_label, "bad"
    return text_label, "wait"


def _mp_method_label(value: str) -> str:
    v=(value or "").strip().lower()
    if not v: return "A combinar"
    if v in {"pix pela chave", "pix manual", "pix_manual", "pix chave", "pix_chave"}: return "Pix pela chave"
    if "pix" in v: return "Pix online"
    if "dinheiro" in v: return "Dinheiro"
    if "cart" in v: return "Cartão"
    return v.replace("_", " ").title()


PIX_EXPIRATION_MINUTES = 30

def _mp_is_pix_expired(origin, expiration_minutes: int | None = None) -> bool:
    created = getattr(origin, "criado_em", None)
    if not created:
        return False
    try:
        minutes = int(expiration_minutes or PIX_EXPIRATION_MINUTES)
    except (TypeError, ValueError):
        minutes = PIX_EXPIRATION_MINUTES
    minutes = min(1440, max(5, minutes))
    return datetime.utcnow() >= created + timedelta(minutes=minutes)

def _mp_apply_expiration(
    origin,
    db=None,
    company=None,
    origin_type: str | None = None,
    expiration_minutes: int | None = None,
) -> bool:
    """Expira cobrança local somente depois de fechar/reconciliar a cobrança no MP.

    Antes da v894 a simples abertura de uma tela podia marcar o Pix como expirado
    e devolver estoque sem cancelar a cobrança no gateway. Se o cliente ainda
    pagasse aquele QR salvo, havia risco de pagamento tardio com estoque já
    liberado. Agora a expiração é gateway-aware e falha de forma conservadora.
    """
    payment_status = normalize_order_value(getattr(origin, "status_pagamento", None))
    order_status = normalize_order_value(getattr(origin, "status", None))
    if not (
        getattr(origin, "gateway_payment_id", None)
        and payment_status in {"pendente", "aguardando_pagamento"}
        and order_status != "cancelado"
        and _mp_is_pix_expired(origin, expiration_minutes)
    ):
        return False

    if db is None or company is None:
        # Sem contexto do gateway é mais seguro manter pendente do que devolver
        # estoque enquanto uma cobrança externa ainda pode ser paga.
        return False

    kind = origin_type or ("reserva" if isinstance(origin, Reserva) else "pedido")
    callback = (
        _reserva_approved_callback(db, company, origin)
        if kind == "reserva"
        else _pedido_approved_callback(db, company, origin)
    )

    try:
        payment = sync_origin(company, origin, kind, on_approved=callback)
        if normalize_order_value(getattr(origin, "status_pagamento", None)) == "pago":
            return False

        gateway_status = normalize_order_value(payment.get("status"))
        if gateway_status in {"pending", "in_process", "authorized"}:
            mp = MercadoPagoService(PaymentService.ensure_company_enabled(company))
            cancel_response = mp.cancel_payment(origin.gateway_payment_id)
            if not cancel_response.ok:
                LOGGER.warning(
                    "v894 não expirou %s %s porque o gateway não confirmou cancelamento: %s",
                    kind,
                    getattr(origin, "id", None),
                    cancel_response.data,
                )
                return False
            sync_origin(company, origin, kind, on_approved=callback)
            if normalize_order_value(getattr(origin, "status_pagamento", None)) == "pago":
                return False

        origin.status_pagamento = "expirado"
        origin.gateway_status = "expired"
        try:
            timeout_minutes = int(expiration_minutes or PIX_EXPIRATION_MINUTES)
        except (TypeError, ValueError):
            timeout_minutes = PIX_EXPIRATION_MINUTES
        origin.gateway_status_detail = f"pix_timeout_{timeout_minutes}m_gateway_closed"
        origin.status = "cancelado"
        if isinstance(origin, Pedido):
            restore_stock(db, origin)
        return True
    except (PaymentError, ValueError) as error:
        LOGGER.warning(
            "v894 não expirou %s %s porque não foi possível reconciliar/cancelar no gateway: %s",
            kind,
            getattr(origin, "id", None),
            error,
        )
        return False


def _mp_cpf_pedido(pedido: Pedido) -> str:
    texto = str(getattr(pedido, "observacao", None) or "")
    encontrado = re.search(r"(?:^|[\n|])\s*CPF\s*:\s*([0-9.\-]{11,14})", texto, flags=re.I)
    return _somente_digitos(encontrado.group(1)) if encontrado else ""


@app.post("/api/publico/{slug}/meus-pedidos")
async def meus_pedidos_publicos(slug: str, request: Request):
    _mp_limit_public_lookup(request, slug)
    try:
        payload = await request.json()
    except Exception:
        raise HTTPException(status_code=400, detail="Dados inválidos.")
    cpf_mode = str(payload.get("modo") or "").strip().lower() == "produto_cpf"
    cpf = _somente_digitos(payload.get("cpf"))
    phone = _mp_only_digits(str(payload.get("telefone") or ""))
    first_name = _mp_first_name(str(payload.get("nome") or ""))
    if cpf_mode:
        if len(cpf) != 11:
            raise HTTPException(status_code=400, detail="Informe um CPF válido.")
    elif len(phone) < 8 or len(first_name) < 2:
        raise HTTPException(status_code=400, detail="Informe o primeiro nome e um telefone válido.")

    db = SessionLocal()
    try:
        company = db.query(Empresa).filter(Empresa.slug == slug).first()
        if not company:
            raise HTTPException(status_code=404, detail="Empresa não encontrada.")
        since = datetime.utcnow() - timedelta(days=90)
        orders_query = db.query(Pedido).filter(Pedido.empresa_id == company.id, Pedido.criado_em >= since)
        if cpf_mode:
            orders_query = orders_query.filter(or_(Pedido.origem_menu == "produto", Pedido.origem_menu == None))
        orders = orders_query.order_by(Pedido.criado_em.desc()).limit(150).all()
        # V922 — ``Meus pedidos`` do Restaurante deve listar somente pedidos.
        # Agendamentos/serviços continuam podendo reutilizar este componente,
        # enquanto Produtos usa exclusivamente a busca por CPF. Reservas de mesa
        # possuem o fluxo próprio ``Minhas reservas`` e não podem se misturar à
        # lista de pedidos do restaurante.
        reservations = (
            db.query(Reserva)
            .filter(Reserva.empresa_id == company.id, Reserva.criado_em >= since)
            .order_by(Reserva.criado_em.desc())
            .limit(100)
            .all()
            if (not cpf_mode and tipo_negocio_servico(company.tipo))
            else []
        )
        result=[]
        expirations_changed=False
        for order in orders:
            if cpf_mode:
                if _mp_cpf_pedido(order) != cpf:
                    continue
            elif _mp_only_digits(order.telefone_cliente) != phone or _mp_first_name(order.nome_cliente) != first_name:
                continue
            expirations_changed = _mp_apply_expiration(order, db, company=company, origin_type="pedido") or expirations_changed
            pay_text,pay_color=_mp_payment_label(order.pagamento, order.status_pagamento)
            order_text,order_color=_mp_order_label(order.status)
            items=db.query(PedidoItem).filter(PedidoItem.pedido_id==order.id).order_by(PedidoItem.id).all()
            result.append({
                "tipo":"pedido","id":order.id,"token":_mp_recovery_token("pedido",order.id,company.id),
                "titulo":f"Pedido #{order.numero_dia or order.id}","data_hora":order.criado_em.strftime("%d/%m/%Y às %H:%M") if order.criado_em else "",
                "total":float(order.total or 0),"status_pedido_texto":order_text,"pedido_cor":order_color,
                "status_pagamento_texto":pay_text,"pagamento_cor":pay_color,"forma_pagamento_texto":_mp_method_label(order.pagamento),
                "tipo_pedido_texto":(order.tipo_pedido or "").replace("_"," ").title(),
                "numero_pedido":int(order.numero_dia or order.id),
                "pode_cancelar_pedido":bool(
                    (
                        cpf_mode
                        and normalize_order_value(getattr(order, "status", None)) not in {"cancelado", "finalizado", "concluido", "concluído"}
                        and normalize_order_value(getattr(order, "status_pagamento", None)) in {"pendente", "aguardando pagamento", "aguardando_pagamento"}
                    )
                    or
                    (
                        not cpf_mode
                        and normalize_order_value(getattr(order, "origem_menu", None)) in {"", "comida"}
                        and normalize_order_value(getattr(order, "status", None)) in {"novo", "aguardando pagamento", "aguardando_pagamento"}
                        and normalize_order_value(getattr(order, "status_pagamento", None)) != "pago"
                    )
                ),
                "pode_solicitar_cancelamento":bool(
                    (
                        cpf_mode
                        and normalize_order_value(getattr(order, "status", None)) != "cancelado"
                        and normalize_order_value(getattr(order, "status_pagamento", None)) == "pago"
                    )
                    or
                    (
                        not cpf_mode
                        and normalize_order_value(getattr(order, "origem_menu", None)) in {"", "comida"}
                        and normalize_order_value(getattr(order, "status", None)) not in {"cancelado", "finalizado", "concluido", "concluído", "entregue"}
                        and not (
                            normalize_order_value(getattr(order, "status", None)) in {"novo", "aguardando pagamento", "aguardando_pagamento"}
                            and normalize_order_value(getattr(order, "status_pagamento", None)) != "pago"
                        )
                    )
                ),
                "pode_continuar_pix":bool(order.gateway_payment_id and (order.status or "").lower() != "cancelado" and not _mp_is_pix_expired(order) and (order.status_pagamento or "").lower() in {"pendente","aguardando_pagamento"}),
                "pode_copiar_pix_manual":bool(
                    normalize_order_value(getattr(order, "gateway_pagamento", None)) == "pix_manual"
                    and (order.status or "").lower() != "cancelado"
                    and (order.status_pagamento or "").lower() in {"pendente", "aguardando_pagamento"}
                    and bool(getattr(company, "aceita_pix_chave", False))
                    and str(getattr(company, "pix_manual_chave", "") or "").strip()
                ),
                "pix_manual_chave":(
                    str(getattr(company, "pix_manual_chave", "") or "").strip()
                    if normalize_order_value(getattr(order, "gateway_pagamento", None)) == "pix_manual"
                    and (order.status_pagamento or "").lower() in {"pendente", "aguardando_pagamento"}
                    else ""
                ),
                "sort":order.criado_em.isoformat() if order.criado_em else "",
                "itens":[{"nome":i.nome_item,"quantidade":i.quantidade,"subtotal":float(i.subtotal or 0)} for i in items],
            })
        for reservation in reservations:
            if _mp_only_digits(reservation.telefone_cliente) != phone or _mp_first_name(reservation.nome_cliente) != first_name:
                continue
            expirations_changed = _mp_apply_expiration(
                reservation,
                db,
                company=company,
                origin_type="reserva",
                expiration_minutes=int(getattr(company, "sinal_prazo_minutos", 30) or 30),
            ) or expirations_changed
            pay_text,pay_color=_mp_payment_label("pix" if reservation.gateway_payment_id else "atendimento", reservation.status_pagamento)
            order_text,order_color=_mp_order_label(reservation.status)
            amount=PaymentService.reservation_amount(reservation)
            result.append({
                "tipo":"reserva","id":reservation.id,"token":_mp_recovery_token("reserva",reservation.id,company.id),
                "titulo":f"Agendamento #{reservation.numero_dia or reservation.id}","data_hora":reservation.criado_em.strftime("%d/%m/%Y às %H:%M") if reservation.criado_em else "",
                "total":amount,"status_pedido_texto":order_text,"pedido_cor":order_color,
                "status_pagamento_texto":pay_text,"pagamento_cor":pay_color,"forma_pagamento_texto":("Pix (sinal)" if getattr(reservation, "gateway_pagamento", None) == "pix_manual" else ("Pix online" if reservation.gateway_payment_id else "No atendimento")),
                "tipo_pedido_texto":f"{reservation.data} às {reservation.horario}",
                "pode_continuar_pix":bool(reservation.gateway_payment_id and (reservation.status or "").lower() != "cancelado" and not _mp_is_pix_expired(reservation, int(getattr(company, "sinal_prazo_minutos", 30) or 30)) and (reservation.status_pagamento or "").lower() in {"pendente","aguardando_pagamento"}),
                "pode_copiar_pix_manual":bool(
                    normalize_order_value(getattr(reservation, "gateway_pagamento", None)) == "pix_manual"
                    and (reservation.status or "").lower() not in {"cancelada", "cancelado"}
                    and (reservation.status_pagamento or "").lower() in {"pendente", "aguardando_pagamento"}
                    and str(getattr(company, "sinal_pix_chave", "") or "").strip()
                ),
                "pix_manual_chave":(
                    str(getattr(company, "sinal_pix_chave", "") or "").strip()
                    if normalize_order_value(getattr(reservation, "gateway_pagamento", None)) == "pix_manual"
                    and (reservation.status_pagamento or "").lower() in {"pendente", "aguardando_pagamento"}
                    else ""
                ),
                "sort":reservation.criado_em.isoformat() if reservation.criado_em else "","itens":[],
            })
        if expirations_changed:
            db.commit()
        result.sort(key=lambda x:x["sort"], reverse=True)
        for item in result: item.pop("sort",None)
        return {"ok":True,"pedidos":result[:30]}
    finally:
        db.close()


@app.post("/api/publico/{slug}/meus-pedidos/pedido/{pedido_id}/cancelar")
async def cancelar_pedido_publico(slug: str, pedido_id: int, request: Request):
    """Cancela pedido ainda não aceito/pago em Produtos ou Restaurante.

    Produtos autentica pelo CPF. Restaurante autentica pelo primeiro nome +
    telefone usados na consulta de ``Meus pedidos``. Pedidos já pagos ou que
    avançaram operacionalmente não são cancelados automaticamente: o cliente
    deve solicitar o cancelamento ao estabelecimento.
    """
    _mp_limit_public_lookup(request, slug)
    try:
        payload = await request.json()
    except Exception:
        raise HTTPException(status_code=400, detail="Dados inválidos.")

    token = str(payload.get("token") or "")
    cpf = _somente_digitos(payload.get("cpf"))
    phone = _mp_only_digits(str(payload.get("telefone") or ""))
    first_name = _mp_first_name(str(payload.get("nome") or ""))

    db = SessionLocal()
    try:
        company = db.query(Empresa).filter(Empresa.slug == slug).first()
        if not company:
            raise HTTPException(status_code=404, detail="Empresa não encontrada.")

        pedido = db.query(Pedido).filter(
            Pedido.id == int(pedido_id),
            Pedido.empresa_id == company.id,
        ).first()
        if not pedido or not hmac.compare_digest(
            token, _mp_recovery_token("pedido", int(pedido_id), int(company.id))
        ):
            raise HTTPException(status_code=404, detail="Pedido não encontrado.")

        origem = normalize_order_value(getattr(pedido, "origem_menu", None))
        # Registros antigos de Produtos podem ter origem_menu vazio; o CPF
        # presente no payload mantém compatibilidade sem confundir pedidos de
        # Restaurante, que usam nome + telefone.
        produto = origem == "produto" or (origem == "" and len(cpf) == 11)
        restaurante = origem == "comida" or (origem == "" and not produto)
        if not produto and not restaurante:
            raise HTTPException(status_code=404, detail="Pedido não encontrado.")

        if produto:
            if len(cpf) != 11:
                raise HTTPException(status_code=400, detail="Informe o CPF usado no pedido.")
            if _mp_cpf_pedido(pedido) != cpf:
                raise HTTPException(status_code=403, detail="Os dados informados não conferem com este pedido.")
        else:
            if len(phone) < 8 or len(first_name) < 2:
                raise HTTPException(status_code=400, detail="Informe o primeiro nome e o telefone usados no pedido.")
            if (
                _mp_only_digits(getattr(pedido, "telefone_cliente", "")) != phone
                or _mp_first_name(getattr(pedido, "nome_cliente", "")) != first_name
            ):
                raise HTTPException(status_code=403, detail="Os dados informados não conferem com este pedido.")

        status = normalize_order_value(getattr(pedido, "status", None))
        pagamento = normalize_order_value(getattr(pedido, "status_pagamento", None))
        if status == "cancelado":
            return {"ok": True, "pedido_id": pedido.id, "status": "cancelado"}
        if pagamento == "pago":
            raise HTTPException(
                status_code=409,
                detail="O pagamento já foi confirmado. Solicite o cancelamento diretamente ao estabelecimento.",
            )

        if produto:
            if pagamento not in {"pendente", "aguardando pagamento", "aguardando_pagamento"}:
                raise HTTPException(
                    status_code=409,
                    detail="Este pedido não pode mais ser cancelado automaticamente.",
                )
        else:
            # Restaurante: o cliente pode desistir sozinho apenas enquanto o
            # pedido ainda não foi aceito pela operação. Dinheiro/cartão na
            # entrega nascem como ``novo`` e também entram nessa janela.
            if status not in {"novo", "aguardando pagamento", "aguardando_pagamento"}:
                raise HTTPException(
                    status_code=409,
                    detail="O pedido já foi aceito ou está em andamento. Solicite o cancelamento ao estabelecimento.",
                )

        # Se existir cobrança Mercado Pago, reconcilia e cancela no gateway antes
        # de liberar o pedido/estoque. Assim uma aprovação ocorrida no mesmo
        # instante nunca é descartada localmente. Pix pela chave e pagamentos
        # presenciais não possuem cobrança externa a cancelar aqui.
        if str(getattr(pedido, "gateway_payment_id", "") or "").strip():
            try:
                _cancelar_tentativa_gateway_v894(
                    db,
                    company,
                    pedido,
                    "pedido",
                    on_approved=_pedido_approved_callback(db, company, pedido),
                )
            except PaymentError as error:
                db.rollback()
                raise HTTPException(status_code=error.status_code, detail=str(error))

        if normalize_order_value(getattr(pedido, "status_pagamento", None)) == "pago":
            db.commit()
            raise HTTPException(
                status_code=409,
                detail="O pagamento foi confirmado durante o cancelamento. Fale com o estabelecimento.",
            )

        PaymentService.cancel_pending(pedido)
        pedido.status = "cancelado"
        pedido.status_pagamento = "cancelado"
        pedido.cancelamento_origem = "cliente"
        pedido.cancelamento_em = agora_brasilia()
        pedido.reembolso_status = "nao_aplicavel"
        pedido.reembolso_valor = 0
        pedido.gateway_status = "cancelled_by_customer"
        pedido.gateway_status_detail = (
            "customer_cancelled_product_order" if produto
            else "customer_cancelled_restaurant_order"
        )
        restore_stock(db, pedido)
        db.commit()
        pedido_id_final = int(pedido.id)
        produto_final = bool(produto)
    except HTTPException:
        db.rollback()
        raise
    except Exception:
        db.rollback()
        LOGGER.exception("Falha no cancelamento público do pedido %s", pedido_id)
        raise HTTPException(status_code=500, detail="Não foi possível cancelar o pedido agora.")
    finally:
        db.close()

    enqueue_order_cancelled_by_customer(pedido_id_final)
    return {
        "ok": True,
        "pedido_id": pedido_id_final,
        "status": "cancelado",
        "message": (
            "Pedido cancelado. O estabelecimento foi avisado e o estoque foi liberado."
            if produto_final
            else "Pedido cancelado. O estabelecimento foi avisado e o pedido foi retirado da fila."
        ),
    }


@app.get("/api/publico/{slug}/meus-pedidos/{kind}/{origin_id}/pix")
def recuperar_pix_publico(slug: str, kind: str, origin_id: int, token: str):
    if kind not in {"pedido", "reserva"}:
        raise HTTPException(status_code=404, detail="Pagamento não encontrado.")
    db = SessionLocal()
    try:
        company = db.query(Empresa).filter(Empresa.slug == slug).first()
        if not company or not hmac.compare_digest(
            token or "", _mp_recovery_token(kind, origin_id, company.id)
        ):
            raise HTTPException(status_code=404, detail="Pagamento não encontrado.")

        model = Pedido if kind == "pedido" else Reserva
        origin = db.query(model).filter(
            model.id == origin_id, model.empresa_id == company.id
        ).first()
        if not origin or not origin.gateway_payment_id:
            raise HTTPException(status_code=404, detail="Pix não encontrado.")
        if (origin.status or "").lower() == "cancelado":
            raise HTTPException(
                status_code=409,
                detail="Este pedido foi cancelado e não aceita mais pagamento.",
            )

        # v894: antes de considerar o Pix expirado/localmente pendente, consulta
        # o gateway. Isso evita expirar uma cobrança que já foi paga enquanto o
        # webhook estava atrasado e centraliza validação de referência + valor.
        approval_callback = (
            _pedido_approved_callback(db, company, origin)
            if kind == "pedido"
            else _reserva_approved_callback(db, company, origin)
        )
        try:
            payment = sync_origin(
                company,
                origin,
                kind,
                on_approved=approval_callback,
            )
            if kind == "pedido" and normalize_order_value(origin.status_pagamento) in {
                "recusado", "cancelado", "erro", "expirado"
            }:
                restore_stock(db, origin)
            db.commit()
        except PaymentError as error:
            db.rollback()
            raise HTTPException(status_code=error.status_code, detail=str(error))

        if origin.status_pagamento == "pago":
            return {"ok": True, "status_pagamento": "pago"}

        # O prazo local continua sendo respeitado, mas o MenuFacile só encerra
        # a tentativa local depois de confirmar que a cobrança deixou de ser
        # pagável no gateway. Isso evita restaurar estoque enquanto um Pix ainda
        # pode ser pago pelo cliente.
        expiration_minutes = (
            int(getattr(company, "sinal_prazo_minutos", 30) or 30)
            if kind == "reserva"
            else PIX_EXPIRATION_MINUTES
        )
        if _mp_is_pix_expired(origin, expiration_minutes):
            gateway_status = normalize_order_value(getattr(origin, "gateway_status", None))
            if gateway_status in {"pending", "in_process", "authorized", ""}:
                try:
                    mp = MercadoPagoService(PaymentService.ensure_company_enabled(company))
                    cancel_response = mp.cancel_payment(origin.gateway_payment_id)
                except (PaymentError, ValueError) as error:
                    raise HTTPException(
                        status_code=503,
                        detail="Não foi possível encerrar este Pix agora. Tente novamente em instantes.",
                    ) from error
                if not cancel_response.ok:
                    raise HTTPException(
                        status_code=503 if int(cancel_response.status_code or 0) >= 500 else 409,
                        detail="Não foi possível encerrar este Pix no Mercado Pago.",
                    )
                try:
                    payment = sync_origin(
                        company,
                        origin,
                        kind,
                        on_approved=approval_callback,
                    )
                except PaymentError as error:
                    raise HTTPException(status_code=error.status_code, detail=str(error))
                if normalize_order_value(getattr(origin, "status_pagamento", None)) == "pago":
                    db.commit()
                    return {"ok": True, "status_pagamento": "pago"}

            origin.status_pagamento = "expirado"
            origin.status = "cancelado"
            origin.gateway_status_detail = f"pix_timeout_{expiration_minutes}m_gateway_closed"
            if kind == "pedido":
                restore_stock(db, origin)
            db.commit()
            raise HTTPException(status_code=409, detail=f"O prazo de {expiration_minutes} minutos deste Pix expirou.")

        transaction = ((payment.get("point_of_interaction") or {}).get("transaction_data") or {})
        return {
            "ok": True,
            "status_pagamento": origin.status_pagamento,
            "qr_code": transaction.get("qr_code"),
            "qr_code_base64": transaction.get("qr_code_base64"),
            "ticket_url": transaction.get("ticket_url"),
        }
    finally:
        db.close()


