# PAGAMENTOS ONLINE — ROTAS INTEGRADAS AO NÚCLEO CENTRAL
# ==================================================

def garantir_colunas_checkout_mercadopago():
    ensure_payment_columns(engine, SessionLocal)


def _payment_notification_url(request: Request, empresa_id: int) -> str | None:
    configured = os.getenv("PUBLIC_BASE_URL", "").strip().rstrip("/")
    if configured:
        if os.getenv("APP_ENV", "development").strip().lower() in {"prod", "production", "producao", "produção", "live"} and not configured.lower().startswith("https://"):
            raise PaymentError("PUBLIC_BASE_URL precisa usar HTTPS em produção.", status_code=503)
        return configured + f"/api/pagamentos/mercadopago/{empresa_id}/webhook"

    host = str(request.url.hostname or "").lower()
    if host in {"127.0.0.1", "localhost", "0.0.0.0"}:
        return None
    return str(request.base_url).rstrip("/") + f"/api/pagamentos/mercadopago/{empresa_id}/webhook"


def _pedido_approved_callback(db, empresa, pedido):
    def callback():
        # Uma tentativa online só vira pedido operacional após a aprovação.
        # Nesse momento recebe o código diário visível (#001, #002...).
        if not getattr(pedido, "numero_dia", None):
            data_operacional = (
                getattr(pedido, "data_operacional", None)
                or (getattr(pedido, "criado_em", None).date() if getattr(pedido, "criado_em", None) else hoje_brasilia())
            )
            pedido.data_operacional = data_operacional
            pedido.numero_dia = gerar_numero_dia(
                db, Pedido, pedido.empresa_id, data_operacional
            )
        enviar_whatsapp_automatico_evento(
            db=db,
            empresa_id=pedido.empresa_id,
            destino=getattr(pedido, "telefone_cliente", ""),
            tipo="pedido",
            status_evento="pedido recebido",
            contexto={
                "nome_cliente": getattr(pedido, "nome_cliente", ""),
                "pedido_id": f"#{int(getattr(pedido, 'numero_dia', None) or getattr(pedido, 'id', 0)):03d}",
                "total": getattr(pedido, "total", 0),
                "empresa_nome": getattr(empresa, "nome", ""),
            },
        )
        enqueue_new_order(pedido.id)
    return callback


def _reserva_approved_callback(db, empresa, reserva):
    def callback():
        if reserva is None:
            return

        total = max(0.0, float(getattr(reserva, "valor_total", 0) or 0))
        sinal_configurado = max(0.0, float(getattr(reserva, "valor_sinal", 0) or 0))
        valor_cobrado = sinal_configurado if sinal_configurado > 0 else total
        valor_cobrado = min(valor_cobrado, total) if total > 0 else valor_cobrado

        # V929: o gateway é a confirmação. Não exigir conferência manual do sinal online.
        recebido_atual = max(0.0, float(getattr(reserva, "valor_recebido", 0) or 0))
        reserva.valor_recebido = round(max(recebido_atual, valor_cobrado), 2)
        if sinal_configurado > 0:
            reserva.valor_sinal_recebido = round(min(sinal_configurado, reserva.valor_recebido), 2)

        quitado = total > 0 and reserva.valor_recebido >= (total - 0.005)
        reserva.status_pagamento = "pago" if quitado else "parcial"
        reserva.pagamento_tipo = "integral" if quitado else "sinal"
        reserva.pagamento_registrado_em = agora_brasilia()
        if quitado:
            reserva.pago_em = reserva.pago_em or datetime.utcnow()
        else:
            reserva.pago_em = None

        reserva.status = "confirmada"
        if hasattr(reserva, "horario_liberado"):
            reserva.horario_liberado = False

        forma = normalizar_forma_pagamento_reserva(getattr(reserva, "forma_pagamento", ""))
        reserva.forma_pagamento = forma
        forma_label = {
            "cartao_credito_online": "Cartão crédito online",
            "cartao_debito_online": "Cartão débito online",
            "pix_online": "Pix online",
        }.get(forma, "Pagamento online")
        valor_texto = f"R$ {valor_cobrado:,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
        marcador = f"gateway:{getattr(reserva, 'gateway_payment_id', '') or 'online'}"
        historico = str(getattr(reserva, "pagamento_observacao", "") or "")
        if marcador not in historico:
            linha = f"{agora_brasilia().strftime('%d/%m/%Y %H:%M')} · {valor_texto} · {forma_label} · {'integral' if quitado else 'sinal'} · {marcador}"
            reserva.pagamento_observacao = (historico + "\n" + linha).strip()

        # Notificações são enfileiradas apenas na primeira transição aprovada.
        enqueue_new_reservation(reserva.id)
        enqueue_reservation_online_payment(reserva.id)
    return callback

def _payment_error_response(error: PaymentError):
    content = {"error": str(error)}
    if error.details is not None and os.getenv("PAYMENT_DEBUG_DETAILS", "false").lower() == "true":
        content["details"] = error.details
    return JSONResponse(content, status_code=error.status_code)


def _payment_token_from_request(request: Request, payload: dict | None = None) -> str:
    payload = payload or {}
    return str(
        request.headers.get("X-Public-Token")
        or request.query_params.get("token")
        or payload.get("public_token")
        or payload.get("token")
        or ""
    ).strip()


def _admin_can_access_payment(request: Request, empresa_id: int) -> bool:
    return empresa_admin_sessao(request) == int(empresa_id) or saas_admin_logado(request)


def _require_payment_origin_access(
    request: Request,
    origin,
    empresa_id: int,
    payload: dict | None = None,
) -> None:
    if _admin_can_access_payment(request, empresa_id):
        return
    expected = str(getattr(origin, "public_token", None) or "").strip()
    supplied = _payment_token_from_request(request, payload)
    if not expected or not supplied or not hmac.compare_digest(expected, supplied):
        raise PaymentError("Acesso ao pagamento não autorizado.", status_code=403)


async def _payment_json(request: Request) -> dict:
    try:
        data = await request.json()
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def _mf_normalizar_chave_parcelamento(valor) -> str:
    texto = unicodedata.normalize("NFKD", str(valor or ""))
    texto = texto.encode("ascii", "ignore").decode("ascii").lower()
    return " ".join(re.sub(r"[^a-z0-9]+", " ", texto).split())


def _mf_config_parcelamento_item(atributos_json) -> dict | None:
    if isinstance(atributos_json, dict):
        atributos = atributos_json
    else:
        try:
            atributos = json.loads(atributos_json or "{}")
        except (TypeError, ValueError, json.JSONDecodeError):
            return None
    if not isinstance(atributos, dict):
        return None

    normalizados = {
        _mf_normalizar_chave_parcelamento(chave): valor
        for chave, valor in atributos.items()
    }
    texto_parcelas = str(normalizados.get("parcelamento") or "").strip()
    encontrado = re.search(r"(\d+)\s*x", texto_parcelas, flags=re.I)
    if not encontrado:
        return None

    return {
        "max_parcelas": min(12, max(1, int(encontrado.group(1)))),
    }


def _mf_politica_parcelamento_pedido(db, pedido: Pedido) -> dict | None:
    itens_pedido = db.query(PedidoItem).filter(PedidoItem.pedido_id == pedido.id).all()
    item_ids = sorted({
        int(item.item_id)
        for item in itens_pedido
        if item.item_id is not None
    })
    if not item_ids:
        return None

    itens_catalogo = db.query(Item).filter(
        Item.empresa_id == pedido.empresa_id,
        Item.id.in_(item_ids),
    ).all()
    por_id = {int(item.id): item for item in itens_catalogo}
    configuracoes = []
    for item_pedido in itens_pedido:
        if item_pedido.item_id is None:
            continue
        item_catalogo = por_id.get(int(item_pedido.item_id))
        if not item_catalogo:
            continue
        configuracao = _mf_config_parcelamento_item(item_catalogo.atributos_json)
        if configuracao:
            configuracoes.append(configuracao)

    if not configuracoes:
        return None
    return {
        "max_parcelas": min(config["max_parcelas"] for config in configuracoes),
    }


def _mf_validar_parcelamento_pedido(db, pedido: Pedido, form_data: dict) -> dict | None:
    politica = _mf_politica_parcelamento_pedido(db, pedido)
    if not politica:
        return None
    try:
        parcelas_escolhidas = int(form_data.get("installments") or 1)
    except (TypeError, ValueError):
        parcelas_escolhidas = 1
    if parcelas_escolhidas > int(politica["max_parcelas"]):
        raise PaymentError(
            f"Este pedido permite no máximo {politica['max_parcelas']} parcelas.",
            status_code=400,
        )
    return politica


@app.post("/api/pagamentos/mercadopago/{empresa_id}/processar")
async def processar_pagamento_mercadopago(empresa_id: int, request: Request):
    db = SessionLocal()
    try:
        recebido = await _payment_json(request)
        pedido_id = int(recebido.get("pedido_id") or 0)
        empresa = db.query(Empresa).filter(Empresa.id == empresa_id).first()
        pedido = db.query(Pedido).filter(
            Pedido.id == pedido_id, Pedido.empresa_id == empresa_id
        ).first()
        if not pedido:
            raise PaymentError("Pedido não encontrado.", status_code=404)
        _require_payment_origin_access(request, pedido, empresa_id, recebido)
        form_data = recebido.get("formData") or recebido.get("form_data") or {}
        if not isinstance(form_data, dict):
            form_data = {}
        _mf_validar_parcelamento_pedido(db, pedido, form_data)

        # Uma nova tentativa pode reutilizar o mesmo checkout interno. Caso o
        # estoque tenha sido devolvido após uma falha anterior, reserve-o de novo.
        if bool(getattr(pedido, "estoque_devolvido", False)):
            reserve_existing_order_stock(db, pedido)

        try:
            resultado = PaymentService.create_payment(
                company=empresa,
                origin=pedido,
                origin_type="pedido",
                amount=float(pedido.total or 0),
                form_data=form_data,
                device_id=str(recebido.get("deviceId") or recebido.get("device_id") or "").strip() or None,
                payer_email=recebido.get("email") or "cliente@menufacile.org",
                notification_url=_payment_notification_url(request, empresa_id),
                on_approved=_pedido_approved_callback(db, empresa, pedido),
            )
        except PaymentError as error:
            # O pedido provisório continua apenas como auditoria interna. Ele não
            # entra na Central de Pedidos, não recebe código diário e não infla o
            # contador operacional.
            pedido.status_pagamento = "erro"
            pedido.status = "pagamento_recusado"
            pedido.gateway_status = pedido.gateway_status or "error"
            pedido.gateway_status_detail = pedido.gateway_status_detail or str(error)
            restore_stock(db, pedido)
            db.commit()
            return _payment_error_response(error)

        if normalize_order_value(pedido.status_pagamento) in {"recusado", "cancelado", "erro", "expirado"}:
            restore_stock(db, pedido)
        db.commit()
        return resultado.as_dict()
    except PaymentError as error:
        db.rollback()
        return _payment_error_response(error)
    except Exception:
        db.rollback()
        LOGGER.exception("Falha inesperada ao processar pagamento do pedido %s", empresa_id)
        return JSONResponse({"error": "Não foi possível processar o pagamento."}, status_code=500)
    finally:
        db.close()


@app.post("/api/pagamentos/mercadopago/{empresa_id}/reserva/processar")
async def processar_pagamento_reserva_mercadopago(empresa_id: int, request: Request):
    db = SessionLocal()
    try:
        recebido = await _payment_json(request)
        reserva_id = int(recebido.get("reserva_id") or 0)
        empresa = db.query(Empresa).filter(Empresa.id == empresa_id).first()
        reserva = db.query(Reserva).filter(
            Reserva.id == reserva_id, Reserva.empresa_id == empresa_id
        ).first()
        if not reserva:
            raise PaymentError("Agendamento não encontrado.", status_code=404)
        _require_payment_origin_access(request, reserva, empresa_id, recebido)

        total = PaymentService.reservation_amount(reserva)
        if total <= 0:
            raise PaymentError("Não foi possível identificar o valor do agendamento.")

        # V930: "Trocar forma" precisa alterar também o estado persistido da
        # reserva. Antes, a UI podia trocar débito -> crédito, mas o backend
        # continuava com a forma escolhida quando o agendamento foi criado.
        forma_solicitada = str(recebido.get("forma_pagamento") or "").strip()
        if forma_solicitada:
            try:
                forma_solicitada = validar_forma_pagamento_reserva(
                    empresa,
                    forma_solicitada,
                    exige_sinal=bool(float(getattr(reserva, "valor_sinal", 0) or 0) > 0.005),
                    valor_cobranca=total,
                )
            except ValueError as erro_forma:
                raise PaymentError(str(erro_forma), status_code=400) from erro_forma
            if forma_solicitada not in {"pix_online", "cartao_credito_online", "cartao_debito_online"}:
                raise PaymentError("Forma de pagamento online inválida.", status_code=400)
            reserva.forma_pagamento = forma_solicitada

        resultado = PaymentService.create_payment(
            company=empresa,
            origin=reserva,
            origin_type="reserva",
            amount=total,
            form_data=recebido.get("formData") or recebido.get("form_data") or {},
            device_id=str(recebido.get("deviceId") or recebido.get("device_id") or "").strip() or None,
            payer_email=recebido.get("email") or "cliente@menufacile.org",
            notification_url=_payment_notification_url(request, empresa_id),
            on_approved=_reserva_approved_callback(db, empresa, reserva),
        )
        db.commit()
        return resultado.as_dict()
    except PaymentError as error:
        db.rollback()
        return _payment_error_response(error)
    except Exception:
        db.rollback()
        LOGGER.exception("Falha inesperada ao processar pagamento da reserva %s", empresa_id)
        return JSONResponse({"error": "Não foi possível processar o pagamento."}, status_code=500)
    finally:
        db.close()


@app.post("/api/pagamentos/mercadopago/{empresa_id}/webhook")
async def webhook_mercadopago(empresa_id: int, request: Request):
    db = SessionLocal()
    try:
        empresa = db.query(Empresa).filter(Empresa.id == empresa_id).first()
        token = PaymentService.ensure_company_enabled(empresa)
        corpo = await _payment_json(request)

        payment_id = extract_payment_id(corpo, request.query_params)
        if not payment_id:
            return {"ok": True}

        try:
            webhook_secret = decrypt_secret(getattr(empresa, "mercadopago_webhook_secret", ""))
        except SecretProtectionError:
            LOGGER.exception("Segredo do webhook do Mercado Pago não pôde ser aberto para empresa %s", empresa_id)
            return JSONResponse({"ok": False}, status_code=503)

        signature = request.headers.get("x-signature", "")
        request_id = request.headers.get("x-request-id", "")
        signature_data_id = str(request.query_params.get("data.id") or payment_id or "")
        production_gateway = str(getattr(empresa, "gateway_ambiente", "") or "").strip().lower() in {"prod", "production", "producao", "produção", "live"}
        if production_gateway and not webhook_secret:
            LOGGER.error("Webhook Mercado Pago de produção sem assinatura secreta na empresa %s", empresa_id)
            return JSONResponse({"ok": False, "error": "Webhook não configurado."}, status_code=503)
        if webhook_secret and (signature or production_gateway):
            if not verify_mercadopago_signature(
                x_signature=signature,
                x_request_id=request_id,
                data_id=signature_data_id,
                secret=webhook_secret,
            ):
                LOGGER.warning("Assinatura inválida no webhook Mercado Pago da empresa %s", empresa_id)
                return JSONResponse({"ok": False}, status_code=401)

        resposta = MercadoPagoService(token).get_payment(payment_id)
        if not resposta.ok:
            raise PaymentError("Não foi possível consultar o pagamento recebido no webhook.")

        pagamento = resposta.data
        referencia = parse_external_reference(pagamento.get("external_reference"))
        if not referencia:
            return {"ok": True}
        if referencia.company_id != empresa_id:
            return JSONResponse({"ok": False}, status_code=403)

        if referencia.origin_type == "reserva":
            origem = db.query(Reserva).filter(
                Reserva.id == referencia.origin_id, Reserva.empresa_id == empresa_id
            ).first()
            valor_esperado = PaymentService.reservation_amount(origem) if origem else 0
            callback = _reserva_approved_callback(db, empresa, origem) if origem else None
        elif referencia.origin_type == "encomenda":
            origem = db.query(Encomenda).filter(
                Encomenda.id == referencia.origin_id, Encomenda.empresa_id == empresa_id
            ).first()
            valor_esperado = _encomenda_valor_pagamento(origem) if origem else 0
            callback = _encomenda_payment_callback(db, empresa, origem) if origem else None
        else:
            origem = db.query(Pedido).filter(
                Pedido.id == referencia.origin_id, Pedido.empresa_id == empresa_id
            ).first()
            valor_esperado = float(origem.total or 0) if origem else 0
            callback = _pedido_approved_callback(db, empresa, origem) if origem else None

        if not origem:
            return {"ok": True}

        # v786: ao trocar a forma de pagamento, uma tentativa antiga pode ainda
        # entregar um webhook de cancelamento/pendência. Não deixamos essa tentativa
        # sobrescrever a cobrança nova da mesma encomenda.
        if referencia.origin_type == "encomenda":
            current_payment_id = str(getattr(origem, "gateway_payment_id", "") or "").strip()
            current_detail = str(getattr(origem, "gateway_status_detail", "") or "").strip()
            incoming_payment_id = str(payment_id or "").strip()
            if current_payment_id and incoming_payment_id and current_payment_id != incoming_payment_id:
                LOGGER.info(
                    "v786 ignorando webhook de pagamento substituído encomenda=%s antigo=%s atual=%s",
                    origem.id, incoming_payment_id, current_payment_id,
                )
                return {"ok": True, "ignored": "superseded_payment"}
            if (not current_payment_id) and current_detail == f"v786_superseded:{incoming_payment_id}":
                LOGGER.info(
                    "v786 ignorando webhook da tentativa cancelada durante troca encomenda=%s payment=%s",
                    origem.id, incoming_payment_id,
                )
                return {"ok": True, "ignored": "superseded_payment"}

        if not amounts_match(valor_esperado, pagamento.get("transaction_amount")):
            return JSONResponse({"ok": False, "error": "Valor divergente."}, status_code=400)

        PaymentService.update_origin(
            origem, pagamento, origin_type=referencia.origin_type, on_approved=callback
        )
        if referencia.origin_type == "encomenda":
            _v788_respeitar_liberacao_encomenda_online(empresa, origem)
        if referencia.origin_type == "pedido" and normalize_order_value(origem.status_pagamento) in {
            "recusado", "cancelado", "erro", "expirado"
        }:
            restore_stock(db, origem)
        status_gateway_webhook = str(pagamento.get("status") or "").strip().lower()
        encomenda_push_id = int(origem.id) if (
            referencia.origin_type == "encomenda"
            and (
                status_gateway_webhook == "approved"
                or (
                    not bool(getattr(empresa, "pedido_so_apos_pagamento", False))
                    and status_gateway_webhook in {"pending", "in_process", "authorized"}
                )
            )
        ) else None
        db.commit()
        if encomenda_push_id is not None:
            enqueue_new_encomenda(encomenda_push_id)
        return {"ok": True}
    except PaymentError as error:
        db.rollback()
        return _payment_error_response(error)
    except Exception:
        db.rollback()
        LOGGER.exception("Falha inesperada no webhook Mercado Pago da empresa %s", empresa_id)
        return JSONResponse({"ok": False}, status_code=500)
    finally:
        db.close()


@app.get("/api/pagamentos/mercadopago/{empresa_id}/pedido/{pedido_id}/status")
def status_pagamento_pedido(empresa_id: int, pedido_id: int, request: Request):
    db = SessionLocal()
    try:
        empresa = db.query(Empresa).filter(Empresa.id == empresa_id).first()
        pedido = db.query(Pedido).filter(
            Pedido.id == pedido_id, Pedido.empresa_id == empresa_id
        ).first()
        if not pedido:
            return JSONResponse({"error": "Pedido não encontrado."}, status_code=404)
        try:
            _require_payment_origin_access(request, pedido, empresa_id)
        except PaymentError as error:
            return _payment_error_response(error)

        # v894: o status público também consulta o gateway enquanto houver uma
        # cobrança pendente. Assim Pedido/Produtos/Comida não dependem somente
        # da chegada do webhook para sair de pending/in_process.
        payment_status = normalize_order_value(getattr(pedido, "status_pagamento", None))
        gateway_status = normalize_order_value(getattr(pedido, "gateway_status", None))
        if empresa and getattr(pedido, "gateway_payment_id", None) and (
            payment_status in {"pendente", "aguardando_pagamento"}
            or gateway_status in {"pending", "in_process", "authorized"}
        ):
            try:
                sync_origin(
                    empresa,
                    pedido,
                    "pedido",
                    on_approved=_pedido_approved_callback(db, empresa, pedido),
                )
                if normalize_order_value(pedido.status_pagamento) in {
                    "recusado", "cancelado", "erro", "expirado"
                }:
                    restore_stock(db, pedido)
                db.commit()
            except PaymentError as error:
                db.rollback()
                LOGGER.warning(
                    "Fallback de status do pedido %s não conseguiu consultar o Mercado Pago: %s",
                    pedido_id,
                    error,
                )
                pedido = db.query(Pedido).filter(
                    Pedido.id == pedido_id, Pedido.empresa_id == empresa_id
                ).first()
        return PaymentService.status_payload(pedido, "pedido")
    finally:
        db.close()


