# ==================================================
# ERROS JSON DO CHECKOUT
# ==================================================

from fastapi.exceptions import RequestValidationError


@app.exception_handler(RequestValidationError)
async def checkout_validation_exception_handler(request: Request, exc: RequestValidationError):
    fields = []
    for item in exc.errors():
        location = item.get("loc") or ()
        field = ".".join(str(part) for part in location if part not in {"body", "query", "path"})
        if field and field not in fields:
            fields.append(field)
    content = {"error": "Dados enviados são inválidos."}
    if fields:
        content["campos"] = fields[:12]
    return JSONResponse(status_code=422, content=content)


@app.exception_handler(Exception)
async def checkout_unhandled_exception_handler(request: Request, exc: Exception):
    request_id = uuid.uuid4().hex[:12]
    LOGGER.exception(
        "Erro não tratado %s em %s %s",
        request_id,
        request.method,
        request.url.path,
    )
    return JSONResponse(
        status_code=500,
        content={
            "error": "Erro interno. Tente novamente em alguns instantes.",
            "request_id": request_id,
        },
    )


# ==================================================
# CANCELAMENTO DE PIX PENDENTE — CHECKOUT
# ==================================================

def _cancelar_tentativa_gateway_v894(db, empresa, origin, origin_type: str, on_approved=None) -> None:
    """Cancela a tentativa no Mercado Pago antes de descartá-la localmente."""
    payment_id = str(getattr(origin, "gateway_payment_id", "") or "").strip()
    if not payment_id:
        return

    # Primeiro reconcilia: se o cliente pagou em outra aba/instante, não podemos
    # cancelar localmente um pagamento que já foi aprovado no gateway.
    payment = sync_origin(
        empresa,
        origin,
        origin_type,
        on_approved=on_approved,
    )
    if normalize_order_value(getattr(origin, "status_pagamento", None)) == "pago":
        db.commit()
        raise PaymentError(
            "O pagamento já foi aprovado e não pode mais ser cancelado.",
            status_code=409,
        )

    gateway_status = normalize_order_value(payment.get("status"))
    if gateway_status in {"pending", "in_process", "authorized"}:
        mp = MercadoPagoService(PaymentService.ensure_company_enabled(empresa))
        response = mp.cancel_payment(payment_id)
        if not response.ok:
            raise PaymentError(
                "Não foi possível cancelar a cobrança no Mercado Pago.",
                status_code=503 if int(response.status_code or 0) >= 500 else 409,
                details=response.data,
            )
        # Consulta de novo pela rotina validada, em vez de confiar cegamente no
        # corpo do PUT de cancelamento.
        sync_origin(
            empresa,
            origin,
            origin_type,
            on_approved=on_approved,
        )


